"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1728],{1728:(e,t,s)=>{s.r(t),s.d(t,{search:()=>n});let a=new(s(1252)).Ay.Document({tokenize:"full",document:{id:"url",index:"content",store:["title","pageTitle"]},context:{resolution:9,depth:2,bidirectional:!0}});for(let{url:e,sections:t}of[{url:"/",sections:[["UniLM.jl",null,["One Julia API for language models and decision models.","","UniLM.jl gives Julia one set of types and verbs for two kinds of model. A language model writes: an answer, a call of one of your functions, JSON that fits a schema. A decision model reads a piece of state — a message, a record, a picture — and answers the questions you list about it with a probability for each answer you allowed, writing no text. Each kind has its chapter, and each provider an entry of its own: its setup, its first call, its options, limits and failures, on its own pages."]],["Language models","home_llm",["A Chat holds a conversation and chatrequest! sends it; respond sends one request of a provider's agentic API; embeddings, images, speech, transcription and fill-in-the-middle completion have verbs of their own, on the providers that serve them. Choose your provider below: its name opens its entry. Language models maps the concepts every provider shares."]],["Decisions","home_decisions",["ask sends the questions — which of these options, where on this scale, whether this statement holds — and returns typed answers your code branches on, and nl_classify and nl_dispatch turn an answer into the key or the method that runs. Choose your provider below: its name opens its entry. Decisions maps the concepts every decision provider shares, and Decisions with LLMs puts a decision on each side of a language model's call."]],["One API across providers","home_across",["The provider is one argument: service names its endpoint and model its model, so code written for one provider runs on another once those two change, as far as the other provider serves what the code asks: the same types and verbs, the same typed results, the same cost accounting and the same RequestConfig. One API across providers says what every provider shares, how to switch, and where the providers differ — which speak their own API and which the OpenAI-compatible one; Capabilities by provider shows what each provider serves; and Write your own backend adds a provider UniLM does not ship. For decision models, the same choice is Choosing a decision provider."]],["Install","home_install",["UniLM requires Julia 1.13 or later and is registered in Julia's General registry:","Install leads on to your provider's setup and its first call."]]]},{url:"/decisions/",sections:[["Decisions",null,["A decision model reads a piece of state — a message, a record, a picture — and answers the questions you list about it with a probability for each answer you allowed: which of these options, where on this scale, whether this statement holds. It writes no text, so there is nothing to parse: ask returns typed answers your code branches on, and their probabilities say whether to act on an answer or to hand the case to a person. Use a decision model rather than a language model when the outcome is one of a set you can name and your code acts on it — the team that handles a ticket, how urgent it is, whether a draft is safe to send — and a language model when the output is text a person reads; Decisions with LLMs puts a decision on each side of a language model's call."]],["Choose your provider","decisions_providers",["Every provider answers ask and the verbs built on it with the same result types, though not every provider takes every question kind or option. A call names its provider with service = …, a with_system_one scope names one for every call inside it, and a call that names neither goes to Jev. What each provider takes, and why a confidence threshold is tuned for each, is on Choosing a decision provider."]],["Concepts","decisions_concepts",[]],["Across providers","decisions_across",[]]]},{url:"/getting_started/",sections:[["Install",null,[]],["Add the package","getting_started_package",["UniLM requires Julia 1.13 or later and is registered in Julia's General registry:","Or from the Pkg REPL:","To track the latest unreleased changes, install from GitHub instead:"]],["Set up your provider","getting_started_keys",["A hosted provider reads its API key from an environment variable; set it in the environment Julia starts from, for example:","A model you run yourself — through Ollama, vLLM, LM Studio or llama.cpp — needs no key unless its server was started with one: the setup is where the server listens. Each provider's Setup section names what it reads and where its requests go; the provider's name below opens it.","The decision providers:"]],["Make a first call","getting_started_first_call",["Each provider's first call is a short example on its entry:","The first decision on each decision provider:"]],["Handle the result","getting_started_results",["A request to a model returns its outcome as a typed result rather than throwing it: a success holding the reply, a failure holding what the provider answered with, or a call error holding what ended the call; nl_classify, nl_dispatch and @branch, which turn a decision into a key or a method, throw a SystemOneError for a failed call instead, and, with no fallback or _ line, a LowConfidenceError or DecisionDeclinedError for an answer they cannot act on. Results shows the types each verb returns and how to read them; four of the Responses lifecycle verbs — delete_response, list_input_items, compact_response and count_input_tokens — return the provider's answer as a Dict on success."]],["Next steps","getting_started_next",[]]]},{url:"/llm/",sections:[["UniLM.jl — LLM Reference",null,["Single-file reference for LLM code-generation systems. This is a Julia package. Julia ≥ 1.13 \xb7 Deps: HTTP.jl (≥ 2.11.2), JSON.jl (≥ 1.12), PrecompileTools.jl, Base64, Dates, SHA Repo: https://github.com/algunion/UniLM.jl"]],["Installation","Installation",[]],["Environment Variables","Environment-Variables",[]],["The APIs","The-APIs",["UniLM.jl wraps these surfaces:","Which API to use:"]],["Service Endpoints","Service-Endpoints",["Provider Compatibility","UniLM talks to native provider APIs where it implements them, and rides the OpenAI-compatible standard elsewhere:","Anthropic and native Gemini use their own APIs here (ANTHROPICServiceEndpoint / GEMINIServiceEndpoint) — not an OpenAI-compat shim — and that is the recommended path. The OpenAI-compat Gemini shim (GEMINIOpenAIServiceEndpoint) exists for embeddings and drop-in compatibility. Google calls generateContent legacy (still fully supported) and launches new models and features on its Interactions API, which respond(…; service=GEMINIServiceEndpoint) speaks.","Register additional Azure deployments at runtime:","Pass the backend via the service keyword on Chat, Respond, or ImageGeneration:","Ollama (local)","OllamaEndpoint sends no key to a server of your own (Ollama's cloud, https://ollama.com, gets OLLAMA_API_KEY as a Bearer token whenever it is set; without it an inference request is not sent, the call error's cause an ArgumentError naming it, while list_models, model_info, running_models, pull_model and delete_model go without it) and has no default model (Chat(service=OllamaEndpoint()) throws ArgumentError; name an installed model, e.g. \"gemma4:e4b\"). Contract of its native chat wire (/api/chat):","Ollama model management","Provider model listings","list_models(; service) on OPENAIServiceEndpoint, ANTHROPICServiceEndpoint (the bare type or an instance) or GEMINIServiceEndpoint lists every model the provider serves the key (GET /v1/models on OpenAI and Anthropic, GET /v1beta/models on Gemini), every page of a paged listing (Anthropic's after_id, Gemini's pageToken; a repeated cursor is a ModelListCallError); all three declare :models. It rides the shared retry seam (max_attempts; total_deadline bounds the whole listing) and is not recorded by with_recorded_answers.","The Anthropic listing sends the key, anthropic-version and the endpoint's anthropic-workspace-id, the headers Anthropic's Models API reference names for GET /v1/models — not the endpoint's user profile, nor its betas (the reference marks anthropic-beta deprecated there). OpenAI keeps listing a model after its shutdown_date, so a listed model is not always one that still answers: compare retires with today's date. Anthropic lists active and deprecated models, not retired ones, and may revise a retires_at it lists. A listing is the provider's view for the key that asks."]],["Chat Completions API","Chat-Completions-API",["Chat","_cumulative_cost is internal bookkeeping for cumulative_cost — read it through that accessor, never directly.","Message",'Validation: role must be one of the four roles; at least one of content, tool_calls, refusal_message, attachments or audio_output must be non-nothing; tool_call_id is required when role == "tool"; attachments only on user messages (an empty vector is stored as nothing); audio_output only on assistant messages, and with content unset or empty the content is its transcript.','Audio replies: AudioOutput(; id, data, expires_at, transcript) — fields id::String, data::Vector{UInt8} (decoded from base64), format::Union{String,Nothing} ("wav", "mp3", "flac", "opus", "aac" by file signature; nothing for raw pcm16), expires_at::Union{Int,Nothing} (Unix seconds — until then OpenAI keeps the audio for later turns, and it answered an id it never issued with HTTP 400 audio_not_found; nothing when the reply names none, or when a stream closed after the turn\'s finish, before the update that alone carries it — the turn is kept either way; an expires_at that is not an integer fails a call that is not streamed, while a stream drops that update — counted in sse_dropped, with one warning — and keeps the turn with expires_at = nothing), transcript::String; an empty id throws ArgumentError. A Chat with modalities=["text", "audio"] and audio=Dict("voice" => …, "format" => …) (e.g. gpt-audio-1.5) gets it on the reply\'s audio_output, streamed (assembled from delta.audio; the transcript is forwarded to the callback as text) or not, with content = the transcript (also when the turn\'s content is unset or empty). Sent back on OPENAIServiceEndpoint and AZUREServiceEndpoint as {"role":"assistant","content":content,"audio":{"id":id}} until a minute before expires_at (always when it is nothing), and from then on as the content alone, which every other encoder sends. On OPENAIServiceEndpoint, estimated_cost bills its audio tokens at the model\'s audio-token rates (gpt-audio-1.5; see TokenUsage).','Attachments: ImageAttachment(path_or_bytes; detail=nothing) (PNG, JPEG, GIF or WebP; detail ∈ "auto", "low", "high", "original"), AudioAttachment(path_or_bytes) (WAV or MP3) and DocumentAttachment(path) / DocumentAttachment(bytes; filename="document.pdf") (PDF: %PDF- only, else ArgumentError("document data is not PDF (checked by file signature; N bytes)"); a blank filename throws), all <: Attachment, recognised by their leading bytes (a URL in place of a path throws). OpenAI-wire endpoints send them as image_url (data URL; detail only when set) / input_audio / file ({"filename", "file_data": "data:application/pdf;base64,…"}) content parts after the text part; OllamaEndpoint sends images and clips in the message\'s images and refuses a document and a detail level; native Anthropic sends an image and a document as base64 image / document blocks before the text and throws for a sound clip or an image detail; native Gemini sends every kind as an inlineData part ahead of the text, an image\'s detail as its per-part media resolution ("low"/"high"; "auto" sends none; "original", or any level on the Gemini 2.5 and Gemma 4 models, throws), and on respond (Interactions) as image/audio/document parts of an InputMessage\'s content; a System One request refuses documents, and an image\'s detail level except on OpenAI\'s Decisions API, whose input_image part takes it; an embeddings input refuses documents and detail levels. Each refusal is an ArgumentError before any request.','Reasoning: reasoning_text(m::Message) / reasoning_text(r::LLMSuccess) → the thinking text a provider returned (:ollama thinking, :deepseek reasoning_content, :anthropic thinking blocks joined by a blank line, :gemini the thought summaries a native Chat that sets reasoning_effort asks for (includeThoughts), :mistral the thinking chunks of a reply, streamed or not, :generic the reasoning_content or reasoning of another generic server\'s reply, such as llama-server\'s or vLLM\'s), else nothing; throws LLMResultError on a failure result. On native Anthropic, a reasoning_effort level from "low" to "max" is the request\'s output_config.effort, and what else it sends follows the model\'s Thinking cell in the Claude family table (Reasoning): on a model with adaptive thinking, thinking = {"type": "adaptive", "display": "summarized"}, so reasoning_text holds the summarized thinking; on a model with extended thinking (budget_tokens) only, the effort alone. "none" sends no effort: what it sends instead — thinking = {"type": "disabled"}, {"type": "between_tools"} or nothing — follows the same cell, and a model whose thinking cannot be disabled refuses it. A model whose Effort levels cell is "—" refuses every reasoning_effort, "none" included.','On the wire a message never sends finish_reason (response-only) or provider_content, and a refusal travels as refusal (with content: null). A tool-call turn reads finish_reason == "tool_calls" when the provider finished it with "stop" or reported none, and keeps any other reason ("length", "content_filter", …). Partial calls are dropped: on a turn that kept another reason, a call whose arguments are not a JSON object (cut off by the token limit) is removed and the turn — text, reason, usage — kept; under "tool_calls" such arguments are an LLMCallError.',"provider_content carries provider-native blocks captured for verbatim round-trip — Anthropic thinking blocks (:anthropic), Gemini parts with thought signatures (:gemini), DeepSeek reasoning_content (:deepseek, echoed on requests that carry tools), Ollama thinking (:ollama, echoed as the assistant message's thinking), a Mistral reply's thinking chunks (:mistral: an unstreamed reply's ThinkChunks as they came, a streamed reply's joined into one; never sent), another generic server's reasoning_content or reasoning (:generic, [Dict(field => text)]; never sent); it never serializes on the OpenAI wire.","Convenience constructors:",'Role constants: RoleSystem = "system", RoleUser = "user", RoleAssistant = "assistant".',"chatrequest!","Conversation Management","issendvalid is true only when ALL of these hold — note it is stricter than push!, with no tool exemption:",'Important: A Chat must begin with a system message. push! throws InvalidConversationError on a non-system message pushed onto an empty Chat and on consecutive same-role messages (except tool), so chat = Chat(); push!(chat, Message(Val(:user), "…")) raises rather than silently leaving the chat empty. pop! on an empty Chat likewise throws InvalidConversationError rather than returning nothing. Use respond("…") for a single turn without a system prompt.','A later system message changes the instructions from that point on. It goes in place on the OpenAI wire and OllamaEndpoint; native Gemini joins it into systemInstruction; on native Anthropic, where it goes depends on two columns of the Claude family table (Conversations). On a model whose Mid-conversation system messages cell is "yes", it stays in place, as a system turn, where the Messages API takes one: right after a user turn (tool results count as one), and last or right before an assistant turn; anywhere else it joins the top-level system prompt, except, on an append-only model, one pushed after a sent assistant turn. On a model whose cell is "—", it joins the top-level system prompt. Append-only are the models whose Thinking prefix check cell is "yes", and any id that matches no row: once an assistant turn is sent, UniLM never edits the top-level system prompt of an append-only model, so a later system message that cannot stay in place is held back, then sent right after a later user turn, and the turns before each sent reply stay as they were in the request that got it. A system message pushed after a reply needs a user turn after it — a user message, or the results of the reply\'s tool calls — except in a response prefill on a model whose Prefill cell is "yes": until one follows, chatrequest! throws ArgumentError before sending.',"Tool Calling Types","The pre-rename names GPTTool, GPTToolCall, GPTFunctionSignature, and GPTFunctionCallResult remain exported as aliases of these types, so existing code keeps working unchanged.","ResponseFormat (Structured Output)","Chat Completions Example","Tool Calling Example (Chat)","Streaming Example (Chat)"]],["Responses API","Responses-API",["Respond",'seed is sent by Gemini Interactions, as an int32 (outside that range it throws), and by a GenericOpenAIEndpoint, as given (vLLM\'s Responses API forwards it to its engine); OpenAI\'s Responses API has none, so OPENAIServiceEndpoint, the other OpenAI-wire endpoints (Azure, GEMINIOpenAIServiceEndpoint) and OllamaEndpoint throw ArgumentError for it before any request. On GEMINIServiceEndpoint, a Respond\'s service_tier is "standard", "flex" or "priority", the tiers Google\'s Interactions API reference lists; "deferred" throws ArgumentError before any request, since the API answered it with HTTP 400 on 2026-10-26 (Request options). The positional constructor takes all 32 fields in declaration order; build a Respond with keywords, which name each field.','With service=GEMINIServiceEndpoint, a set Respond field the Interactions wire has no equivalent for makes respond throw ArgumentError before any request rather than being silently dropped, so a request never goes out quietly ignoring what you asked for. That wire maps model, input (each InputMessage, or Dict with a role, becomes a user_input or model_output step, its content Interactions text, image, audio and document parts; a system or developer message, a phase, a web-URL or file-id media part and a cache breakpoint are rejected), instructions, tools, tool_choice, temperature and top_p (only for these exact ids, released before Gemini 3.6 Flash: gemini-3.1-pro-preview, gemini-3.1-pro-preview-customtools, gemini-3.1-flash-lite, gemini-3-flash-preview, gemini-2.5-pro, gemini-2.5-flash, gemini-2.5-flash-lite, gemma-4-31b-it, gemma-4-26b-a4b-it and the image models gemini-3.1-flash-lite-image, gemini-3-pro-image, gemini-3.1-flash-image and gemini-2.5-flash-image; Gemini ignores them on later models, so for any other id they throw, as on native Chat and GEMINIOpenAIServiceEndpoint), max_output_tokens (above 65,536 on gemini-4-argon only with background=true), stream, text (its format becomes the top-level response_format; verbosity is rejected), store, previous_response_id, background (with store=false it is rejected: Google answers that with HTTP 400), reasoning (effort and automatic summaries only), service_tier ("standard", "flex" or "priority"; "deferred" is rejected: the API answers it with HTTP 400), safety_identifier (the request label safety_identifier) and seed (generation_config.seed). Every other field — moderation, prompt_cache_options (Gemini caches prompts implicitly; UniLM does not wrap its explicit caching), and the rest of the OpenAI-only options — is rejected; leave it unset, or send the request to an OpenAI Responses service. A FunctionTool with async, allowed_callers, defer_loading, or output_schema set is rejected the same way.',"Input Helpers","input_image and input_file throw ArgumentError when none of their source arguments is given.","Tool Types","Convenience constructors:","Text Format / Structured Output","Convenience constructors:","Reasoning controls","OpenAI GPT-5.6 and later (on Respond and Chat) and native Anthropic (on Chat) take typed prompt-cache options:",'Another ttl throws ArgumentError at construction, and each endpoint takes its own subset, refusing the rest with an ArgumentError naming it, before any request: native OpenAI takes "30m" on Chat Completions (which answers any other ttl with HTTP 400) and "30m" or "12h" on Responses and on its Decisions API; on ANTHROPICServiceEndpoint the options become a top-level cache_control (automatic caching, the breakpoint on the last cacheable block) with ttl "5m" or "1h" and mode "implicit" or unset — prewarm=true, comparison_response_id and the OpenAI ttls throw; native Gemini (Chat and Interactions) and OllamaEndpoint refuse prompt_cache_options (Gemini caches prompts implicitly; UniLM does not wrap its explicit caching); Azure, GEMINIOpenAIServiceEndpoint, DeepSeek and generic endpoints send the object unchanged, the server\'s answer being the check. A Chat with mode="explicit" throws ArgumentError when it is built, whatever its endpoint (below).','On OpenAI, prompt_cache_retention throws ArgumentError for gpt-6-astra, gpt-6.1-sol, gpt-6.1-terra, gpt-6-sol, gpt-6-luna, gpt-5.6 and gpt-5.6-sol/-terra/-luna (and their dated snapshots), whose cache lifetime prompt_cache_options sets; on other models UniLM sends it unchecked, beside prompt_cache_options when that is set too (the Responses reference lists the two fields independently, and documents prompt_cache_options for gpt-5.6 and later), leaving both to the server — the reference takes only "24h" on gpt-5.5 and gpt-5.5-pro. Explicit mode requires cache breakpoints in input content to create cache writes — mark them with input_text(text; cache_breakpoint=true), a Responses input part; a Chat sets none, so explicit mode would turn its caching off, and the Chat constructor refuses it. Chat Completions takes only mode and ttl (a native OpenAI Chat with prewarm or comparison_response_id set throws ArgumentError). Diagnostics requested with comparison_response_id come back in r.response.raw["prompt_cache_diagnostics"]. Unset fields are omitted. OpenAI prompt caching, Anthropic prompt caching.',"Moderation",'The moderation field on Respond and Chat runs a moderation model over the request input and the generated output. model is required, as in both the Responses and the Chat Completions API references: ModerationConfig() without it throws UndefKeywordError, and a mode other than "score"/"block" throws ArgumentError. It serializes as {"model": …, "policy": {"input": {"mode": …}, "output": {"mode": …}}} with unset policy parts omitted. A respond result carries the outcome in r.response.raw["moderation"] ("input" and "output" moderation results), and a chatrequest! result in r.moderation, the completion\'s moderation (a stream\'s moderation chunks merged).',"respond","Response Accessors","Response Management Functions","Each makes a single bounded attempt (no retries) and observes the ambient with_cancel token; every call error carries its exception in .cause.","ResponseObject",'A generation whose terminal status is "failed" is reported as a ResponseFailure, not a success — on both agentic wires, streamed and non-streamed alike. The failure carries the wire body verbatim, so the response\'s own error and metadata are preserved on .response. Only "failed" flips: incomplete, cancelled, expired, in_progress, queued and requires_action are legitimate terminals of the capped, background and tool-action flows and stay ResponseSuccess, inspectable via response_status and incomplete_details. An incomplete generation — one cut short by a token or output cap — therefore arrives as a ResponseSuccess carrying its partial output, .response.status == "incomplete", and the wire\'s incomplete_details verbatim. A terminal response.incomplete event decodes exactly as the non-streamed body does, so issuccess reflects what happened rather than how the call was made.',"Responses API Examples"]],["Image Generation API","Image-Generation-API",["ImageGeneration","input_fidelity is an edit-only parameter: it lives on ImageEdit, and ImageGeneration(...; input_fidelity=...) is a MethodError. A field the request's provider does not take (an OpenAI-only field on Gemini; aspect_ratio or resolution on OpenAI), n other than 1 on Gemini, a Gemini aspect_ratio or resolution outside its list, and a safety_identifier outside its provider's rule (empty or over 128 characters on OpenAI) throw ArgumentError naming the provider and the field — when the request is serialized, and in generate_image / edit_image before any request; other OpenAI values are sent as given, for OpenAI to judge.",'Unlike Chat and Respond, ImageGeneration does not resolve its model at construction: the field stays "" and resolves at serialization time, to "gpt-image-2.5-sunburst" for OpenAI or "gemini-nano-banana-2.1" for Gemini. So ImageGeneration(prompt="…").model reads back as the empty string — pass model= explicitly if you need to read it, or inspect JSON.json(ig) to see what will go on the wire (Gemini names the model in the URL instead). A service with no default image model throws ArgumentError at serialization.',"generate_image","Retries transient statuses (408/429/500/502–504/520–524/529) inside the request budget (RequestConfig.max_attempts, default 3; the wait a reply asks for, retry-after-ms else Retry-After, is a floor under the jitter) — a retry whose wait would exceed the remaining total_deadline is not attempted, so the call returns the last real response rather than sleeping past it. Bound per call with config=RequestConfig(...); a cancelled call returns ImageCallError with cause::UniLMCancelled.","Gemini (Nano Banana): with service=GEMINIServiceEndpoint both verbs call generateContent (GEMINI_API_KEY) with responseModalities: [\"IMAGE\"] and an imageConfig from aspect_ratio / resolution, a safety_identifier as the request label safety_identifier; an edit sends its input image(s) inline ahead of the prompt (no mask). The model's image parts are the result's images, in order — JPEG as observed (each part's mimeType is in raw); text it sends with an image is the revised_prompt, interim thinking images are not results; a reply with no image is an ImageCallError naming Gemini's finish reason (IMAGE_SAFETY, NO_IMAGE, …); created is the reply's arrival time (Gemini sends none); usage is the reply's usageMetadata, read by token_usage (thinking counted as output). estimated_cost of an image result throws ArgumentError unless model= is given (a model= with no row in pricing is estimated at 0.0, with the no-row warning).","Response Types","Accessors","Image Generation Example"]],["Embeddings API","Embeddings-API",["Embeddings",'Model defaults: "text-embedding-3-small" for OpenAI, "gemini-embedding-2" for Gemini (OpenAI-compat shim). Every other service has none: without model the constructor throws ArgumentError naming the service. Embeddings run on an endpoint that declares :embeddings — OpenAI, GEMINIOpenAIServiceEndpoint, Ollama, generic endpoints (Mistral included) — or declares no capabilities; embeddingrequest! refuses any other (DeepSeek, Azure, native Gemini, Anthropic, TypeSafe) with an ArgumentError before any request, whatever the model. An empty vector input also throws. A reply row without an index beside numbered ones is row 0 (Gemini\'s compatible endpoint leaves the index out of its first row), a reply numbering none is read in order, and a second row 0 is an EmbeddingCallError.','Task prompts (checked at construction, ArgumentError, no I/O): task ∈ :search_query, :question_answering, :fact_checking, :code_retrieval, :document, :classification, :clustering, :sentence_similarity, :none. An EmbeddingGemma model (name contains embeddinggemma, case-insensitive; v1 and v2, any service) requires a task and gets the model card\'s prompt in front of each text: "task: search result | query: ", "task: question answering | query: ", "task: fact checking | query: ", "task: code retrieval | query: ", "task: classification | query: ", "task: clustering | query: ", "task: sentence similarity | query: ", and for :document "title: " * something(title, "none") * " | text: "; :none sends the text as is. A title is refused with any other task; EmbeddingGemma\'s dimensions ∈ (768, 512, 256, 128). gemini-embedding-2 (exact id) gets the same prompts but also takes no task (its text then sent as is; Google\'s embeddings guide recommends the prompts for text), with no dimensions check. Any other model takes task = :none or nothing (another task, or a title, is refused). Media items need an OllamaEndpoint (/api/embed): every other service\'s wire is text-only and throws before I/O; media take no prompt, the text of a mixed item does (Ollama 0.40.6, Apple M4 Max, 2026-10-21, embeddinggemma-2:740m-q8_0 and :740m-mxfp8: a text with its picture or clip as one item gave a vector distinct from each part\'s, cosine 0.845–0.958 with each); the 440m (text and images) and 570m (text and audio) builds are untested.',"The embeddings buffer is pre-allocated to something(dimensions, 1536) zeros per input, filled in place, and resized to the length the model returns (a 3072-dimension model needs no adjustment). Because a pre-zeroed slot would be indistinguishable from a real vector, a response that does not cover every input exactly once — a missing or duplicated row index — is reported as an EmbeddingCallError rather than left as zeros, and so is a row whose vector is empty, all zeros or holds a value that is not a finite number (a JSON true included), a row without a vector, and a row index that is not an integer; every row is checked before any is stored, for every provider. The result aliases the request (result.embeddings === emb), so use one Embeddings per concurrent call.","embeddingrequest!","Returns an EmbeddingSuccess/EmbeddingFailure/EmbeddingCallError (a <: LLMRequestResponse). Fills emb.embeddings in-place; embedding_vectors(result) returns the vectors (and throws LLMResultError on a failure). Retries transient statuses (408/429/500/502–504/520–524/529) with backoff and jitter under the resolved RequestConfig (max_attempts, total_deadline; the wait a reply asks for, retry-after-ms else Retry-After, is a floor under the jitter), but a retry whose wait would exceed the remaining deadline is not attempted — it returns the last real response rather than sleeping past it. Timeouts surface as EmbeddingCallError with status=nothing and the UniLMTimeout in .cause; a cancelled call carries UniLMCancelled there. A service that declares capabilities without :embeddings throws ArgumentError before any request.","Embeddings Example"]],["Cost Tracking","Cost-Tracking",["TokenUsage","The counts come from the providers' usage objects and default to 0 when the provider omits them. cached_tokens is load-bearing for cost: it is billed at the discounted cached-input rate. OpenAI (Chat streamed and not, Responses, Decisions) and Anthropic report cache writes, and the extended-retention share of them (OpenAI's 12-hour, Anthropic's 1-hour); service_tier comes from OpenAI's service_tier, Anthropic's (\"fast\" for a request served in fast mode) and Gemini's (the x-gemini-service-tier header, else usageMetadata.serviceTier, or an interaction's service_tier; on GEMINIOpenAIServiceEndpoint, whose replies name none, the tier the request asked for); inference_geo from Anthropic. The audio counts come from OpenAI Chat Completions' prompt_tokens_details.audio_tokens / completion_tokens_details.audio_tokens, and prompt_audio_tokens also from Gemini's AUDIO counts on the native endpoint (promptTokensDetails and toolUsePromptTokensDetails) and in Interactions (input_tokens_by_modality and tool_use_tokens_by_modality), streamed and not; cached_audio_tokens comes from Gemini alone, the AUDIO count of cacheTokensDetails and the audio of an interaction's cached_tokens_by_modality: estimated_cost bills them at the model's audio-token rates on OPENAIServiceEndpoint (gpt-audio-1.5: $32 / $64 per 1M) and at the audio input rate Gemini's pricing page states (below); any other audio tokens — another model or endpoint (Azure, DeepSeek, generic, custom) — give 0.0 with one warning per model and endpoint. GEMINIOpenAIServiceEndpoint reports no audio count: its audio is in prompt_tokens, priced at the text rate — a lower bound on a model with an audio price of its own, for which such a request warns once per model.","Functions","The OpenAI, Anthropic and Gemini rows were verified October 22, 2026 (OpenAI's gpt-5-search-api October 25, 2026, gpt-5.2-pro October 26, 2026), the TypeSafe rows October 25, 2026 and the DeepSeek rows September 24, 2026 (its peak rates; off-peak hours bill half). The rows are standard short-context text rates; surcharges apply only where UniLM models the provider's, and multimodal rates (except OpenAI's and Gemini's audio rates) and hosted-tool fees are not included. A billed tier the provider's pricing page lists no price for (OpenAI's Scale; Fast on gpt-5.4-pro or on a gpt-5.5 prompt over 272K tokens) is estimated at the standard rates with one warning per model and tier. OpenAI estimates bill cache writes at 1.25\xd7 input (\"30m\") or 2.5\xd7 (\"12h\", cache_write_extended_tokens) on GPT-6 and GPT-5.6, a prompt over 272K input tokens at 2\xd7 the input and cache rates and 1.5\xd7 the output rate, and the billed tier's multiple of every rate (Flex 0.5\xd7; Fast 2\xd7 on GPT-6, GPT-5.6, gpt-5.4, gpt-5.4-mini and gpt-5.2, 2.5\xd7 on gpt-5.5, 1.75\xd7 on GPT-4.1 and o3; Ultrafast 6\xd7 on Astra and 6.1 Sol; a reported \"priority\" is Fast); a tier the pricing page gives no price for is estimated at the standard rates with one warning per model and tier. Anthropic prompt_tokens include cache reads and writes (cached_tokens the reads, cache_write_tokens the writes and cache_write_extended_tokens the 1-hour ones), and its results bill cache writes at 1.25\xd7 (5-minute) or 2\xd7 (1-hour) input, every rate 2\xd7 in fast mode (service_tier == \"fast\"), 1.1\xd7 for inference_geo == \"us\" on Claude 4.6 and later (the 4.5 models bill the standard rates) and 5\xd7 for a Claude Haiku 5.5 prompt over 100,000 tokens, the multipliers stacking; a reply at Anthropic's Priority Tier is estimated at the list rates. DeepSeek cache hits (prompt_cache_hit_tokens) are billed at the cached rate. A Gemini result is priced as the model that served it (result.model from modelVersion, response.model), so routed ids and -latest aliases bill at their targets' rates (gemini-3.1-pro-preview serves gemini-pro-latest), and a tool-use prompt counts as prompt tokens. A prompt over 200K tokens on gemini-3.1-pro-preview (and -customtools) or gemini-2.5-pro bills at the long-context rates, the whole request: 2\xd7 the input and cache-hit rates, 1.5\xd7 the output rate. Audio input bills at the input price the pricing page states for audio, at the tier's and a long prompt's multiples as text: a model's own audio price where the page lists one apart — gemini-3.1-flash-lite $0.50, gemini-3-flash-preview and gemini-2.5-flash $1.00, gemini-2.5-flash-lite $0.30 per 1M — else the row's input rate, since an input price that names no modality (or names audio among the others) is every modality's: Gemini 4 Argon, 3.8 and 3.6 Flash, 3.5 Flash-Lite, 3.1 Pro Preview, 2.5 Pro, Robotics-ER 2 Preview. A cache hit bills at the row's cached rate, except the cached audio (cached_audio_tokens) on the four models with an audio price of their own, which bills at the cached-audio price their tables list — gemini-3.1-flash-lite $0.05, gemini-3-flash-preview and gemini-2.5-flash $0.10, gemini-2.5-flash-lite $0.03 per 1M — scaled by the billed tier as the cache-hit rate is. Audio on a model the page prices without audio (the image models) or does not list, Gemini audio output, and a cache hit on one of those four models whose usage reports more cached tokens than text tokens and cached audio together give 0.0 with one warning per model and endpoint. A Gemini result is billed at the tier it reports (usage.service_tier: the x-gemini-service-tier header, else usageMetadata.serviceTier, or an interaction's service_tier; GEMINIOpenAIServiceEndpoint replies name none, so a Chat result there records the requested tier — \"priority\" priced at Priority is an upper bound, since Google bills a downgraded Priority request at Standard and this endpoint does not report the downgrade) — input and output at half the standard rates on Flex and 1.8 times on Priority, a cache hit at the same multiple except where a model's table lists another cache-hit price (Flex's standard rate on 3.1 Pro Preview, 3 Flash Preview and the 2.5 models; $0.02 on Flex and $0.05 on Priority for 3.5 Flash-Lite's $0.03), a tier the page does not price at the standard rates with a warning; a long generation Gemini sends in several requests is one turn whose usage is the requests' summed, priced at the last reply's tier. A streamed Chat turn accrues cost when its stream reports usage: OpenAI, DeepSeek and GEMINIOpenAIServiceEndpoint streams request it automatically, native Anthropic and Gemini report it, and other OpenAI-compatible servers need stream_options=Dict(\"include_usage\" => true). Gemini 4 Argon's introductory rates hold through November 30, 2026 and Gemini 3.8 and 3.6 Flash's through December 31, 2026; refresh pricing before estimating later calls.","Cost Tracking Example"]],["Conversation Forking","Conversation-Forking",["Fork Example"]],["Tool Loop","Tool-Loop",["Automated tool dispatch for both APIs. Wraps a tool schema with a callable function.","CallableTool","to_tool","ToolCallOutcome / ToolLoopResult","tool_loop! (Chat Completions)","callback and on_tool_call are the streaming hooks from chatrequest!, applied to every turn of the loop and passed through unchanged (so they need stream=true, else ArgumentError before any request). Rules:","tool_loop (Responses API)","Turns chain through previous_response_id, or through conversation alone when the Respond sets it. Function calls run only on a completed or requires_action turn; another status stops the loop (completed=false, llm_error naming the status and the incomplete_details reason). Call arguments that are not a JSON object are answered with \"Error: invalid arguments: …\" and the loop continues. A turn requesting a client-side action the loop cannot run (custom_tool_call, apply_patch_call, computer_call, a shell_call without a shell_call_output in the same output, mcp_approval_request) stops it with completed=false, naming the type, and runs none of the turn's calls. Result encoding, max_turns, cancel and tool_concurrency behave as in tool_loop! (a cancelled loop's response is a ResponseCallError)."]],["MCP Client","MCP-Client",["Native MCP client (JSON-RPC 2.0 over stdio or Streamable HTTP). Client and server negotiate revisions 2025-11-25 (preferred), 2025-06-18 and 2025-03-26; the stateless 2026-07-28 revision is not supported yet, so a 2026-07-28-only peer cannot connect.","Types","Lifecycle","stderr is where a stdio server's stderr goes — an IO (e.g. devnull) or a file path (appended to); nothing inherits this process's. A stdio server runs in its own process group: disconnecting or a fatal timeout tears it down (stdin EOF, SIGTERM, then SIGKILL of the group), the group is killed when its leader exits, and servers still running at exit are torn down by an exit hook.","Discovery","When the client reads a notifications/tools/list_changed, session.tools_stale is set to true to flag the cached tool list as out of date; call list_tools!(session) to refresh it (which clears the flag). Server frames are read only during an exchange: a stdio notification sent between calls is seen on the next call, and over HTTP (no standing listener) only notifications inside a response body are seen.","Operations",'call_tool and get_prompt accept any AbstractDict for arguments, so the natural Dict("path" => "/tmp/x") form works without conversion.',"Timeouts surface as the exported MCPTimeoutError (phase :connect, :queue or :request). A stdio request timeout closes the session — killing the server is the only way to release a read blocked on it; the error surfaces at about the bound and a reply that raced the teardown is discarded. An HTTP request timeout does not close the session, and the timed-out request gets a best-effort notifications/cancelled. A stdio server that exits or whose pipe breaks surfaces the exported MCPCrashError (the session closes with cause :crash). With auto_respawn=true the next call on a session closed by a timeout or a crash respawns the server; otherwise, and after mcp_disconnect!, every call throws MCPSessionClosedError.","A CancelToken (ambient with_cancel) reaches MCP calls over HTTP: a cancel throws UniLMCancelled at once, sends a best-effort notifications/cancelled, and leaves the session open. A stdio exchange does not observe the token (bounded by mcp_request_timeout). Teardown requests (the disconnect DELETE, a cancellation notice) are sent even inside a cancelled scope.","Session Concurrency","An MCPSession runs one call at a time: each call's liveness check, id allocation and request/response exchange holds the session, and waiting callers are served in arrival order (FIFO).","For genuine parallelism, open one session per concurrent worker.","Tool Result","call_tool returns a typed result — a tool-execution error (isError: true) is carried on is_error, not thrown; only JSON-RPC protocol errors throw (MCPError).","The mcp_tools / mcp_tools_respond bridges surface content to the model on success (falling back to JSON.json(structured) when content is empty), and raise content as an error when is_error is set.","Tool Bridge","Bridged tool names are provider-safe for service, the endpoint the tools go to: any character outside [A-Za-z0-9_-] becomes _, and a name longer than the provider takes — 128 characters on ANTHROPICServiceEndpoint, GEMINIServiceEndpoint and DeepSeekEndpoint, 64 on OPENAIServiceEndpoint and every other endpoint — is cut to the limit less 9 characters and followed by _ and the first 8 hex digits of the SHA-256 of its MCP name, so names that agree up to the cut stay apart (the callable still calls the MCP name); two tools mapping to one name raise ArgumentError.","Client Example"]],["MCP Server","MCP-Server",["Build MCP servers that expose tools, resources, and prompts.","Types","Registration","The inferred-schema register_tool!(server, name, description, handler) binds each tools/call arguments object to the handler's positional parameters by name, as @mcp_tool does: a parameter whose type admits nothing is optional, every other one required, and a value must have its parameter's JSON type (a Symbol binds from a string; typed Vector/Dict parameters convert element-wise). A violation is answered with an isError: true tool result naming the argument. A handler taking one Dict or varargs throws ArgumentError — pass an explicit schema for those. Registration is synchronized: it may run while serve is dispatching. @mcp_tool registers the tool without a description.","Macros","Serving","The HTTP transport blocks until the server is closed (like HTTP.serve); pass block=false to get the running server handle back and close it yourself. It also validates the Origin header (DNS-rebinding defense): requests with no Origin header and localhost origins pass, any other origin gets 403 unless listed in allowed_origins. A request other than initialize whose MCP-Protocol-Version header names an unsupported revision gets 400; initialize answers the requested revision when supported, otherwise 2025-11-25.","Concurrency: over HTTP, tools/call, resources/read and prompts/get handlers run concurrently, one task per request on the default thread pool — handlers must be thread-safe; protocol requests (initialize, lists, ping) are answered inline. Over stdio handlers run one at a time, and the process stdout points at stderr while serving on it, so a printing handler cannot corrupt the frame stream.","Error and Limit Contracts","Server Example"]],["FIM Completion","FIM-Completion",["Fill-in-the-Middle: generate text between a prompt (prefix) and suffix. Supported by DeepSeek (beta), Mistral (routed to /v1/fim/completions), and Ollama; vLLM's completions endpoint rejects suffix.",'Unlike Chat, FIMCompletion does not resolve its model at construction — the field stays "" until serialization, where it becomes "deepseek-flash" for DeepSeekEndpoint. Endpoints without a default FIM model must set model= explicitly, or fim_complete throws ArgumentError. Local validation (capability — strict, so an endpoint that declares nothing throws ArgumentError — model resolution, routing) throws before any request; every later failure, including a 200 body that is not a completions response, is a FIMCallError whose cause holds the exception. Retries follow the shared policy; FIMSuccess results report usage and cost.',"FIM Example"]],["Chat Prefix Completion","Chat-Prefix-Completion",["Continue from a partial assistant message. The model generates text continuing from the assistant's prefix. DeepSeek beta feature.","The result's message is the continuation the API returns; with chat.history the conversation keeps the whole assistant turn, prefix followed by continuation. The request is never streamed: a chat with stream=true is sent without its stream and stream_options. A cancelled call returns LLMCallError (cause::UniLMCancelled) and leaves chat untouched.","Prefix Example"]],["System One API (Jev, OpenAI Decisions, Ollama)","System-One-API-(Jev,-OpenAI-Decisions,-Ollama)",["A System One model answers enumerated questions about a piece of state with a probability distribution over the outcomes you named — no generated text, no parsing. The generic surface below works with any backend that declares :system_one. Three ship, each behind a wrapper (its protocol) that checks before anything is sent what its wire cannot carry, with an ArgumentError naming the backend, the rule and the fix:","Each wrapper's rules, refused before any I/O (on every backend also a DocumentAttachment, which no System One wire carries, and on TypeSafe and Ollama an image's detail level, for which their wires have no field):","Calibration differs per backend: on 129 labelled tickets with 7 options (2026-10-20) Jev (jev-1.13.0) scored accuracy 0.969 / ECE 0.016 and OpenAI (gpt-6-luna) 0.946 / 0.080, under-confident (accuracy ≥ mean top probability in every bin above 0.5) — tune min_confidence per backend.","Constructors, verbs and accessors","questions accepts name => question pairs (vector, tuple, NamedTuple, or AbstractDict — a plain Dict in sorted name order), or bare questions auto-named \"q1\", \"q2\", … in order. Mixing the two, repeating a name, a blank name, or passing none is an ArgumentError; so is a state that is not a string, object, array or image, a NaN/Inf anywhere in the content, and anything the backend's wrapper refuses — all before any request. Every answer is checked against the request before a success is built (each question answered once and nothing else; the question's kind, except for a RawQuestion; a Choice of an offered option that is the most probable, with probabilities for exactly the offered options; Score levels exactly 0 … n−1 in canonical decimal, a score between them that is Σ i\xb7pᵢ within (n − 1)\xb7tolerance + step (the sum tolerance and the rounding step below), and a legend that repeats each level asked as a string unchanged — OpenAI's echoed labels likewise; object, array and image levels are not compared; every probability, confidence, noul and box edge in 0 … 1, a box not inside out (top ≤ bottom, left ≤ right); probabilities summing to 1 within the backend's rounding — 0.005n on TypeSafe and OpenAI, n\xb70.5e-4 on Ollama, plus a floating-point margin — and the chosen option at most one rounding step below the most probable (0.01, 0.01, 1e-4); a model string that is not blank); a reply that fails is a SystemOneCallError. A usage value that is not a non-negative whole number reads as 0 with a warning (on OpenAI, so does a usage details value that is not an object). ask, ask_each and list_models ride the shared retry seam, so RequestConfig.max_attempts applies to 408, 429, 500, 502–504, 520–524 and 529, and the final SystemOneFailure carries retry_after — the wait the service asked for in seconds, or nothing when it sent no hint. With no RequestConfig set by the user (no config, no with_request_config scope, no set_default_config!), calls on TypeSafe's wire and OpenAI's use request_timeout = 60, total_deadline = 150; Ollama's use the field defaults. TypeSafe retries carry X-TypeSafe-Retry-Count (\"1\" on the second attempt). Every System One exchange uses one connection pool per process (256 idle connections per host, kept 30 s), created by the first live request.","Decision provider contracts","Provider protocol (public, not exported)",'The exchange: resolve the backend, model and options, check :system_one, encode (outside the error handling), then — through any with_recorded_answers scope, keyed by "/<namespace>" * path (TypeSafe\'s namespace is empty, OpenAI\'s "openai-decisions", Ollama\'s "ollama", a protocol of your own its type\'s name) and record_body plus key_extra (TypeSafe: record_body == body; Ollama leaves out keep_alive, OpenAI prompt_cache_key, safety_identifier and prompt_cache_options) — send body with auth_header(service) read only for a live call, through the System One connection pool, and decode. An endpoint that declares :system_one and no protocol speaks TypeSafe\'s wire: a gateway needs provider_capabilities (with :system_one), a base URL (the internal hook UniLM._api_base_url) and auth_header, or no code at all when TYPESAFE_BASE_URL points TYPESAFEServiceEndpoint at it.',"Example","Recorded answers","Identical requests are not answered identically, so tests and docs builds replay recorded answers. Inside the scope, every ask (hence ask_each, nl_dispatch, nl_classify and @branch) and TypeSafe's list_models, every chatrequest! and respond, streamed or not, and embeddingrequest! (hence tool_loop! and tool_loop), the Responses lifecycle operations (get_response, delete_response, list_input_items, cancel_response, compact_response, count_input_tokens), fim_complete and prefix_complete exchange through dir; everything else reaches the network as usual (images, audio, files, batch, moderation, the other model listings, Ollama's pulls, realtime, MCP), in every mode. Scopes cover spawned tasks and nest (an inner scope's service is the enclosing scope).","Natural-language control flow","A Choice answer is already a branch decision, so two constructs compile ordinary control flow into ONE System One request. @branch is a natural-language switch that evaluates only the selected body; nl_dispatch sends one Choice per Meaning slot and then hands the resolved meanings to Julia's own dispatch, so the remaining arguments still dispatch on their types.",'Methods without a concrete Meaning argument (including wildcard ::Meaning ones) are ordinary methods and are not part of the natural-language interface. Every natural-language method of f must agree on arity and on which positions are slots, so a partial wildcard (f(::nl"a", ::Meaning, x)) is an ArgumentError. A call offers only the meanings of methods that accept the types of its ordinary arguments. Types no such method accepts, and a combination of offered meanings with no method or an ambiguous one, are each an ArgumentError raised before any request. A combination with no method is closed by defining it, or by one method wild in every slot (f(::Meaning, ::Meaning, x)), which is not an option and covers every combination that has no method; an ambiguous one only by a method for the intersection of the methods it collides on, which the error names. Without state, the state is a JSON.Object{String,Any} keyed by the ordinary argument names of the first such method, in argument order; the questions are named from the same method. confidence is (n\xb7p_max − 1)/(n − 1) clamped to 0 … 1 over the n offered options, so a min_confidence is a different bar whenever the option list changes.','With texts, the methods of f dispatch on keys, and the request is the one the same sentences written as nl"..." would make. The call\'s arity is length(args) plus one per table, and only methods of that arity take part. A table fills the one position whose declared type its keys have (::Val{:refund}, ::Refund, ::Type{<:Billing}, ::Val; ::Any declares none). Refused before any request: a Dict, an empty table, more entries than the backend lets one question offer (255 on TypeSafe), a blank sentence or one that is not a string, a sentence given twice, two keys whose dispatched values are isequal (:a and Val(:a), Vector and Array{S,1} where S), nothing or missing as a key, a Tuple of pairs, a key that is not a Symbol, singleton instance, type or enum value, a table with no position or several, two tables in one position, a method of that arity pinning a Meaning, and a key no method takes at its position whatever the other arguments are (a catch-all f(k, t) takes every key). Options follow the argument types in table order, where meanings are offered in definition order; gaps are refused alike. The questions and the state are named from the first method, in definition order, that pins a table — never from a catch-all defined before it.']],["Audio: speech, transcription, translation","Audio:-speech,-transcription,-translation",["Speech. On OPENAIServiceEndpoint, speak runs on a Realtime API session (wss://api.openai.com/v1/realtime, gpt-realtime-2.1-mini unless model names another — OpenAI's replacement for its text-to-speech models, which shut down on 2027-01-06): UniLM sets the voice (alloy, ash, ballad, coral, echo, sage, shimmer, verse, marin, cedar), 24 kHz PCM output and instructions to read the text word for word, and collects the response's audio (Realtime models are conversational; OpenAI notes instructions are not guaranteed to be followed). On GEMINIServiceEndpoint it is Gemini TTS (generateContent on gemini-3.8-flash-tts; instructions as the speech style), which reads the text verbatim: one of its 30 studio voices goes as prebuiltVoiceConfig.voiceName, any other voice — an Extended Voice Library voice, a voice_… id or a voicekey_… key — as voiceConfig.voice, sent as given. An empty input, a voice the Realtime session lacks, a blank Gemini voice, a response_format other than \"wav\"/\"pcm\" (mp3, opus, aac and flac are refused), a speed out of range and any speed on Gemini throw ArgumentError before any request, as does GEMINIOpenAIServiceEndpoint (no speech route there: the error points to GEMINIServiceEndpoint). translate streams a 16-bit PCM WAV file (any rate and channel count: mixed down to mono and resampled to 24 kHz) through an OpenAI Realtime translation session (wss://api.openai.com/v1/realtime/translations; OpenAI shuts /v1/audio/translations down on 2027-02-26) into language (English unless named) and returns the translated text as a TranscriptionSuccess (speech already in the target language can come back empty); any other file, an empty one, a blank language and a service without the Realtime API throw ArgumentError before I/O. A failure the provider reports is an AudioFailure — an HTTP error status, a refused WebSocket upgrade (a bad key is a 401), a Gemini candidate that did not finish (finishReason other than STOP) or a reply without one (a blocked prompt), both with status 200, or a Realtime error event — read even when the server closes the session while UniLM sends — or unfinished response.done (status = nothing, the event's JSON as response); a session that closes before its result (the close's status and reason in error, the HTTP.WebSockets.WebSocketError in cause), a timeout, a cancel and a reply without usable audio are an AudioCallError, and audio received before a failure is never returned. Both make a single bounded attempt (total_deadline the whole call, connect_timeout the WebSocket open, stream_idle_timeout every send and every wait for the next event) and observe the ambient CancelToken (with_cancel): a token already cancelled sends nothing, and a cancel ends the call at once with cause = UniLMCancelled. Speech is not priced: token_usage and estimated_cost throw for a SpeechSuccess.",'Transcription. The default model is "gpt-transcribe" on OpenAI, and on an endpoint of your own that declares :audio or :transcription; an OllamaEndpoint has none, so a request to it names an installed model that hears audio (model = "gemma4:e4b") or throws ArgumentError before any request. A GenericOpenAIEndpoint has none either: its request names the model its server serves, or throws the same way, and goes to the server\'s /v1/audio/transcriptions with every field it sets, as given (vLLM serves OpenAI\'s Transcriptions API there). On Ollama the request goes to /v1/audio/transcriptions and asks for JSON only; temperature, languages, keywords and a response_format other than "json" throw before I/O — "text" with the fix, since Ollama reports a failure that arrives after its reply has begun only as JSON and "text" would read it as an empty transcript: leave response_format unset and read the text with transcript_text — and the reply is read as JSON (Ollama labels it application/x-ndjson). On OpenAI, srt, vtt and verbose_json (subtitles and timestamps) are documented only for whisper-1 and diarized_json (speaker labels) only for gpt-4o-transcribe-diarize, models that shut down on 2027-02-26. transcribe needs :transcription, which has_capability reports for any endpoint declaring :audio; speak needs :speech (OpenAI, through a Realtime session, and GEMINIServiceEndpoint, through Gemini TTS), and translate needs :realtime.']],["Provider Contracts","Provider-Contracts",[]],["Provider Capabilities","Provider-Capabilities",["Each endpoint declares supported features. Request functions validate before dispatch, so an unsupported feature is an ArgumentError naming the endpoint and what it does support, not an HTTP 404.","Capabilities by Provider","Validation comes in two strengths, and the difference matters if you write your own endpoint:","Either way you never need to check capabilities manually before a request."]],["Request Configuration & Timeouts","Request-Configuration-and-Timeouts",["Every network operation is bounded. One struct carries all knobs — all time fields are seconds, Inf disables that bound:","Which verbs retry","max_attempts applies to the inference verbs only: chatrequest!, embeddingrequest!, respond, fim_complete, prefix_complete, generate_image, edit_image, transcribe, ask, ask_each (per request), list_models, and the tool_loop family (streams retry only before the first callback fires). Platform and lifecycle verbs — batch, container, conversation, file (upload_file included: a create is never retried), fine-tuning, moderation, upload, vector-store, speech and translation (speak, translate), realtime, and the Responses lifecycle operations — make a single bounded attempt, and max_attempts has no effect on them. A 429 that no retry can serve — spent credit, a reached spend or usage limit, insufficient_quota, Gemini Interactions' daily quota_exceeded (the codes under chatrequest!) — is never retried. poll_batch / poll_file_batch poll through retryable statuses (such a 429 ends the poll with its failure) and per-attempt timeouts until their own wall-clock timeout (interval and timeout must be > 0); a poll that times out returns the family's call error with cause = UniLMTimeout(:deadline, …) and the last object seen in last_observed. Both take cancel.","Cancellation","HTTP verbs take cancel::Union{Nothing,CancelToken}=nothing (chatrequest!, respond, embeddingrequest!, generate_image, edit_image, fim_complete, prefix_complete, ask, ask_each, list_models, poll_batch, poll_file_batch, the tool loops, nl_dispatch, nl_classify, @branch); nothing resolves the ambient token, and every other HTTP verb observes the ambient token. A cancelled call returns its call-error result with status = nothing and cause = UniLMCancelled(source, elapsed) (source is :token, or :callback for a stream stopped with close[] = true), is never retried, commits nothing — unless the provider's completion marker already arrived on a stream: then the turn is committed, the final-message callback runs, and usage may be missing (a Chat stream's marker is the chunk carrying the finish reason, before the usage chunk and [DONE] on the OpenAI wire; a Responses stream's is its terminal event, whose response carries its usage). A pre-cancelled token sends nothing. Limits: a TCP connect / TLS handshake in progress is not interrupted (it completes or hits connect_timeout), a running callback finishes first, and a realtime_connect session and MCP stdio exchanges do not observe the token (speak and translate, which run Realtime sessions of their own, do). See Concurrency, Tasks and Cancellation.","Sharp edges","Concurrency"]],["Result Type Hierarchy","Result-Type-Hierarchy",["All 71 API call result types inherit from LLMRequestResponse, in 18 per-API families:","Every *Success wraps a parsed response object, every *Failure carries the HTTP status and body (every family but Embeddings and Realtime also the request_id; an AudioFailure a Realtime session reported has status = nothing and the event's JSON as response), and every *CallError carries the rendered error and, in cause, the exception behind it when there is one (a UniLMTimeout for a timeout, a UniLMCancelled for a cancellation). Fields of the five primary families:","request_id carries the provider's request id for support escalation — the x-request-id header, else request-id (Anthropic). It exists on the Chat / Responses / FIM / image failure and call-error types above, on the System One results and on every platform *Failure; the embedding limbs do not carry it.","sse_dropped (default 0) counts the undecodable SSE data: payloads dropped while assembling that streamed turn. It is 0 for a non-streamed call and for a clean stream; anything higher means the result was built from an incomplete wire — see Streaming.","Credentials never reach a result value. API keys and request bodies are redacted from the error strings these types carry, and a *CallError's cause is named by type rather than dumped when the result is displayed.","Standard pattern-matching idiom:"]],["API Constants","API-Constants",["Not exported and not public: qualify them (UniLM.OPENAI_BASE_URL), and expect them to change. Where each provider's requests go is in the Setup section of its entry."]],["Exceptions","Exceptions",["Thrown by push! (a non-system message onto an empty Chat, or a same-role repeat other than tool), by pop! on an empty Chat, and by chatrequest! before any request when history=true and the conversation ends with an assistant message. issendvalid never throws — it returns a Bool.","Thrown by the result accessors text, output_text, embedding_vectors, image_data and fim_text when the result is not a success. showerror prints only the status and a trimmed (≤200-char) excerpt of the response body or error message — never the conversation, endpoint, or API key.","Raised when a RequestConfig bound is exceeded. Value-returning surfaces (chat, embeddings, responses, images, FIM, System One, platform verbs) deliver UniLMTimeout — and a cancellation's UniLMCancelled — inside their call-error results; the MCP surface throws MCPTimeoutError (and UniLMCancelled for a cancelled HTTP call). A stdio MCP server that exits or whose pipe breaks throws MCPCrashError instead (the session closes with cause :crash), and a call on a closed session throws MCPSessionClosedError."]],["Public Extension API (not exported)","Public-Extension-API-(not-exported)",["Declared public, not exported (19 names) — qualify them (UniLM.get_url). These are the functions a new backend adds methods to and the stream-state types its handlers mutate (Write your own backend): get_url, auth_header, default_model, encode_request, decode_response, handle_sse_event!, StreamState, encode_agentic, decode_agentic, decode_agentic_stream, AgenticStreamState; and the System One protocol seam: SystemOneProtocol, TypeSafeProtocol, OpenAIDecisionsProtocol, OllamaSystemOneProtocol, system_one_protocol, encode_system_one, decode_system_one, SystemOneWire."]],["Complete Exports List","Complete-Exports-List",["Every exported symbol (402), grouped by area:","Chat Completions: Chat, Message, ProviderContent, Attachment, ImageAttachment, AudioAttachment, DocumentAttachment, AudioOutput, RoleSystem, RoleUser, RoleAssistant, Tool, ToolCall, FunctionSignature, FunctionCallResult, ResponseFormat, InvalidConversationError, issendvalid, chatrequest!, update!, fork","Responses API & Agentic: Respond, InputMessage, ResponseObject, ResponseSuccess, ResponseFailure, ResponseCallError, Reasoning, PromptCacheOptions, ModerationConfig, TextConfig, TextFormatSpec, respond, get_response, delete_response, cancel_response, list_input_items, compact_response, count_input_tokens, text_format, json_schema_format, json_object_format","Image Generation & Edits: ImageGeneration, ImageEdit, ImageObject, ImageResponse, ImageSuccess, ImageFailure, ImageCallError, generate_image, edit_image, image_data, save_image","Embeddings: Embeddings, EmbeddingInput, embeddingrequest!, embedding_vectors, EmbeddingSuccess, EmbeddingFailure, EmbeddingCallError","Cost Tracking: TokenUsage, token_usage, estimated_cost, cumulative_cost, DEFAULT_PRICING","Service Endpoints: ServiceEndpoint, OpenAIWireEndpoint, ServiceEndpointSpec, OPENAIServiceEndpoint, AZUREServiceEndpoint, GEMINIServiceEndpoint, GEMINIOpenAIServiceEndpoint, ANTHROPICServiceEndpoint, GenericOpenAIEndpoint, OllamaEndpoint, OllamaOptions, MistralEndpoint, DeepSeekEndpoint, add_azure_deploy_name!","Provider model listings: ProviderModel, ModelListSuccess, ModelListFailure, ModelListCallError (and list_models with service=OPENAIServiceEndpoint, ANTHROPICServiceEndpoint or GEMINIServiceEndpoint)","Ollama model management: OllamaModel, OllamaModelInfo, OllamaRunningModel, OllamaPullProgress, OllamaSuccess, OllamaFailure, OllamaCallError, model_info, pull_model, running_models, load_model, unload_model, delete_model (and list_models with service=OllamaEndpoint())","Provider Capabilities: provider_capabilities, has_capability","Tool Loop: CallableTool, ToolCallOutcome, ToolLoopResult, tool_loop!, tool_loop, to_tool","Forking: fork","MCP Client: MCPSession, MCPToolInfo, MCPToolResult, MCPResourceInfo, MCPPromptInfo, MCPServerCapabilities, MCPTransport, StdioTransport, HTTPTransport, MCPError, MCPCrashError, MCPSessionClosedError, mcp_connect, mcp_disconnect!, mcp_tools, mcp_tools_respond, list_tools!, list_resources!, list_prompts!, call_tool, read_resource, get_prompt, ping","MCP Server: MCPServer, MCPServerTool, MCPServerResource, MCPServerResourceTemplate, MCPServerPrompt, MCPServerPrimitive, register_tool!, register_resource!, register_resource_template!, register_prompt!, serve, @mcp_tool, @mcp_resource, @mcp_prompt","FIM / Completions: FIMCompletion, FIMChoice, FIMResponse, FIMSuccess, FIMFailure, FIMCallError, fim_complete, fim_text, prefix_complete","Files: FileUpload, FileObject, FileList, FileSuccess, FileListSuccess, FileContentSuccess, FileDeleteSuccess, FileFailure, FileCallError, upload_file, list_files, retrieve_file, delete_file, file_content, save_file_content","Vector Stores: VectorStoreObject, VectorStoreFileObject, VectorStoreFileBatch, VectorStoreList, VectorStoreSuccess, VectorStoreListSuccess, VectorStoreFileSuccess, VectorStoreBatchSuccess, VectorStoreDeleteSuccess, VectorStoreFailure, VectorStoreCallError, create_vector_store, retrieve_vector_store, list_vector_stores, delete_vector_store, add_vector_store_file, create_file_batch, retrieve_file_batch, poll_file_batch, vector_store_id","Conversations: ConversationObject, ConversationItem, ConversationItemList, ConversationSuccess, ConversationItemSuccess, ConversationItemListSuccess, ConversationDeleteSuccess, ConversationFailure, ConversationCallError, create_conversation, retrieve_conversation, update_conversation, delete_conversation, add_conversation_items, list_conversation_items, retrieve_conversation_item, delete_conversation_item, conversation_id","Moderations: ModerationResponse, ModerationResult, ModerationSuccess, ModerationFailure, ModerationCallError, moderate, is_flagged","System One (TypeSafe's Jev and other backends): TYPESAFEServiceEndpoint, SystemOneQuestion, ChoiceQuestion, ScoreQuestion, NoulQuestion, NoulCriteria, BoxQuestion, RawQuestion, choice, score, noul, box, SystemOneRequest, ask, ask_each, with_system_one, SystemOneAnswer, ChoiceAnswer, ScoreAnswer, NoulAnswer, BoxCoordinates, BoxAnswer, RefusalAnswer, UnknownAnswer, SystemOneResponse, SystemOneSuccess, SystemOneFailure, SystemOneCallError, SystemOneError, answers, answer, TypeSafeModelCard, TypeSafeModelsSuccess, list_models","Audio: SpeechRequest, TranscriptionRequest, SpeechSuccess, TranscriptionSuccess, AudioFailure, AudioCallError, speak, save_audio, transcribe, translate, transcript_text","Batch: BatchObject, BatchList, BatchSuccess, BatchListSuccess, BatchFailure, BatchCallError, create_batch, retrieve_batch, cancel_batch, list_batches, poll_batch","Fine-tuning: FineTuningJob, FineTuningList, FineTuningSuccess, FineTuningListSuccess, FineTuningFailure, FineTuningCallError, create_fine_tuning_job, retrieve_fine_tuning_job, cancel_fine_tuning_job, list_fine_tuning_jobs, list_fine_tuning_events, list_fine_tuning_checkpoints","Containers: ContainerObject, ContainerList, ContainerSuccess, ContainerListSuccess, ContainerDeleteSuccess, ContainerFailure, ContainerCallError, create_container, retrieve_container, list_containers, delete_container, add_container_file","Uploads: UploadObject, UploadPartObject, UploadSuccess, UploadPartSuccess, UploadFailure, UploadCallError, create_upload, add_upload_part, complete_upload, cancel_upload","Webhooks: WebhookEvent, WEBHOOK_EVENTS, verify_webhook, parse_webhook","Realtime: RealtimeSession, RealtimeSecretSuccess, RealtimeFailure, RealtimeCallError, mint_realtime_secret, realtime_connect, realtime_send, realtime_receive, realtime_event, session_update, input_audio_append, response_create","Result Types (base): LLMRequestResponse, LLMSuccess, LLMFailure, LLMCallError, LLMResultError, issuccess, isfailure, text, reasoning_text","Request Config, Timeouts & Cancellation: RequestConfig, current_config, with_request_config, set_default_config!, UniLMTimeout, MCPTimeoutError, UniLMCancelled, CancelToken, cancel!, iscancelled, with_cancel"]]]},{url:"/providers/",sections:[["Language models",null,["A language model reads a conversation — text, and on the providers that take them images, sound clips and PDF documents — and writes the next turn: an answer, a call of one of your functions, or JSON that fits a schema. Use one when the output is text a person reads, or work the model does through your tools; when the outcome is one of a set you can name and your code acts on it, a decision model answers with a probability for each option (Decisions)."]],["Choose your provider","llm_providers",[]],["Concepts","llm_concepts",[]],["Across providers","llm_across",[]]]},{url:"/stability/",sections:[["Versioning & Stability",null,["UniLM follows Semantic Versioning, with the pre-1.0 conventions below. The aim is that the version number alone tells you whether an upgrade can break your code."]],["What 0.x means here","What-0.x-means-here",["UniLM is pre-1.0 and under active development. While on 0.x:","Pin accordingly: allowing patch upgrades is always safe; allowing minor upgrades means reading the CHANGELOG's Breaking section first."]],["Breaking changes are batched","Breaking-changes-are-batched",["Breaking changes are grouped into infrequent minor releases rather than dribbled across many small ones. When one lands, related changes tend to land with it, so you migrate once per minor instead of repeatedly."]],["Renames keep their old names","Renames-keep-their-old-names",["When an exported name changes, the old name keeps working as an alias for at least until 1.0. A rename is a deprecation path, not a same-day hard break."]],["Toward 1.0","Toward-1.0",["There is no date. 1.0 is defined by contract, not calendar — it ships when these hold:"]],["The CHANGELOG is authoritative","The-CHANGELOG-is-authoritative",["The CHANGELOG is the authoritative migration record. If a release breaks something, the exact change and how to migrate are documented there under that version's Breaking heading."]]]},{url:"/api/accounting/",sections:[["Cost Tracking & Token Usage",null,["Token accounting works across providers — Gemini and Anthropic usage is normalized to the shared shape at decode time, so these accessors and the pricing table apply uniformly to Chat, Responses, and the agentic verb.","For a worked walkthrough — reading usage, the silent-\\$0 footgun on unpriced models, custom pricing, and per-Chat cumulative totals — see the Cost Tracking guide."]],["Token Usage","Token-Usage",[]],["UniLM.TokenUsage","UniLM.TokenUsage",["Token usage statistics returned by the API, in one shape for every provider.",'prompt_tokens counts every input token, cache reads and cache writes included. Of them, cached_tokens were read from the prompt cache and cache_write_tokens written to it; cache_write_extended_tokens is the part of cache_write_tokens written at the extended retention (OpenAI "12h", Anthropic "1h"). reasoning_tokens is the part of completion_tokens spent on hidden reasoning. prompt_audio_tokens is the part of prompt_tokens that is audio input and completion_audio_tokens the part of completion_tokens that is audio output, as OpenAI Chat Completions reports them for a model that hears or speaks; prompt_audio_tokens also counts Gemini\'s audio input on the native endpoint and Gemini Interactions. cached_audio_tokens is the part of cached_tokens that is audio, as Gemini reports it on the native endpoint (cacheTokensDetails) and Gemini Interactions (cached_tokens_by_modality); no other provider reports it. The counts are 0 when the provider omits them, as GEMINIOpenAIServiceEndpoint does: its audio input is in prompt_tokens alone. service_tier is the tier the provider reports billing the call at (OpenAI\'s service_tier, for example) and inference_geo the inference region it reports; each is nothing when the provider reports none. One exception: on GEMINIOpenAIServiceEndpoint, whose replies name no billed tier, a Chat result\'s service_tier is the tier the request asked for, so "flex" is priced at the Flex rates and "priority" at the Priority rates — an upper bound, since Google bills a downgraded Priority request at Standard and this endpoint does not report the downgrade.',"estimated_cost bills cached_tokens at the discounted cached-input rate and the rest at the standard rates, unless the provider's own pricing applies (see DEFAULT_PRICING): OpenAI bills the audio tokens at the model's audio-token rates and Gemini audio input, and the audio it reads from the cache, at the rates its pricing page states for the model; any other audio leaves the estimate at 0.0. Audio a provider does not count apart (GEMINIOpenAIServiceEndpoint's) is priced with the text in prompt_tokens. Positionally the fields go in the order listed, the five counts first; the fields left out take their defaults."]],["UniLM.token_usage","UniLM.token_usage",["Extract token usage from a token-billed API result (chat, Responses, embeddings, image generation and FIM completions); failures of those APIs report zero usage.","Results from APIs that do not report token usage at all — audio, files, batches, moderations, vector stores, … — throw an ArgumentError. A zero would be indistinguishable from a genuinely free call and would quietly under-count spend."]],["Cost Estimation","Cost-Estimation",[]],["UniLM.estimated_cost","UniLM.estimated_cost",["Estimate the cost in USD of a single API call from the token usage its result carries.","The model priced is model when given; else the one the provider reports having served — result.model of a Chat result (LLMSuccess), result.response.model of a Responses or FIM result; else the one requested — result.self.model for Chat, result.embeddings.model for Embeddings.","Returns 0.0 for failures, which carry no billable usage, for an unpriced model, for audio tokens UniLM has no rate for (see DEFAULT_PRICING for the audio it prices) and for an embeddings reply that reported no usage (Gemini's OpenAI-compatible endpoint reports none); the last three also log a warning, once per model id (for audio, per model and endpoint). A local model — one an OllamaEndpoint serves from a server of your own, its name carrying no cloud tag — bills no one: unless model is given, it costs 0.0, without the warning, unless pricing holds a row you gave its exact name. The rows UniLM ships price hosted models, never a local model that bears one's name (Ollama's ollama cp llama3.2 gpt-3.5-turbo), in DEFAULT_PRICING or copied into a table such as merge(DEFAULT_PRICING, …); a row equal to a shipped one counts as the shipped one. A billed service tier the provider's pricing page lists no price for is estimated at the standard rates, with one warning per model and tier. Throws ArgumentError for result types outside the token-billed APIs — see token_usage — and, unless model is given, for an ImageSuccess: the Images API bills image tokens at rates a price row does not model, and a price this function cannot compute is not a zero it can report. pricing is any AbstractDict{String,PriceRow}.","Model lookup: the exact id first, then the id without a dated snapshot suffix (gpt-5.4-mini-2026-03-17 → gpt-5.4-mini, claude-opus-4-5-20251101 → claude-opus-4-5). A versioned Jev id with no row of its own (jev-X.Y.Z, e.g. a release newer than this table) is priced at the jev-latest row. That is an assumption: TypeSafe's Models page lists Jev 1.14 and Jev 1.13 at one price, USD 42 per billion input tokens (2026-10-25); a later version is assumed to keep it until the page says otherwise. The same lookup prices SystemOneSuccess results.","The row's rates bill fresh input tokens and cache writes at input, cache reads at cached_input and completion tokens at output, except where UniLM models a provider's surcharges, which apply to that provider's results (see DEFAULT_PRICING).","Estimate the USD cost of one System One evaluation from its token usage and the price row of the model that answered (result.response.model), unless model overrides it. TypeSafe bills input tokens only — output tokens are currently free, which the shipped jev-* price rows encode as an output rate of 0.0. An id with a dated snapshot suffix uses its base id's row; a versioned jev-X.Y.Z id without its own row is priced at the jev-latest row (assuming a later Jev keeps the price TypeSafe's Models page lists for Jev 1.14 and Jev 1.13); any other unpriced name returns 0.0. An answer from a local model through an OllamaEndpoint costs 0.0, without a missing-price warning, unless pricing holds a row you gave the model's exact name (a row UniLM ships for a hosted model of that name does not count) or model is passed; a cloud model reached through it (a tag of cloud or ending in -cloud) is priced by the name requested, which an answer whose reply drops the tag keeps. A backend that bills otherwise is priced its own way: an answer from OpenAI's Decisions API (OpenAIDecisionsProtocol) costs its input tokens alone, and no output: the uncached ones at the row's input rate, cache reads at its cached-input rate, and cache writes and more than 272K input tokens at the surcharges OpenAI lists for the model (gpt-6-luna: a write at 1.25 times the input rate, 2.5 times for a 12-hour lifetime, and every rate twice above 272K)."]],["UniLM.cumulative_cost","UniLM.cumulative_cost",["Return the estimated cost, in USD, that chatrequest! and prefix_complete calls on this Chat have accrued, priced with DEFAULT_PRICING as estimated_cost prices a result: a local model's turns add 0.0 unless you added a row for its exact name to the table (a row UniLM ships for a hosted model of that name does not count). A committed turn adds its result's cost. A call that ends without committing one adds what its provider reported billing it, a lower bound: the replies of a continued Gemini turn received before the failure or stop, and the usage a stream had reported when it was stopped, cancelled, timed out, cut off or ended by an exception from its callback or on_tool_call — Anthropic reports a request's input when its stream starts and Gemini the usage so far on every chunk, while OpenAI reports it after the finish reason. A request stopped before any usage arrived adds nothing, though the provider bills it, as do an attempt that was retried, a stream the provider ended with an error event, and an unstreamed reply UniLM could not decode."]],["UniLM.DEFAULT_PRICING","UniLM.DEFAULT_PRICING",["Default per-token pricing; OpenAI, Anthropic and Gemini rows verified on 2026-10-22 (OpenAI's gpt-5-search-api on 2026-10-25, gpt-5.2-pro on 2026-10-26), TypeSafe rows on 2026-10-25, DeepSeek rows on 2026-09-24 (prices drift — re-verify before relying on them). Cached input is billed at the discounted cached_input rate; reasoning tokens are already counted within output tokens. The rows are standard short-context text rates. Where UniLM models a provider's surcharges — cache-write premiums, long-context tiers, service-tier, speed or region multipliers — estimated_cost applies them to these rates for that provider's results; every other result is billed at the standard rates. A billed service tier the provider's pricing page lists no price for — such as OpenAI's Scale tier, Fast on gpt-5.4-pro or on a gpt-5.5 prompt over 272K tokens — is estimated at the standard rates, with one warning per model and tier.","A row has no audio-token rates. estimated_cost bills the audio tokens (prompt_audio_tokens, completion_audio_tokens) of an OPENAIServiceEndpoint result at the model's audio-token rates, which UniLM has for gpt-audio-1.5, and the audio input of a native Gemini or Interactions result at the input price Google's pricing page states for audio, scaled by the billed tier and a long prompt's multiples as text is: the model's own audio price where the page lists one apart (gemini-3.1-flash-lite, gemini-3-flash-preview, gemini-2.5-flash, gemini-2.5-flash-lite), else the row's input rate, since the page spells modalities out wherever their rates differ and an input price that names none is every modality's. A cache hit bills at the row's cached rate, since a one-price model's cache price names no modality either, except the audio a usage reports among its cached tokens (cached_audio_tokens) on those four models, which bills at the cached-audio price their tables list apart. Any other audio — on a model the page prices without audio (the image models) or does not list, on another endpoint, Gemini audio output, or a cache hit on one of those four models whose usage reports more cached tokens than text tokens and cached audio together, so that its split is unknown — leaves the estimate at 0.0, with one warning per model and endpoint. GEMINIOpenAIServiceEndpoint reports no audio count, so its audio input is priced at the text rate, a lower bound where the model's audio price is its own; such a request warns once per model. Off-peak discounts, other multimodal rates and hosted-tool fees are not included.","A lock-guarded AbstractDict{String,PriceRow}: add or replace rows with DEFAULT_PRICING[model] = row from any task while requests are running."]]]},{url:"/api/audio/",sections:[["Audio API",null,["Synthesize speech from text, transcribe audio to text, and translate speech into another language. speak runs on OpenAI's Realtime API or on Gemini TTS and returns 24 kHz, 16-bit mono audio, as a WAV file or as raw PCM. transcribe uploads an audio file to OpenAI and, with a local model that hears audio, to Ollama (Audio). translate streams a WAV file through an OpenAI Realtime translation session and returns the translated text."]],["Request Types","Request-Types",[]],["UniLM.SpeechRequest","UniLM.SpeechRequest",["A text-to-speech request; pass it to speak. input is the text to read aloud. model and voice left nothing are the service's defaults:",'Both services produce 16-bit mono PCM at 24 kHz: response_format "wav" returns it as a WAV file, "pcm" as the raw samples. instructions direct the delivery (tone, pace, accent): on OpenAI they follow the session\'s instruction to read input word for word, on Gemini they are the text\'s speech style (speechMetadata.style). Gemini TTS has no speed parameter: describe the pace in instructions ("speaking slowly").','Throws ArgumentError, before any request, for an empty input, a voice the Realtime session does not have or a blank Gemini voice, a response_format other than "wav" or "pcm", a speed out of range, and any speed on Gemini; and for GEMINIOpenAIServiceEndpoint, which has no speech route, naming GEMINIServiceEndpoint. The Extended Voice Library\'s names are listed only by Gemini\'s GET /v1beta/voices, so a Gemini voice is sent as given, and Gemini answers a name it does not have. Voices: OpenAI Realtime, Gemini TTS.']],["UniLM.TranscriptionRequest","UniLM.TranscriptionRequest",["An audio transcription request. file is a path on disk. model left nothing is the service's default: gpt-transcribe for OpenAI; Ollama has none, so a request to it names an installed model that hears audio (e.g. model=\"gemma4:e4b\") or throws ArgumentError before any request, and so does a GenericOpenAIEndpoint, whose request names the model its server serves. Optional languages, keywords, prompt, response_format, and temperature refine decoding. For gpt-transcribe, a legacy singular language is translated to languages. Other models retain their singular language field. Never set both forms. response_format is one of json, text, srt, verbose_json, vtt, diarized_json, and temperature lies in 0 … 1; anything else is an ArgumentError. On OpenAI, srt, vtt and verbose_json (subtitles and timestamps) are documented only for whisper-1, and diarized_json (speaker labels) only for gpt-4o-transcribe-diarize: deprecated models that shut down on February 26, 2027 (speech to text). Ollama's /v1/audio/transcriptions reads one language and the prompt, transcribes at temperature 0, and is asked for JSON only, the one form in which it reports a failure that arrives after its reply has begun (as text that failure reads as an empty transcript): a request to it that sets temperature, languages, keywords, or a response_format other than json throws ArgumentError before any request; read the text with transcript_text. Pass to transcribe."]],["Result Types","Result-Types",[]],["UniLM.SpeechSuccess","UniLM.SpeechSuccess",['Successful speak result: audio holds a WAV file (content_type "audio/wav") or the raw 16-bit little-endian mono samples at 24 kHz ("audio/pcm"). Save it with save_audio.']],["UniLM.TranscriptionSuccess","UniLM.TranscriptionSuccess",["Successful transcribe/translate result; text holds the transcript or translation (via transcript_text), raw the parsed JSON a transcription reply carried (nothing for a translation)."]],["UniLM.AudioFailure","UniLM.AudioFailure",["Audio error result: the HTTP status (nothing when a Realtime session reported the failure as an event, which carries no HTTP status), the raw response (the reply body, the Realtime event's JSON, or for a refused WebSocket upgrade HTTP.jl's report of its status) and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.AudioCallError","UniLM.AudioCallError",["Audio call that produced no usable reply (transport failure, timeout, cancel, a session that closed before its result, or a reply that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout, a UniLMCancelled for a cancel, and, when the server closed a Realtime session, the HTTP.WebSockets.WebSocketError that carries its status and reason, which error names too."]],["Functions","Functions",[]],["UniLM.speak","UniLM.speak",["Synthesize speech from text; the keywords build a SpeechRequest.","On OPENAIServiceEndpoint the speech comes from a Realtime API session (wss://api.openai.com/v1/realtime, gpt-realtime-2.1-mini unless model names another), the replacement OpenAI names for its retiring text-to-speech models (text to speech): UniLM sets the voice, 24 kHz PCM output and instructions to read the text word for word, adds the text as a user message, asks for a response and collects its audio. Realtime models are conversational, and OpenAI notes that instructions are not guaranteed to be followed. On GEMINIServiceEndpoint it comes from Gemini TTS (generateContent on gemini-3.8-flash-tts unless model names another, speech generation), which reads the text verbatim.",'Returns SpeechSuccess: a WAV file (response_format = "wav") or the raw samples ("pcm"). A failure the provider reports is an AudioFailure: an HTTP error status, a WebSocket upgrade the server refuses included (a bad key is a 401; response is then HTTP.jl\'s report of the status, since it does not keep the reply); a Gemini reply whose candidate did not finish (a finishReason other than STOP, such as MAX_TOKENS or SAFETY) or that has no candidate (a blocked prompt, its reason in promptFeedback), with status 200 and the reply as response; or on a Realtime session the error event, read even when the server closes the session while UniLM is still sending, or a response.done that did not complete (status is then nothing and response the event\'s JSON). A session that closes before its response is done (error names the close\'s status and reason, and cause is the close), a timeout, a cancel and a reply without usable audio are an AudioCallError. Audio received before a failure is never returned.',"Pass config::Union{Nothing,RequestConfig} to bound the call (a single attempt; max_attempts does not apply). On OpenAI, total_deadline bounds the whole call whatever the socket does, connect_timeout the WebSocket open, and stream_idle_timeout every send and every wait for the next event; on Gemini it bounds the one HTTP request. Both observe the ambient CancelToken (with_cancel): a token already cancelled sends nothing, and a cancel ends the call at once, with an AudioCallError whose cause is a UniLMCancelled. Speech is not priced: token_usage and estimated_cost throw for a SpeechSuccess."]],["UniLM.transcribe","UniLM.transcribe",["Transcribe audio to text in the source language. Returns TranscriptionSuccess (.text, via transcript_text), AudioFailure, or AudioCallError. model left nothing is the service's default (gpt-transcribe on OpenAI).","On Ollama, an installed model that hears audio transcribes through Ollama's OpenAI-compatible /v1/audio/transcriptions route. There is no default model, and what that route cannot carry — temperature, languages, keywords, a response_format other than json (text included: a failure after the reply has begun would read as an empty transcript) — throws ArgumentError before any request:","A GenericOpenAIEndpoint sends the request to its server's /v1/audio/transcriptions with every field it sets, as given — vLLM serves OpenAI's Transcriptions API there — and has no default model either.","Transient statuses (408/429/500/502–504/520–524/529) and transport failures are retried with backoff and jitter under the resolved RequestConfig (max_attempts, total_deadline; retry-after-ms, else Retry-After, honored), as chatrequest! retries them, and each attempt sends the whole file again; a 429 that no retry can serve is returned at once. Pass config::Union{Nothing,RequestConfig} to override the timeout and retry budget for this call."]],["UniLM.translate","UniLM.translate",["Translate the speech in the WAV file at path into language and return the translation as text: a TranscriptionSuccess, read with transcript_text.",'The audio goes to an OpenAI Realtime translation session (wss://api.openai.com/v1/realtime/translations, Realtime translation): UniLM sets the target language (the session\'s audio.output.language, such as "fr" or "es"; English unless named), streams the audio in 200 ms frames, closes the session and joins the translated transcript. The session also returns translated speech, which translate does not keep. Speech already in the target language can come back as empty text: an English clip translated into English did. A short clip\'s translation also varies from call to call: of ten translations into English of a two-second French sentence made with speak, one came back empty and six named words the sentence does not have (October 2026).',"path must be a 16-bit PCM WAV file, at any sample rate and channel count: a translation session takes 24 kHz mono PCM16 only, so UniLM mixes the channels down and resamples by linear interpolation (speech-grade: there is no anti-aliasing filter). Any other file throws ArgumentError before any I/O, naming the conversion; so do an empty file, a blank language and a service without OpenAI's Realtime API.","A failure the provider reports is an AudioFailure: a Realtime error event, for example for a language it does not translate into (status = nothing, the event's JSON as response), read even when the server closes the session during the upload, or a WebSocket upgrade the server refuses (a bad key is a 401). A session that closes before session.closed (error names the close's status and reason), a timeout and a cancel are an AudioCallError. config::Union{Nothing,RequestConfig} bounds the call as for speak: total_deadline the whole call whatever the socket does, connect_timeout the open, stream_idle_timeout every send and every wait for the next event; a single attempt. The ambient CancelToken (with_cancel) is observed: a token already cancelled sends nothing, and a cancel ends the call at once, with an AudioCallError whose cause is a UniLMCancelled."]],["Accessors","Accessors",[]],["UniLM.transcript_text","UniLM.transcript_text",["The transcript text from a transcribe or translate result."]],["UniLM.save_audio","UniLM.save_audio",["Write the synthesized audio bytes to path, atomically: the bytes go to a temporary file in the same directory, which is then renamed over path, so a failed write leaves any existing file intact. An existing file keeps its permission bits. A symlink is written through — a dangling one creates its target; a directory throws ArgumentError."]],["Usage","Usage",[]],["Speech","Speech",['Both services produce 16-bit mono PCM at 24 kHz: response_format = "wav" (the default) wraps it in a 44-byte WAV header, "pcm" returns the samples (content_type "audio/pcm"). Any other format, a voice the Realtime session does not have (nova, onyx and fable are not Realtime voices), a blank Gemini voice, a speed out of range, any speed on Gemini, and an empty input throw ArgumentError before any request, as does GEMINIOpenAIServiceEndpoint: Google\'s OpenAI-compatible API has no speech route, so the error points to GEMINIServiceEndpoint.',"On OpenAI, speak opens a Realtime WebSocket session, sets the voice, PCM output and instructions to read the text word for word, adds the text as a user message and collects the response's audio. Realtime models are conversational, and OpenAI notes that a model is not guaranteed to follow its instructions. instructions add delivery directions (tone, pace, accent) after UniLM's own. OpenAI's tts-1, tts-1-hd and gpt-4o-mini-tts shut down on January 6, 2027, and gpt-realtime-2.1-mini on the Realtime API is the replacement OpenAI names (text to speech, Realtime voices).",'On Gemini, speak sends one generateContent request with responseModalities ["AUDIO"], the voice in speechConfig and 24 kHz L16 output requested. Gemini 3.8 TTS reads the text verbatim; instructions become the text\'s speech style, which is also where the pace goes ("speaking slowly"): Gemini TTS has no speed parameter (speech generation).',"An error the provider reports is an AudioFailure: an HTTP error status (a WebSocket upgrade the server refuses included: a bad key is a 401), a Gemini reply whose candidate did not finish (a finishReason other than STOP, such as MAX_TOKENS or SAFETY) or that has no candidate (a blocked prompt), with status 200 and the reply as response, or, on a Realtime session, the error event or a response.done that did not complete, with status = nothing and the event's JSON as response. An error event the server sends before it closes the session is that failure even when the close interrupts UniLM's sending. A session that closes before its response is done (its close status and reason in error, the close itself in cause), a timeout, a cancel and a reply without usable audio are an AudioCallError. Audio received before a failure is never returned. On OpenAI, total_deadline bounds the whole call whatever the socket does, connect_timeout the WebSocket open, and stream_idle_timeout every send and every wait for the next event. Both services observe the ambient CancelToken: a token already cancelled sends nothing, and a cancel ends the call at once, with an AudioCallError whose cause is a UniLMCancelled. Speech is not priced: token_usage and estimated_cost throw for a SpeechSuccess."]],["Translation","Translation",['translate(path; language="en", model="gpt-realtime-translate") opens a Realtime translation session (wss://api.openai.com/v1/realtime/translations), sets the target language (audio.output.language), streams the audio in 200 ms frames, closes the session and joins the translated transcript into the text of a TranscriptionSuccess. The session also returns translated speech, which translate does not keep. Speech already in the target language can come back as empty text: an English clip translated into English did. A short clip\'s translation also varies from call to call: of ten translations into English of a two-second French sentence made with speak, one came back empty and six named words the sentence does not have (October 2026). A translation session takes 24 kHz mono 16-bit PCM only, so path must be a 16-bit PCM WAV file, at any sample rate and channel count: UniLM mixes the channels down and resamples by linear interpolation, which suits speech (there is no anti-aliasing filter). Any other file throws ArgumentError before any I/O, naming the conversion; convert it first, for example with ffmpeg -i in.m4a -c:a pcm_s16le out.wav. A language the session does not translate into is an AudioFailure carrying the provider\'s error event; the bounds and the cancellation are those of speech on OpenAI. Translation replaces OpenAI\'s file-upload translation endpoint, which shuts down on February 26, 2027 (Realtime translation).']],["Transcription","Transcription",["Transcription takes the service's default model when model is left nothing: gpt-transcribe on OpenAI. Its languages and keywords options are vectors of strings sent as repeated multipart fields. A singular language is translated to a one-element languages list for this model; older models keep their singular field. Setting both forms raises ArgumentError.",'Ollama has no default: name a model that hears audio, such as gemma4:e4b. Its /v1/audio/transcriptions transcribes at temperature 0 and reads one language and a prompt, and UniLM asks it for JSON only, the one form in which Ollama reports a failure that arrives after its reply has begun, as an AudioCallError (by Ollama 0.40.6\'s source; untested here). response_format = "text" throws ArgumentError before the request — such a failure would read as an empty transcript — and so do temperature, languages, keywords and any other format: leave response_format unset and read the text with transcript_text. Ollama labels its replies application/x-ndjson, so they are read as JSON whatever the label. An endpoint declares transcription with the capability :transcription, which :audio implies.',"OpenAI deprecated gpt-4o-transcribe, gpt-4o-mini-transcribe, gpt-4o-transcribe-diarize, and whisper-1 on August 26, 2026, with shutdown scheduled for February 26, 2027. The srt, vtt and verbose_json formats (subtitles and timestamps) are documented only for whisper-1, and diarized_json (speaker labels) only for gpt-4o-transcribe-diarize. OpenAI transcription guide, deprecation schedule."]]]},{url:"/api/batch/",sections:[["Batch API",null,['Create, retrieve, cancel, and list async bulk jobs, and poll them to completion. The Batch API processes large request sets asynchronously at roughly half the cost: the input is a JSONL file uploaded via the Files API with purpose="batch", and output is fetched with file_content using batch.output_file_id. OpenAI only.']],["Parsed Objects","Parsed-Objects",[]],["UniLM.BatchObject","UniLM.BatchObject",["A batch job from the Batch API: id, status, endpoint, input_file_id, output_file_id, error_file_id, and request_counts; raw holds the unparsed JSON response."]],["UniLM.BatchList","UniLM.BatchList",["A page of BatchObjects from list_batches; has_more signals that further pages are available."]],["Result Types","Result-Types",[]],["UniLM.BatchSuccess","UniLM.BatchSuccess",["Successful create/retrieve/cancel result wrapping a BatchObject."]],["UniLM.BatchListSuccess","UniLM.BatchListSuccess",["Successful list_batches result wrapping a BatchList."]],["UniLM.BatchFailure","UniLM.BatchFailure",["Batch API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.BatchCallError","UniLM.BatchCallError",["Batch API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout. last_observed is set only when poll_batch runs out of time or is cancelled: the last BatchObject it saw, if any."]],["Request Functions","Request-Functions",[]],["UniLM.create_batch","UniLM.create_batch",['Create a batch job. endpoint is e.g. "/v1/chat/completions", "/v1/responses", or "/v1/embeddings". input_file_id comes from upload_file(path, "batch").',"Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_batch","UniLM.retrieve_batch",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.cancel_batch","UniLM.cancel_batch",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.list_batches","UniLM.list_batches",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.poll_batch","UniLM.poll_batch",["Poll a batch until it reaches a terminal status (completed/failed/cancelled/expired). timeout bounds the wall-clock time of the whole poll (Inf waits indefinitely); interval is the pause between GETs. Both must be positive, else ArgumentError.","A transient failure — a status in the retryable set (408/429/500/502–504/520–524/529) or a GET that timed out — is polled through; any other failure is returned as it came. When the time runs out the result is a BatchCallError with cause = UniLMTimeout(:deadline, …) and last_observed set to the last BatchObject seen (nothing if no GET succeeded).","Pass cancel::Union{Nothing,CancelToken} (default: the ambient with_cancel token) to make the poll cancellable: a cancel ends it at once, mid-GET or mid-pause, with a BatchCallError whose cause is a UniLMCancelled and last_observed as above; a token cancelled before the poll sends nothing.","Pass config::Union{Nothing,RequestConfig} to bound each GET (a single attempt; its total_deadline is capped at the time left)."]],["Usage","Usage",[]]]},{url:"/api/capabilities/",sections:[["Provider Capabilities",null,["Functions for querying and validating provider capabilities.","Each service endpoint declares which API features it supports. Request functions validate capabilities before dispatching, giving clear errors instead of HTTP 404s."]],['What "validate before dispatch" means','What-"validate-before-dispatch"-means',["Validation comes in two strengths, and which one applies depends on the verb:",'That asymmetry is deliberate. Defining a ServiceEndpoint subtype is the documented way to reach an OpenAI-compatible backend this package does not ship, and such a backend cannot declare anything — refusing to dispatch it would be a false negative about a server the package knows nothing about. "Undeclared" is therefore no applicable method, never an empty capability set. Declaring capabilities is opt-in strictness: once your endpoint declares, the three primary verbs hold it to that declaration like any built-in.',"A rejection of a declared endpoint throws ArgumentError before any request, naming the feature and the endpoint and listing what it does support (for example Files API is not supported by ANTHROPICServiceEndpoint. Supported: chat, json_output, models, streaming, tools)."]],["Functions","Functions",[]],["UniLM.provider_capabilities","UniLM.provider_capabilities",["Return the set of capabilities supported by the given service endpoint.","Standard capability symbols include:"]],["UniLM.has_capability","UniLM.has_capability",["Check whether the service endpoint supports a given capability. An endpoint that declares :audio has :transcription too: transcription is part of the audio API."]],["Capability Symbols","Capability-Symbols",[]],["Capabilities by Provider","Capabilities-by-Provider",[]]]},{url:"/api/chat/",sections:[["Chat Completions API",null,["Types and functions for the Chat Completions API."]],["Chat Object","Chat-Object",[]],["UniLM.Chat","UniLM.Chat",["Creates a new Chat object with default settings:",'On the native OpenAI endpoint, max_tokens is sent as max_completion_tokens (setting both throws ArgumentError); DeepSeekEndpoint and MistralEndpoint() send max_completion_tokens as max_tokens, the name their references give the cap, taken over a max_tokens also set, and every other endpoint sends the name the Chat sets. On the native OpenAI endpoint user throws (use safety_identifier or prompt_cache_key), and service_tier must be one of "auto", "default", "flex", "scale", "priority" or "fast". Native Gemini and GEMINIOpenAIServiceEndpoint take service_tier "standard", "flex" or "priority", and native Gemini sends seed (an int32) and store; ANTHROPICServiceEndpoint takes "auto", "standard_only" or "fast" (fast mode). Each refuses another value with ArgumentError before any request.',"OpenAI options, omitted from the request when unset:",'The constructor validates ranges and throws ArgumentError on a violation; among them, n must be 1 when set — a result carries a single choice — top_logprobs must be in [0, 20], every logit_bias value (any Real) in [-100, 100], and reasoning_effort one of "none", "minimal", "low", "medium", "high", "xhigh", "max", and on a DeepSeekEndpoint also "ultra", which DeepSeek maps to max. An empty tools vector is stored as nothing.']],["Messages","Messages",["Audio replies","The audio an OpenAI model answers with, on an assistant Message; see Audio replies for how to ask for it and how later turns send it.","Attachments","Images, sound clips and PDF documents sent with a user message; see Images, audio and documents for how each endpoint sends them, and Attachments for a worked example on Ollama.","Convenience Constructors"]],["UniLM.Message","UniLM.Message",["Represents a single message in a Chat Completions conversation.","Fields","Validation","Convenience Constructors"]],["UniLM.ProviderContent","UniLM.ProviderContent",["Provider-native assistant content captured verbatim at decode time and echoed verbatim at encode time when the SAME provider encodes the turn again.",'The neutral Message carries content::String + tool_calls, but some providers attach blocks that must round-trip byte-faithfully for multi-turn flows to work: Anthropic thinking/redacted_thinking blocks (their signature must be echoed unmodified or tool round-trips on thinking models are rejected with HTTP 400), Gemini text-part thoughtSignatures, DeepSeek reasoning_content and Ollama thinking. provider tags the wire dialect (:anthropic, :gemini, :deepseek, :ollama, :mistral or :generic); blocks is the provider\'s content/parts array exactly as decoded (String-keyed JSON) — for :deepseek, [Dict("reasoning_content" => text)], echoed only on requests that carry tools; for :ollama, [Dict("thinking" => text)], echoed as the assistant message\'s thinking; for :mistral, a reply\'s Mistral ThinkChunks — an unstreamed reply\'s as they came, a streamed reply\'s joined into one, [Dict("type" => "thinking", "thinking" => [Dict("type" => "text", "text" => text)])]; for :generic, [Dict(field => text)], the reasoning_content (llama-server) or reasoning (vLLM) another GenericOpenAIEndpoint server returned. No encoder sends :mistral or :generic blocks.','Encoders ignore a ProviderContent tagged for a different provider — a conversation moved across providers falls back to the neutral reconstruction (the standard "other models drop thinking" semantics). The field never serializes on the OpenAI wire (excluded from JSON.lower(::Message)).']],["UniLM.reasoning_text","UniLM.reasoning_text",["The reasoning (\"thinking\") text a provider returned with an assistant turn, read from its ProviderContent: Ollama's thinking, DeepSeek's reasoning_content, Anthropic thinking blocks (separate blocks joined by a blank line; redacted blocks carry no text), the thought summaries of a native Gemini reply (a Chat that sets reasoning_effort asks for them), the thinking chunks of a Mistral reply and the reasoning_content or reasoning of another generic server's reply (llama-server, vLLM), streamed or not. nothing when the turn carries none — the provider returned no reasoning, or the model did not think. Like text, it throws an LLMResultError on a failure result."]],["UniLM.AudioOutput","UniLM.AudioOutput",['The audio an OpenAI model answers a Chat Completions turn with, on the assistant Message\'s audio_output. A Chat asks for it with modalities=["text", "audio"] and audio=Dict("voice" => …, "format" => …) on a model that speaks, such as gpt-audio-1.5 (Audio in Chat Completions).','The OpenAI-wire decoders read it from a reply\'s message.audio; a streamed reply assembles it from its delta.audio chunks, and the transcript reaches the streaming callback as text. When the conversation goes on, the OpenAI and Azure Chat encoders (OPENAIServiceEndpoint, AZUREServiceEndpoint) send the turn back as {"role": "assistant", "content": content, "audio": {"id": id}}, the turn\'s content beside the id, until a minute before expires_at, and always when expires_at is nothing; from then on they send the content alone. Such a follow-up\'s request bytes therefore depend on the clock: one recorded with with_recorded_answers while the audio was live replays only until a minute before expires_at, then throws ReplayMissError; record it after the expiry. Every other encoder — the Gemini OpenAI-compatible endpoint, DeepSeek, generic endpoints, OllamaEndpoint, native Anthropic and Gemini — sends the turn\'s content alone, the neutral form it also sends for another provider\'s ProviderContent. Throws ArgumentError for an empty id.']],["UniLM.Attachment","UniLM.Attachment",["Abstract supertype of the media a user Message carries besides its text: ImageAttachment, AudioAttachment and DocumentAttachment. An attachment holds the media's bytes and the format read from their leading bytes (the file signature), never from a file name, so its declared format always matches its content.",'Endpoints on the OpenAI Chat Completions wire (OpenAI, Azure, the Gemini OpenAI-compatible endpoint, DeepSeek, generic endpoints) send an image as an image_url part, with its detail level when it sets one, a sound clip as an input_audio part and a document as a file part, all base64: UniLM sends every kind as a content part on this wire, and the server decides what to do with it. For the Responses API, input_file turns a document into an input_file part. OllamaEndpoint sends images and clips in the message\'s images list and refuses a document — a chat attachment, or an input_file part for its Responses API, which documents no file inputs — and an image\'s detail level. The native Anthropic encoder sends an image and a document as base64 image and document blocks before the text, and refuses a sound clip and an image\'s detail level. Native Gemini sends every kind as an inlineData part ahead of the text, an image\'s detail level as its per-part media resolution ("low", "high"; "auto" sends none; "original" is refused, as is any level on the Gemini 2.5 and Gemma 4 models), and Gemini Interactions sends each as an image, audio or document part of an InputMessage\'s content. A System One request carries images, with a detail level on OpenAI\'s Decisions API alone, and refuses a document and a sound clip; an embedding input carries an image or a clip without a level. Each refusal is an ArgumentError before any network I/O.']],["UniLM.ImageAttachment","UniLM.ImageAttachment",['An image for a user Message: PNG, JPEG, GIF or WebP, recognised from its leading bytes. mime holds the media type ("image/png", …). detail is the level of detail an OpenAI model receives the image at — "auto", "low", "high" or "original", the image at its original dimensions, on the models that accept that level, such as GPT-5.6 (image inputs) — or nothing, which sends none and leaves the model\'s default. The OpenAI Chat Completions wire sends it as the part\'s detail; an endpoint without an equivalent refuses an image that sets one. Throws ArgumentError for empty data, bytes in any other format, or any other detail.']],["UniLM.AudioAttachment","UniLM.AudioAttachment",['A sound clip for a user Message: WAV or MP3, recognised from its leading bytes. format holds "wav" or "mp3", the names the OpenAI input_audio part uses. Throws ArgumentError for empty data or bytes in any other format.']],["UniLM.DocumentAttachment","UniLM.DocumentAttachment",['A PDF document for a user Message, recognised from its leading bytes (%PDF-). mime is "application/pdf"; filename is the file\'s own name (basename(path)) or, for bytes, the keyword. Endpoints on the OpenAI Chat Completions wire send the document as a file part with its filename (file inputs); for the Responses API, input_file turns it into an input_file part with its filename. The native Anthropic encoder (a base64 document block), native Gemini (inlineData) and Gemini Interactions (a document part) send the document without it. See Attachment for the endpoints that refuse it. Throws ArgumentError for bytes that are not PDF, whatever the file is called, and for a blank filename.']],["Conversation Management","Conversation-Management",["Building a Conversation"]],["Base.push!","Base.push!-Tuple{Chat, Message}",["Add a message to the conversation, refusing any mutation that would make it invalid.","Throws InvalidConversationError when the mutation would produce an invalid conversation: a non-system message pushed onto an empty conversation (it must start with a system message), or a message whose role repeats the last message's role (consecutive tool-result messages are the one exception). chat[i] = msg and direct edits to chat.messages are not validated.","A system message pushed once the conversation has started changes the instructions from that point on. Where it reaches the provider depends on the encoder:",'On native Anthropic, a system message pushed after a reply needs a user turn after it — a user message, or the results of the reply\'s tool calls — except in a response prefill on a model whose Prefill cell is "yes". Until one follows, chatrequest! throws ArgumentError before sending: as it stands, the request would end with the assistant turn, a response prefill.']],["Base.pop!","Base.pop!-Tuple{Chat}",["Remove the last message from the conversation.","Throws InvalidConversationError when the conversation is empty."]],["UniLM.issendvalid","UniLM.issendvalid",["Check if the conversation is valid for sending to the API.","Returns true only when the conversation has at least two messages, the first is a system message, the LAST is a user message, and no two adjacent messages share a role. Note the last two clauses are stricter than push!, which permits consecutive tool messages — this check has no such exemption, and a conversation ending in a tool result is false here.","This is a heuristic, not a proof: it cannot catch every malformed shape (a second system message in the middle passes the adjacency test). It never throws — a false is a verdict, not an error."]],["UniLM.update!","UniLM.update!",["Append msg to the conversation when chat.history is on; with history=false the chat is left unchanged, as documented for that setting (logged at debug level only)."]],["UniLM.fork","UniLM.fork",["Create an independent copy of a Chat: every field except service is deep-copied in one pass, so mutating a fork's messages, tools, metadata, stop or any other field never reaches its source or its siblings; service is shared (the endpoint a chat talks to, not conversation state); the cumulative-cost Ref is fresh (copied by value). The copy runs over fieldnames(Chat), so new Chat fields fork automatically. fork itself applies no normalization or rewrite — a fork is configuration-identical to its source.","Create n independent forks of a Chat."]],["UniLM.InvalidConversationError","UniLM.InvalidConversationError",["Thrown when a conversation violates structural rules (e.g., missing system message, consecutive messages from the same role).","Fields"]],["Tools","Tools",["Legacy aliases","The provider-neutral names above are canonical. These GPT* consts are exported aliases that keep pre-rename code working unchanged (silent, no deprecation warning; retained until the 1.0 stability boundary)."]],["UniLM.Tool","UniLM.Tool",["Wraps a FunctionSignature for use in the tools parameter of a Chat.","Example"]],["UniLM.FunctionSignature","UniLM.FunctionSignature",["Describes a function that can be called by the model in the Chat Completions API.","Fields","Example"]],["UniLM.ToolCall","UniLM.ToolCall",["Represents a tool call returned by the model. Contains the call id (used to match results back), the tool type, and the [GPTFunction] with name and parsed arguments.","Also carries an optional thought_signature::Union{Nothing,String} field holding Gemini-3's opaque tool-call signature, which must be echoed verbatim on the next turn; it is read from Gemini's replies (a native functionCall part's thoughtSignature, or extra_content.google.thought_signature on the OpenAI-compatible wire), nothing from every other provider, and sent back only to Gemini: it is excluded from JSON.lower, so the other endpoints' request bytes are unaffected."]],["UniLM.FunctionCallResult","UniLM.FunctionCallResult",["Holds the result of executing a function that was requested by the model via a tool call.","Fields"]],["UniLM.GPTTool","UniLM.GPTTool",["Legacy alias for Tool."]],["UniLM.GPTToolCall","UniLM.GPTToolCall",["Legacy alias for ToolCall."]],["UniLM.GPTFunctionSignature","UniLM.GPTFunctionSignature",["Legacy alias for FunctionSignature."]],["UniLM.GPTFunctionCallResult","UniLM.GPTFunctionCallResult",["Legacy alias for FunctionCallResult."]],["Output Format","Output-Format",[]],["UniLM.ResponseFormat","UniLM.ResponseFormat",["Specifies the output format for Chat Completions.","Fields","Examples","JsonSchemaAPI and the convenience constructors UniLM.json_object() and UniLM.json_schema(name, description, schema; strict=nothing) are not exported: qualify them with UniLM.."]],["Request Function","Request-Function",[]],["UniLM.chatrequest!","UniLM.chatrequest!",["Send chat to its provider and return a typed result.","Non-streaming (chat.stream !== true): returns LLMSuccess, LLMFailure, or LLMCallError. Transient statuses (408/429/500/502–504/520–524/529) are retried with backoff and jitter under the resolved RequestConfig (max_attempts, total_deadline; retry-after-ms, else Retry-After, honored). Timeouts surface as LLMCallError with status = nothing and the UniLMTimeout in cause — no fabricated HTTP statuses. Inside a with_recorded_answers scope the request passes through the recordings, and one the scope cannot replay — no recording in :replay mode, or a recording file that cannot be read — throws ReplayMissError instead of returning: a gap in the recordings is not a service failure. A streamed call passes through them too, replayed through the same callbacks: a miss on its first request is thrown by chatrequest! itself, while its reply's lost recording (RecordingWriteError), or a miss on a later request of a turn the provider continues, is thrown inside the task, so fetch raises a TaskFailedException whose task.exception is that error.","Streaming (chat.stream === true): returns a Task whose fetch yields the same typed results. callback(chunk::Union{String,Message}, close::Ref{Bool}) receives text deltas then the final assembled Message; on_tool_call(tc::ToolCall) fires once per completed streamed tool call. Setting close[] = true — in the callback or from any other task — stops the stream at once: the call ends with LLMCallError(status=nothing, cause=UniLMCancelled(:callback, …)), unless the provider's completion marker already arrived — then the turn is committed, the final-message callback runs, and usage may be missing. The marker is the chunk that carries the finish reason; on the OpenAI wire it precedes the usage chunk and [DONE]. The turn is final at the end-of-stream sentinel ([DONE], Anthropic message_stop): the final-message callback runs then, and the result follows when the HTTP body ends, at most 0.5 s later (a body still open then has its connection closed rather than reused). An exception thrown by callback or on_tool_call ends the call with that exception in cause: never retried, nothing committed, and no callback runs after it. Time spent in these callbacks does not count toward stream_idle_timeout, which bounds only the gap between bytes off the socket. A user InterruptException is never converted into a result value: it propagates, so fetch on the streaming task throws a TaskFailedException whose task.exception is the InterruptException. So does the ReplayMissError or RecordingWriteError of a recorded call made in callback or on_tool_call, and either of them or an interrupt that a callback throws inside a wrapper, such as a fetched task's TaskFailedException: task.exception is what the callback threw.","A stream that ends without committing a turn — stopped, cancelled, timed out, cut off, or ended by an exception from callback or on_tool_call — adds the usage its provider had reported to cumulative_cost, as a lower bound of what was billed: Anthropic reports a request's input when its stream starts, Gemini the usage so far on every chunk, and OpenAI only after the finish reason, so a stopped OpenAI stream adds nothing. A request stopped before any usage arrived adds nothing, though the provider bills it; so does an attempt that was retried, and a stream the provider ended with an error event.","config::Union{Nothing,RequestConfig}: per-call timeout/retry budget; nothing resolves the ambient configuration (with_request_config scope, else the process default set via set_default_config!, else the model's own default where it has one — the 20-minute bounds of a Gemini 4 model, see set_default_config! — else the field defaults).","A long generation the provider stops at its per-request cap and returns a token to continue (Gemini 4 Argon's long decode on GEMINIServiceEndpoint) is continued inside the call: the same request is sent again with the latest token, as often as the output budget (max_completion_tokens, else max_tokens) needs at Google's per-request cap — 32,768 output tokens, 65,536 on a stream — plus one request, and at least 8 requests in all. The result is one assistant turn — the replies' parts joined, their usage summed field by field, since every reply is billed, and priced at the tier the last reply reported. Each request has the whole config budget, timeouts and retries alike; a retry sends its request again from the start: a stream that drops after one of its checkpoint tokens is not resumed from it, and what Google bills for the attempt that dropped (up to that checkpoint) is not added to cumulative_cost. A turn still unfinished after the last of those requests, or whose reply continues without having produced an output token (thinking included), is returned as it stands, with finish_reason == \"continuation\". A request that fails ends the call with its failure and commits nothing, and the replies already received are added to cumulative_cost. A streamed turn streams every reply into the same callback, which receives one final message. The turn's completion marker is its last reply's finish reason, not a reply's CONTINUATION: a stop or cancel before it ends the call with UniLMCancelled in cause and nothing committed, and the replies already answered — one whose CONTINUATION chunk the stop, or a throwing callback, landed on included — are added to cumulative_cost too, with what the reply in flight had reported. Continuation is exercised against a local mock; a live CONTINUATION reply was not observed.","cancel::Union{Nothing,CancelToken}: a CancelToken; nothing resolves the ambient token of with_cancel, at call entry. A cancel at any point — before connecting, during the response-header wait, mid-stream, or during a retry backoff — ends the call with LLMCallError(status=nothing, cause=UniLMCancelled(:token, …)): never retried, nothing committed to chat, no terminal callback — unless the provider's completion marker already arrived (as for close[] = true above): then the turn is committed, the final-message callback runs, and usage may be missing. A pre-cancelled token sends nothing. A TCP connect or TLS handshake already in progress cannot be interrupted (HTTP.jl 2.7.1), so a cancel during one takes effect when it completes or reaches connect_timeout.","Local validation throws before any network I/O, streaming or not: ArgumentError when callback or on_tool_call is passed without chat.stream === true (they run only on a stream, so they would be ignored), when chat.service is an endpoint type that declares its capabilities and does not list :chat (a custom endpoint declares none and is dispatched unvalidated), or when the provider's encoder rejects the request (e.g. an option the provider or model does not support); InvalidConversationError when chat.history is on and the conversation ends with an assistant message, so the reply could not be appended; and the MethodError of a seam method the endpoint type lacks — encode_request, and on a stream handle_sse_event!, whose missing method would otherwise drop every payload of the reply.","Build a Chat from keyword arguments, send it with chatrequest!(chat; config, cancel), and return that result (the reply is appended to result.self).","The conversation is EITHER messages — copied, so the caller's vector is never mutated — OR systemprompt and userprompt, each a String or a Message. Passing neither, only one prompt, or messages together with a prompt throws ArgumentError before any network I/O. Every other keyword but config and cancel is a Chat field, for example:","config and cancel go to chatrequest!(chat):"]],["Role Constants","Role-Constants",[]],["UniLM.RoleSystem","UniLM.RoleSystem",['Role constant "system" — used for system-level instructions.']],["UniLM.RoleUser","UniLM.RoleUser",['Role constant "user" — used for user messages.']],["UniLM.RoleAssistant","UniLM.RoleAssistant",['Role constant "assistant" — used for model-generated messages.']],["Tool Loop","Tool-Loop",[]],["UniLM.CallableTool","UniLM.CallableTool",["Wraps a tool schema T (Tool or FunctionTool) with a callable. JSON serialization delegates to the inner tool, preserving backward compatibility.","Fields","Example"]],["UniLM.ToolCallOutcome","UniLM.ToolCallOutcome",["Per-call record from a tool dispatch.","Fields"]],["UniLM.ToolLoopResult","UniLM.ToolLoopResult",["Result of a tool dispatch loop.","Fields"]],["UniLM.tool_loop!","UniLM.tool_loop!",["Run a tool-calling loop on a Chat. Repeatedly calls chatrequest!, dispatches tool calls via dispatcher(name, args), pushes tool-role messages back, and repeats until a text response, API error, or max_turns.",'Tool calls run only on a turn whose finish_reason is "tool_calls". A turn that carries tool calls but finished for any other reason ("length", "content_filter", a provider-specific value) may hold partial calls: none runs, the loop stops with completed=false and an llm_error naming the reason, and that unanswered assistant turn is removed from chat, so the conversation stays sendable. A text turn completes the loop only when it finished with "stop" or reported no reason (or finished with "tool_calls" but carried no calls); "length" stops it with completed=false and llm_error = "Model output was truncated by the token limit", and any other reason ("content_filter", a provider-specific value) with an llm_error naming it — the turn stays in chat.',"chat.history must be true (else ArgumentError before any request): each follow-up request carries the tool results together with the assistant turn that requested them.","Arguments","Example","No-dispatcher variant: builds a dispatcher from CallableTool entries."]],["UniLM.tool_loop","UniLM.tool_loop",['Run a tool-calling loop on a Respond request. Dispatches function calls via dispatcher(name, args) (a non-String return is sent JSON-encoded), builds function_call_output input items, and chains via previous_response_id — or, when r.conversation is set, through the conversation alone (the API rejects the two together). A call whose arguments are not a JSON object is answered with an "Error: invalid arguments: …" output, like a dispatcher error, and the loop goes on.',"Function calls run only on a completed or requires_action turn. Any other status (e.g. incomplete, whose calls may be partial) stops the loop with completed=false and an llm_error naming the status and the incomplete_details reason. A turn that requests a client-side call this loop cannot execute (custom_tool_call, apply_patch_call, computer_call, a shell_call the platform did not run itself, or an mcp_approval_request) stops it the same way, with the pending call type in llm_error; none of that turn's calls run.","max_turns (default 10; < 1 throws ArgumentError) bounds the round-trips; when they run out, the result keeps the last response, with completed=false and llm_error = \"max turns (N) exhausted\". Every turn's response stays in the result's responses, so each turn's usage and cost can be read (ToolLoopResult).","cancel works as in tool_loop!: every turn runs inside with_cancel(cancel) (nothing uses the ambient token), the token is checked before each dispatch, and a cancelled loop returns promptly with completed=false and the turn's typed cancellation result — the cancelled request's ResponseCallError, or, between dispatches, a ResponseCallError whose cause is UniLMCancelled. tool_concurrency (default 1) works as in tool_loop!: above 1, up to that many of a turn's calls run at once and their outputs are sent in call order. An InterruptException, a ReplayMissError or a RecordingWriteError from a dispatch propagates, as in tool_loop!.","Per-call config::RequestConfig overrides timeouts/retry budget.","No-dispatcher variant: extracts callables from CallableTool entries in r.tools.","Per-call config::RequestConfig overrides timeouts/retry budget.","Convenience form: creates a Respond and runs the tool loop.","Per-call config::RequestConfig overrides timeouts/retry budget; max_turns, cancel and tool_concurrency drive the loop as in tool_loop(::Respond, ::Function); every other keyword goes to the Respond constructor.","No-dispatcher convenience form of the Responses-API tool loop for a plain-string prompt. Wraps input and tools in a Respond and delegates to tool_loop(::Respond), which dispatches each model-requested function call to the matching CallableTool callable.","Keyword routing is explicit: max_turns, config, cancel and tool_concurrency drive the loop (config::RequestConfig overrides timeouts/retry budget), while every other keyword is forwarded verbatim to the Respond constructor — an unknown keyword raises there rather than being silently dropped. tools is required and must hold CallableTool entries (e.g. from mcp_tools_respond).","Example"]],["UniLM.to_tool","UniLM.to_tool",["Overloadable conversion protocol. Identity for Tool, FunctionTool, CallableTool. Converts AbstractDict to Tool. Package extensions can add methods for other types.","Convert an MCPServerTool to a FunctionTool for use with the Responses API."]],["Model Constants","Model-Constants",[]]]},{url:"/api/completions/",sections:[["FIM Types",null,["Types and functions for FIM (Fill-in-the-Middle) Completion and Chat Prefix Completion."]],["Request Type","Request-Type",[]],["UniLM.FIMCompletion","UniLM.FIMCompletion",["A Fill-in-the-Middle completion request. The model generates text between prompt (prefix) and suffix.","Supported by DeepSeekEndpoint (beta), Mistral and Ollama (vLLM's completions endpoint does not accept suffix). stream=true throws an ArgumentError: fim_complete has no streaming path.","Example"]],["Response Types","Response-Types",[]],["UniLM.FIMChoice","UniLM.FIMChoice",["A single completion choice from a FIM response.","Fields"]],["UniLM.FIMResponse","UniLM.FIMResponse",["Parsed FIM completion response containing choices, usage, and raw data.","Fields"]],["Result Types","Result-Types",[]],["UniLM.FIMSuccess","UniLM.FIMSuccess",["Successful FIM completion result."]],["UniLM.FIMFailure","UniLM.FIMFailure",["HTTP-level failure from FIM completion."]],["UniLM.FIMCallError","UniLM.FIMCallError",["Exception-level error during FIM completion."]],["Request Functions","Request-Functions",[]],["UniLM.fim_complete","UniLM.fim_complete",["Execute a FIM (Fill-in-the-Middle) completion request. Returns FIMSuccess, FIMFailure, or FIMCallError.","Per-call config::RequestConfig overrides timeouts and the retry budget; a silent peer fails with a typed timeout inside the FIMCallError result (cause::UniLMTimeout). Local validation (capability, model resolution, routing) throws an ArgumentError before any request; every later failure — transport, a 200 body that is not a completions response — is a FIMCallError whose cause holds the exception. Inside a with_recorded_answers scope the request passes through the recordings: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning a FIMCallError.","cancel::Union{Nothing,CancelToken} (default: the ambient with_cancel token) makes the call cancellable: once the token is cancelled it returns a FIMCallError whose cause is a UniLMCancelled — without sending anything when the token was already cancelled, at once when mid-request (never retried).","Convenience form: creates a FIMCompletion and executes it. config and cancel go to the request; every other keyword to the constructor."]],["UniLM.fim_text","UniLM.fim_text",['Extract the generated text from a FIM completion result. On a FIMFailure or FIMCallError it throws an LLMResultError, as text does on a failed Chat result: a failed call has no text, and "" would read as an empty completion. Guard with issuccess.']],["UniLM.prefix_complete","UniLM.prefix_complete",["Chat prefix completion: the model continues from a partial assistant message. The last message in chat must be role=assistant containing the text prefix to continue from. The result's message is the continuation the API returns; with chat.history the conversation keeps the whole assistant turn, prefix followed by continuation. The request is never streamed: the call reads one whole reply and takes no callback, so a chat with stream=true is sent without its stream and stream_options. A successful call adds its turn's cost to cumulative_cost(chat), with or without chat.history, as chatrequest! does.","Supported by DeepSeekEndpoint (beta).","Per-call config::RequestConfig overrides timeouts and the retry budget; a silent peer fails with a typed timeout inside the LLMCallError result (cause::UniLMTimeout). Local validation throws an ArgumentError before any request; every later failure is an LLMCallError whose cause holds the exception. Inside a with_recorded_answers scope the request passes through the recordings: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning an LLMCallError. cancel::Union{Nothing,CancelToken} makes the call cancellable as for fim_complete: a cancelled call returns an LLMCallError whose cause is a UniLMCancelled, and chat is left untouched.","Example"]],["Example","Example",[]]]},{url:"/api/config/",sections:[["Request Configuration & Timeouts",null,["See the Timeouts & Retries guide for usage and rationale.","Timeout, deadline, and retry-budget configuration for UniLM network operations, plus the typed timeout errors."]],["Configuration","Configuration",[]],["UniLM.RequestConfig","UniLM.RequestConfig",["Timeout and retry budget for every UniLM network operation. All time fields are seconds (Float64); Inf disables that bound.","Fields","The constructor throws ArgumentError for NaN or non-positive time values (NaN is rejected explicitly because it compares false against every bound and would silently disable the timeout), for finite time values above 1e9 seconds (too large for the timers that enforce them; use Inf instead), and for max_attempts < 1.","The two-argument form copies base with the named fields overridden, under the same validation.","See also with_request_config, set_default_config!, current_config."]],["UniLM.current_config","UniLM.current_config",["The ambient RequestConfig: the innermost active with_request_config scope if any, otherwise the process default set by set_default_config!, otherwise the field defaults. A System One call, or a Chat or Responses call to a Gemini 4 model, with no scope and no process default set uses its backend's or its model's own default instead of the field defaults (see set_default_config!)."]],["UniLM.with_request_config","UniLM.with_request_config",["Run f() with a RequestConfig pinned in dynamic scope and return f()'s value. The given fields are merged over current_config once at entry; the resulting complete struct governs every UniLM call inside f, including tasks spawned inside the scope (scoped values propagate into Threads.@spawn). Mutating the process default while the scope is active does not affect it."]],["UniLM.set_default_config!","UniLM.set_default_config!",["Set the process-wide default RequestConfig and return it. The keyword form merges the given fields over the CURRENT process default (never over an active scope), or over the field defaults while none is set. Intended for REPL/notebook sessions, which cannot hold a dynamic scope across cells; prefer with_request_config in programs.","A process default you set — even one equal to the field defaults — also replaces the default a System One backend or a model brings. Until one is set, ask, ask_each and the natural-language verbs on TypeSafe and OpenAI's Decisions API, and list_models on TypeSafe, use request_timeout = 60 and total_deadline = 150 (both services typically answer in under a second; the field defaults' ten minutes per attempt would only delay reporting a stalled call); chatrequest! and respond to a Gemini 4 model (an id starting gemini-4-, on GEMINIServiceEndpoint or GEMINIOpenAIServiceEndpoint) use request_timeout, stream_idle_timeout and total_deadline of 1200 seconds (Google ends such a call after 10 minutes, a stream after 20, and advises a 20-minute read timeout); every other call uses the field defaults. A with_request_config scope or a per-call config replaces either default too, as a whole.","The keyword form is a read-modify-write and retries on a compare-and-swap miss: a plain read-then-write loses one of two concurrent calls, because the loser installs a snapshot taken before the winner's write and silently drops its field."]],["Timeout Errors","Timeout-Errors",[]],["UniLM.UniLMTimeout","UniLM.UniLMTimeout",["A configured UniLM time bound was exceeded.","Fields","Configure the bounds via RequestConfig. Value-returning surfaces (chat, embeddings, responses) deliver this inside their error results rather than throwing; see each surface's documentation."]],["UniLM.MCPTimeoutError","UniLM.MCPTimeoutError",["An MCP operation exceeded its configured time bound. The MCP surface is throw-based, so this surfaces as an exception rather than a failure value.","Fields"]],["Cancellation","Cancellation",["A cooperative, level-triggered token: cancel it from any task, and every operation that observes it — explicitly through a cancel keyword, or as the ambient token of a with_cancel scope — stops and reports UniLMCancelled in its call-error result. See Concurrency, Tasks and Cancellation."]],["UniLM.CancelToken","UniLM.CancelToken",["A cooperative cancellation token: make it ambient with with_cancel (or pass it where an operation takes a cancel keyword), then call cancel! from any task. Cancellation is level-triggered — a cancelled token stays cancelled, and every later request that sees it stops before any network I/O — so use a fresh token per unit of work you may want to abandon.","A token reaches what goes through the package's HTTP layer: every HTTP verb, streams included, and the pauses between retries and polls; speak and translate observe it on their Realtime sessions too. A session opened with realtime_connect (realtime_receive) and MCP stdio exchanges do not observe it.","The Julia 1.14 development branch adds task cancellation built on scoped cancellation tokens (Base.CancellationTokenSource / Base.CANCEL_TOKEN) with a cancel keyword on blocking operations; this API has the same shape so a later version can bridge to it."]],["UniLM.cancel!","UniLM.cancel!",["Cancel tok. The first call flips the flag and then runs every registered hook exactly once, outside the token's lock. A hook that throws is @debug-logged and the rest still run; an InterruptException from a hook is rethrown once every hook has run (the first one, if several). Later calls are no-ops."]],["UniLM.iscancelled","UniLM.iscancelled",["Whether tok has been cancelled; false for nothing (no token)."]],["UniLM.with_cancel","UniLM.with_cancel",["Run f() with tok as the ambient cancellation token and return f()'s value. What f sends through the package's HTTP layer observes tok — every HTTP verb, streams included, and the pauses between retries and polls — including requests made in tasks spawned inside f (scoped values propagate into Threads.@spawn); the innermost scope wins. speak and translate observe it on their Realtime sessions; a session opened with realtime_connect and MCP stdio exchanges do not. The Julia 1.14 development branch adds task cancellation built on scoped cancellation tokens (Base.CancellationTokenSource / Base.CANCEL_TOKEN) with a cancel keyword on blocking operations; this API has the same shape so a later version can bridge to it."]],["UniLM.UniLMCancelled","UniLM.UniLMCancelled",["An operation was cancelled before it completed.","Fields"]],["Resolution Precedence","Resolution-Precedence",["A request resolves its RequestConfig struct-wise (whichever channel wins supplies every field):","A backend's default fills in only while you have chosen nothing: a scope, a per-call config or a process default you set — even one equal to the field defaults — replaces it as a whole. current_config reports channels 2, 3 and 5, the config of every verb whose backend brings none."]]]},{url:"/api/containers/",sections:[["Containers API",null,["Create, retrieve, list, and delete code-interpreter containers, and add files to them. Containers provide sandboxed compute for the Responses code-interpreter tool and expire after idle. OpenAI only."]],["Objects","Objects",["add_container_file returns a ContainerSuccess whose response is the created ContainerFileObject (not exported); create and retrieve return a ContainerObject."]],["UniLM.ContainerObject","UniLM.ContainerObject",["A code-interpreter container: id, status, and name; raw holds the unparsed JSON response."]],["UniLM.ContainerList","UniLM.ContainerList",["A page of container records (raw JSON dicts) from list_containers; has_more signals that further pages are available."]],["UniLM.ContainerFileObject","UniLM.ContainerFileObject",['A file inside a container, as add_container_file returns it: id, container_id, path (where the code interpreter sees the file), bytes, source (e.g. "user", "assistant") and created_at; raw holds the unparsed JSON response.']],["Result Types","Result-Types",[]],["UniLM.ContainerSuccess","UniLM.ContainerSuccess",["Successful Containers API result: a ContainerObject from create/retrieve, or the ContainerFileObject that add_container_file created."]],["UniLM.ContainerListSuccess","UniLM.ContainerListSuccess",["Successful list_containers result wrapping a ContainerList."]],["UniLM.ContainerDeleteSuccess","UniLM.ContainerDeleteSuccess",["Successful delete_container result: the service confirmed (deleted is always true) the removal of id."]],["UniLM.ContainerFailure","UniLM.ContainerFailure",["Containers API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.ContainerCallError","UniLM.ContainerCallError",["Containers API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout."]],["Request Functions","Request-Functions",[]],["UniLM.create_container","UniLM.create_container",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_container","UniLM.retrieve_container",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.list_containers","UniLM.list_containers",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.delete_container","UniLM.delete_container",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.add_container_file","UniLM.add_container_file",["Upload the file at path into the container. A success is a ContainerSuccess whose response is the created ContainerFileObject. A path that is no file throws ArgumentError before any request, as in upload_file.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["Usage","Usage",[]]]},{url:"/api/conversations/",sections:[["Conversations API",null,["Create, retrieve, update, and delete durable, server-side conversations, and manage their items. A conversation's id, read with conversation_id, is the conversation of a Respond (respond(input; conversation=id)): the Responses API prepends the conversation's items and adds the response's items to it, so a multi-turn exchange resends no history (Conversations). OpenAI only."]],["Parsed Objects","Parsed-Objects",[]],["UniLM.ConversationObject","UniLM.ConversationObject",["A durable, server-side conversation: id, optional created_at and metadata; raw holds the unparsed JSON response."]],["UniLM.ConversationItem","UniLM.ConversationItem",["A single item in a conversation: its id and optional type; raw holds the unparsed JSON response. id is nothing for an item that has none: OpenAI's Conversations reference gives every item one except a custom tool call and its output, whose id is optional."]],["UniLM.ConversationItemList","UniLM.ConversationItemList",["A page of ConversationItems from list_conversation_items; has_more signals further pages, and first_id/last_id bound the page."]],["Result Types","Result-Types",[]],["UniLM.ConversationSuccess","UniLM.ConversationSuccess",["Successful create/retrieve/update result wrapping a ConversationObject; also the result of delete_conversation_item, which the service answers with the updated conversation."]],["UniLM.ConversationItemListSuccess","UniLM.ConversationItemListSuccess",["Successful list_conversation_items / add_conversation_items result wrapping a ConversationItemList."]],["UniLM.ConversationItemSuccess","UniLM.ConversationItemSuccess",["Successful retrieve_conversation_item result wrapping the ConversationItem it read."]],["UniLM.ConversationDeleteSuccess","UniLM.ConversationDeleteSuccess",["Successful delete_conversation result: the service confirmed (deleted is always true) the removal of id."]],["UniLM.ConversationFailure","UniLM.ConversationFailure",["Conversations API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.ConversationCallError","UniLM.ConversationCallError",["Conversations API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout."]],["Request Functions","Request-Functions",[]],["UniLM.create_conversation","UniLM.create_conversation",["Create a conversation. items is an optional vector of input items (e.g. InputMessage). Returns ConversationSuccess, ConversationFailure, or ConversationCallError.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_conversation","UniLM.retrieve_conversation",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.update_conversation","UniLM.update_conversation",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.delete_conversation","UniLM.delete_conversation",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.add_conversation_items","UniLM.add_conversation_items",["Append input items to a conversation. Returns ConversationItemListSuccess.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.list_conversation_items","UniLM.list_conversation_items",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_conversation_item","UniLM.retrieve_conversation_item",['Read one item of a conversation, "a single item from a conversation with the given IDs" (GET /v1/conversations/{conversation_id}/items/{item_id}). include names the "Additional fields to include in the response", such as "message.output_text.logprobs", each sent as an include[] query parameter, as OpenAI\'s SDKs send it. Returns ConversationItemSuccess (its response the ConversationItem), ConversationFailure, or ConversationCallError.',"Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.delete_conversation_item","UniLM.delete_conversation_item",["Delete one item. The service answers with the updated conversation, so a success is a ConversationSuccess wrapping that ConversationObject.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["Accessors","Accessors",[]],["UniLM.conversation_id","UniLM.conversation_id",["Return the id of a ConversationObject."]],["Usage","Usage",[]]]},{url:"/api/embeddings/",sections:[["Embeddings API",null,["Types and functions for the Embeddings API."]],["Embeddings Object","Embeddings-Object",["Construction"]],["UniLM.Embeddings","UniLM.Embeddings",["Create an embedding request for one or more texts. model=\"\" resolves to the service's default embedding model — OpenAI's text-embedding-3-small (1536 dimensions), gemini-embedding-2 for GEMINIOpenAIServiceEndpoint —, and any other service needs an explicit model (ArgumentError otherwise). DeepSeek and Azure do not serve embeddings through UniLM: embeddingrequest! refuses them with an ArgumentError before any I/O, whatever the model, as it refuses every endpoint whose declared capabilities lack :embeddings. Embeddings work with OpenAI, GEMINIOpenAIServiceEndpoint, Ollama, GenericOpenAIEndpoint (Mistral included) and custom endpoints that declare :embeddings or no capabilities.","An input is a text, an EmbeddingInput, or an ImageAttachment or AudioAttachment on its own; a vector of them embeds each item as a vector of its own. A DocumentAttachment, or an image with a detail level, is an ArgumentError, as in an EmbeddingInput. A vector of strings is copied into a Vector{String} and sent as is, an empty string included. In a vector holding any other item, every item becomes an EmbeddingInput, so an empty string there is refused (ArgumentError: an item needs a non-empty text, an image or a sound clip).","The embeddings field is pre-allocated (something(dimensions, 1536) zeros per input), filled in place by embeddingrequest!, and resized to the length the model returns. The result aliases this struct, so use one Embeddings per concurrent call.","Fields","Task prompts (EmbeddingGemma, Gemini Embedding 2)","EmbeddingGemma models (embeddinggemma, embeddinggemma-2, on any service) and gemini-embedding-2 read a short prompt that says what a text is for, and neither Ollama nor the OpenAI-compatible request adds it: pass task and UniLM writes the model card's prompt in front of each text — :search_query, :question_answering, :fact_checking, :code_retrieval (the query side), :document (the corpus side, with each item's title), :classification, :clustering, :sentence_similarity — or task = :none to send the text as is. Without a task an EmbeddingGemma request is an ArgumentError; gemini-embedding-2 takes none, its text then sent as is (Google's embeddings guide recommends the prompts for text); any other model takes task = :none or none. EmbeddingGemma's dimensions are 768 (default), 512, 256 or 128. Through an OllamaEndpoint, an EmbeddingGemma 2 request carries the model's trained 8,192-token window (num_ctx and num_batch) unless the endpoint sets either (EmbeddingGemma v1 reads 2,048 tokens); with truncate=false, the default, a longer input is an EmbeddingFailure, never a vector of part of it (measured on Ollama 0.40.6 with 740m-q8_0, 740m-mxfp8, 270m-q8_0-text and v1).","Example"]],["UniLM.EmbeddingInput","UniLM.EmbeddingInput",["One item for Embeddings, embedded as one vector: a text, an image, a sound clip, or a text with an image or a sound clip — one of them per item on an OllamaEndpoint, which refuses an item holding both before any request; a service that embeds text only refuses media. title names the document a text comes from; it is used by the :document task of models with task prompts (EmbeddingGemma, gemini-embedding-2) and refused with any other task or model. Images and audio go only to an OllamaEndpoint (Ollama's /api/embed takes them for models that see or hear, such as embeddinggemma-2:740m-q8_0, which embedded a text with its picture or clip as one item on Ollama 0.40.6). Ollama passes an item's image and clip to the model in a random order, which is why an item holding both is refused (on Ollama 0.40.6, ten requests of one such item to embeddinggemma-2:740m-q8_0 gave two different vectors): send the image and the audio as separate items. Two items are == when their texts, titles and media are. An empty text beside an image or clip is no text: the item holds the media alone (text === nothing), sent with no task prompt. An empty or whitespace-only title is no title (title === nothing): with task = :document the text is sent as \"title: none | text: …\", the model card's prompt for a document without one.","Throws ArgumentError for an item with nothing to embed (no image or clip, and no text or an empty one), a title without a non-empty text, more than one image or clip, an image with a detail level, or an attachment of any other kind, such as a DocumentAttachment: no embedding endpoint UniLM sends to takes a level or a document (OpenAI's and its compatibles take text, Ollama's /api/embed an image's or a clip's bytes alone)."]],["Request Function","Request-Function",[]],["UniLM.embeddingrequest!","UniLM.embeddingrequest!",["Send an Embeddings API request for the input in emb. Returns EmbeddingSuccess, EmbeddingFailure (non-2xx), or EmbeddingCallError (network/parse/timeout). The resulting vectors are filled into emb.embeddings in place and are also reachable via embedding_vectors(result).","Transient statuses (408/429/500/502–504/520–524/529) are retried with backoff and jitter under the resolved RequestConfig (config === nothing resolves the ambient configuration). Timeouts surface as EmbeddingCallError with status = nothing and the UniLMTimeout in cause. Inside a with_recorded_answers scope the request passes through the recordings, and one the scope cannot replay throws ReplayMissError instead of returning an EmbeddingCallError.","cancel::Union{Nothing,CancelToken} (nothing: the ambient token of with_cancel): a cancel ends the call with EmbeddingCallError(status=nothing, cause=UniLMCancelled(:token, …)), never retried; a pre-cancelled token sends nothing. A TCP connect or TLS handshake already in progress finishes (or reaches connect_timeout) before the cancel takes effect.","Throws ArgumentError before any network I/O when emb.service is an endpoint type that declares its capabilities and does not list :embeddings."]],["Result Types","Result-Types",[]],["UniLM.EmbeddingSuccess","UniLM.EmbeddingSuccess",["Successful Embeddings API response. Vectors are in embeddings.embeddings (also filled in place on the request struct); embedding_vectors(r) returns them."]],["UniLM.EmbeddingFailure","UniLM.EmbeddingFailure",["HTTP-level failure from the Embeddings API (non-2xx)."]],["UniLM.EmbeddingCallError","UniLM.EmbeddingCallError",["Exception-level error during an Embeddings API call (network, parse, timeout, etc.). cause holds the underlying typed exception when one exists (e.g. a UniLMTimeout); status stays nothing for timeouts — no fabricated HTTP statuses."]],["UniLM.embedding_vectors","UniLM.embedding_vectors",["Return the embedding vector(s): Vector{Float64} (single input) or Vector{Vector{Float64}} (batch). On an EmbeddingFailure or EmbeddingCallError it throws an LLMResultError; guard with issuccess."]],["Model Constants","Model-Constants",[]],["Usage Example","Usage-Example",[]]]},{url:"/api/endpoints/",sections:[["Service Endpoints",null,["Types for configuring multi-backend service endpoints, and the extension API a new backend implements."]],["Abstract Types","Abstract-Types",[]],["UniLM.ServiceEndpoint","UniLM.ServiceEndpoint",["Abstract supertype for LLM service backends. Subtypes control URL routing and authentication.","OpenAI-compatible backends subtype OpenAIWireEndpoint (itself a subtype of ServiceEndpoint) to inherit the chat request/response encoding and SSE handling; backends with a native wire (Anthropic, Gemini) subtype ServiceEndpoint directly and implement the wire seam (encode_request/decode_response/handle_sse_event!) themselves.","Built-in subtypes:"]],["UniLM.OpenAIWireEndpoint","UniLM.OpenAIWireEndpoint",["Abstract supertype for backends that speak the OpenAI-compatible chat wire. Subtypes inherit the OpenAI Chat Completions request/response encoding (encode_request/decode_response) and the default SSE stream handling (handle_sse_event!) for free, so a new OpenAI-compatible provider defines only get_url and auth_header (plus, optionally, the _api_base_url pattern that routes the Responses/agentic surface).","Backends that speak a genuinely different wire (Anthropic's Messages API, Gemini's native generateContent) subtype ServiceEndpoint directly and additionally implement encode_request, decode_response, and handle_sse_event!. A bare ServiceEndpoint subtype that omits those methods fails with a MethodError at call time rather than silently emitting OpenAI-shaped requests to a foreign API.","Built-in OpenAI-wire subtypes: OPENAIServiceEndpoint, AZUREServiceEndpoint, GEMINIOpenAIServiceEndpoint, GenericOpenAIEndpoint, DeepSeekEndpoint, and OllamaEndpoint, which overrides the chat seam with Ollama's native wire and keeps the OpenAI-wire Responses and completions routes."]],["Built-in Endpoints","Built-in-Endpoints",["TYPESAFEServiceEndpoint is not a chat backend: it serves TypeSafe's System One model, Jev (System One API), and declares only :system_one and :models, so the chat, Responses and embedding verbs reject it up front. OPENAIServiceEndpoint answers System One requests too, through OpenAI's Decisions API, and so does an OllamaEndpoint, from a local decision model."]],["UniLM.OPENAIServiceEndpoint","UniLM.OPENAIServiceEndpoint",["OpenAI API service endpoint (default). Requires OPENAI_API_KEY env variable. OPENAIServiceEndpoint() returns the type."]],["UniLM.AZUREServiceEndpoint","UniLM.AZUREServiceEndpoint",["Azure OpenAI Service endpoint. Requires AZURE_OPENAI_BASE_URL, AZURE_OPENAI_API_KEY, and AZURE_OPENAI_API_VERSION env variables. AZUREServiceEndpoint() returns the type."]],["UniLM.GEMINIServiceEndpoint","UniLM.GEMINIServiceEndpoint",["Native Google Gemini generateContent API (x-goog-api-key; model in URL). Requires GEMINI_API_KEY. GEMINIServiceEndpoint() returns the type."]],["UniLM.GEMINIOpenAIServiceEndpoint","UniLM.GEMINIOpenAIServiceEndpoint",["Google Gemini endpoint (OpenAI-compatible). Requires GEMINI_API_KEY env variable. GEMINIOpenAIServiceEndpoint() returns the type."]],["UniLM.ANTHROPICServiceEndpoint","UniLM.ANTHROPICServiceEndpoint",["Anthropic (Claude) native Messages API endpoint. Requires the ANTHROPIC_API_KEY env variable. Native wire format (content blocks, top-level system, user/assistant roles) — NOT OpenAI-compatible.","The type itself (service=ANTHROPICServiceEndpoint) is the endpoint with no options set. An instance adds options that every request through it carries (Messages API):",'estimated_cost bills US-only inference (a usage that reports inference_geo "us") at 1.1\xd7 every rate on Claude 4.6 and later; an earlier model is billed at the standard rates, whatever region its usage reports (data residency pricing). A reply at Priority Tier (a usage that reports service_tier "priority") is estimated at the list rates, as at the standard tier: Priority Tier draws down an organization\'s contracted capacity commitment (service tiers).','The constructor throws ArgumentError for a blank value, a value that holds a control character (CR, LF, …), a beta name that holds a comma, and an inference_geo other than "global" or "us". Instances with the same options are equal (==, hash).',"The fields are read-only: to change an option, build a new endpoint. betas is copied at construction but is a Vector, so it can still be changed in place; that changes the endpoint's hash (a Dict or Set holding it no longer finds it), and the beta names are checked again by the same rule when the header is built, so a name changed in place that breaks it is refused before anything is sent (the verb returns the ArgumentError as the cause of its call-error result)."]],["UniLM.TYPESAFEServiceEndpoint","UniLM.TYPESAFEServiceEndpoint",["TypeSafe System One API endpoint (model family Jev). Requires the TYPESAFE_API_KEY environment variable; TYPESAFE_BASE_URL overrides the API root and TYPESAFE_DEFAULT_MODEL the default model name. It speaks TypeSafeProtocol, and it is the System One backend a call uses when it names none and no with_system_one scope sets another.","This endpoint speaks neither the OpenAI chat wire nor any other chat wire: it declares only :system_one and :models, so ask and list_models accept it while the verbs — chatrequest!, respond, embeddingrequest!, moderate and the other OpenAI platform verbs — reject it up front with an ArgumentError rather than posting a request no server here would answer. A Chat or an Embeddings that names this endpoint can be built only with an explicit model= (without one the constructor throws ArgumentError, since there is no default model to resolve); sending it is refused. TYPESAFEServiceEndpoint() returns the type."]],["Generic Endpoint","Generic-Endpoint",["OllamaEndpoint and its options are on the Ollama page."]],["UniLM.GenericOpenAIEndpoint","UniLM.GenericOpenAIEndpoint",["Configurable endpoint for any OpenAI-compatible API provider. Supports Chat Completions, Embeddings, FIM, transcription and (where the provider implements it) the Responses API.","Fields",'An empty key, given or read, sends no Authorization header: use "" for local servers with no auth.',"A request goes out with its fields as set and under their own names, except on Mistral's host, as MistralEndpoint() is: there a Chat's max_completion_tokens goes out as max_tokens (taken over a max_tokens also set), its seed as random_seed, and an Embeddings request's dimensions as output_dimension, the names Mistral's references give them.","Example"]],["UniLM.ServiceEndpointSpec","UniLM.ServiceEndpointSpec",["Type alias accepting both marker types (OPENAIServiceEndpoint) and instances (GenericOpenAIEndpoint(...)). Used as the type of service fields. The field-less built-in endpoints — OPENAIServiceEndpoint, AZUREServiceEndpoint, GEMINIServiceEndpoint, GEMINIOpenAIServiceEndpoint, TYPESAFEServiceEndpoint — are passed as types: calling one, OPENAIServiceEndpoint(), returns the type."]],["UniLM.MistralEndpoint","UniLM.MistralEndpoint",['Pre-configured endpoint for Mistral AI API. A given api_key is sent as is; without one the key is read from MISTRAL_API_KEY each time a request is built (GenericOpenAIEndpoint("https://api.mistral.ai", "", "MISTRAL_API_KEY")), so building the endpoint needs no key and a missing variable fails the request, naming it. Requests go out under Mistral\'s names: a Chat\'s max_completion_tokens as max_tokens, its seed as random_seed, an Embeddings request\'s dimensions as output_dimension (GenericOpenAIEndpoint).']],["UniLM.DeepSeekEndpoint","UniLM.DeepSeekEndpoint",["Pre-configured endpoint for DeepSeek API. Supports chat completions, tool calling, FIM completion, and prefix completion.","api_key::Union{String,Nothing}: a given key is sent as is; nothing (the default) reads DEEPSEEK_API_KEY each time a request is built, so building the endpoint needs no key and a missing variable fails the request, naming it.","FIM and prefix completion use the beta base URL (https://api.deepseek.com/beta)."]],["Configuration","Configuration",["Each endpoint reads its configuration from environment variables:","OpenAI (default)","Azure OpenAI","A registration made with add_azure_deploy_name! wins over the variable; a model with neither fails the call with an ArgumentError (in the result's cause) naming the variable to set. Azure's newer v1 API (no api-version) is not wrapped by AZUREServiceEndpoint; see The v1 API for reaching it through GenericOpenAIEndpoint (untested).","Google Gemini","Both GEMINIServiceEndpoint (native generateContent) and GEMINIOpenAIServiceEndpoint (the OpenAI-compat shim) read GEMINI_API_KEY.","Anthropic (Claude)","TypeSafe (System One / Jev)"]],["Azure Deployment Mapping","Azure-Deployment-Mapping",["Azure requires model-to-deployment name mappings. Use add_azure_deploy_name! to register custom mappings:"]],["UniLM.add_azure_deploy_name!","UniLM.add_azure_deploy_name!",["Register an Azure OpenAI deployment for a given model name. Without a registration the deployment is read from AZURE_OPENAI_DEPLOY_NAME_<MODEL> (model id upper-cased, other characters mapped to _) when a request is built.","Example"]],["Selecting a Backend","Selecting-a-Backend",["Pass the service keyword to any request constructor:"]],["Extension API","extension_api",["The functions a new backend adds methods to, and the stream-state types its handlers mutate. They are declared public but not exported: qualify them (UniLM.get_url) when adding methods. Write your own backend walks through both cases — an OpenAI-compatible provider (routing and authentication only) and a provider with its own wire (the chat and agentic seams). Pre-1.0, this contract can still change in a minor release, under the CHANGELOG's Breaking heading.","Routing, authentication and defaults","provider_capabilities (exported) is the capability hook: an endpoint that defines it opts into validation against that set.","Chat wire seam","Agentic wire seam","System One protocols","A System One backend is reached through a protocol, a Holy trait of its endpoint: UniLM.system_one_protocol maps the endpoint to a UniLM.SystemOneProtocol, whose UniLM.encode_system_one turns a request into a UniLM.SystemOneWire — what is sent, and the record_body a recording is keyed on — refusing before any I/O what the backend cannot carry — and whose UniLM.decode_system_one turns the reply into a typed result. Three protocols ship: UniLM.TypeSafeProtocol (TypeSafe's POST /v1/systemone), UniLM.OpenAIDecisionsProtocol (OpenAI's POST /v1/decisions, for OPENAIServiceEndpoint) and UniLM.OllamaSystemOneProtocol (Ollama's POST /v1/systemone, for OllamaEndpoint). They are documented with the System One API.","A server that speaks TypeSafe's wire — a gateway, a proxy, a mock — needs no protocol code. To send TYPESAFEServiceEndpoint's requests there, set TYPESAFE_BASE_URL. To give it an endpoint of its own, declare :system_one, its base URL and its credentials; an endpoint without a system_one_protocol method speaks TypeSafeProtocol:","Its requests are TypeSafe's, byte for byte, and its recordings are keyed as TypeSafe's — on the request's path and body, never its host — so an answer recorded through one replays for the other."]],["UniLM.get_url","UniLM.get_url",["The URL a request is sent to. get_url(chat), get_url(emb) and get_url(r::Respond) dispatch on the request's service, so a backend adds get_url(::MyEndpoint, ::Chat) (and, for the surfaces it serves, ::Embeddings or ::Respond): dispatch on the instance for an endpoint with fields, on ::Type{MyEndpoint} for a singleton. The built-in methods return the provider's documented URLs.","Public extension API (not exported); see the Custom Backends guide."]],["UniLM.auth_header","UniLM.auth_header",["The headers sent with every request to service: its credentials, where it takes any, and the Content-Type. A backend adds auth_header(::MyEndpoint) (or auth_header(::Type{MyEndpoint}) for a singleton endpoint). A built-in endpoint that takes a key sends the key it was given, or else reads its key variable from the environment when a request is built, so a missing variable surfaces in the verb's call-error result, naming it: as a KeyError, or for TYPESAFEServiceEndpoint as an ArgumentError naming the variable, which a blank value gets too. An OllamaEndpoint sends no credentials (a local server takes none), except to Ollama's cloud, https://ollama.com, which gets OLLAMA_API_KEY as a Bearer token, read here, a missing or blank one an ArgumentError naming the variable (these are the headers of its inference requests; its model verbs go without the key when it is unset); and a GenericOpenAIEndpoint whose key is empty sends no Authorization header.","Public extension API (not exported); see the Custom Backends guide."]],["UniLM.default_model","UniLM.default_model",["Return the default chat/completions model for the given service endpoint. Returns nothing for generic and user-defined endpoints (model must be specified explicitly; Chat then throws an ArgumentError when it is not). A backend adds default_model(::MyEndpoint) to make model= optional for it.","Public extension API (not exported); see the Custom Backends guide."]],["UniLM.encode_request","UniLM.encode_request",["Serialize chat into the provider's request body. The OpenAIWireEndpoint default emits OpenAI Chat Completions JSON. An ArgumentError thrown here — an option the provider or model cannot express — is local validation: chatrequest! calls the encoder before any network I/O and lets it propagate.","Public extension API (not exported); see the Custom Backends guide."]],["UniLM.decode_response","UniLM.decode_response",["Parse a provider's 200 response into (; message::Message, usage::Union{TokenUsage,Nothing}, model::Union{String,Nothing}): the reply, its token usage, and the model id the provider reports having served it (nothing when it reports none), which becomes the result's model and prices the call. model is optional: a decoder that returns (; message, usage) reports no model. So are logprobs and moderation, the reply's log probabilities and moderation results (Dict{String,Any} or nothing), which become the result's fields of those names. The OpenAIWireEndpoint default reads OpenAI Chat Completions (extract_message). A body that is not a valid reply should throw: chatrequest! reports the exception as an LLMCallError carrying it in cause, never as an empty success.","Public extension API (not exported); see the Custom Backends guide."]],["UniLM.handle_sse_event!","UniLM.handle_sse_event!",["Per-provider chat-streaming event handler — the seam that replaces decode_stream_chunk (removed in 0.11.3). Called by the stream driver once per complete data: payload, with the current SSE event name. Mutates state and returns","Text deltas are appended to BOTH state.content and state.pending_delta (the driver forwards the latter to the streaming callback). Throwing on an undecodable payload is safe: the dispatcher logs the payload, counts it in the result's sse_dropped and drops it, the rest of the stream is read, and a stream that ends without its turn is an LLMFailure. The OpenAIWireEndpoint default reads OpenAI Chat Completions chunks and ends at [DONE]; a provider without a sentinel (native Gemini) never returns :done, and its stream ends at EOF with state.finish_reason recorded.","Public extension API (not exported): a backend adds a method for its own service type (dispatch is on the first argument); see the Custom Backends guide. A streamed chatrequest! on an endpoint with no method throws the MethodError for this function before anything is sent, as a missing encode_request does, and so does a streamed respond on one with no decode_agentic_stream."]],["UniLM.StreamState","UniLM.StreamState",['Mutable accumulator for one streamed chat attempt, filled by handle_sse_event! and read by the stream driver. A handler appends text to both content and pending_delta (the driver forwards the latter to the streaming callback), refusal text to refusal, and records finish_reason, usage (a TokenUsage), the model the provider reports having served (the result\'s model; nothing when it reports none) and, for an in-band error, the decoded payload in error. service_tier holds the billed tier a chunk (or the response head) reported, for a handler whose provider reports it apart from the usage, and continuation_token the token a provider returns for continuing a long generation in another request. audio is filled by the OpenAI-wire handler only, from a streamed audio reply\'s delta.audio updates, and becomes the message\'s AudioOutput; a handler of another wire leaves it nothing. logprobs and moderation become the result\'s fields of those names: each token list a chunk gives extends the list of its name ("content", …), a list only ever given as null stays nothing, and each moderation object\'s results are merged in. Tool calls live in tool_calls by index as Dict("id" => …, "type" => "function", "function" => Dict("name" => …, "arguments" => …)); "complete" => true on an entry tells the driver the call has finished streaming. The raw_* fields capture provider-native content blocks for verbatim round-trip, and sse_dropped counts undecodable payloads. A retried attempt starts from a fresh state.',"Public extension API (not exported); see the Custom Backends guide."]],["UniLM.encode_agentic","UniLM.encode_agentic",["Serialize r into the request body of service's agentic surface. The OpenAIWireEndpoint default emits OpenAI Responses JSON; a backend with its own agentic wire overrides it (the Gemini Interactions backend is the in-repo reference). An ArgumentError thrown here — a field the wire cannot express — is local validation: respond calls the encoder before any network I/O and lets it propagate.","Public extension API (not exported); see the Custom Backends guide."]],["UniLM.decode_agentic","UniLM.decode_agentic",["Parse service's 200 response into the neutral ResponseObject, whose output uses the OpenAI Responses item shapes the accessors read. A body that is not a valid response should throw: respond and the lifecycle operations report the exception as a ResponseCallError carrying it in cause.","Public extension API (not exported); see the Custom Backends guide."]],["UniLM.decode_agentic_stream","UniLM.decode_agentic_stream",["Streaming half of the agentic wire seam: consume one raw read's bytes, mutate state (an AgenticStreamState; text deltas go to both textbuff and pending_delta), and return (; done, event, data, terminal): done is true at a terminal event, terminal is :completed, :failed, :incomplete or :error, and data holds that event's decoded payload. Default: OpenAI Responses SSE via _parse_response_stream_chunk.","A raw read can hold several payloads, so the method drops an undecodable payload itself and counts it in state.sse_dropped, as the built-in methods do; an exception it throws ends the streamed respond as a ResponseCallError with the exception in cause.","Public extension API (not exported); see the Custom Backends guide. A streamed respond on an endpoint with no method throws the MethodError for this function before anything is sent, as a streamed chatrequest! does for a missing handle_sse_event!."]],["UniLM.AgenticStreamState","UniLM.AgenticStreamState",["Public extension API (not exported); see the Custom Backends guide.","Mutable per-stream assembly state for the agentic streaming seam (decode_agentic_stream). Carries the layer-1/2 SSE machinery state (carry partial-line buffer, last_event sticky event name), the accumulated output text (textbuff), the not-yet-forwarded text deltas (pending_delta), the per-stream drop count (sse_dropped), and — for providers whose terminal event omits the step list (Gemini Interactions) — a per-index registry of assembled steps: steps maps a step index to its (mutable) step dict, and order records first-seen index order for deterministic output rebuilding. text_by_step holds each step's streamed string (answer text, function-call argument JSON, or thought signature, depending on the step type), read once when the interaction completes."]]]},{url:"/api/files/",sections:[["Files API",null,["Upload, list, retrieve, and delete files, and download their content. Files feed the Responses file_search and code-interpreter tools, the Batch API, and fine-tuning. OpenAI only."]],["Request Type","Request-Type",[]],["UniLM.FileUpload","UniLM.FileUpload",['A file-upload request. file is a path on disk; purpose is one of "assistants", "batch", "fine-tune", "vision", "user_data". Any other purpose throws ArgumentError, "evals" naming the Evals API\'s shutdown on 2026-11-30.']],["Parsed Objects","Parsed-Objects",[]],["UniLM.FileObject","UniLM.FileObject",['A file stored by the Files API: id, bytes, created_at, filename, purpose, and status; raw holds the unparsed JSON response. bytes is nothing when the reply gives the size as null, which OpenAI\'s Files reference allows "In a completed file upload response, … when the file size is not yet available". A reply without id, bytes, created_at, filename or purpose, each of which the reference requires, is no file: the call returns its call error, a FileCallError (from complete_upload, an UploadCallError).']],["UniLM.FileList","UniLM.FileList",["A page of FileObjects from list_files; has_more signals that further pages are available."]],["Result Types","Result-Types",[]],["UniLM.FileSuccess","UniLM.FileSuccess",["Successful upload/retrieve result wrapping a FileObject."]],["UniLM.FileListSuccess","UniLM.FileListSuccess",["Successful list_files result wrapping a FileList."]],["UniLM.FileContentSuccess","UniLM.FileContentSuccess",["Successful file_content result; content holds the raw file bytes."]],["UniLM.FileDeleteSuccess","UniLM.FileDeleteSuccess",["Successful delete_file result: the service confirmed (deleted is always true) the removal of id."]],["UniLM.FileFailure","UniLM.FileFailure",["Files API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.FileCallError","UniLM.FileCallError",["Files API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout."]],["Request Functions","Request-Functions",[]],["UniLM.upload_file","UniLM.upload_file",["Upload a file (multipart/form-data). Returns FileSuccess, FileFailure, or FileCallError.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply). Like every other create, an upload is never retried: a POST that timed out, or drew a gateway 5xx after the backend stored the file, may still have created it, and a second attempt would store it twice. A FileFailure/FileCallError therefore does not prove that no file was created."]],["UniLM.list_files","UniLM.list_files",["List uploaded files. Returns FileListSuccess, FileFailure, or FileCallError.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_file","UniLM.retrieve_file",["Retrieve a file's metadata. Returns FileSuccess, FileFailure, or FileCallError.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.delete_file","UniLM.delete_file",["Delete a file. Returns FileDeleteSuccess, FileFailure, or FileCallError.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.file_content","UniLM.file_content",["Download a file's raw bytes. Returns FileContentSuccess (.content::Vector{UInt8}), FileFailure, or FileCallError. Use save_file_content to write to disk.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.save_file_content","UniLM.save_file_content",["Write downloaded file bytes to path, atomically: the bytes go to a temporary file in the same directory, which is then renamed over path, so a failed write leaves any existing file intact. An existing file keeps its permission bits. A symlink is written through — a dangling one creates its target; a directory throws ArgumentError."]],["Usage","Usage",[]]]},{url:"/api/fine_tuning/",sections:[["Fine-tuning API",null,["OpenAI restricts new jobs to eligible existing customers. Job creation ends January 6, 2027; inference remains available until the base model retires. See OpenAI's availability schedule.",'Create, retrieve, cancel, and list fine-tuning jobs, and list a job\'s events and checkpoints. Training and validation data is uploaded via the Files API with purpose="fine-tune". OpenAI only.']],["Objects","Objects",[]],["UniLM.FineTuningJob","UniLM.FineTuningJob",["A fine-tuning job: id, status, model, and fine_tuned_model (the resulting model name once training completes); raw holds the unparsed JSON response."]],["UniLM.FineTuningList","UniLM.FineTuningList",["A page of records from list_fine_tuning_jobs, list_fine_tuning_events, or list_fine_tuning_checkpoints; data holds the raw JSON entries and has_more signals that further pages are available."]],["Result Types","Result-Types",[]],["UniLM.FineTuningSuccess","UniLM.FineTuningSuccess",["Successful create/retrieve/cancel result wrapping a FineTuningJob."]],["UniLM.FineTuningListSuccess","UniLM.FineTuningListSuccess",["Successful list result wrapping a FineTuningList."]],["UniLM.FineTuningFailure","UniLM.FineTuningFailure",["Fine-tuning API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.FineTuningCallError","UniLM.FineTuningCallError",["Fine-tuning API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout."]],["Request Functions","Request-Functions",[]],["UniLM.create_fine_tuning_job","UniLM.create_fine_tuning_job",['Create a fine-tuning job. training_file is a file id from upload_file(path, "fine-tune"). method is e.g. Dict("type"=>"supervised", "supervised"=>Dict("hyperparameters"=>...)).',"Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_fine_tuning_job","UniLM.retrieve_fine_tuning_job",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.cancel_fine_tuning_job","UniLM.cancel_fine_tuning_job",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.list_fine_tuning_jobs","UniLM.list_fine_tuning_jobs",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.list_fine_tuning_events","UniLM.list_fine_tuning_events",["List a job's events, a page at a time: limit sets the page size and after the last event id of the previous page (see has_more on the result).","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.list_fine_tuning_checkpoints","UniLM.list_fine_tuning_checkpoints",["List a job's checkpoints, a page at a time: limit sets the page size and after the last checkpoint id of the previous page (see has_more on the result).","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["Usage","Usage",[]]]},{url:"/api/images/",sections:[["Image Generation API",null,["Types and functions for generating and editing images: OpenAI's Images API (/v1/images/generations, /v1/images/edits) and Gemini's native image generation (Nano Banana) through generateContent, chosen by the request's service."]],["Request Type","Request-Type",["Construction","JSON Serialization","A Gemini request serializes to its generateContent body; the model, gemini-nano-banana-2.1 unless set, goes in the URL:","A field the other provider owns is refused before anything is sent:"]],["UniLM.ImageGeneration","UniLM.ImageGeneration",["An image-generation request for generate_image. It goes to OpenAI's Images API (/v1/images/generations), or, with service=GEMINIServiceEndpoint, to Gemini's generateContent with image output (Nano Banana). Each field below says which provider takes it.","Fields — both providers","Fields — OpenAI only","Fields — Gemini only","Gemini's image controls:","A field the request's provider does not take (an OpenAI-only field on Gemini; aspect_ratio or resolution on OpenAI), n other than 1 on Gemini, a Gemini aspect_ratio or resolution outside the lists above, and a safety_identifier outside its provider's rule throw ArgumentError naming the provider and the field — when the request is serialized, and in generate_image before any request. Other OpenAI values are sent as given, for OpenAI to judge. input_fidelity is an image-edit parameter: set it on ImageEdit, not here.","Examples"]],["UniLM.ImageEdit","UniLM.ImageEdit",['An image-edit request for edit_image: the image(s) at image (a path, or a vector of paths) changed as prompt asks. OpenAI is sent multipart/form-data at /v1/images/edits; GEMINIServiceEndpoint is sent generateContent with each image as an inline part ahead of the prompt, its format read from the file\'s bytes (PNG, JPEG, GIF or WebP). model left "" is the service\'s default image model ("gpt-image-2.5-sunburst" on OpenAI, "gemini-nano-banana-2.1" on Gemini), resolved when the edit is sent.',"Fields — both providers","image and model (above); service, prompt, n and safety_identifier, as on ImageGeneration: Gemini takes n=1 only.","Fields — OpenAI only","Fields — Gemini only","aspect_ratio and resolution, as on ImageGeneration; unset, the edited image follows the input's aspect ratio.","image names at least one file: edit_image throws ArgumentError for an empty vector before any request, as it does, naming the provider and the field, for a field the request's provider does not take, n other than 1 on Gemini, a Gemini aspect_ratio or resolution outside its list, and a safety_identifier outside its provider's rule. Other OpenAI values are sent as given, for OpenAI to judge."]],["Response Types","Response-Types",[]],["UniLM.ImageObject","UniLM.ImageObject",["A single generated image from the API response.","Fields"]],["UniLM.ImageResponse","UniLM.ImageResponse",["Parsed response from the Image Generation API.","Accessors","Fields"]],["Result Types","Result-Types",[]],["UniLM.ImageSuccess","UniLM.ImageSuccess",["Successful image generation. Access the parsed response via .response.","Examples"]],["UniLM.ImageFailure","UniLM.ImageFailure",["HTTP-level failure from the Image Generation API: the raw response body, the status code, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.ImageCallError","UniLM.ImageCallError",["Exception-level error during an Image Generation API call (network, timeout, or a 200 that could not be parsed — on Gemini, one that holds no image). cause is the underlying exception — a UniLMTimeout for a timeout — and request_id is set when a reply arrived but could not be decoded."]],["Request Function","Request-Function",["Usage Examples"]],["UniLM.generate_image","UniLM.generate_image",["Send an image-generation request: to OpenAI's Images API, or, for service=GEMINIServiceEndpoint, to Gemini's models/{model}:generateContent, asking for image output only and sizing the image by imageConfig when aspect_ratio or resolution is set (Gemini image generation).","Returns ImageSuccess, ImageFailure, or ImageCallError. A Gemini reply's image parts become its ImageObjects, in order, each carrying the text the model sent, if any, as revised_prompt; the interim images of the model's thinking are not among them. A Gemini 200 that holds no image is an ImageCallError naming Gemini's finish reason (such as IMAGE_SAFETY or NO_IMAGE).","Throws ArgumentError before any network I/O when ig.service does not declare :images (an endpoint type that declares no capabilities at all included), and when the request sets a field its provider does not take, n other than 1 on Gemini, a Gemini aspect_ratio or resolution outside its list, or a safety_identifier outside its provider's rule (see ImageGeneration). Other OpenAI values are sent as given.","Examples","Pass config::Union{Nothing,RequestConfig} to override the timeout/retry budget for this call.","Pass cancel::Union{Nothing,CancelToken} (default: the ambient with_cancel token) to make the call cancellable: once the token is cancelled it returns an ImageCallError whose cause is a UniLMCancelled — without sending anything when the token was already cancelled, at once when mid-request (never retried).","Convenience method: create an ImageGeneration from a prompt + keyword arguments and send it. config and cancel go to the request, as for generate_image(ig).","Examples"]],["UniLM.edit_image","UniLM.edit_image",["Edit/extend image(s) under a text prompt — on OpenAI's Images API, or on Gemini's generateContent for service=GEMINIServiceEndpoint. Returns the same ImageSuccess/ImageFailure/ImageCallError shapes as generate_image, and a Gemini reply decodes the same way.","Throws ArgumentError before any network I/O when e.service does not declare :image_edits (an endpoint type that declares no capabilities at all included), when e.image is an empty vector, when an input image or the mask is no file (as upload_file and transcribe refuse one), and when the request sets a field its provider does not take, n other than 1 on Gemini, a Gemini aspect_ratio or resolution outside its list, or a safety_identifier outside its provider's rule (see ImageEdit). Other OpenAI values are sent as given.","Pass config::Union{Nothing,RequestConfig} to override the timeout/retry budget for this call, and cancel::Union{Nothing,CancelToken} to make it cancellable exactly as for generate_image: a cancelled call returns an ImageCallError whose cause is a UniLMCancelled."]],["Accessor Functions","Accessor-Functions",["Saving Images"]],["UniLM.image_data","UniLM.image_data",["The image payloads of a response, one per generated image: the base64 data, or — for an image the service delivered by URL — its url (download it; only base64 data can go to save_image). An entry carrying neither is skipped.",'On an ImageFailure or ImageCallError this throws an LLMResultError, as text does: a call that did not succeed has no images, and an empty list would read as "zero images generated".',"Examples"]],["UniLM.save_image","UniLM.save_image",["Decode a base64-encoded image and save it to a file.","Decoding happens before filepath is opened, so a malformed payload raises without touching whatever already lives there — a failed save costs nothing.","Examples"]],["Parameters Reference","Parameters-Reference",["Defaults shown as quoted strings other than model are the API's defaults for an omitted field; the struct stores nothing and omits them from the request body. A field set for the provider that does not take it throws ArgumentError naming the provider and the field. input_fidelity and mask are edit parameters (OpenAI): set them on ImageEdit — ImageGeneration does not accept them."]]]},{url:"/api/mcp/",sections:[["MCP Client & Server",null,["Types and functions for the Model Context Protocol — connecting to MCP servers and building MCP servers in Julia. Both sides negotiate MCP revisions 2025-11-25 (preferred), 2025-06-18 and 2025-03-26; the 2026-07-28 revision is not supported yet. A session runs one call at a time in arrival order, and a call's timeout bounds its wait for the session too (MCPTimeoutError phase :queue); over HTTP, serve runs handlers concurrently. See the MCP guide and Concurrency, Tasks and Cancellation."]],["Client Types","Client-Types",[]],["UniLM.MCPSession","UniLM.MCPSession",["A live connection to an MCP server. Manages lifecycle, transport, and cached tool/resource/prompt lists.","Create via mcp_connect. Disconnect via mcp_disconnect!.","Requests are serialized: each call (its liveness/respawn check, id allocation and request/response exchange) holds the session, and callers are served in arrival order. Interleaved server → client frames are handled in place (notifications skipped, server ping requests answered). A caller's per-call bound (timeout, default mcp_request_timeout) also covers its wait for the session: a caller that cannot acquire it in time raises MCPTimeoutError with phase :queue without touching it. Once acquired, the exchange gets its full bound, measured from that moment — a waiter's clock never tears down the exchange in progress. After the server sends notifications/tools/list_changed, tools_stale is true until the next list_tools!.","Cancellation depends on the transport. Over HTTP every request observes the ambient with_cancel token: a cancel ends the call promptly with UniLMCancelled — after a best-effort notifications/cancelled for its request, bounded to 2 s — and the session stays usable. A stdio exchange is not interruptible: it ignores the token and is bounded by mcp_request_timeout. mcp_disconnect! tears down under a cancelled token too."]],["UniLM.MCPToolInfo","UniLM.MCPToolInfo",["A tool definition received from an MCP server via tools/list. Convert to CallableTool via mcp_tools or mcp_tools_respond."]],["UniLM.MCPToolResult","UniLM.MCPToolResult",["The typed result of a call_tool call, mirroring an MCP tools/call result. A tool-execution error (isError: true on the wire) is reported here as data (is_error == true), not thrown, so callers can distinguish it from a JSON-RPC protocol error (which still throws MCPError).","Fields","The mcp_tools / mcp_tools_respond bridges surface this to a tool-calling loop: content on success (falling back to a JSON encoding of structured when content is empty), or a raised error carrying content when is_error."]],["UniLM.MCPResourceInfo","UniLM.MCPResourceInfo",["A resource definition received from an MCP server via resources/list."]],["UniLM.MCPPromptInfo","UniLM.MCPPromptInfo",["A prompt definition received from an MCP server via prompts/list."]],["UniLM.MCPServerCapabilities","UniLM.MCPServerCapabilities",["Capabilities declared by an MCP server during initialization."]],["UniLM.MCPTransport","UniLM.MCPTransport",["Abstract type for MCP transport implementations. Subtypes must implement:","A custom transport must bound its own IO: the connect and per-call bounds are enforced by the stdio transport's watchdog and inside the HTTP transport's requests, and a custom transport's connect handshake and exchanges run without either — an unbounded read in one blocks its caller, and every caller queued behind it, indefinitely."]],["UniLM.StdioTransport","UniLM.StdioTransport",["Stdio transport: launches a subprocess and communicates via stdin/stdout. Messages are newline-delimited JSON-RPC 2.0. stderr is where the server's own stderr goes — an IO (e.g. devnull) or a file path, appended to; nothing inherits this process's stderr."]],["UniLM.HTTPTransport","UniLM.HTTPTransport",["Streamable HTTP transport: communicates via POST requests to an MCP endpoint. Handles Mcp-Session-Id header for session management. Each transport keeps its own connection pool and never reuses a connection that has been idle for more than a second, so a server that closes idle keep-alive connections cannot fail the next request."]],["UniLM.MCPError","UniLM.MCPError",["Error from MCP protocol operations. Contains the JSON-RPC error code, message, and the optional data member from the server — any JSON value, nothing when absent."]],["UniLM.MCPCrashError","UniLM.MCPCrashError",["The stdio MCP server process exited or its stdio pipe broke. The session is closed with cause :crash; with auto_respawn=true the next call respawns the server, otherwise it errors naming the opt-in.","Fields","Best-effort diagnostics: both exitcode and termsignal are nothing when the process had not been reaped within a brief settle window after the failure surfaced (or was still alive with a broken pipe)."]],["UniLM.MCPSessionClosedError","UniLM.MCPSessionClosedError",["The session is closed, or its transport is not connected, so the call never reached the server.","Fields","A stdio session closed by :timeout or :crash respawns its server instead of raising this when it was connected with auto_respawn=true."]],["Client Functions","Client-Functions",["Lifecycle","Discovery","Operations","Tool Bridge"]],["UniLM.mcp_connect","UniLM.mcp_connect",["Connect to an MCP server via stdio transport (subprocess). stderr is where the server's stderr goes — an IO such as devnull, or a file path (appended to); nothing (the default) inherits this process's stderr. A respawned server keeps the same setting.","config::Union{Nothing,RequestConfig} is resolved (config if given, else the ambient/process default) and captured on the session: config.mcp_connect_timeout bounds the spawn→initialize handshake, config.mcp_request_timeout is the default per-call bound (it covers the wait for the session and then the exchange). A stdio request timeout is session-fatal — killing the server is the only way to release a read blocked on an unresponsive one — as is a server crash; with auto_respawn=true the next call respawns the server (same command, fresh handshake — in-memory server state is lost), otherwise it raises MCPSessionClosedError. A stdio exchange is not interruptible: it ignores a with_cancel token, and mcp_request_timeout is what bounds it.","The server runs in its own process group. Disconnecting (or a fatal timeout) tears it down: stdin EOF, then SIGTERM, then a SIGKILL of the whole group. If its group leader exits on its own, the rest of the group is killed at once; and servers still running when this process exits are torn down by an exit hook.","Example","Connect to an MCP server via HTTP transport.","config::Union{Nothing,RequestConfig} is resolved (config if given, else the ambient/process default) and captured on the session: config.mcp_connect_timeout bounds the connect step, config.mcp_request_timeout is the default per-call bound. A per-call timeout is not session-fatal over HTTP; the timed-out request is cancelled with a best-effort notifications/cancelled. Every request observes the ambient with_cancel token: a cancelled call raises UniLMCancelled promptly, its request is cancelled the same way, and the session stays usable.","Example","Connect to an MCP server via the given transport. Performs initialization handshake and populates tool cache; client_name/client_version are sent as clientInfo. config (a RequestConfig, default: the ambient configuration) is resolved and captured on the session — its mcp_connect_timeout bounds this handshake and mcp_request_timeout bounds each later call (the wait for the session, then the exchange). auto_respawn=true lets a stdio session closed by a request timeout or a server crash respawn its server (same command, captured config) and retry the next call once. A custom MCPTransport must bound its own IO (see MCPTransport).","Do-block form: automatically disconnects after the block executes.","Example"]],["UniLM.mcp_disconnect!","UniLM.mcp_disconnect!",["Gracefully disconnect from the MCP server.","Takes the session lock, so a disconnect racing a call in flight WAITS for that exchange to finish instead of tearing the transport down under its reader — the same concurrency-1 semantics every other call obeys. The wait stays bounded transitively: the exchange ahead runs under its own mcp_request_timeout. Every later call on the session raises MCPSessionClosedError with cause :disconnected."]],["UniLM.list_tools!","UniLM.list_tools!",["Fetch the tool list from the MCP server. Handles pagination via cursor. Stores result in session.tools.","timeout::Union{Nothing,Float64} overrides the per-call bound for this call (kwarg > ambient with_request_config > session-captured config; Inf disables; NaN, ≤ 0 and finite values above 1e9 s are rejected). The whole listing — every page and the cache update — holds the session once, so a list_changed another caller receives meanwhile is recorded after the refresh and leaves tools_stale set."]],["UniLM.list_resources!","UniLM.list_resources!",["Fetch the resource list from the MCP server. Handles pagination."]],["UniLM.list_prompts!","UniLM.list_prompts!",["Fetch the prompt list from the MCP server. Handles pagination."]],["UniLM.call_tool","UniLM.call_tool",["Call a tool on the MCP server and return its result as an MCPToolResult.","content concatenates text content parts (non-text parts JSON-encoded); structured carries the server's structuredContent verbatim; parts is the raw content array. A tool-execution error (isError: true) is returned with is_error == true — it is not thrown. JSON-RPC protocol errors still throw MCPError.","timeout::Union{Nothing,Float64} overrides the per-call bound for this call (kwarg > ambient with_request_config > session-captured config; Inf disables; NaN, ≤ 0 and finite values above 1e9 s are rejected). It bounds the wait for the session — calls on one session run one at a time, in arrival order; a call that cannot acquire it in time raises MCPTimeoutError with phase :queue — and then, from acquisition, the exchange itself (phase :request).","Over HTTP the call observes the ambient with_cancel token: a cancel raises UniLMCancelled promptly (a token cancelled before the call sends nothing) and tells the server with a best-effort notifications/cancelled, bounded to 2 s; the session stays usable. Over stdio the exchange is not interruptible — it ignores the token and timeout bounds it."]],["UniLM.read_resource","UniLM.read_resource",["Read a resource from the MCP server."]],["UniLM.get_prompt","UniLM.get_prompt",["Get a rendered prompt from the MCP server. Returns the messages array."]],["UniLM.ping","UniLM.ping",["Send a ping to the MCP server. Throws on error."]],["UniLM.mcp_tools","UniLM.mcp_tools",["Convert all tools from an MCP session into CallableTool{Tool} instances that work directly with tool_loop! (Chat Completions API) on service, the endpoint the tools go to.",'Each tool\'s callable invokes call_tool(session, name, args) under the hood. Tool names are advertised provider-safe: a function name takes letters, digits, _ and -, so any other character of an MCP name (e.g. the dots in admin.tools.list) becomes _, and at most the length service\'s provider gives — 128 characters for ANTHROPICServiceEndpoint (^[a-zA-Z0-9_-]{1,128}$), GEMINIServiceEndpoint and DeepSeekEndpoint ("a maximum length of 128"), 64 for OPENAIServiceEndpoint (its Chat Completions reference: "a maximum length of 64") and for any other endpoint. A longer name is cut to that limit less 9 characters, followed by _ and the first 8 hex digits of the SHA-256 of its MCP name, so names that agree up to the cut stay apart. The callable still calls the tool by its MCP name. Two tools whose names map to the same alias raise an ArgumentError.',"Example"]],["UniLM.mcp_tools_respond","UniLM.mcp_tools_respond",["Convert all tools from an MCP session into CallableTool{FunctionTool} instances that work directly with tool_loop (Responses API) on service, the endpoint the tools go to. Tool names are advertised provider-safe for service, as in mcp_tools. OpenAI's Responses API and Gemini's Interactions API state no function-name limit of their own: the limit applied is the provider's Chat one (64 on OpenAI, 128 on Gemini), unwitnessed on those two APIs.","Example"]],["Server Types","Server-Types",[]],["UniLM.MCPServer","UniLM.MCPServer",["An MCP server that can host tools, resources, and prompts.","Register primitives via register_tool!, register_resource!, register_prompt!, or the @mcp_tool, @mcp_resource, @mcp_prompt macros. Registration is thread-safe: it may run while serve is dispatching.","Start serving via serve.","Example"]],["UniLM.MCPServerPrimitive","UniLM.MCPServerPrimitive",["Abstract supertype for MCP server-side primitives (tools, resources, prompts)."]],["UniLM.MCPServerTool","UniLM.MCPServerTool",["A tool registered on an MCP server. The handler receives Dict{String,Any} arguments and returns any value (converted to text content by the server).","Fields"]],["UniLM.MCPServerResource","UniLM.MCPServerResource",["A static resource registered on an MCP server.","Fields"]],["UniLM.MCPServerResourceTemplate","UniLM.MCPServerResourceTemplate",["A URI-templated resource. Template variables like {path} are extracted and passed to the handler.","Fields"]],["UniLM.MCPServerPrompt","UniLM.MCPServerPrompt",["A prompt template registered on an MCP server.","Fields"]],["Server Functions","Server-Functions",["Registration","Serving","Macros"]],["UniLM.register_tool!","UniLM.register_tool!",["Register a tool on the MCP server with an explicit JSON Schema.","handler(args::Dict{String,Any}) receives the client's arguments object (a tools/call whose arguments is not an object is answered with JSON-RPC -32602 and never reaches it). An exception it raises is NOT a protocol error: the message is relayed to the client as tool content with isError: true, so a model can see the failure and correct itself. Write handlers with that in mind — raise with a message you are willing to show both the model and the client, and never one carrying secrets or internals. Errors below the handler (in dispatch itself) answer a generic JSON-RPC -32603 instead, with the detail going to the server's logs. An InterruptException is never converted, even inside the TaskFailedException of a task the handler waited on: it propagates. Neither is a ReplayMissError — a request the handler made inside with_recorded_answers that has no recording — nor a RecordingWriteError — a paid answer the handler's scope could not record: the client gets the generic -32603 and the server logs the error, since neither is a mistake the model can correct, and no local path reaches the client.","Over HTTP, handlers run concurrently — one task per request, on the default thread pool — so a handler must be thread-safe. Over stdio they run one at a time, with the process stdout pointed at stderr (see serve).","Register a tool whose input schema is inferred from handler's positional parameters (names and declared types of its first method). Each tools/call binds the client's arguments object to those parameters BY NAME — the binding @mcp_tool generates: a parameter whose type admits nothing (Union{T,Nothing}) is optional and binds nothing when omitted, every other parameter is required, and a value must have its parameter's JSON type (a string for String or Symbol, an integral number for an integer type, a number for a float type, a boolean for Bool, an array for a Vector{T} and an object for a Dict{String,T}, whose elements convert to T the same way). A call that violates this never reaches the handler: it is answered with a tool result carrying isError: true and a text naming the argument, the MCP report for an input validation error, so the model can correct its call.","A handler taking one dictionary is the explicit-schema calling convention, and a variadic handler has no parameter names to bind: both are rejected with an ArgumentError — register them with an explicit input_schema.","Example","Register a CallableTool{Tool} on the MCP server, bridging from UniLM's Chat Completions tool type.","Register a CallableTool{FunctionTool} on the MCP server, bridging from UniLM's Responses API tool type."]],["UniLM.register_resource!","UniLM.register_resource!",["Register a static resource on the MCP server."]],["UniLM.register_resource_template!","UniLM.register_resource_template!",["Register a URI-templated resource on the MCP server."]],["UniLM.register_prompt!","UniLM.register_prompt!",["Register a prompt template on the MCP server."]],["UniLM.serve","UniLM.serve",["Start the MCP server using the specified transport.","Transports","initialize answers the protocol revision the client requested when it is supported, otherwise the latest supported one.","Robustness contract",'Both transports cap an incoming frame (stdio) or request body (HTTP) at 16 MiB and answer an oversized one — stdio with JSON-RPC -32600, HTTP with 413 Payload Too Large — rather than parsing it: parsing an attacker-sized payload allocates a multiple of it, which is an out-of-memory kill rather than a protocol error. Any unhandled error while dispatching a request — including an exception from a resource or prompt handler — is answered with a generic -32603 "Internal error" and logged locally, so one bad frame cannot take the transport down and no exception text (file paths, argument values) reaches the peer. Tool-handler exceptions are excluded: they reach the client as tool results — see register_tool! — except a ReplayMissError or a RecordingWriteError, which is answered and logged like any other dispatch error. An InterruptException is never converted into an answer, even inside the TaskFailedException of a task a handler waited on: it propagates. A JSON-RPC response sent to the server is accepted without an answer (HTTP: 202).',"Examples"]],["UniLM.@mcp_tool","UniLM.@mcp_tool",["Register a tool on server with auto-generated JSON Schema from the function signature.","Each tools/call binds the arguments object to the parameters BY NAME. A typed parameter is required; an untyped one is optional and binds nothing when omitted. A value must have its parameter's JSON type — a string for String, an integral number for an integer type (5.0 binds 5), a number for a float type, a boolean for Bool; other declared types pass through unconverted. A missing required argument or a value of the wrong type never reaches the function: it is answered with a tool result carrying isError: true whose text names the argument.","Example"]],["UniLM.@mcp_resource","UniLM.@mcp_resource",["Register a resource or resource template on server. If the URI contains {...} placeholders, it is registered as a template.","Examples"]],["UniLM.@mcp_prompt","UniLM.@mcp_prompt",["Register a prompt on server. The handler should return a Vector of message Dicts.","Example"]],["Example","Example",[]]]},{url:"/api/models/",sections:[["Model Listings",null,["list_models asks OpenAI, Anthropic or Gemini which models it serves your key, and returns each as a ProviderModel: the id a request names, the provider's display name, the token limits, the capabilities the provider reports, and the lifecycle dates — when the model was released, when it was deprecated, and when it retires or shuts down. Anthropic and Gemini answer in pages, and list_models fetches every page. A listing bills no tokens."]],["What each provider reports","What-each-provider-reports",["A dash reads as nothing, or an empty Dict for capabilities. Times are in UTC, and Anthropic's timestamps give their UTC date for deprecated and retires; the Unix epoch, which Anthropic gives for an unknown release date, reads as no created at all. Each entry keeps the provider's object in raw, and the success keeps every page's body in its own raw.","A listing is the provider's view for the key that asks, so two accounts can see different models. Anthropic lists active and deprecated models, not retired ones — its lifecycle field, in raw, says which — and may still revise a retires_at it lists. OpenAI keeps listing a model after its shutdown_date, so a listed model is not always one that still answers: compare retires with today's date before relying on it.","The Anthropic capabilities are the ones UniLM's request checks encode for each Claude model — the thinking types it accepts (adaptive, disabled, between_tools) and its effort levels — so they show what a request may set on a model UniLM has no rule for."]],["Results","Results",["A missing key, a network failure, a timeout or a cancel gives a ModelListCallError, and so does a reply that is not the documented listing; an error status on any page gives a ModelListFailure. list_models is documented with the System One verbs: on TypeSafe it lists the Jev models and aliases, on an OllamaEndpoint the models a server has installed."]],["UniLM.ProviderModel","UniLM.ProviderModel",["One model a provider lists (list_models on OPENAIServiceEndpoint, ANTHROPICServiceEndpoint or GEMINIServiceEndpoint):"]],["UniLM.ModelListSuccess","UniLM.ModelListSuccess",["Successful list_models result on OpenAI, Anthropic or Gemini: the ProviderModels of every page, in the order listed, and raw, the parsed body of each page in the order fetched."]],["UniLM.ModelListFailure","UniLM.ModelListFailure",["list_models error result on OpenAI, Anthropic or Gemini: HTTP status, the raw response body, and the request_id the provider sent (x-request-id/request-id header), if any. An error status on any page is the listing's failure."]],["UniLM.ModelListCallError","UniLM.ModelListCallError",["list_models call on OpenAI, Anthropic or Gemini that produced no listing (a missing key, no connection, a timeout, a cancel, or a reply that is not the documented listing); cause is the underlying exception — a UniLMTimeout for a timeout, a UniLMCancelled for a cancel."]]]},{url:"/api/moderations/",sections:[["Moderations API",null,["Classify text and images for policy violations, returning per-category flags and confidence scores. Moderation is free. OpenAI only."]],["Parsed Objects","Parsed-Objects",[]],["UniLM.ModerationResult","UniLM.ModerationResult",["One classification result: flagged (any policy violation), categories (per-category booleans), and category_scores (per-category confidence); raw holds the unparsed JSON result."]],["UniLM.ModerationResponse","UniLM.ModerationResponse",["A moderation response: results, one ModerationResult per input, and the model used; raw holds the unparsed JSON response."]],["Result Types","Result-Types",[]],["UniLM.ModerationSuccess","UniLM.ModerationSuccess",["Successful moderate result wrapping a ModerationResponse."]],["UniLM.ModerationFailure","UniLM.ModerationFailure",["Moderations API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.ModerationCallError","UniLM.ModerationCallError",["Moderations API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout."]],["Functions","Functions",[]],["UniLM.moderate","UniLM.moderate",["Classify input (a String, a vector of strings, or a vector of multi-modal content parts) for policy violations (free). Returns ModerationSuccess, ModerationFailure, or ModerationCallError. A 200 whose results array does not hold exactly one row per input (one row for a string or a parts vector, one per string of a string vector) is a ModerationCallError: a verdict that cannot be matched to its input is no verdict.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.is_flagged","UniLM.is_flagged",["True if any moderation result is flagged. Works on ModerationResult/ModerationResponse/ModerationSuccess.","A call that did not succeed has no verdict, so ModerationFailure and ModerationCallError throw an ArgumentError rather than answering false: in the usual is_flagged(moderate(text)) && reject() shape, a false from a failed call would wave unmoderated content straight through. Check issuccess first, or handle the throw, and decide explicitly what an unavailable verdict should mean."]],["Usage","Usage",[]]]},{url:"/api/nl_dispatch/",sections:[["Natural-Language Dispatch",null,["Dispatch on Meaning is the how-to. nl_classify, nl_dispatch and @branch each send one ask request, whose answers, errors and limits are documented in System One API. Like ask, they run on the backend a call names with service, else on the one of the enclosing with_system_one scope, else on TypeSafe's Jev. The provider options ask takes as keywords they take as options, a NamedTuple — options = (long_context = true,) on TypeSafe — checked by the backend's wrapper before the request; a call that names no service and no options takes the scope's.","@branch is a switch whose cases are written in plain language. The option names become the criteria of one choice question about the state; the winning option selects which expression is evaluated and the other bodies never run. However many options a branch lists, it costs a single request.","nl_dispatch lifts the same idea into the method table, in two spellings that send the same request. With texts = TABLE, methods dispatch on short keys — Val{:billing}, your own types or instances, enum values — and the ordered table holds the sentence the model reads for each key; the keys never leave the process. With nl\"...\", the sentence is itself a Meaning type written in the signature. Either way nl_dispatch sends one Choice question per such position — again in a single request — turns each answer back into the key or the Meaning instance and calls the function, so Julia's own dispatch selects the method and the remaining arguments still dispatch on their types. nl_classify asks the same question over a table and returns the key itself, without dispatching. All three act on an answer through a decision policy, and all three take on_response, which sees the whole SystemOneSuccess — request id, model, raw body — before the policy runs. The default policy gates on confidence: below min_confidence @branch takes its _ line and nl_dispatch and nl_classify call fallback, and with neither they raise LowConfidenceError rather than act on a near-tie. The default min_confidence is 0, which acts on every answer, near-ties included: set it, or pass decide, to hand unsure answers elsewhere. decide replaces the gate with any function of the ChoiceAnswer that returns an offered option — not only the winner — or nothing to decline, which takes the same fallback or raises DecisionDeclinedError. A question the backend declines to answer — a RefusalAnswer, which OpenAI's Decisions API may send — is a decline no policy sees: the fallback runs, or DecisionDeclinedError carries the refusal. meanings(f) is the union of the options of every natural-language method of f; meanings(f, Tuple{…}) lists the ones a call with ordinary arguments of those types sends, in the order it sends them. Both take the same texts a keyed call does.","Before any request, the inputs of a call are checked. min_confidence must be a finite number in 0 … 1: anything else, NaN included, is an ArgumentError. A @branch option name is a String, or a Symbol sent as its String; any other value is an ArgumentError naming its line. How many options one question may offer — a table's entries, a branch's lines — is the backend's limit (255 on TypeSafe). And the state nl_dispatch builds from its ordinary arguments must be data: a function, a type, a module, a Ref or Ptr, a Task, a Channel, a lock, a condition, an event, an IO, an Expr or a value JSON.jl cannot write, such as an AudioAttachment, anywhere in an argument, or a container nested more than 64 levels deep, is an ArgumentError naming the argument and the path to the value. An ImageAttachment is data: the backend's wrapper sends it as it sends any image in a state — TypeSafe as an asset — or refuses it before the request, as OpenAI's and Ollama's do in a state built from arguments. Everything else is sent as JSON.jl writes it — every field of a struct argument, a credential held as a String included — and a :record scope of with_recorded_answers writes it to disk: pass state = … to send only what the model should read. An explicit state is sent as given.",'A Meaning type prints as Julia prints any type, Meaning{Symbol("…")} (for a sentence of several words; one word prints as Meaning{:x}) — in a MethodError or a methods(f) listing too — and an instance as nl"…"(). Two identical sentences are the same type, so === compares them, and meanings lists the sentences as strings.']],["UniLM.Meaning","UniLM.Meaning",["A natural-language description lifted into the type domain: S is a Symbol holding the description itself, and Meaning{S} is a zero-field singleton, so it costs nothing at run time and can appear in an ordinary method signature.",'Write the type with the @nl_str string macro — nl"the customer wants a refund" is Meaning{Symbol("the customer wants a refund")} — and the instance with nl"..."() or Meaning(text).',"Dispatching on a Meaning is ordinary Julia dispatch: nothing about the type reaches the network. Only nl_dispatch talks to the service, and only to turn a piece of state into the Meaning instance to call with."]],["UniLM.@nl_str","UniLM.@nl_str",["The Meaning type for that description, so it reads as a type wherever one is expected:",'Append () for the instance: nl"the customer wants a refund"(). The text is interned as the type parameter, so two identical descriptions are the same type and === compares them.',"The macro performs no interpolation and no escaping — the description is taken verbatim, which is what the model is shown."]],["UniLM.@branch","UniLM.@branch",["A natural-language switch. The option names are sent as the criteria of ONE choice question about state; the selected option's expression is the only one evaluated, and its value is the value of the macro.",'Each line is option => expression. A bare left-hand side is the option name — the text the model actually reads and the text the answer returns. The 2-tuple form ("name", "description") attaches a longer description to that name; it is the only way to do so. Left-hand sides are ordinary expressions evaluated once, in source order, so an option name may be computed. A name is a String, or a Symbol sent as its String; any other value is an ArgumentError naming its line, before the request.',"A final _ => expression line is the fallback taken when the decision policy declines: the winner's confidence is below min_confidence, or decide returned nothing. It requires one of the two: without a policy nothing is ever declined and the line would be unreachable, so that spelling is rejected at macro-expansion time. A policy that cannot decline when the branch runs — decide = nothing, or a min_confidence of 0 or less — leaves the line just as unreachable, and is an ArgumentError before the request. A backend that declines the question itself — a RefusalAnswer, which OpenAI's Decisions API may send — takes the _ line too, or throws DecisionDeclinedError without one; decide is not called.","Keywords go between the state and the block, written key = value:","confidence is computed over the options offered — (n\xb7p_max − 1)/(n − 1), clamped to 0 … 1, for n of them (Confidence) — so the same min_confidence is a different bar whenever the option list changes. decide replaces the threshold with any policy over the full distribution; a threshold is itself the policy a -> a.confidence >= τ ? a.choice : nothing, so giving both is an error.","An unknown keyword, a block that is not begin ... end, a line that is not option => expression, no options at all, two _ lines, a _ that is not last, or decide together with min_confidence is an ArgumentError raised while the macro expands, so it surfaces when the surrounding code is loaded rather than when the branch is first reached. A decide that returns anything but an option name or nothing is an ArgumentError, and no body runs. A non-success call throws SystemOneError; the branch is never guessed. A cancelled call is one of those: its result is a SystemOneCallError whose cause is a UniLMCancelled, and no body runs."]],["UniLM.nl_dispatch","UniLM.nl_dispatch",["Resolve the natural-language arguments of f against a piece of state and call the method Julia's own dispatch selects.",'f is an ordinary generic function whose methods pin one or more positions to a concrete Meaning — written nl"..." in the signature. One choice question per such slot goes out in a single request; each answer becomes a Meaning instance, those instances are spliced back into the positions they came from, args fill the rest in order, and f is called. The remaining arguments still dispatch normally, so a natural-language slot composes with ordinary type-based dispatch.',"Only meanings the call can reach are offered: a slot's options come from the natural-language methods that accept the types of args, and meanings(f, argtypes) previews them exactly as they will be sent. Types no such method accepts are an ArgumentError. So is a gap — a combination of offered meanings with no method, or with an ambiguous one, which meaning_gaps lists — because an answer landing on it would be billed and then end in a MethodError. Define the missing methods, or add a method that is wild in every slot (f(::Meaning, ::Meaning, x)), which is not an option and covers every combination that has no method; an ambiguous combination needs a method for the intersection of the methods it collides on, which the error names. Both are raised before any request. The options and this check are worked out once per type of f, types of args and state of the method table, so a method defined later is offered from the next call on.",'The state is state when given, otherwise a JSON.Object{String,Any} built from args in argument order, keyed by the argument names of the first natural-language method (an unnamed position becomes "arg<index>"), so the same arguments always make the same request. With no ordinary arguments there is nothing to describe, so state is then required.',"Every value of that state is sent as JSON.jl writes it — every field of a struct argument, a credential held in one included — and a :record scope of with_recorded_answers writes it to disk with the request: pass state to send only what the model should read. A value that is not data is an ArgumentError before the request, naming the argument, the path to the value and its type: a function or closure, a type, a module, a Ptr or other Ref, a Task, a Channel, a lock, a condition, an event, an IO, an Expr, or a value JSON.jl cannot write (such as an AudioAttachment), in the argument or anywhere in its dicts, arrays, sets, tuples and fields. So is a container nested more than 64 levels deep, where the check stops. An ImageAttachment is data: the backend's wrapper sends it as it sends the images of any state (TypeSafe as an asset), or refuses it before the request. An explicit state is sent as given.",'Each slot\'s question is named after that argument (an unnamed one becomes "meaning_<index>") and carries instructions: nothing for a generic default, a String for every slot, or a Vector with one entry per slot.',"A decision policy turns the answers into meanings. The default is the argmax gated by min_confidence: below it, fallback is called with the caller's args if given, and otherwise LowConfidenceError is thrown. A fallback that cannot be called with arguments of the types of args is an ArgumentError before any request, and so is a min_confidence that is not a finite number in 0 … 1, NaN included. confidence is computed over the options offered — (n\xb7p_max − 1)/(n − 1), clamped to 0 … 1, for n of them (Confidence) — so the same threshold is a different bar whenever the option list changes, including with the types of args. decide replaces the gate: one callable for every slot, or a Vector with one per slot, each called with that slot's ChoiceAnswer and returning an offered meaning — any of them, not only the argmax — or nothing to decline. Every slot is decided before anything is called; if any declined, fallback runs, or DecisionDeclinedError is thrown for the first declined slot. A slot whose question the backend declined to answer — a RefusalAnswer, which OpenAI's Decisions API may send — is declined without calling its policy, and its error is a DecisionDeclinedError whatever the policy. Any other return is an ArgumentError, and neither f nor fallback runs. decide with a nonzero min_confidence is an ArgumentError before any request: a threshold is itself the policy a -> a.confidence >= τ ? a.choice : nothing.","on_response is called once with the SystemOneSuccess as soon as the request has succeeded, before the policy runs: audits get request_id, model and raw from its response — which decide cannot see. Its return value is ignored; an exception from it propagates, and neither f nor fallback runs. It is not called when nothing was sent, nor for a failed call, whose result the thrown SystemOneError carries. A value that cannot be called on a SystemOneSuccess is an ArgumentError before the request.","options are the request's provider options, a NamedTuple of what ask takes as keywords ((long_context = true,) on TypeSafe); none given, a call that names no service takes those of the enclosing with_system_one scope. The backend's wrapper checks them before the request.","A non-success call throws SystemOneError — including one cancelled through cancel::Union{Nothing,CancelToken} (default: the ambient with_cancel token), whose result is a SystemOneCallError with a UniLMCancelled cause; f is then never called.","Keys and a table of sentences",'With texts, the methods of f dispatch on short keys, and a table maps each key to the sentence the model reads. Only the sentences are sent — the request is byte for byte the one the same sentences written as nl"..." would make — and the chosen sentence maps back to its key locally, so no key reaches the model:',"A table is a NamedTuple of sentences or a vector of key => sentence pairs, with no sentence or key twice, and as many entries as the backend lets one question offer (255 on TypeSafe, checked before the request) — two keys are the same when their dispatched values are isequal, as :a and Val(:a) are. A Dict is refused: it has no order, and option order is part of what the model reads. nothing and missing cannot be keys: a policy returns nothing to decline, and missing compares as neither true nor false. A Symbol key is passed as Val(key); a Val or other singleton instance (Refund()), a type (Refund) or an enum value is passed as written, so methods on ::Refund, ::Type{<:Billing} or an enum type select through ordinary dispatch, and a table of leaf keys reaches the most specific method of a type hierarchy. A table fills the one position whose declared type its keys have (::Any declares none); several keyed positions take a Tuple of tables, one per position. The call has length(args) positional arguments plus one per table, and only the methods of that arity take part; one of them pinning a Meaning is an ArgumentError, since a call uses meanings in signatures or texts, not both. Each keyed position is a slot as above — one question, and one entry of an instructions or decide vector, in position order. The question names and the state's keys come from the first of those methods, in definition order, that pins a table (declares a type its keys have), as they come from the first natural-language method for meanings: a catch-all route(k, t) defined before it names nothing.","Every key must be taken at its position by some method whatever the other arguments are: a key none takes is an ArgumentError before any request, naming the method that would take it, such as route(::Val{:shipping}, _) — a catch-all route(k, t) takes every key. Options then follow the types of args as above, but in table order, where meanings in signatures are offered in definition order; gaps are refused the same way. decide may also return the key of an offered sentence as the table writes it (:refund, not Val(:refund)). Plans are cached by the tables' contents as well. meanings and meaning_gaps take the same texts, and nl_classify returns the chosen key without dispatching."]],["UniLM.nl_classify","UniLM.nl_classify",["Classify state against ONE table of key => sentence entries and return the chosen key as the table writes it: :refund for a NamedTuple table — the Symbol, not Val(:refund) — and the instance, type or enum value otherwise. It is the keyed form of nl_dispatch without the dispatch.",'One ask goes out, with one choice question named "classify" whose options are every sentence of the table, in table order, with no descriptions and the default instructions of nl_dispatch unless instructions, a String, is given; state is sent as given. The keys never reach the model. The table is checked as nl_dispatch checks it — a Dict, an empty table or one longer than the backend accepts (255 on TypeSafe), a blank sentence, a sentence or key given twice, or a key no signature could name is an ArgumentError before the request — and a tuple of tables is an ArgumentError too.',"The decision policy is that of nl_dispatch: the argmax gated by min_confidence, or decide, called with the ChoiceAnswer and returning an offered sentence, a key as the table writes it, or nothing to decline — not both. A declined answer calls fallback(state) when given, and otherwise throws LowConfidenceError or DecisionDeclinedError for the question \"classify\"; any other verdict is an ArgumentError, and fallback does not run. A refusal by the backend — a RefusalAnswer, which OpenAI's Decisions API may send — is a decline that no policy sees: it calls fallback(state), or throws DecisionDeclinedError. A fallback that cannot be called with state is an ArgumentError before the request, and so is a min_confidence that is not a finite number in 0 … 1, NaN included. A non-success call throws SystemOneError. on_response is called once with the SystemOneSuccess before the policy runs — audits get request_id, model and raw from its response, which decide cannot see — and options are the request's provider options, as they are for nl_dispatch."]],["UniLM.meanings","UniLM.meanings",["The natural-language options f dispatches on, keyed by positional argument index. Each vector lists the distinct descriptions defined for that slot in definition order, the order in which nl_dispatch sends them.","Definition order is the order in which the methods were defined as the code ran: at the REPL, in a script, or in a package loaded from source (--compiled-modules=no). A precompiled package defines all of its methods at once when it loads, and those are ordered by source file path and then line — which is not include order when one function's meanings span several files. Keep each function's meanings in one file.","Methods of f without a concrete Meaning argument are not part of the natural-language interface and do not appear. f with no such method at all is an ArgumentError.","This is the union over every natural-language method. A call offers only the meanings whose method accepts its ordinary arguments; meanings(f, argtypes) previews that.","With texts — a table of key => sentence entries, or a tuple of them, as nl_dispatch takes it — the options are sentences: each table's position maps to every sentence of the table, in table order. With no call to take an arity from, the arity is the one at which the methods of f declare arguments for the keys; when several arities do, pass argtypes. The tables and their positions are checked as a call checks them — each table is validated as nl_dispatch validates it, its keys must fill one position of its own, no method of that arity may pin a Meaning, and some method must take every key at its position — and a failure is an ArgumentError. The combinations of keys are not checked: meaning_gaps(f, argtypes; texts) lists those with no method, which a call refuses before its request.","The options nl_dispatch offers when its ordinary arguments have the types in argtypes — one entry per ordinary argument, in order, such as Tuple{String}, or Tuple{} when every argument is a meaning. A slot's options are the distinct descriptions of the natural-language methods whose signature accepts those types, in definition order as meanings(f) defines it; an abstract type admits only the methods that accept all of it.","A tuple type of the wrong length is an ArgumentError, and so are types no natural-language method accepts — nl_dispatch refuses such a call before any request.","With texts, a keyed position offers the sentences whose keys a method accepts there together with those types — and, at other keyed positions, some entry of their tables — in table order: exactly the options nl_dispatch(f, args...; texts) sends. A key accepted only with other types is not offered, and is no error."]],["UniLM.meaning_gaps","UniLM.meaning_gaps",["The combinations of meanings nl_dispatch would offer for ordinary arguments of the types in argtypes — as meanings(f, argtypes) lists them — that no method of f covers. Each gap holds one description per slot, slots in position order; gaps are listed with the first slot varying slowest. A combination whose call is ambiguous is a gap too: Julia could not call it either.","nl_dispatch runs this check before its request and sends nothing while a gap exists, because an answer landing on one would be billed and then end in a MethodError; its error tells the two kinds apart. Close a missing combination by defining its method, with every slot pinned to a meaning, or add a method that is wild in every slot, such as f(::Meaning, ::Meaning, x): it is not an option, and it covers every combination that has no method. It does not settle an ambiguity, not being more specific than the methods that collide: close an ambiguous combination with a method for their intersection, which the error spells out.","With texts, a gap holds one sentence per keyed position. A missing combination is closed by a method for its keys, or by a catch-all such as f(_, _, x); a method may also take any key at one position and pin a key at another, as ordinary dispatch allows."]],["UniLM.LowConfidenceError","UniLM.LowConfidenceError",["Thrown when a natural-language branch or dispatch resolved to an option whose confidence fell below the threshold the caller required, and no fallback was given.",'A Choice answer always names a winner, even when the distribution is nearly flat; confidence is what separates "the state clearly matches this option" from "this option won by a nose". Raising the threshold therefore converts a silent mis-route into a loud failure. answer is the full ChoiceAnswer, so probabilities is available for a diagnostic or a second-best policy.',"Supply a _ fallback line to @branch, or the fallback keyword of nl_dispatch, to handle the case instead of raising. A threshold is one decision policy; the decide keyword of both takes any other."]],["UniLM.DecisionDeclinedError","UniLM.DecisionDeclinedError",['Thrown when the decide policy of nl_dispatch or @branch returned nothing for an answer — it declined to act on it — and no fallback was given. question names the question ("branch" for @branch); answer is the full ChoiceAnswer the policy saw.',"A refusal is a decline by the backend: when the backend declined to answer the question — a RefusalAnswer, which OpenAI's Decisions API may send for any question — and no fallback was given, this error is thrown whatever the policy, with that RefusalAnswer as answer; no policy sees it.","Supply a _ fallback line to @branch or the fallback keyword of nl_dispatch, or return an offered option from the policy, to handle the case. A min_confidence threshold raises LowConfidenceError instead."]],["Usage","Usage",["A non-success call raises SystemOneError instead of resolving to a branch, and a combination of offered meanings that no method covers is an ArgumentError raised before any request — meaning_gaps lists such gaps without a request."]]]},{url:"/api/ollama/",sections:[["Ollama",null,["A local Ollama server: the endpoint, its runtime options, and the model-management verbs. The Ollama entry shows them at work."]],["Endpoint","Endpoint",[]],["UniLM.OllamaEndpoint","UniLM.OllamaEndpoint",["A local (or remote) Ollama server. Chat and Embeddings requests use Ollama's native /api/chat and /api/embed, which carry what the OpenAI-compatible routes ignore: the context window and the other OllamaOptions, how long the model stays loaded (keep_alive), and the think and truncate fields. respond, compact_response, FIMCompletion and transcribe use the OpenAI-compatible routes (/v1/responses, /v1/responses/compact, /v1/completions, /v1/audio/transcriptions), which carry none of the endpoint's keep_alive, OllamaOptions or runner.",'A Chat\'s reasoning_effort, and a Respond\'s Reasoning effort, go to Ollama by name: "none" turns thinking off (think: false), and every other effort is sent as it is, for Ollama to resolve against the model, whose thinking levels are its own (thinking). On /api/chat, a model with thinking metadata applies a level it names and uses its default for any other name; a model without takes "low", "medium", "high" and "max", and answers another name, such as "minimal" or "xhigh", with HTTP 400 invalid think value (Ollama 0.40.11). On /v1/responses (OpenAI compatibility), a model without metadata reads "minimal" as "low" and "xhigh" as "max", a model whose levels are true and false takes any effort but "none" as true, and GPT-OSS reads "minimal" as "low" and "xhigh" as "high". model_info reports a model\'s thinking_levels and thinking_default.',"A server of the caller's own gets no API key. Ollama's cloud does: a request to https://ollama.com (which OLLAMA_HOST=ollama.com names) carries the OLLAMA_API_KEY environment variable as Authorization: Bearer whenever it is set, read each time a request is built. Ollama asks for it for inference — \"Direct cloud inference at https://ollama.com/api and https://ollama.com/v1 requires an API key\" (authentication) — and lists the cloud's models without one (cloud). With the variable unset or blank, an inference request (chat, embeddings, respond, compaction, FIM, transcription, System One, a model's load or unload) is not sent — the call error's cause is an ArgumentError naming it — and list_models, model_info, running_models, pull_model and delete_model go without it. Local models cost nothing unless you price them: estimated_cost reports 0.0 for a chat, embeddings, respond or FIM result, without a missing-price warning, unless you gave the model's exact name a row, in pricing= or added to DEFAULT_PRICING; a row UniLM ships for a hosted model never prices a local model that bears its name. A cloud model reached through the local server — a model whose tag is cloud or ends in -cloud (clef:cloud, gpt-oss:120b-cloud) — is billed by Ollama and is priced by the name requested, never as a free local call: a System One, respond or FIM result whose reply drops the tag (gpt-oss:120b) keeps the requested name, and the server's stays in its raw, while a chat or embeddings result is priced by the model its request names; a name missing from the price table logs the missing-price warning. Every model a request to Ollama's cloud itself (https://ollama.com) names is priced the same way: the cloud bills it, and names its models without a tag, \"such as gemma4:31b\" (cloud). Through a local server a model is recognised as cloud by that tag alone, so a cloud model copied under a name without it (ollama cp) is priced as local: 0.0 unless you gave it a row."]],["UniLM.OllamaOptions","UniLM.OllamaOptions",["The Ollama runtime and sampling options that Chat has no field for, sent as the options object of an OllamaEndpoint request; unset options are omitted, so the model's own defaults apply. Options Chat already names (temperature, top_p, seed, stop, max_tokens, presence_penalty, frequency_penalty) stay on the Chat, so no option can be set in two places.",'Every option is passed through unchanged; the effect of those other than num_ctx on the MLX runner is not verified. Ollama\'s API reference also lists penalize_newline and numa, which Ollama 0.40.11 does not read (its log says "invalid option provided", and the request goes on without them), so OllamaOptions has neither.',"The constructor throws ArgumentError for a value out of range: num_ctx, num_batch and num_thread must be positive, top_k non-negative (0 turns top-k off), min_p in [0, 1], typical_p in [0, 1], repeat_penalty and draft_num_predict non-negative, repeat_last_n and num_keep at least -1, num_gpu at least -1 and main_gpu non-negative."]],["Models","Models",["list_models lists a server's installed models when its service is an OllamaEndpoint."]],["UniLM.model_info","UniLM.model_info",["What an Ollama server knows about the installed model name (POST /api/show): an OllamaSuccess holding an OllamaModelInfo — capabilities, context length, thinking levels, Modelfile parameters — or an OllamaFailure (404 for a model that is not installed) or an OllamaCallError. Transient statuses are retried under config (a RequestConfig); cancel (default: the ambient with_cancel token) ends the call with a UniLMCancelled in cause. The endpoint's runner goes with it: Ollama shows the variant it would run with that runner, and answers a model that has none with HTTP 404 no compatible manifest found for runners: <runner> (Ollama 0.40.6). An empty name throws ArgumentError before any request."]],["UniLM.pull_model","UniLM.pull_model",['Download name from the Ollama registry to the server (POST /api/pull). progress(p::OllamaPullProgress) runs once per report the server streams, in order, on the calling task; the last reports "success". Returns OllamaSuccess{Nothing} once the server reports success, an OllamaFailure for a non-200 reply, or an OllamaCallError: the server\'s message for a failure it reports on the stream (an unknown tag: "pull model manifest: file does not exist"), a stream that ends before success, an exception progress threw (in cause), a timeout, or a cancel.',"One attempt, never retried. The response headers must arrive within min(request_timeout, remaining total_deadline) of the RequestConfig; after that only stream_idle_timeout — the longest gap between bytes, time spent in progress excluded — bounds the download, however long it runs. cancel (default: the ambient with_cancel token) stops it at once, with a UniLMCancelled in cause. The endpoint's runner goes with it: by Ollama 0.40.6's source (untested), from a model published for several runners Ollama pulls the variant for that runner, and a model published for another one fails with no compatible manifest found for runners: <runner>. An empty name throws ArgumentError before any request."]],["UniLM.running_models","UniLM.running_models",["The models an Ollama server holds in memory now (GET /api/ps): an OllamaSuccess holding a Vector{OllamaRunningModel} — empty when none is loaded — or an OllamaFailure or OllamaCallError. config and cancel work as for model_info."]],["UniLM.load_model","UniLM.load_model",["Load name into memory now, so the first request does not wait for it. Loads name the way its kind allows (read from model_info): a chat model with an empty chat request, an embedding or decision model with an empty embeddings request (EmbeddingGemma 2 with the 8,192-token window its embeddings requests carry); the reply comes once the model is loaded. The endpoint's keep_alive and runner go with it, and so does what the model's own requests carry: a chat model's load the endpoint's OllamaOptions and shift, an embedding model's those options, and a decision model's no options at all, as System One requests carry none. Ollama loads the model with those settings, so load through the endpoint you will use. On the llama.cpp runner a later request with other options loads the model again; on the MLX runner a loaded model keeps its context when a later request asks for more: unload_model first to load it with another num_ctx. Returns OllamaSuccess{Nothing}, an OllamaFailure (404 for a model that is not installed), or an OllamaCallError, also for a reply that does not report the load. config and cancel work as for model_info; total_deadline bounds the whole call. An empty name throws ArgumentError before any request, and so does an endpoint with keep_alive=0: Ollama reads that request as an unload."]],["UniLM.unload_model","UniLM.unload_model",["Free the memory name holds now rather than when its keep-alive runs out (an empty chat request with keep_alive 0, which works for every kind of model; the endpoint's runner goes with it). Returns OllamaSuccess{Nothing}, an OllamaFailure, or an OllamaCallError, also for a reply that does not report the unload. config and cancel work as for model_info; an empty name throws ArgumentError before any request."]],["UniLM.delete_model","UniLM.delete_model",["Remove the installed model name from an Ollama server's disk (DELETE /api/delete). Returns OllamaSuccess{Nothing}, an OllamaFailure (404 for a model that is not installed), or an OllamaCallError. config and cancel work as for model_info. An empty name throws ArgumentError before any request. There is no undo: pull_model downloads it again."]],["UniLM.OllamaModel","UniLM.OllamaModel",['One model installed on an Ollama server, as list_models reports it (/api/tags): name (e.g. "gemma4:e4b"), size on disk in bytes, content digest, modified_at (the server\'s RFC 3339 text), and from its details family, parameter_size (e.g. "8.0B"), quantization (e.g. "Q4_K_M") and context_length, the longest context the model supports. runner — the runner the server\'s listing names for the model (:mlx, :llamacpp, :ggml), the one an OllamaEndpoint\'s runner must name to reach it, which can differ from the one that serves it once loaded: OllamaRunningModel.runner (/api/ps) reports that — and format (:gguf, :safetensors), as Ollama 0.40 and later report them; nothing when not reported. capabilities holds what the server reports, e.g. :completion, :tools, :insert, :vision, :embedding, :thinking, :image and :audio. A detail the server does not report, or reports empty (""), is nothing; raw holds the unparsed entry.']],["UniLM.OllamaModelInfo","UniLM.OllamaModelInfo",['What model_info reports about one model (/api/show): the name asked for, its capabilities (as for OllamaModel), context_length (the longest context it supports, from its metadata), the thinking_levels it accepts — [false, true] for a model that thinks or not, names such as "low", "medium", "high" for one with levels, empty for a model that cannot think — and thinking_default. parameters are its Modelfile defaults with numbers parsed ("top_k" => 64); a parameter set more than once, such as stop, collects a Vector{String}. family, parameter_size and quantization come from its details, nothing when not reported or empty (""). runner — the runner /api/show\'s details name: :llamacpp or :mlx on Ollama 0.40.6, else nothing (a legacy GGUF model names none: embeddinggemma:latest, and qwen2.5-coder:1.5b-base even shown through an endpoint pinned to :ggml, while list_models reports :ggml for both), which can differ from OllamaModel.runner (/api/tags) and from the runner that serves it once loaded (OllamaRunningModel.runner, /api/ps) — and format (:gguf, :safetensors), as Ollama 0.40 and later report them; nothing when not reported or empty (""). raw holds the whole reply (template, license, model_info, …).']],["UniLM.OllamaRunningModel","UniLM.OllamaRunningModel",['A model loaded in an Ollama server\'s memory, as running_models reports it (/api/ps): name, size (bytes of memory it takes), size_vram (the part in GPU memory), the context_length it was loaded with, and expires_at, when it unloads unless used again (RFC 3339 text). runner — the runner serving it now (:mlx, :llamacpp, :ggml), as Ollama 0.40 and later report it; nothing when not reported or empty (""). raw holds the unparsed entry.']],["UniLM.OllamaPullProgress","UniLM.OllamaPullProgress",['One progress report of pull_model: status ("pulling manifest", "pulling <digest prefix>", "verifying sha256 digest", "writing manifest", "success") and, while a layer downloads, its digest and the completed and total bytes (nothing otherwise). completed is an Int whenever total is: Ollama leaves a zero count out of its report, and it is read back as 0.']],["Results","Results",[]],["UniLM.OllamaSuccess","UniLM.OllamaSuccess",["Successful Ollama model-management result: response holds what the verb reports (nothing for pull_model, load_model, unload_model and delete_model)."]],["UniLM.OllamaFailure","UniLM.OllamaFailure",['Ollama error result: HTTP status, the raw response body (Ollama\'s {"error": …}), and the request_id the server sent (x-request-id/request-id header), if any.']],["UniLM.OllamaCallError","UniLM.OllamaCallError",["Ollama call that produced no usable reply (no server, a timeout, a cancel, a malformed reply, or a failure reported on the pull stream); cause is the underlying exception — a UniLMTimeout for a timeout, a UniLMCancelled for a cancel."]]]},{url:"/api/realtime/",sections:[["Realtime API",null,["Low-latency speech and text over a WebSocket. This client covers the WebSocket event transport and ephemeral client-secret minting; audio is exchanged as base64 PCM inside events. WebRTC media capture and SIP telephony are out of scope. OpenAI only. speak (on OPENAIServiceEndpoint) and translate drive a whole Realtime session for you — a voice session and a translation session — and return typed results; see the Audio API."]],["Bounds","Bounds",["realtime_connect takes a config::Union{Nothing,RequestConfig}, resolves it the usual four ways, and captures it on the session's config field:","Realtime throws rather than returning a typed result value, and realtime_connect makes a single attempt; max_attempts does not apply. Neither the WebSocket open nor realtime_receive observes a CancelToken. mint_realtime_secret is an ordinary HTTP verb that returns typed results: a 200 without a non-empty secret is a RealtimeCallError, and a RealtimeCallError carries its exception in cause and the provider's request_id when one was sent. A minted client secret is a live credential, so RealtimeSecretSuccess redacts it when displayed — read .value programmatically. See Realtime sessions."]],["Session and Result Types","Session-and-Result-Types",[]],["UniLM.RealtimeSession","UniLM.RealtimeSession",["A live Realtime WebSocket session. Created by realtime_connect, which resolves a RequestConfig and captures it on config — realtime_receive reads its stream_idle_timeout from there. The two-argument constructor inherits the ambient config."]],["UniLM.RealtimeSecretSuccess","UniLM.RealtimeSecretSuccess",["Successful mint_realtime_secret result; value is the ephemeral client secret and raw the unparsed JSON response."]],["UniLM.RealtimeFailure","UniLM.RealtimeFailure",["Realtime API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any. Built positionally, response and status alone build one."]],["UniLM.RealtimeCallError","UniLM.RealtimeCallError",["Realtime API call that produced no usable reply (transport failure, timeout, cancel, or a 200 without a secret); cause is the underlying exception — a UniLMTimeout for a timeout, a UniLMCancelled for a cancel — and request_id is the id the service sent with a reply that could not be used."]],["Transport Functions","Transport-Functions",[]],["UniLM.realtime_connect","UniLM.realtime_connect",["Open a Realtime WebSocket and run handler(session::RealtimeSession). Inside the handler use realtime_send to send event dicts and realtime_receive to read server events. The socket closes when handler returns.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this session. ONLY the open phase is bounded, by connect_timeout: a peer that accepts the TCP connection but never completes the upgrade throws UniLMTimeout(:connect, …) instead of blocking forever. Once handler is running the session's lifetime is the caller's to decide, so no bound applies to it. The resolved config travels on the session, so realtime_receive inherits stream_idle_timeout. handler runs on an internal task (that is what makes the open phase separable); dynamically scoped values propagate into it. An upgrade that completes only after the caller received the timeout is closed without calling handler.","Throws ArgumentError before any I/O for a service other than OPENAIServiceEndpoint: the Realtime WebSocket is served by api.openai.com, and another endpoint's credentials must not be sent there."]],["UniLM.realtime_send","UniLM.realtime_send",[]],["UniLM.realtime_receive","UniLM.realtime_receive",["Block for the next server event, bounded by the session's stream_idle_timeout. A parked read cannot be polled out of, so a breach ends the read and the connection and throws UniLMTimeout(:stream_idle, …); the session is closed after it. Neither needs a lock, so a realtime_send parked on a peer that stopped reading cannot hold the bound open (that send then throws too). On a ws:// connection the breach surfaces just after the limit; on wss:// it can surface up to about 5 s later, the time the TLS close may wait to send its close notice. A session built on a WebSocket opened over the caller's own stream (HTTP.WebSockets.open(io)) keeps that stream, which is the caller's to close: the breach ends the read, and a send parked on that stream stays parked until the caller closes it."]],["Event Builders","Event-Builders",[]],["UniLM.realtime_event","UniLM.realtime_event",[]],["UniLM.session_update","UniLM.session_update",[]],["UniLM.input_audio_append","UniLM.input_audio_append",[]],["UniLM.response_create","UniLM.response_create",[]],["Client Secret","Client-Secret",[]],["UniLM.mint_realtime_secret","UniLM.mint_realtime_secret",["Create an ephemeral client secret for client-side Realtime connections (POST /v1/realtime/client_secrets). session is an optional session-config dict. Returns RealtimeSecretSuccess (.value), RealtimeFailure, or RealtimeCallError.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["Usage","Usage",["The session shape follows OpenAI's Realtime client events (session.type, output_modalities, output audio under session.audio.output)."]]]},{url:"/api/responses/",sections:[["Responses API",null,["Types and functions for the Responses API — the newer, more flexible alternative to Chat Completions."]],["Request Type","Request-Type",["Construction"]],["UniLM.Respond","UniLM.Respond",["Configuration struct for an OpenAI Responses API request.","Key Fields","On OPENAIServiceEndpoint the encoder also applies OpenAI's per-model rules (reasoning efforts, sampling controls, prompt_cache_retention) to those GPT-6 and GPT-5.6 models, by exact id or a dated snapshot, before any request; other models are checked by the server. Ultrafast is served by gpt-6-astra and gpt-6.1-sol alone, so \"ultrafast\" throws ArgumentError on every other model, an unknown one included. See OpenAI's GPT-6 guide. Build a Respond with keywords: the positional form takes all 32 fields in declaration order.","Examples"]],["Response Object","Response-Object",[]],["UniLM.ResponseObject","UniLM.ResponseObject",["Parsed response from the Responses API.","Accessors"]],["Result Types","Result-Types",[]],["UniLM.ResponseSuccess","UniLM.ResponseSuccess",["Successful response from the Responses API. Access the parsed response via .response."]],["UniLM.ResponseFailure","UniLM.ResponseFailure",['A failure from the Responses API: an HTTP status other than 200, or a response whose status is "failed" (read by respond, get_response or cancel_response), whose status field is then 200. Contains the response body, status code, and optional request ID.']],["UniLM.ResponseCallError","UniLM.ResponseCallError",["Exception-level error during a Responses API call (network, parsing, etc.)."]],["Accessor Functions","Accessor-Functions",[]],["UniLM.output_text","UniLM.output_text",['Extract the text of the response\'s answer: the output_text parts of its messages, joined by " ". A message the model labels phase: "commentary" — an intermediate update, such as a preamble before a tool call — is not part of the answer and is left out, so a turn that stops at its commentary has no text yet; a message without a phase counts. On a ResponseFailure or ResponseCallError it throws an LLMResultError — there is no model output to return; guard with issuccess.',"Examples"]],["UniLM.function_calls","UniLM.function_calls",["Extract function call outputs from a response.",'Each dict contains: "id", "call_id", "name", "arguments" (JSON string), "status".',"Examples"]],["UniLM.url_citations","UniLM.url_citations",["URL-citation annotations on outputtext parts: those of an answer grounded by OpenAI's `websearchor by Gemini Interactions'googlesearch([geminigooglesearch](@ref)). Each is the provider's ownurlcitationdict; Gemini counts itsstartindexandendindex` in bytes of the answer's text."]],["UniLM.web_search_results","UniLM.web_search_results",["Raw web_search_call output items (request results via include)."]],["UniLM.file_search_results","UniLM.file_search_results",["Raw file_search_call output items."]],["UniLM.image_generation_results","UniLM.image_generation_results",["Base64 image results from image_generation_call output items."]],["UniLM.code_interpreter_outputs","UniLM.code_interpreter_outputs",["Raw code_interpreter_call output items."]],["UniLM.mcp_call_outputs","UniLM.mcp_call_outputs",["Raw mcp_call output items."]],["UniLM.mcp_approval_requests","UniLM.mcp_approval_requests",["Raw mcp_approval_request output items (feed back via mcp_approval_response)."]],["UniLM.reasoning_summaries","UniLM.reasoning_summaries",["Reasoning-summary text from each reasoning output item (OpenAI Responses) and each thought step (Gemini Interactions)."]],["UniLM.reasoning_items","UniLM.reasoning_items",["Raw reasoning output items."]],["UniLM.refusals","UniLM.refusals",["Refusal messages from any refusal content part of the output messages."]],["UniLM.response_status","UniLM.response_status",["The response's lifecycle status string (e.g. completed, requires_action); failed/error for non-success results."]],["UniLM.incomplete_details","UniLM.incomplete_details",["Why a response is incomplete (the API's incomplete_details object), or nothing."]],["UniLM.usage_details","UniLM.usage_details",["The response's raw token-usage dict; see token_usage for the typed TokenUsage."]],["Request Functions","Request-Functions",[]],["UniLM.respond","UniLM.respond",["Send r to the agentic API of r.service: the Responses API of OpenAI, of an OllamaEndpoint or a GenericOpenAIEndpoint server, or of an endpoint type of your own, or Gemini Interactions on GEMINIServiceEndpoint.","Returns ResponseSuccess, ResponseFailure, or ResponseCallError. Inside a with_recorded_answers scope the request passes through the recordings, streamed or not, and one the scope cannot replay throws ReplayMissError instead of returning a ResponseCallError; a streamed response whose recording cannot be written throws RecordingWriteError inside the returned task, so fetch raises a TaskFailedException whose task.exception is that error.","Per-call config::RequestConfig overrides timeouts and the retry budget (max_attempts); the process/scoped defaults apply otherwise.","For streaming, set stream=true and pass a callback:","Setting close[] = true — in the callback or from any other task — stops the stream at once with ResponseCallError(status=nothing, cause=UniLMCancelled(:callback, …)), unless the provider's completion marker — the terminal event — already arrived: then the outcome it recorded stands (a response with its usage, whose final callback has already run; or the failure the event reported). An exception thrown by the callback ends the call with that exception in cause, never retried. Time spent in the callback does not count toward stream_idle_timeout. A user InterruptException during a stream is not swallowed — it rethrows inside the task and surfaces as a TaskFailedException at fetch — and neither is the ReplayMissError or RecordingWriteError of a recorded call made in the callback, nor either of them or an interrupt that the callback throws inside a wrapper (task.exception is what the callback threw).","cancel::Union{Nothing,CancelToken}: a CancelToken; nothing resolves the ambient token of with_cancel, at call entry. A cancel at any point — before connecting, during the response-header wait, mid-stream, or during a retry backoff — ends the call with ResponseCallError(status=nothing, cause=UniLMCancelled(:token, …)), never retried — unless the terminal event already arrived, as for close[] = true above. A pre-cancelled token sends nothing. A TCP connect or TLS handshake already in progress cannot be interrupted (HTTP.jl 2.7.1), so a cancel during one takes effect when it completes or reaches connect_timeout.","Local validation throws ArgumentError before any network I/O, streaming or not: when callback is passed without r.stream === true (it runs only on a stream, so it would be ignored), when r.service is an endpoint type that declares its capabilities and lists neither :responses (OpenAI wire) nor :agentic (Gemini Interactions), or when the provider's encoder rejects the request (e.g. an option the provider or model does not support). A streamed call on an endpoint type with no decode_agentic_stream method throws that function's MethodError before any network I/O too, as a streamed chatrequest! does for a missing handle_sse_event!.","Examples","Convenience method: create a Respond from input + keyword arguments and send it.","Examples","do-block form for streaming. Automatically sets stream=true.","Examples"]],["UniLM.get_response","UniLM.get_response",['Retrieve an existing response by its ID: a ResponseSuccess, or a ResponseFailure when the response\'s status is "failed", as respond returns it. OpenAI keeps a stored response (store=true, the default) "for at least 30 days, subject to the data retention exceptions"; the data of a background request made with store=false is "temporarily stored to support asynchronous execution and polling", and OpenAI\'s background guide names two exceptions: a Zero Data Retention project\'s "Background requests … run with store=false", their data kept "for roughly 10 minutes", and in a Modified Abuse Monitoring project "Background responses are retained after the polling period only when store=true is explicitly provided" (background mode). get_response reads a response while OpenAI holds it, and not once it is deleted. An endpoint whose Responses API stores no responses (OllamaEndpoint) throws ArgumentError before any request. Inside a with_recorded_answers scope the request passes through the recordings: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning a ResponseCallError.',"Examples"]],["UniLM.delete_response","UniLM.delete_response",['Delete a stored response by its ID. Returns a Dict with "id", "object", "deleted" keys. An endpoint whose Responses API stores no responses (OllamaEndpoint) throws ArgumentError before any request. Inside a with_recorded_answers scope the request passes through the recordings: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning a ResponseCallError.',"Examples"]],["UniLM.list_input_items","UniLM.list_input_items",['List input items for a stored response. Returns a Dict with "data", "first_id", "last_id", "has_more". An endpoint whose Responses API stores no responses (OllamaEndpoint) throws ArgumentError before any request, and so does GEMINIServiceEndpoint: Google\'s Interactions API gets, cancels and deletes an interaction, and has no method that lists its input items. Inside a with_recorded_answers scope the request passes through the recordings, keyed with its limit, order and after: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning a ResponseCallError.',"Examples"]],["UniLM.cancel_response","UniLM.cancel_response",['Cancel an in-progress response by its ID. Returns ResponseSuccess with the response it read back, or a ResponseFailure when that response\'s status is "failed", as respond does. An endpoint whose Responses API stores no responses (OllamaEndpoint) throws ArgumentError before any request. Inside a with_recorded_answers scope the request passes through the recordings: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning a ResponseCallError.',"Examples"]],["UniLM.compact_response","UniLM.compact_response",["Compact a conversation by running a compaction pass. Returns opaque, encrypted items that can be passed as input to subsequent requests, reducing token usage in long conversations.","Fields",'Returns a Dict with "id", "object", "output", and "usage" keys. Inside a with_recorded_answers scope the request passes through the recordings: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning a ResponseCallError.',"Examples"]],["UniLM.count_input_tokens","UniLM.count_input_tokens",['Count the number of input tokens a request would use without actually generating a response. Useful for estimating costs or checking whether input fits within the context window. model defaults to OpenAI\'s default model, "gpt-6-sol".','Returns a Dict with "object" ("response.input_tokens") and "input_tokens" keys. Inside a with_recorded_answers scope the request passes through the recordings: one the scope cannot replay throws ReplayMissError, and an answer whose recording cannot be written throws RecordingWriteError, instead of returning a ResponseCallError.',"Examples"]],["Input Helpers","Input-Helpers",["Multimodal Input"]],["UniLM.InputMessage","UniLM.InputMessage",["A structured input message for the Responses API.","Fields","Examples"]],["UniLM.input_text","UniLM.input_text",["Create an input_text content part for multimodal input messages.",'cache_breakpoint=true marks the end of this block as an explicit prompt-cache breakpoint (GPT-5.6 and later) by adding prompt_cache_breakpoint: {"mode": "explicit"}. OpenAI\'s prompt-caching guide: "mark each desired breakpoint by adding prompt_cache_breakpoint: { "mode": "explicit" } to a supported content block inside an input message." Pair it with PromptCacheOptions(mode="explicit") to cache only the prefixes you mark.','cache_ttl gives this breakpoint its own cache lifetime, "30m" or "12h" (the Responses API\'s), in place of the request\'s prompt_cache_options ttl: "Set prompt_cache_breakpoint.ttl to override it for an individual explicit breakpoint." It needs cache_breakpoint=true; another value, or a ttl without a breakpoint, throws ArgumentError. See OpenAI prompt caching.']],["UniLM.input_image","UniLM.input_image",['Create an input_image content part. Provide either an image url or a file_id. detail can be "auto" (the API\'s default), "low", "high" or "original".']],["UniLM.input_file","UniLM.input_file",["Create an input_file content part. Provide a url, a file id, or inline file_data (base64). filename is recommended when passing file_data.","The input_file content part of a DocumentAttachment: file_data is the PDF as a base64 data URL (\"data:application/pdf;base64,…\", the form OpenAI's file inputs guide sends) and filename the document's name — the same Dict as input_file(; file_data=…, filename=document.filename). OllamaEndpoint's Responses API documents no file inputs and refuses an input_file part before any request."]],["UniLM.configuration_update","UniLM.configuration_update",['Build a configuration_update input item, {"type": "configuration_update", "reasoning": {"effort": effort}}, that changes the reasoning effort of this and later responses without rewriting the request-level reasoning.effort, so the cached prompt prefix stays reusable. Place it in input before the next user message. Supported by the GPT-6 model family in standard, single-agent requests; the API rejects two adjacent updates. effort must be one of "none", "minimal", "low", "medium", "high", "xhigh", "max". See Change reasoning mid-conversation.']],["Tool Types","Tool-Types",["Tool Constructors","Tool Choice","Tool Results & Hosted (Gemini) Tools"]],["UniLM.ResponseTool","UniLM.ResponseTool",["Abstract supertype for Responses API tools. Subtypes: FunctionTool, WebSearchTool, FileSearchTool, MCPTool, ComputerTool, ImageGenerationTool, CodeInterpreterTool, ShellTool, ApplyPatchTool and CustomTool."]],["UniLM.FunctionTool","UniLM.FunctionTool",["A function tool for the Responses API.","Unset fields are omitted from the request.","Examples"]],["UniLM.WebSearchTool","UniLM.WebSearchTool",["A web search tool for the Responses API. Allows the model to search the web.",'Fetch sources/results back via include=["web_search_call.results", "web_search_call.action.sources"].']],["UniLM.FileSearchTool","UniLM.FileSearchTool",["A file search tool for the Responses API. Searches over uploaded vector stores."]],["UniLM.MCPTool","UniLM.MCPTool",['A Model Context Protocol (MCP) tool for the Responses API. Connect the model to a remote MCP server (server_url), an OpenAI connector (connector_id, e.g. "connector_googledrive", "connector_gmail", "connector_dropbox"), or a Secure MCP Tunnel (tunnel_id). Connectors are OpenAI\'s legacy connectors: connector_id "is deprecated for models released after September 1, 2026", which take server_url or tunnel_id, and "Existing models retain connector support" (connectors and MCP). Use authorization for an OAuth access token. require_approval/allowed_tools accept the string or object forms.']],["UniLM.ImageGenerationTool","UniLM.ImageGenerationTool",["An image generation tool for the Responses API. Allows the model to generate images inline during a response.","action, moderation, partial_images, and input_fidelity are validated at construction (ArgumentError). quality, background, and output_format are passed through unchecked (the accepted quality values depend on the model). Unset fields are omitted from the request."]],["UniLM.CodeInterpreterTool","UniLM.CodeInterpreterTool",['A code interpreter tool for the Responses API. Allows the model to execute code in a sandboxed environment: the container OpenAI\'s tool requires. By default it is an auto container ({"type": "auto"}), which OpenAI creates or reuses; a Dict is sent as given (e.g. Dict("type" => "auto", "memory_limit" => "4g")), and a String is the id of a container created beforehand (create_container). file_ids are sent inside the auto container; with a container id, or beside a container Dict that names file_ids already, they are an ArgumentError.']],["UniLM.ComputerTool","UniLM.ComputerTool",['Computer-use tool (type:"computer"); the computer_call items the model returns are actions for your application to perform.']],["UniLM.CustomTool","UniLM.CustomTool",['Custom tool (type:"custom") with free-form text input, or a grammar-constrained input via format = Dict("type"=>"grammar", "syntax"=>"lark"|"regex", "definition"=>...).']],["UniLM.ShellTool","UniLM.ShellTool",['Hosted shell tool (type:"shell").']],["UniLM.ApplyPatchTool","UniLM.ApplyPatchTool",['Structured file-edit tool (type:"apply_patch").']],["UniLM.function_tool","UniLM.function_tool",["Shorthand constructor for FunctionTool.",'Construct a FunctionTool from a dict. Accepts both the bare format {"name": ...} and the wrapped format {"type": "function", "function": {"name": ...}}. The keys "description", "parameters", "strict", "async", "allowed_callers", "defer_loading", and "output_schema" are copied when present.']],["UniLM.web_search","UniLM.web_search",["Shorthand constructor for WebSearchTool."]],["UniLM.file_search","UniLM.file_search",["Shorthand constructor for FileSearchTool."]],["UniLM.mcp_tool","UniLM.mcp_tool",["Shorthand constructor for MCPTool."]],["UniLM.image_generation_tool","UniLM.image_generation_tool",["Shorthand constructor for ImageGenerationTool."]],["UniLM.code_interpreter","UniLM.code_interpreter",["Shorthand constructor for CodeInterpreterTool."]],["UniLM.computer_tool","UniLM.computer_tool",["Construct a ComputerTool (computer tool)."]],["UniLM.custom_tool","UniLM.custom_tool",["Construct a CustomTool (custom tool); format optionally constrains input to a grammar."]],["UniLM.shell","UniLM.shell",["Construct a ShellTool (hosted shell tool)."]],["UniLM.apply_patch_tool","UniLM.apply_patch_tool",["Construct an ApplyPatchTool (structured apply_patch file-edit tool)."]],["UniLM.mcp_approval_response","UniLM.mcp_approval_response",["Build an mcp_approval_response input item to approve/deny a pending MCP tool call. Pass it back as an element of the next request's input."]],["UniLM.tool_choice_function","UniLM.tool_choice_function",['Force the model to call a specific function tool: {type:"function", name}.']],["UniLM.tool_choice_hosted","UniLM.tool_choice_hosted",['Force a specific hosted tool, e.g. tool_choice_hosted("file_search"), "image_generation", "code_interpreter". Note: the hosted web-search selector is "web_search_preview" (not "web_search").']],["UniLM.tool_choice_allowed","UniLM.tool_choice_allowed",['Constrain the model to a subset of tools: {type:"allowed_tools", mode, tools}. mode is "auto" or "required"; tools is a vector of tool-reference dicts.']],["UniLM.tool_choice_mcp","UniLM.tool_choice_mcp",['Force a specific MCP server (optionally a specific tool): {type:"mcp", server_label, name?}.']],["UniLM.tool_choice_custom","UniLM.tool_choice_custom",['Force a specific custom tool: {type:"custom", name}.']],["UniLM.tool_result","UniLM.tool_result",["Neutral multi-turn tool-result input item for the agentic verb. Feed a function's output back via respond(Respond(; previous_response_id=id, input=[tool_result(...)])) — respond takes the input positionally or as a Respond, so a keyword-only call is a MethodError — or through tool_loop. Wire-neutral: OpenAI serializes it as function_call_output (ignoring name); the Gemini encoder translates it to function_result (which requires name). output is the function's return value as a string."]],["UniLM.gemini_google_search","UniLM.gemini_google_search",["Hosted Google Search tool for the Gemini Interactions API. Pass in respond(...; tools=[gemini_google_search()], service=GEMINIServiceEndpoint)."]],["UniLM.gemini_code_execution","UniLM.gemini_code_execution",["Hosted code-execution tool for the Gemini Interactions API. Pass in respond(...; tools=[gemini_code_execution()], service=GEMINIServiceEndpoint)."]],["UniLM.gemini_url_context","UniLM.gemini_url_context",["Hosted URL-context tool for the Gemini Interactions API. Pass in respond(...; tools=[gemini_url_context()], service=GEMINIServiceEndpoint)."]],["Text Format","Text-Format",[]],["UniLM.TextConfig","UniLM.TextConfig",["Wrapper for the text field in the Responses API request body."]],["UniLM.TextFormatSpec","UniLM.TextFormatSpec",["Output text format specification."]],["UniLM.text_format","UniLM.text_format",["Create a TextConfig with the given format options."]],["UniLM.json_schema_format","UniLM.json_schema_format",["Create a JSON Schema output format for structured output.",'Construct a JSON Schema TextConfig from a dict with keys "name", "description", and "schema".']],["UniLM.json_object_format","UniLM.json_object_format",["Create a JSON object output format (unstructured)."]],["Reasoning, Prompt Caching & Moderation","Reasoning,-Prompt-Caching-and-Moderation",[]],["UniLM.Reasoning","UniLM.Reasoning",["Reasoning configuration for OpenAI and Gemini Interactions models."]],["UniLM.PromptCacheOptions","UniLM.PromptCacheOptions",['Prompt-cache controls (OpenAI: GPT-5.6 and later; Anthropic). mode is "implicit" or "explicit"; ttl, how long a cached prefix is kept, is one of "5m" or "1h" (Anthropic\'s lifetimes), "30m" or "12h" (OpenAI\'s) — any other value throws ArgumentError. Each native endpoint takes its own subset and throws ArgumentError naming it, before any request:',"Explicit mode caches only prefixes marked with prompt_cache_breakpoint in input content blocks (see input_text with cache_breakpoint=true).","Responses API only:",'Chat Completions accepts only mode and ttl: a Chat for OPENAIServiceEndpoint with prewarm or comparison_response_id set throws ArgumentError when encoded. Message content is a plain string, so a Chat cannot mark cache breakpoints, and per the Chat Completions reference an explicit-mode request without one "does not use prompt caching": a Chat with mode="explicit" throws ArgumentError when it is built, whatever its endpoint. Unset fields are omitted from the request. See OpenAI prompt caching.']],["UniLM.ModerationConfig","UniLM.ModerationConfig",['OpenAI moderated completions for Chat and Respond: the required moderation model (e.g. "omni-moderation-latest") checks the request input and the generated output. The optional input_mode / output_mode set the policy per side: "score" or "block". Serialized as {"model": …, "policy": {"input": {"mode": …}, "output": {"mode": …}}} with unset policy parts omitted. A respond result carries the outcome in r.response.raw["moderation"] ("input" and "output" moderation results), and a chatrequest! result in its moderation (LLMSuccess). See the moderation parameter of Create a model response.']]]},{url:"/api/results/",sections:[["Result Types",null,["Abstract and concrete types for handling API call outcomes. All result types are subtypes of LLMRequestResponse."]],["Abstract Type","Abstract-Type",[]],["UniLM.LLMRequestResponse","UniLM.LLMRequestResponse",["Abstract supertype for all API call results. Pattern-match on subtypes to handle outcomes:"]],["Chat Completions Results","Chat-Completions-Results",["Pattern Matching"]],["UniLM.LLMSuccess","UniLM.LLMSuccess",["Successful Chat Completions API response.","Fields","The OpenAI-wire endpoints (OpenAI, within the model's rules, Azure, GEMINIOpenAIServiceEndpoint, DeepSeekEndpoint and generic endpoints) send logprobs, top_logprobs and moderation as set and keep what the reply returns; OllamaEndpoint sends the first two and refuses moderation; native Gemini and ANTHROPICServiceEndpoint refuse all three before any request. Built positionally, the first five fields build one, the last two nothing."]],["UniLM.LLMFailure","UniLM.LLMFailure",["HTTP-level failure from the Chat Completions API. The server returned a non-200 status.","Fields"]],["UniLM.LLMCallError","UniLM.LLMCallError",["Exception-level error during a Chat Completions API call (network failure, JSON parse error, timeout, etc.).","Fields"]],["Result Helpers","Result-Helpers",["Predicates and an accessor for consuming any result — success or failure:","text returns the assistant reply on a LLMSuccess (possibly nothing for a tool-calls-only turn) and throws an LLMResultError on a failure. Guard with issuccess / isfailure, or pattern-match the result type first:"]],["UniLM.issuccess","UniLM.issuccess",["true when r is a success result (any *Success type), false for every failure or call-error result. The generic method returns false; each concrete *Success result type gets its own true method (registered once every result type across the APIs is defined — see the bottom of UniLM.jl)."]],["UniLM.isfailure","UniLM.isfailure",["Negation of issuccess: true for any failure or call-error result."]],["UniLM.text","UniLM.text",["The assistant reply text — r.message.content. Can be nothing when the reply carries only tool calls (no text), or is a refusal (r.message.refusal_message holds it). On a LLMFailure or LLMCallError, text throws an LLMResultError; guard with issuccess / isfailure, or pattern-match the result type first."]],["UniLM.LLMResultError","UniLM.LLMResultError",["Thrown by the result accessors — text, output_text, embedding_vectors, image_data and fim_text — when they are called on a non-success result. Carries the offending result. showerror prints only the status and a short (≤200-char) excerpt of the response body or error message — never the conversation, the service endpoint, or the API key."]],["Responses API Results","Responses-API-Results",["See also the Responses API reference.","Pattern Matching"]],["Image Generation Results","Image-Generation-Results",["See also the Images API reference.","Pattern Matching"]],["Type Hierarchy","Type-Hierarchy",["All result types share the abstract parent LLMRequestResponse:","Every *Success wraps a parsed response object; every *Failure carries the HTTP status and body; every *CallError carries the rendered error text and, in cause, the exception behind it when there is one — a UniLMTimeout for a timeout, a UniLMCancelled for a cancellation. Pattern-match on the family you called (see each API-reference page for the concrete fields)."]]]},{url:"/api/system_one/",sections:[["System One API (Jev, OpenAI Decisions, Ollama)",null,["A System One model does not write text. It reads a piece of state and answers the questions you enumerate with a probability distribution over the outcomes you named, already typed — a String option, a Float64 score, a probability, a box — so there is nothing to parse. The answer says what, the distribution says whether to act on it.","UniLM has one System One surface — ask, ask_each, the question builders and the typed answers below — over three backends: TypeSafe's Jev (the default), OpenAI's Decisions API (generally available) and local decision models served by Ollama. Route and Decide is the how-to and Choosing a decision provider compares the three. This page gives what every backend shares, then each backend's setup, rules, errors and cost, then every type and verb; nl_classify, nl_dispatch and @branch have a page of their own, Natural-Language Dispatch."]],["Backends","system_one_backend_api",["A call takes its backend from service = …; without one, from the enclosing with_system_one scope, which can also set the model of the calls that name none; outside every scope, from TypeSafe. ask, ask_each, list_models and the natural-language verbs resolve it alike. Any other endpoint that declares :system_one is a backend too, and one without a protocol of its own speaks TypeSafe's wire (Provider protocol).","The question types hold only what every backend requires. What a backend's wire cannot carry — more options or levels than it takes, a question kind, an image or an option it does not know — its wrapper refuses before anything is sent, with an ArgumentError naming the backend, the rule and the fix: choice builds a Choice of 256 options, and only sending it to a backend that takes fewer is refused. Every reply is checked against its request alike on every backend (see ask), with the backend's own allowance for how it rounds probabilities; a reply that does not fit is a SystemOneCallError.","confidence is one measure on every backend — (n\xb7p_max − 1)/(n − 1) for a Choice over n options, 1 − Σᵢ pᵢ\xb7|i − m| / MAD_unif for a Score whose most likely level is m (Confidence): TypeSafe and OpenAI report it, and the Ollama wrapper computes it from the probabilities; over a single option it is 1.0, as TypeSafe answers a one-option Choice. How far a confidence can be trusted is a property of the model, not of the formula.","A threshold tuned on one backend does not carry over to another. On the same 129 labelled support tickets with 7 options (2026-10-20), Jev (jev-1.13.0) chose the right option for 96.9% of them, with an expected calibration error of 0.016, and OpenAI's gpt-6-luna for 94.6%, with 0.080 — in every bin above 0.5 its accuracy was at least its mean top probability: it is under-confident. Tune a threshold on the backend, and the model version, it will run on (Choosing a decision provider).","While you set no RequestConfig of your own — no config, no with_request_config scope, no set_default_config! — a backend may bound its calls itself: TypeSafe's wire and OpenAI's by 60 s per attempt and 150 s in all, while Ollama brings no bound of its own, so the field defaults apply (loading a model on a CPU can take minutes). ask_each keeps at most 16 requests in flight on TypeSafe's wire and OpenAI's, 1 on Ollama and 8 on a protocol of your own, unless its ntasks says otherwise. Every System One exchange goes through one connection pool per process, which keeps up to 256 idle connections per host for 30 s, so a batch or a loop finds its connections open.","with_recorded_answers files each backend's exchanges apart: TypeSafe's under the request's path (/v1/systemone), OpenAI's under /openai-decisions/v1/decisions, Ollama's under /ollama/v1/systemone. A recording never replays for another backend; an endpoint that speaks TypeSafe's wire shares TypeSafe's recordings, since its requests are TypeSafe's. An option that changes how a request is served but never what it is answered — OpenAI's prompt_cache_key, safety_identifier and prompt_cache_options, Ollama's keep_alive — is sent and left out of the recording, key and file alike, so the same question replays whatever it is; TypeSafe's long_context is part of the key."]],["TypeSafe's Jev","system_one_typesafe",["TypeSafe's System One model, Jev, answers through TYPESAFEServiceEndpoint — the backend of every call that names none outside a with_system_one scope — on TypeSafe's wire, TypeSafeProtocol.","Setup",'All three are read at call time. jev-latest is an alias that moves when a new version ships, which suits building; once a confidence threshold is tuned against a version, pin its id — ask(...; model="jev-1.13.0") or TYPESAFE_DEFAULT_MODEL=jev-1.13.0 — and move on your own schedule (Models). TYPESAFE_DEFAULT_MODEL changes every request that names no model, and with it the key its recorded answer is filed under: in code whose answers you record, pin with model =, or record with the same environment you replay with (Test and Develop).',"TYPESAFEServiceEndpoint (Service Endpoints) is not a chat backend: it declares only :system_one and :models, so chatrequest!, respond, embeddingrequest! and the other platform verbs refuse it with an ArgumentError before sending anything. A Chat or Embeddings naming it can be built, with an explicit model=, but not sent (Provider Capabilities).","Models and versions","list_models returns the names the account may put in model:","The listing holds aliases: jev-latest, the most recent stable release and the default here, and jev-preview, the most recent release of any kind, ahead of jev-latest when a preview build exists. A versioned id such as jev-1.13.0 is a valid model whether or not it is listed, and the listing is scoped to the account (Models). SystemOneResponse.model reports the versioned id that answered: log it, since an alias moving is otherwise invisible, and a threshold tuned against one version is a claim about that version only.",'In October 2026 jev-latest answers as jev-1.13.0 and jev-preview as jev-1.14.0 (Jev 1.14, available from October 14, 2026). Both read images; a box question needs Jev 1.14 or later — model = "jev-1.14.0" or "jev-preview". Jev 1.13 answers a request with one with HTTP 400 and the bare message "Invalid request.", which ask returns with a hint naming those models. long_context = true works on both (Limits).',"Limits","ask checks every limit but the context and the rate limits before the round trip, and refuses a request over one with an ArgumentError naming TypeSafe's limit and the value — a Choice of 256 options, a Score of 11 levels, a GIF, an image 2000 pixels wide, a file cut short within its header, a JPEG that does not end with its end-of-image marker (FF D9: cut short, or carrying bytes after the image), a state nested 65 levels deep. The question types themselves set no upper bound — other System One backends have other limits, which their wrappers check the same way — so choice and score build such questions; only sending one to TypeSafe is refused. A box question needs an image in the request to locate in, so one in a request without an image is refused as well: TypeSafe answers it anyway, with HTTP 200 and a box at a low confidence — 0.05 to 0.10 in probes on 2026-10-19 and 2026-10-20 — that locates nothing. A Box answer turned inside out (top > bottom or left > right) is a SystemOneCallError.",'An ImageAttachment may stand anywhere in the state, the instructions or the criteria — a Choice whose options are example pictures, a Score whose levels are. TypeSafe marks images and Box questions "Dreamer-ready", not yet ready for production: their request format, answers and limits "can change between releases" (Images). Each distinct image is sent once, as a part of a multipart/form-data request, and every place it stood holds its reference, <image:…> with the first 32 hex digits of the SHA-256 of its bytes; every use is billed, so an image several questions need belongs in the state. A request with an image or a Box question carries the header TypeSafe-Danger-Zone-Images: true TypeSafe requires: passing one is the opt-in. A Score level that is an image comes back in the answer\'s legend as that same ImageAttachment. Images are numbered in an error message as they first occur: the state, then each question\'s instructions and criteria. TypeSafe applies no EXIF orientation, so rotate a photo\'s pixels upright before sending it. A recording of a request with images (with_recorded_answers) is keyed on its JSON part and the SHA-256 of each image, and holds no image.','long_context = true — ask(state, questions...; long_context = true) — sends TypeSafe-Danger-Zone-Long-Context: true, which raises both context limits to 262k tokens at the same price per token; TypeSafe documents it as slower and less accurate than the default limits, and the answer does not say which ran. A request over its context comes back as a 400 whose error_type is "max_tokens_exceeded", and its message names long_context and the limits.',"Errors, timeouts and retries","A call that reaches the service returns a SystemOneSuccess, a SystemOneFailure (a status other than 200) or a SystemOneCallError (no usable response), and issuccess separates them; a wrong service or a malformed request is an ArgumentError before anything is sent. A 200 whose answers do not fit the request — a question unanswered, an answer of another kind, an option that was not offered, probabilities that are not a distribution over the offered outcomes, a value outside 0 … 1, a Score whose score its probabilities contradict or whose legend renames a level asked as a string, no model named — is a SystemOneCallError too, carrying the request id: no success is built from a malformed answer. TypeSafe's probabilities are accepted when they sum to 1 within 0.005 per outcome, and the chosen option when it lies at most 0.01 below the most probable: one live reply, a Choice of four options, summed to 0.99 — the mark of values rounded to two decimals. The service writes errors in three detail shapes: message is extracted from whichever arrived, and error_type is filled in only by the object shape.","ask and list_models ride the shared retry seam, so RequestConfig governs them as it governs a chat call: 408, 429, 500, 502, 503, 504, 520–524 and 529 are retried up to max_attempts within total_deadline, honouring retry-after-ms, else Retry-After; 400, 401, 403, 404, 413, 415 and 422 come back as they are, because an identical retry cannot fix them. While you set no RequestConfig of your own, a call is bounded by 60 s per attempt and 150 s in all: TypeSafe answers a typical request in about 0.3 s, and the slowest call measured — 262k tokens of long context — took 5.3 s. A retry carries X-TypeSafe-Retry-Count, 1 on the second attempt, as TypeSafe's official SDKs send it.","A timeout, a transport failure or a cancellation — through cancel= or the ambient with_cancel token, with a UniLMCancelled as the cause — is a SystemOneCallError, never a partial success (Timeouts & Retries, Concurrency, Tasks and Cancellation).","Cost","Only input tokens are billed; output tokens are currently free (Models). Every question in one call shares one ingestion of the state, so many questions in one ask cost far less than one call per question. An image is billed on every use: on 2026-10-19 the input tokens of a W\xd7H image fit 2\xb7⌈W/28⌉\xb7⌈H/28⌉, plus about 4 per use — an observation, not a published rate.","estimated_cost prices the versioned id in r.response.model, not the alias the request named: a jev-X.Y.Z id without its own row at the jev-latest row, and any other name that is not a key in DEFAULT_PRICING at 0.0 (Cost Tracking)."]],["OpenAI Decisions","system_one_openai",["OpenAI's Decisions API (POST /v1/decisions, a public beta from October 6, 2026, now generally available) answers predicate, choice and score questions, and OPENAIServiceEndpoint speaks it: name the endpoint as the service of ask or of a with_system_one scope, and set OPENAI_API_KEY. The model is gpt-6-luna, the only one the API serves, unless the call names another (Decisions guide).",'Every question needs string instructions, and at most 400 go in one request. prompt_cache_options takes a ttl of "30m" or "12h" — OpenAI\'s prompt-caching guide names "12h" for the Responses API, and the Decisions API answered a "12h" request with HTTP 200 — and a mode; with mode="explicit" the request marks no breakpoint, so OpenAI caches none of it. What has no form on this wire — a Box question, a description or level that is not a string, a Noul\'s yes/no criteria, an image outside the state, another ttl, prewarm or comparison_response_id, any other keyword — is an ArgumentError before anything is sent. The answers come back typed as on any backend, and a question the API declined comes back as a RefusalAnswer: nl_dispatch, nl_classify and @branch take it as a decline — the fallback, or DecisionDeclinedError. Probabilities and confidences arrive rounded to two decimals, so a distribution over n outcomes is accepted when it sums to 1 within 0.005n, and the chosen option when it lies at most 0.01 below the most probable. usage counts input, cached, cache-write (the 12-hour ones apart) and output tokens, and holds the service tier when the reply names one; a count that is not a non-negative whole number, or a …_tokens_details value that is not an object, reads as 0 with a warning. A failure\'s error_type is the error\'s code, and the request id is the x-request-id header. A recording (with_recorded_answers) is keyed without the three options, and holds each image as the SHA-256 of its base64 text, data:<mime>;sha256,<hex>, never its bytes. estimated_cost charges what the guide prices: input tokens only — $0.10 per million uncached, the gpt-6-luna row\'s input rate; cache reads at its cached rate, $0.01, and cache writes at OpenAI\'s write rates, $0.125 per million ($0.25 for a 12-hour lifetime) — every rate twice for a request of more than 272K input tokens.',"The calls are bounded as TypeSafe's are (60 s per attempt, 150 s in all, while you set no RequestConfig of your own), and ask_each keeps 16 of them in flight. list_models on this endpoint lists every model OpenAI serves the key (Model Listings). On the 129 support tickets of the Backends section, OpenAI answered in 0.48 s at the median and 2.44 s at the 95th percentile (Jev: 0.25 s and 0.33 s), at $0.0000296 a ticket (Jev: $0.0000225)."]],["UniLM.OpenAIDecisionsProtocol","UniLM.OpenAIDecisionsProtocol",['OpenAI\'s Decisions API, generally available, as a System One backend, and the protocol of OPENAIServiceEndpoint: ask(state, questions...; service = OPENAIServiceEndpoint), a with_system_one(OPENAIServiceEndpoint) scope and the natural-language verbs send POST https://api.openai.com/v1/decisions with OPENAI_API_KEY, naming "gpt-6-luna" — the only model the API serves — when the call names none.',"The request:","What the wire has no form for is an ArgumentError before any I/O, naming OpenAI's rule and the fix: a question without string instructions; a Noul's yes/no criteria; a description or level that is not a string; a BoxQuestion; an image outside the state; a DocumentAttachment anywhere (the API takes no files), as on every System One backend; a prompt_cache_options with another ttl, prewarm or comparison_response_id; any other option.","The reply: answers are matched to the questions by name and must come in the order asked. A predicate reads as a NoulAnswer, a choice as a ChoiceAnswer, a score as a ScoreAnswer whose legend maps each level to its label, and a refusal — the API may decline any question — as a RefusalAnswer. Probabilities and confidences arrive rounded to two decimals, so a distribution over n outcomes may sum to 1 within 0.005n. usage counts input, cached, cache-write — the 12-hour ones apart, as on the Responses API — and output tokens, and holds the service tier when the reply names one; request_id is the x-request-id header; a reply with a status other than 200 is a SystemOneFailure whose error_type is the error's code, else its type. Recordings are filed under /openai-decisions/v1/decisions, keyed without the three options, which change how a request is served but never what it is answered, and with each image as the SHA-256 of its base64 text, never its bytes. estimated_cost bills what OpenAI bills: the input tokens alone, and no output — uncached ones at the model's input rate, cache reads at its cached-input rate, and cache writes and a request of more than 272K input tokens at the surcharges OpenAI lists for the model (gpt-6-luna: a write at 1.25 times the input rate, 2.5 times for a 12-hour lifetime, and every rate twice above 272K).","Public extension API (not exported)."]],["Ollama","system_one_ollama",["An OllamaEndpoint answers System One requests from a local decision model — Tev1, Nimble, Kev, Clef and the others Ollama lists as decision models — through Ollama's TypeSafe-compatible route POST /v1/systemone: Ollama 0.35 or later, 0.35.1 or later for pictures, and 0.40.0 or later for the MLX builds of Tev1 and Clef Flash used below; what this section reports was measured on 0.40.6. The verbs, the questions and the result types are the ones below; no key is sent and nothing is billed. Start the server and pull the decision models first: the example below uses tev1:4b, clef-flash:9b (a vision model, for pictures) and kev:0.8b-q8_0 (ollama pull tev1:4b, and so on)."]],["UniLM.OllamaSystemOneProtocol","UniLM.OllamaSystemOneProtocol",["Ollama's System One wire, the protocol OllamaEndpoint speaks: POST {base_url}/v1/systemone (Ollama 0.35 or later, pictures 0.35.1 or later; measured on 0.40.6, tev1:4b and clef-flash:9b arriving in 0.40.0) with the System One JSON form TypeSafe's wrapper writes — state, model, questions, then runner when the endpoint sets one (part of a recording's key: the runner the model's listing names answers as if unpinned, and any other is the server's 400, no compatible manifest found for runners: <runner>, never another answer, on Ollama 0.40.6), images when the state holds any, and keep_alive when one is set — answered by a local decision model such as tev1:4b (clef-flash:9b for pictures) and decoded as a TypeSafe reply is. No key is sent, except to Ollama's cloud (see OllamaEndpoint), no request id comes back, and recordings are filed under the namespace \"ollama\", keyed without keep_alive, which changes how long the model stays loaded but never an answer.","There is no default model: the call names one (model = \"tev1:4b\"), or a with_system_one scope does. Before any I/O it refuses what Ollama's route refuses in its shared checks or documents as its maximum (Ollama 0.40.6): more than 64 questions; a Choice of more than 255 options; a Score of fewer than 2 or more than 10 levels; a blank text state without images; a Box question, which Ollama does not answer. By Ollama's source, a Kev model on Ollama's own runner (such as kev:0.8b-mxfp8) skips the shared checks and takes 1 to 255 levels and a blank state; that is untested. It also refuses what Ollama's API reference does not list, though some models read it: instructions given as anything but a string, an object or an array; an option described by anything but a string or nothing; a Score level or a Noul criterion that is not a string (on Ollama 0.40.6, kev:0.8b-q8_0 and d1:3b, on the llama.cpp path, answered an option described by an object, and tev1:0.8b refused it). It refuses blank (whitespace-only) instructions, which Ollama would read as none: not blank, as the reference's pattern: \\S requires; and a Choice, Noul or Score question without instructions, which the reference requires too (measured on Ollama 0.40.6, tev1:4b, nimble:9b and strands-decider:2b answered one with HTTP 400 instructions must be a nonempty string, object, or array, kev:0.8b-q8_0 with 400 questions.intent: \"instructions\" must be provided for a question named intent, and clef-flash:9b answered it), and a Choice of one option, below the two its API reference requires (on Ollama 0.40.6 the models on the llama.cpp path, kev, d1 and d1-omni, answered one, and the MLX models their own 400, criteria must contain 2–26 candidates; strands-decider:2b 2–255). A model that takes fewer options (Tev1: at most 24; Nimble and Clef Flash: 26) says so in its own HTTP 400 too, which comes back as a SystemOneFailure. Ollama also caps a local request's text and schema, images excluded, at 64 KiB (measured on Ollama 0.40.6 with kev:0.8b-q8_0, d1-omni:600m and tev1:0.8b; by its source, 1 MiB for a Kev model on Ollama's own runner, untested): that limit is the server's to count, by its own measure, and is not checked here; a request over it comes back as a SystemOneFailure carrying Ollama's 413, text and schema must not exceed 64 KiB. A RawQuestion is sent verbatim, for the server to judge. Its one option is keep_alive: the seconds the model stays loaded after the request (0 unloads it at once, Inf keeps it loaded), by default the endpoint's own.","Images go in the state. Ollama takes a request's images as one list, images (raw base64), shared by all its questions and apart from the text — by Ollama's v0.40.11 source, Clef reads them before the state's text — so the state is an image, or a vector or tuple of images then texts ([image, \"What is in it?\"]). With images, the state's other entries must be texts; they become state — none: \"\", one: that string, several: an array — and a blank one is allowed, as Ollama 0.40.6 answers a blank state sent with images. An image after a text, inside a JSON object or array, or in a question could only be moved, never sent where it was put, and is refused before any I/O, as is a state of images and anything but texts, an image's detail level — the list holds an image's bytes alone — and, as on every System One backend, a DocumentAttachment anywhere. A model without vision answers its own 400, in its own words (Ollama 0.40.6: tev1:0.8b image inputs are not supported by this decision model, kev:0.8b-q8_0 registry.ollama.ai/library/kev:0.8b-q8_0 does not support vision), which comes back as a SystemOneFailure. Recordings key an image by its digest, data:<mime>;sha256,<hex> (the SHA-256 of its base64 text), never its bytes.","confidence is TypeSafe's published measure, computed here from the returned probabilities: (n\xb7p_max − 1)/(n − 1) clamped to 0 … 1 for a Choice, and 1 − Σᵢ pᵢ\xb7|i − m| / MAD_unif floored at 0 for a Score, m its most likely level (Confidence). Measured on Ollama 0.40.6, the five MLX models (tev1:0.8b, tev1:4b, nimble:9b, strands-decider:2b, clef-flash:9b) report 1 − H(p)/ln n, and Kev and the models on the llama.cpp path (kev, d1, d1-omni) TypeSafe's formulas; the server's value stays in each answer's raw. Usage counts prompt_eval_cached_count as cached tokens where the server reports it (the MLX path); on the llama.cpp path the count is not reported and reads as 0. A cloud model whose reply drops its tag (Ollama's cloud answers clef for clef:cloud) is reported under the requested name, so it is priced as the cloud model; the server's model stays in raw.","Public extension API (not exported)."]],["Questions","Questions",[]],["UniLM.SystemOneQuestion","UniLM.SystemOneQuestion",["Abstract supertype of the questions a System One request asks: ChoiceQuestion (pick one of the named options), ScoreQuestion (place the state on an ordered rubric), NoulQuestion (the probability that a statement is true), BoxQuestion (where something is in an image), and RawQuestion, the hatch for a question kind this version does not know. Build them with choice, score, noul and box.","The types hold only what every backend requires; how many options or levels a backend accepts is its wrapper's rule, checked when the request is sent."]],["UniLM.choice","UniLM.choice",["Build a Choice question: the model picks exactly one of the named options and reports a probability for every one of them.","criteria may be a NamedTuple, an AbstractDict, a vector of name => description pairs, or a vector of bare option names (each described by its name alone). Names may be Strings or Symbols and are stored as Strings; a description may be a string, an object, an array, an image, or nothing.","Option order is the order of what you pass: a NamedTuple, a vector of pairs, and an ordered mapping such as JSON.Object keep theirs. A plain Dict has none of its own — its hash order changes between Julia versions — so its options are taken in sorted name order. Order never changes the answer's meaning — answers are keyed by name — but it is what the model reads.","How many options a question may offer is the backend's rule, checked when the request is sent: TypeSafe accepts up to 255."]],["UniLM.score","UniLM.score",["Build a Score question over an ordered rubric, lowest level first. levels[1] is level 0: the answer's score and its probabilities keys live on that same 0-based scale.","Each level is a string, an object, an array or an image — never nothing. How many levels a rubric may have is the backend's rule, checked when the request is sent: TypeSafe accepts 1 to 10 and advises at least two, since a one-level rubric gives the model nothing to place the state against.","levels is a vector: a tuple, or any other container, throws ArgumentError, as a choice criteria outside its forms does.","The returned score is a probability-weighted expectation, so it falls between integer levels. Threshold it; do not read a magnitude into the fractional part."]],["UniLM.noul","UniLM.noul",['Build a Noul question — a single probability that the statement is true. yes and no describe the two sides and are sent as the wire keys "true" and "false"; either may be omitted.',"At least one of instructions, yes, or no must be present: a bare noul says nothing about what is being asked.","A Noul answer carries no confidence — the probability itself expresses it — and P(q) + P(not q) is not guaranteed to be 1, so do not derive one from the other."]],["UniLM.box","UniLM.box",["Build a Box question: where in an image of the state is what instructions names. The answer is a BoxAnswer — a BoxCoordinates of fractions of the image's height and width, with a confidence when the backend reports one. instructions is required: a string that is not blank, an object, an array or an image."]],["UniLM.ChoiceQuestion","UniLM.ChoiceQuestion",["One question that picks a single named option. criteria maps each option name to its description, in insertion order (the order is sent on the wire; the answer's probabilities map is unordered). A description of nothing tells the model to interpret the option by its name alone.","Constructed through choice, which normalizes the many ways to spell a criteria map. At least one option is required and option names must not be blank; there is no upper bound here, because backends differ — TypeSafe accepts at most 255 options, a limit its wrapper checks before the request is sent."]],["UniLM.ScoreQuestion","UniLM.ScoreQuestion",["One question that places the state on an ordered rubric. criteria lists the levels lowest first; criteria[1] is level 0 on the 0-based scale the answer reports, so a rubric of three levels yields a score in 0.0 … 2.0.","Constructed through score. At least one level is required and a level may not be nothing: an unnamed level is a rung the model cannot recognise. There is no upper bound here — TypeSafe accepts at most 10 levels, a limit its wrapper checks before the request is sent."]],["UniLM.NoulQuestion","UniLM.NoulQuestion",["One question answered by a single probability in 0 … 1 — the model's belief that the statement holds. There is no confidence and no distribution: the value is the distribution, and 0.5 is maximal uncertainty.","Constructed through noul. A noul carrying neither instructions nor a criterion asks nothing, so that is an ArgumentError."]],["UniLM.NoulCriteria","UniLM.NoulCriteria",['The two optional criteria of a NoulQuestion: what makes the statement true (yes, sent as the wire key "true") and what makes it false (no, sent as "false"). Either may be nothing, in which case that key is omitted entirely rather than sent as null.']],["UniLM.BoxQuestion","UniLM.BoxQuestion",["One question that locates something in an image of the state: the answer is a BoxAnswer, a box whose edges are fractions of the image's height and width. instructions says what to locate and is required — a string that is not blank, an object, an array or an image; a box with no target is not a question.","Constructed through box. Not every backend answers Box questions; those that cannot refuse the request with an ArgumentError before it is sent."]],["UniLM.RawQuestion","UniLM.RawQuestion",['A question of a kind this version has no type for, kept as the JSON object fields and sent verbatim by the backends that allow raw questions — TypeSafe, OpenAI\'s Decisions API (which adds the question\'s name as "name") and Ollama all do; a backend that does not refuses it before the request is sent. fields is copied into a JSON.Object{String,Any} with String keys — a plain Dict in sorted key order, any other dictionary in its own order — and must hold a non-blank String "type".',"Its answer is accepted whatever kind it is: an answer the decoder recognises comes back typed, any other as an UnknownAnswer."]],["Request & Verbs","Request-and-Verbs",[]],["UniLM.SystemOneRequest","UniLM.SystemOneRequest",["One System One evaluation: every question in questions is answered about the same state, in a single round trip. The state is ingested once no matter how many questions ride along, which is why batching is far cheaper than one call per question.","Fields",'questions accepts name => question pairs (vector, tuple, NamedTuple, or AbstractDict), or bare questions in a vector or tuple, which are auto-named "q1", "q2", … in order; a plain Dict of questions is taken in sorted name order. A state of any other type, mixing bare and named questions, repeating a name, a blank name, passing none, or passing a blank model is an ArgumentError.']],["UniLM.ask","UniLM.ask",["Evaluate every question against state in one request to a System One backend and return one of SystemOneSuccess, SystemOneFailure (a response with a status other than 200) or SystemOneCallError (no response, or a 200 that was not a usable set of answers). Inside a with_recorded_answers scope, a request the scope cannot replay — no recording in :replay mode, or a recording file that cannot be read — throws ReplayMissError instead of returning: a gap in the recordings is not a service failure.","The backend is service when given, else the one of the enclosing with_system_one scope, else TYPESAFEServiceEndpoint. The model is model (or the request's) when given; else, with no service, the scope's; else the backend's default, read when the request is sent (TypeSafe: TYPESAFE_DEFAULT_MODEL, or \"jev-latest\").",'questions takes the same forms as SystemOneRequest: name => question pairs, a NamedTuple or AbstractDict of them, or bare questions auto-named "q1", "q2", … Any other keyword is a provider option and becomes the request\'s options, which the backend\'s wrapper checks before anything is sent: TypeSafe accepts long_context::Bool (true raises its context limits to 262k tokens), OpenAI\'s Decisions API prompt_cache_key and safety_identifier (strings) and prompt_cache_options (a PromptCacheOptions), Ollama keep_alive (the seconds the model stays loaded), so any other keyword — a misspelt one included — is an ArgumentError that lists the options the backend accepts.',"Malformed input is an ArgumentError before anything is sent: a state that is not a string, object, array or image; a value JSON cannot carry (NaN, Inf); a request the backend cannot carry — TypeSafe takes at most 255 options per Choice and 10 levels per Score, PNG and JPEG images of at most 16 MiB with 280 to 1568 pixels on each side (a JPEG ending with its end-of-image marker), 64 levels of nesting in the state, instructions and criteria, and a body of at most 32 MiB; a service that does not declare :system_one.","Every answer is checked against the request before a success is built, by the decoder of each built-in backend: each question asked is answered once and nothing else is; each answer is of its question's kind (an answer to a RawQuestion may be any); a Choice picks an offered option that is the most probable and gives a probability to exactly the options offered; a Score gives one to exactly the levels 0 to n − 1, its score lies between them and is the expectation of its probabilities within the backend's rounding, and its legend repeats every level asked as a string; probabilities lie in 0 … 1 and sum to 1 within the backend's rounding; confidences, Noul probabilities and box edges lie in 0 … 1; the response names the model that answered, by a name that is not blank. A reply that fails any of these is a SystemOneCallError — never a success built from a malformed answer.","Pass config::Union{Nothing,RequestConfig} to override the timeout and retry budget for this call. With none — no config, no with_request_config scope, no process default set — the backend's own default applies: on TypeSafe and OpenAI's Decisions API, 60 s per attempt and 150 s in all. On TypeSafe a retry carries its number in X-TypeSafe-Retry-Count, as the official SDKs send it. The request rides the package's shared retry seam, so max_attempts applies: a retryable status (408, 429, 500, 502–504, 520–524, 529) or a transport failure is retried within total_deadline, honouring retry-after-ms, else Retry-After. Other statuses — 400, 401, 403, 404, 413, 415, 422 — are returned as they came, because a second identical request cannot fix them.","Pass cancel::Union{Nothing,CancelToken} (default: the ambient with_cancel token) to make the call cancellable: once the token is cancelled it returns a SystemOneCallError whose cause is a UniLMCancelled — without sending anything when the token was already cancelled, at once when mid-request (never retried)."]],["UniLM.ask_each","UniLM.ask_each",["Ask the same questions about every state — or send every request — concurrently, and return a Vector{Union{SystemOneSuccess,SystemOneFailure,SystemOneCallError}} whose i-th entry is the result for item i: what ask returns for that item alone, with the same answers. Each item is a request of its own; nothing is packed together.","questions, model, service, config and any other keyword — a provider option — mean what they mean for ask, and the backend and model resolve as they do there, an enclosing with_system_one scope included. Every request is built and checked by its backend's wrapper before the first one is sent: an item that cannot be sent is an ArgumentError naming its position, and nothing is sent. The checked request is not kept: the worker that sends an item encodes it again, so a batch holds no more request bodies — images and all — than it has requests in flight.","At most ntasks requests are in flight at once — any Integer of at least 1; the default is the backend's — 16 on TypeSafe's wire (a TypeSafe-compatible gateway included) and OpenAI's Decisions API, 1 on Ollama, 8 on a protocol of your own — a default, not a limit. The requests share one connection pool, and when the service answers any of them with 429 or 529, a retried attempt included, no attempt of the batch starts until the wait that response asked for (retry-after-ms, else Retry-After, else the retry seam's own backoff) has passed; requests already in flight finish. A request waits at most what remains of its own total_deadline, whose clock starts when a worker takes it: one whose budget runs out while it waits is not sent, and its result is a SystemOneCallError whose cause is a UniLMTimeout of phase :deadline.","on_result(i, result), when given — any callable of an index and each kind of result, checked before anything is sent — runs in the worker task as each result lands, in the order they complete, one call at a time.","cancel (default: the ambient with_cancel token) stops the batch: the requests in flight end at once, the rest are not sent, and each item still unanswered becomes a SystemOneCallError whose cause is a UniLMCancelled, as for ask. A ReplayMissError or RecordingWriteError inside with_recorded_answers, an InterruptException, or an exception thrown by on_result stops it as well and is rethrown — the first one — once every worker has stopped."]],["UniLM.with_system_one","UniLM.with_system_one",["Run f() with service as the System One backend of every verb inside it that names none — ask, list_models, nl_dispatch, nl_classify and @branch — model, when given, as the model of those calls that name none, and any other keyword as the provider options of those calls that name none (see ask; checked by the backend's wrapper when each request is sent); return f()'s value. service must declare :system_one and model must not be blank, or this is an ArgumentError before f runs.","A call resolves its backend, model and options this way:","The scope is a ScopedValue, so it covers the tasks started inside f (Threads.@spawn, asyncmap), and scopes nest: the innermost applies."]],["Answers","Answers",[]],["UniLM.SystemOneAnswer","UniLM.SystemOneAnswer",["Abstract supertype of the answers a System One evaluation returns: ChoiceAnswer, ScoreAnswer, NoulAnswer, BoxAnswer, RefusalAnswer when a backend declined one question, and UnknownAnswer for a type this version does not recognise."]],["UniLM.ChoiceAnswer","UniLM.ChoiceAnswer",["The option with the highest probability (choice), a confidence in 0 … 1 summarising how concentrated the distribution is, and probabilities — one entry per option of the question, keyed by option name and summing to 1 within the backend's rounding. The map is unordered: a backend need not return the request's option order.","Read probabilities when the ranking matters; choice is only its argmax. raw is the unparsed JSON answer."]],["UniLM.ScoreAnswer","UniLM.ScoreAnswer",['score is the probability-weighted expectation over the rubric levels, so it may fall between them; confidence is in 0 … 1. legend and probabilities are keyed by the 0-based level number (parsed from the wire\'s "0", "1", …), so argmax(a.probabilities) is a level on the same scale as score and legend[argmax(a.probabilities)] is that level\'s description — a string, the original object/array when the rubric was structured, or the level\'s own ImageAttachment when it was an image.',"raw is the unparsed JSON answer."]],["UniLM.NoulAnswer","UniLM.NoulAnswer",["The probability in 0 … 1 that the statement is true. There is no confidence field: the value itself carries the uncertainty, and 0.5 is maximal doubt. raw is the unparsed JSON answer."]],["UniLM.BoxCoordinates","UniLM.BoxCoordinates",["A box in an image, each edge a fraction of the image's size: top and bottom of its height measured from the top edge, left and right of its width measured from the left edge, so (0, 1, 0, 1) is the whole image. Shown compactly, edge by edge."]],["UniLM.BoxAnswer","UniLM.BoxAnswer",["The answer to a BoxQuestion: where the thing the instructions named is, as a BoxCoordinates, and the backend's confidence in 0 … 1 — nothing when the backend reports none. raw is the unparsed JSON answer."]],["UniLM.RefusalAnswer","UniLM.RefusalAnswer",["A backend declined to answer one question — OpenAI's Decisions API does this per question — so there is no value to read; raw is the unparsed JSON answer. It is accepted only from a backend that documents refusals: from any other, a refusal makes the whole result a SystemOneCallError."]],["UniLM.UnknownAnswer","UniLM.UnknownAnswer",["An answer whose type this version does not know, kept verbatim in raw instead of being dropped. A new answer primitive on a backend therefore surfaces as data you can inspect rather than as a silently missing key — to a RawQuestion; for a question of a kind this version does know, an answer of an unknown type is malformed, and the result is a SystemOneCallError."]],["Result Types","Result-Types",[]],["UniLM.SystemOneResponse","UniLM.SystemOneResponse",["A decoded answer to a System One request.","Fields"]],["UniLM.SystemOneSuccess","UniLM.SystemOneSuccess",["Successful ask result wrapping a SystemOneResponse."]],["UniLM.SystemOneFailure","UniLM.SystemOneFailure",["A System One call that reached its backend and came back with a status other than 200 — the status TypeSafe, OpenAI's Decisions API and Ollama answer a success with.","Fields"]],["UniLM.SystemOneCallError","UniLM.SystemOneCallError",["A System One call that produced no usable answer: a timeout, a transport failure, a missing API key (TYPESAFE_API_KEY on TypeSafe), or a 200 whose body could not be decoded into answers or whose answers do not fit the request — a question unanswered or one answered that was not asked, an answer of the wrong kind, an option that was not offered, probabilities that are not a distribution, a value outside its range, a Score whose score its probabilities contradict or whose legend renames a level asked, or no model named. status is filled in only when the underlying exception carried one.","cause is that underlying exception — a UniLMTimeout for a timeout — and request_id is the backend's request id of the 200 that could not be used (TypeSafe: x-typesafe-request-id; nothing when no reply arrived)."]],["UniLM.SystemOneError","UniLM.SystemOneError",["Thrown by answers, answer and getindex when the result is a SystemOneFailure or SystemOneCallError.",'A failed call has no answers, and returning an empty map instead would let r["is_unsafe"].noul > 0.9 read as "safe" on a call that never happened. Check issuccess first, or handle the throw. showerror prints the status, the extracted message and the retry_after hint when the service sent one — never the request or the API key.']],["Models","Models",[]],["UniLM.list_models","UniLM.list_models",["List the models a service offers. The service is service when given, else the backend of the enclosing with_system_one scope, else TYPESAFEServiceEndpoint.","Any other backend with no listing is an ArgumentError. Only TypeSafe's listing is recorded by with_recorded_answers: the others go to their service inside a scope as outside one.","Pass config::Union{Nothing,RequestConfig} to override the timeout and retry budget; like ask, this rides the shared retry seam, so max_attempts applies to the retryable statuses, and total_deadline bounds a paged listing as a whole. cancel::Union{Nothing,CancelToken} makes the call cancellable as for ask: a cancelled call returns its service's call error (a SystemOneCallError on TypeSafe) whose cause is a UniLMCancelled."]],["UniLM.TypeSafeModelCard","UniLM.TypeSafeModelCard",["One entry of GET /v1/models: a model name accepted by SystemOneRequest.model, a human-readable description, and release_date.","release_date is kept as an opaque String: the documented shape is YYYY-MM-DD but the service returns an RFC 3339 timestamp, so parsing it into a date here would either fail or guess. raw holds the unparsed JSON card.",'The list contains aliases only. A pinned version such as "jev-1.13.0" is a valid model even though it does not appear here, and the list is scoped to the authenticated account — do not hard-code names read from someone else\'s list.']],["UniLM.TypeSafeModelsSuccess","UniLM.TypeSafeModelsSuccess",["Successful list_models result: the TypeSafeModelCards and the unparsed body."]],["Accessors","Accessors",['getindex, haskey and keys also work on a SystemOneSuccess and a SystemOneResponse, so result["urgency"] is answer(result, "urgency"). On a SystemOneFailure or SystemOneCallError all of them throw SystemOneError instead of returning an empty map.']],["UniLM.answers","UniLM.answers",["The answers of a SystemOneSuccess (or a SystemOneResponse), keyed by question name.","A SystemOneFailure or SystemOneCallError throws SystemOneError: a call that produced no answers must not read as a call that answered with none. answer, getindex, haskey and keys throw the same error on those two results — a call that never answered has no key set to query either."]],["UniLM.answer","UniLM.answer",["The answer to one question by name (a String or Symbol). A name that was not asked throws a KeyError; a failed call throws SystemOneError, as answers does."]],["Provider protocol","system_one_protocol_api",["Every System One verb reaches its backend through a protocol, a Holy trait of the endpoint: system_one_protocol maps an endpoint to a SystemOneProtocol, whose encode_system_one turns a request into a SystemOneWire — what is sent, and the record_body a recording is keyed on and writes; refusing, before any I/O, what its backend cannot carry — and whose decode_system_one turns the reply into a typed result, its answers checked against the request. The rest is shared by every backend: the backend and model a call resolves (through with_system_one), recording and replay, retries and cancellation, the connection pool, and credentials, which auth_header supplies only when a request really goes out, so a replay needs no key. Three protocols ship: TypeSafeProtocol above, and OpenAIDecisionsProtocol and OllamaSystemOneProtocol in their backends' sections.","An endpoint that declares :system_one and no protocol of its own speaks TypeSafeProtocol, TypeSafe's wire — a TypeSafe-compatible gateway or proxy needs no protocol code (Service Endpoints shows one). A protocol other than TypeSafe's files its recordings under a namespace of its own, before the request's path (/ollama/v1/systemone), so two backends never replay each other's answers, while every TypeSafe recording keeps its key."]],["UniLM.SystemOneProtocol","UniLM.SystemOneProtocol",["Abstract supertype of the System One wire protocols, the trait value system_one_protocol returns for an endpoint. A protocol is a singleton type; its methods of encode_system_one and decode_system_one are the whole of a backend's wire. TypeSafeProtocol is the first.","Public extension API (not exported)."]],["UniLM.TypeSafeProtocol","UniLM.TypeSafeProtocol",['TypeSafe\'s System One wire: POST {base}/v1/systemone with the JSON body {"state", "model", "questions"} in the System One JSON form, answers decoded from {"model", "answers", "usage"}, the request id read from the x-typesafe-request-id header, and failures from TypeSafe\'s three error-body shapes. Recordings are keyed under the plain path (no namespace). It sends a RawQuestion verbatim and never expects a refusal.','TypeSafe marks images and Box questions "Dreamer-ready": they "aren\'t yet up to our standards to call ready for production", and their request format, answers and limits "can change between releases" (Images). Each distinct ImageAttachment of a request — in the state, an instruction, a criterion or a raw question\'s fields — is sent once, as a part of a multipart/form-data request whose first part, request, holds the JSON body; every place the image stood holds its reference, "<image:…>" with the first 32 hex digits of the SHA-256 of its bytes, and the body lists the parts under assets. A request with an image or a BoxQuestion carries the header TypeSafe-Danger-Zone-Images: true: passing one is the opt-in. A Score level that is an image comes back in the answer\'s legend as that ImageAttachment. The one provider option, long_context = true, sends TypeSafe-Danger-Zone-Long-Context: true, which raises the context limits from 64k tokens per request and 32k per question to 262k at the same price per token.','Before any I/O it refuses what TypeSafe rejects: more than 255 options in a Choice or 10 levels in a Score; an image that is not a still PNG or JPEG, is over 16 MiB, has a side under 280 or over 1568 pixels, whose header cannot be read, or a JPEG that does not end with its end-of-image marker; more than 64 levels of nested objects and arrays in the state, an instruction or a criterion; a body over 32 MiB; a DocumentAttachment anywhere, as on every System One backend; an image\'s detail level, for which an image asset has no field; and any option but long_context. Two terse failures get a hint in their message: a context overflow (error_type = "max_tokens_exceeded") names long_context and the limits, and the "Invalid request." a Box question draws from a Jev before 1.14 names the models that answer one.',"The untyped fallback of system_one_protocol returns it, so TYPESAFEServiceEndpoint and every endpoint that declares :system_one without a protocol of its own speak it.","Public extension API (not exported)."]],["UniLM.system_one_protocol","UniLM.system_one_protocol",["The System One protocol service speaks — a Holy trait over endpoints. A backend adds a method following provider_capabilities' convention: on ::Type{MyEndpoint} for a singleton endpoint, on the instance for one with fields. The untyped fallback returns TypeSafeProtocol(), so every endpoint that declares :system_one and no protocol — a TypeSafe-compatible gateway or proxy, a test mock — speaks TypeSafe's wire.","Public extension API (not exported)."]],["UniLM.encode_system_one","UniLM.encode_system_one",["The exchange request is sent as on service. A protocol checks here, before any I/O, everything its backend cannot carry — its limits, the question kinds it does not know, content such as images it cannot send, the options it does not accept — and throws an ArgumentError naming the backend, the rule and the fix; it resolves request.model === nothing to its default. ask calls it outside the exchange's error handling, so its ArgumentError reaches the caller and nothing is sent. Each built-in encoder first calls UniLM._check_request(p, service, request) (internal), the refusals every backend shares, and one that takes Box questions UniLM._check_box_image(request); an encoder of your own runs them only by calling them too.","Public extension API (not exported)."]],["UniLM.decode_system_one","UniLM.decode_system_one",["The typed result of response, the reply service sent to request: a SystemOneSuccess, or a SystemOneFailure for a status other than 200. A 200 that is not a usable answer throws, and ask returns the throw as a SystemOneCallError carrying the reply's request id. Each built-in decoder checks the answers against the request before it builds the success — one per question asked, of the question's kind, each value in its range (see ask) — by calling UniLM._check_answers(p, request, response) (internal). A decoder of your own gets these checks only by calling it too: UniLM checks nothing else of the result.","Public extension API (not exported)."]],["UniLM.SystemOneWire","UniLM.SystemOneWire",["One System One exchange as a protocol encoded it — what is sent and what its recording is keyed by. Credentials are not part of it: the endpoint's auth_header is read only when the request really goes out, so a replay needs no key.","Fields","Public extension API (not exported)."]],["Recorded answers","Recorded-answers",["A service does not answer a repeated request identically, so a test or a docs build that calls it live cannot be reproduced. with_recorded_answers records a real answer once and replays it offline. Inside its scope, ask and TypeSafe's list_models (and so nl_dispatch, nl_classify and @branch), chatrequest! and respond, streamed or not, and embeddingrequest! (and so the tool loops), the Responses lifecycle calls, fim_complete and prefix_complete exchange through a directory of recordings keyed by the exact request bytes — with any credential the body carries redacted, every base64 data: URL it carries (an image, a PDF, audio, any media) replaced by the SHA-256 of its base64 text, and a System One backend's options that change how a request is served left out (media sent as bare base64 are written as sent, such as Ollama's chat images or an input_audio clip, except the images of an Ollama System One request and the media of an Ollama embeddings request, keyed and written by digest too); images, audio, files, MCP and every other verb reach the network as usual. In the default :replay mode no recorded verb reaches the network and none needs a key, and a request with no recording, or an unreadable one, throws ReplayMissError; :record and :record_missing call the service — with its key, or its local server running — for the answers they write. A build of this documentation without a recording flag replays every such example, System One and LLM alike."]],["UniLM.with_recorded_answers","UniLM.with_recorded_answers",["Run f() with the service exchanges inside it passing through the recordings in dir, and return f()'s value. Recorded: ask (and so nl_dispatch, nl_classify and @branch), TypeSafe's list_models, chatrequest! (with its keyword form and tool_loop!) and respond (with its convenience forms and tool_loop), streamed or not, embeddingrequest!, the Responses lifecycle calls (get_response, delete_response, list_input_items, cancel_response, compact_response, count_input_tokens), fim_complete and prefix_complete. Everything else reaches the network as usual — images, audio, files, batch, moderation, the model listings other than TypeSafe's, Ollama's model pulls, realtime, MCP and every other verb behave inside a scope exactly as outside it.","A service does not answer a repeated request identically, so a test or a docs build that calls it live cannot be reproduced; one recorded answer, replayed, can. A request's bytes can depend on the clock: a follow-up that sends an OpenAI audio reply back by its id sends it as text from a minute before the audio's expires_at (AudioOutput), so its recording, made while the audio was live, replays only until then; record such a follow-up after the expiry.","A recording is written after the service has answered, and billed, so both recording modes create dir if needed and prove it writable — a file is created in it and removed — before f runs: a dir that is a file, or a directory that refuses a file, is an ArgumentError naming the path and the cause, and nothing is sent. A recording that still cannot be written once an answer has arrived — the directory was removed or replaced, the disk is full — throws RecordingWriteError, with that I/O error as its cause, out of the verb (and so out of nl_dispatch, nl_classify, @branch and the tool loops, a dispatcher's own request included) instead of returning its call error: the answer was paid for, and a caller's r isa SystemOneSuccess || fallback() path must not absorb the lost write as a service failure. A streamed call reads its reply inside the task it returns, so its lost write — and a miss on a later request of a turn the provider continues (Gemini 4 Argon's long decode) — is thrown inside that task: fetch, and so tool_loop! on a streamed chat, throws a TaskFailedException whose task.exception is the error. A miss on the first request is thrown by the streamed verb itself. A miss or lost write of a recorded call made in a stream's callback or on_tool_call is thrown inside the stream's task too, as the callback threw it.",'A recording is <dir>/<key>.json, where key is the lowercase hex SHA-256 of "<METHOD> <path>\\n" followed by the exact request body, and <path> is the path of the request URL alone: never its host, nor its query, which can carry a credential. A System One backend other than TypeSafe files its requests under a namespace of its own, followed by its wire\'s path — "/openai-decisions/v1/decisions" for OpenAI\'s Decisions API, "/ollama/v1/systemone" for Ollama — so the same question asked of two backends is two recordings; a System One request that carries an option its backend keys (TypeSafe\'s long_context) or image parts, and a list_input_items request, whose query names the page, append a newline and their canonical text — options and the page\'s limit, order and after as sorted name=value lines with JSON values, parts as their names and SHA-256 digests — to the body they are keyed on, so a request without them keeps its key; and a System One backend keys its body without the options that change how a request is served but never what it is answered — Ollama\'s keep_alive, OpenAI\'s prompt_cache_key, safety_identifier and prompt_cache_options — which are sent, and neither keyed nor written, so the same question replays one recording whatever they are. The key is never a canonical form of the request: the order of Choice options and of the state\'s keys moves the answer, so a reordered request is a different request. Two changes are made to the body. A credential it carries: in each object of its top-level tools array, an MCP tool\'s authorization and headers ("type": "mcp", the OpenAI Responses wire), a Gemini Interactions MCP server\'s headers ("mcp_server") and the api_key of a Gemini "retrieval" tool\'s exa_ai_search_config and parallel_ai_search_config read "<redacted>" in the key, the file and a ReplayMissError, so a replay needs none of them; the request sent carries them as given. And every base64 data: URL it carries — an image, a PDF, audio, any media: an OpenAI chat attachment, an OpenAI Decisions image, a Responses input_image or input_file — reads data:<mime>;sha256,<hex>, the SHA-256 of that base64 text, in the key, the file and a ReplayMissError: a recording names the media it answered without holding their bytes, and other media is another request. The file holds the request (with that canonical text as key_extra when there is one), the response body — for a streamed request, the lines of the streamed body (stream) — with its request id, the name of the header that carried it (x-typesafe-request-id, x-request-id or request-id) and the headers a replay gives back (headers: the request-id headers and x-gemini-service-tier, the tier Gemini billed the reply at, those the reply carried), and the time of recording, pretty-printed so a diff is readable; the API key, every other header, an MCP tool\'s authorization and headers, and the bytes of media sent as a base64 data: URL or as a System One image part are never written. Media sent as bare base64 is written as sent — Ollama\'s chat images, an input_audio clip — except the images and sound clips of an Embeddings request to an OllamaEndpoint and the images of a System One request to one: they are keyed and written as their digests, data:<mime>;sha256,<hex>, as the same media sent as a data URL would be. A replay gives back the headers its recording kept; a recording made before they were kept gives back its request id alone, under the header it names (x-typesafe-request-id when it names none). Files are written atomically (a temporary file in dir, then a rename), so concurrent tasks can record at once. A replayed answer goes through the same decoding as a live 200 and has the same type and fields: a Chat gets the reply appended and its cost accumulated, and Embeddings get their vectors. A replayed stream is read through the same parsers and callbacks as a live one, with no first-byte deadline or idle guard; a stream is recorded only when its reply is whole — its final event arrived: the sentinel ([DONE], Anthropic\'s message_stop, Ollama\'s done), the end of a native Gemini stream, or a Responses or Interactions terminal event — and was read with no stop, also when its connection fails after that event. A stream that ends with an error event, or is cut before its final event, is not recorded, even when the call keeps the turn its finish reason completed. A cancelled token ends a call before any recording is read, exactly as it ends one before anything is sent.',"The scope is a ScopedValue, so it covers the tasks started inside f (Threads.@spawn, asyncmap). Scopes nest: an inner scope's service is the enclosing scope, so a :record scope inside a :replay scope copies the replayed answers without touching the network. A mode other than the three above is an ArgumentError, as is :replay with a dir that does not exist.","A request that has no recording yet is recorded by running the same code once with access to its service (TYPESAFE_API_KEY for Jev, OPENAI_API_KEY for OpenAI's Decisions API, a running server for Ollama) and mode = :record_missing."]],["UniLM.ReplayMissError","UniLM.ReplayMissError",["Thrown inside a with_recorded_answers scope when a request cannot be replayed — in :replay mode the directory holds no recording of it, or in :replay or :record_missing mode its recording file cannot be read as one — by the verbs the scope records: ask and TypeSafe's list_models (and so nl_dispatch, nl_classify and @branch), chatrequest! and respond, streamed or not, and embeddingrequest! (and so tool_loop! and tool_loop), the Responses lifecycle calls (get_response, delete_response, list_input_items, cancel_response, compact_response, count_input_tokens), fim_complete and prefix_complete. A verb the scope does not record — images, audio, files, MCP, … — never throws it: it behaves exactly as outside the scope. A streamed call throws it for its first request before returning its task; a miss on a later request of the turn (a reply the provider continues) is thrown inside that task, so fetch — and tool_loop! on a streamed chat — throws a TaskFailedException whose task.exception is it, as it does for a miss of a call made in the stream's callback (task.exception is then what the callback threw). It is thrown rather than returned as the verb's call error (SystemOneCallError, LLMCallError, ResponseCallError, EmbeddingCallError, FIMCallError): a gap in the recordings is not a service failure, and a caller's r isa SystemOneSuccess || fallback() path must not absorb it as if it were one.","Fields","showerror names the request line, the start of the key, what the request asked for — a System One request's questions, any other request's model when its body names one — the directory or (for an unreadable recording) the file, and how to record the answer: with TYPESAFE_API_KEY set for a TypeSafe request, with access to the provider — its API key, or a local server running — for any other. An unreadable file must be deleted first, because :record_missing never overwrites one."]],["UniLM.RecordingWriteError","UniLM.RecordingWriteError",["Thrown inside a with_recorded_answers scope in :record or :record_missing mode when the service has answered a request, and billed it, but its recording cannot be written — the directory was removed or replaced after the scope checked it, or the disk is full. The verbs the scope records throw it — ask, TypeSafe's list_models, chatrequest!, respond, embeddingrequest!, the Responses lifecycle calls (get_response, …), fim_complete and prefix_complete — and so do the calls built on them: nl_dispatch, nl_classify, @branch and the tool loops, a request made by a loop's dispatcher included. A streamed call reads its reply inside the task it returns and throws it there, so fetch — and tool_loop! on a streamed chat — throws a TaskFailedException whose task.exception is it; so does a stream whose callback made the call (task.exception is then what the callback threw). It is thrown rather than returned as the verb's call error: the answer was paid for, and a caller's r isa SystemOneSuccess || fallback() path must not absorb the lost write as a service failure. An MCP server tool handler's is answered, like a ReplayMissError, with the generic JSON-RPC -32603 and logged, never relayed to the client.","Fields","showerror names the file and the cause, and says that the answer was billed."]]]},{url:"/api/uploads/",sections:[["Uploads API",null,["Resumable, multi-part uploads for large files — beyond the single-request limit of the Files API. Create an upload, add its parts, then complete it to receive a FileObject. OpenAI only."]],["Objects","Objects",[]],["UniLM.UploadObject","UniLM.UploadObject",["A resumable upload session: id, status, filename, and bytes; once the upload is completed, file holds the resulting FileObject. raw holds the unparsed JSON response."]],["UniLM.UploadPartObject","UniLM.UploadPartObject",["A single uploaded part; its id is passed to complete_upload to assemble the final file. raw holds the unparsed JSON response."]],["Result Types","Result-Types",[]],["UniLM.UploadSuccess","UniLM.UploadSuccess",["Successful create/complete/cancel result wrapping an UploadObject."]],["UniLM.UploadPartSuccess","UniLM.UploadPartSuccess",["Successful add_upload_part result wrapping an UploadPartObject."]],["UniLM.UploadFailure","UniLM.UploadFailure",["Uploads API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.UploadCallError","UniLM.UploadCallError",["Uploads API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout."]],["Request Functions","Request-Functions",[]],["UniLM.create_upload","UniLM.create_upload",['purpose takes the Files API purposes ("assistants", "batch", "fine-tune", "vision", "user_data"); any other value throws ArgumentError before any request, "evals" naming the Evals API\'s shutdown on 2026-11-30.',"Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.add_upload_part","UniLM.add_upload_part",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.complete_upload","UniLM.complete_upload",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.cancel_upload","UniLM.cancel_upload",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["Usage","Usage",[]]]},{url:"/api/vector_stores/",sections:[["Vector Stores API",null,["Create and manage vector stores, along with their files and file batches, that power the Responses file_search tool. Upload files via the Files API first. OpenAI only."]],["Objects","Objects",[]],["UniLM.VectorStoreObject","UniLM.VectorStoreObject",["A vector store from the Vector Stores API: id, name, status, and file_counts; raw holds the unparsed JSON response."]],["UniLM.VectorStoreFileObject","UniLM.VectorStoreFileObject",["A file attached to a vector store: id and status; raw holds the unparsed JSON response."]],["UniLM.VectorStoreFileBatch","UniLM.VectorStoreFileBatch",["A batch of files added to a vector store: id, status, and file_counts; raw holds the unparsed JSON response."]],["UniLM.VectorStoreList","UniLM.VectorStoreList",["A page of VectorStoreObjects from list_vector_stores; has_more signals that further pages are available."]],["Result Types","Result-Types",[]],["UniLM.VectorStoreSuccess","UniLM.VectorStoreSuccess",["Successful create/retrieve result wrapping a VectorStoreObject."]],["UniLM.VectorStoreListSuccess","UniLM.VectorStoreListSuccess",["Successful list_vector_stores result wrapping a VectorStoreList."]],["UniLM.VectorStoreFileSuccess","UniLM.VectorStoreFileSuccess",["Successful add_vector_store_file result wrapping a VectorStoreFileObject."]],["UniLM.VectorStoreBatchSuccess","UniLM.VectorStoreBatchSuccess",["Successful file-batch result wrapping a VectorStoreFileBatch."]],["UniLM.VectorStoreDeleteSuccess","UniLM.VectorStoreDeleteSuccess",["Successful delete_vector_store result: the service confirmed (deleted is always true) the removal of id."]],["UniLM.VectorStoreFailure","UniLM.VectorStoreFailure",["Vector Stores API error result: HTTP status, the raw response body, and the request_id the service sent (x-request-id/request-id header), if any."]],["UniLM.VectorStoreCallError","UniLM.VectorStoreCallError",["Vector Stores API call that produced no usable reply (transport failure, timeout, or a 200 that could not be decoded); cause is the underlying exception — a UniLMTimeout for a timeout. last_observed is set only when poll_file_batch runs out of time or is cancelled: the last VectorStoreFileBatch it saw, if any."]],["Request Functions","Request-Functions",[]],["UniLM.create_vector_store","UniLM.create_vector_store",["Create a vector store. Returns VectorStoreSuccess, VectorStoreFailure, or VectorStoreCallError.","Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_vector_store","UniLM.retrieve_vector_store",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.list_vector_stores","UniLM.list_vector_stores",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.delete_vector_store","UniLM.delete_vector_store",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.add_vector_store_file","UniLM.add_vector_store_file",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.create_file_batch","UniLM.create_file_batch",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.retrieve_file_batch","UniLM.retrieve_file_batch",["Pass config::Union{Nothing,RequestConfig} to override the timeout budget for this call (a single bounded attempt; max_attempts does not apply)."]],["UniLM.poll_file_batch","UniLM.poll_file_batch",["Poll a file batch until it reaches a terminal status (completed/failed/cancelled) and return that VectorStoreBatchSuccess. timeout bounds the wall-clock time of the whole poll (Inf waits indefinitely); interval is the pause between GETs. Both must be positive, else ArgumentError.","A transient failure — a status in the retryable set (408/429/500/502–504/520–524/529) or a GET that timed out — is polled through; any other failure is returned as it came. When the time runs out the result is a VectorStoreCallError with cause = UniLMTimeout(:deadline, …) and last_observed set to the last VectorStoreFileBatch seen (nothing if no GET succeeded).","Pass cancel::Union{Nothing,CancelToken} (default: the ambient with_cancel token) to make the poll cancellable: a cancel ends it at once, mid-GET or mid-pause, with a VectorStoreCallError whose cause is a UniLMCancelled and last_observed as above; a token cancelled before the poll sends nothing.","Pass config::Union{Nothing,RequestConfig} to bound each GET (a single attempt; its total_deadline is capped at the time left)."]],["Accessors","Accessors",[]],["UniLM.vector_store_id","UniLM.vector_store_id",["Return the id of a VectorStoreObject, for use in file and batch calls."]],["Usage","Usage",[]]]},{url:"/api/webhooks/",sections:[["Webhooks API",null,["Verify inbound webhook signatures (Standard Webhooks / HMAC-SHA256) and parse events into typed values. This is an inbound utility with no provider endpoint — HMAC is built on the SHA standard library. OpenAI webhooks."]],["Types and Constants","Types-and-Constants",[]],["UniLM.WebhookEvent","UniLM.WebhookEvent",["A parsed webhook event from parse_webhook: id, type, and created_at; data holds the event payload and raw the unparsed JSON response."]],["UniLM.WEBHOOK_EVENTS","UniLM.WEBHOOK_EVENTS",["The event types of OpenAI's webhooks (reference): background responses, batches and fine-tuning jobs that end, incoming SIP calls for the Realtime and Live APIs, safety warnings and deactivations for a safety identifier, and safety alerts. live.call.incoming is deprecated in favour of live.transport.incoming and retained for existing subscriptions. The reference also lists eval.run.succeeded, eval.run.failed and eval.run.canceled, which OpenAI sends until its Evals API shuts down on November 30, 2026 (deprecations): they are left out, so a filter on this list drops them."]],["Functions","Functions",[]],["UniLM.verify_webhook","UniLM.verify_webhook",["Verify an OpenAI webhook signature (Standard Webhooks). payload is the raw request body; headers is a Dict or iterable of pairs containing webhook-id, webhook-timestamp, and webhook-signature; secret is the endpoint signing secret, with or without the whsec_ prefix: without it, the secret is read as base64 too, as the Standard Webhooks libraries read it (OpenAI's SDKs take an unprefixed secret's raw bytes as the key). Returns true iff a fresh, validly-signed v1 signature is present.","Replay protection: timestamps outside \xb1tolerance_seconds of now are rejected, as are timestamps that are not finite numbers — pass tolerance_seconds=Inf to skip the time check (e.g. when replaying a stored fixture). Uses a constant-time digest compare. Negative or NaN tolerances throw ArgumentError.",'Whitespace around secret is ignored. Throws ArgumentError before any check when the rest is empty ("", whitespace, or whsec_ alone): anyone can sign with an empty key, so under one a forged delivery would verify. Throws ArgumentError when the rest is not valid base64 — a character outside A-Z, a-z, 0-9, + and / (whitespace inside it included), or = padding anywhere but at its end or more than its last group lacks — for a delivery that reaches the signature check: that is a misconfiguration of this endpoint, and reporting it as an unverified signature would silently drop every webhook. A false return therefore always means the message failed verification.']],["UniLM.parse_webhook","UniLM.parse_webhook",["Parse a webhook JSON payload into a typed WebhookEvent. Verify the signature with verify_webhook first."]],["Usage","Usage",["WEBHOOK_EVENTS leaves out the eval.run.* events, which OpenAI sends until its Evals API shuts down on November 30, 2026: the filter above drops them, so match event.type yourself if you still run evals."]]]},{url:"/decisions/choosing/",sections:[["Choosing a decision provider",null,["UniLM has one decision surface. The questions — choice, score, noul, box — the verbs — ask, ask_each, nl_classify, nl_dispatch, @branch — and the typed results are the same whichever model answers. Three providers answer them, each with an entry of its own: Jev (TypeSafe), the default; OpenAI Decisions API; and Local decision models served by Ollama on your own machine. Each provider has a wrapper that knows its rules. What a provider cannot carry is refused with an ArgumentError before anything is sent, so a request never reaches a provider in a form that provider would read differently."]],["The same call on three providers","backends_same_call",["The job: route the support desk's inbox on the provider that suits it — a hosted model, or one on your own machine — without rewriting the router. Without one surface: a client per provider, each with its own request shape, answer format, errors and tests. With it: the same nl_classify call, and service = names the provider.","Under each message, a line per provider: the team it chose, and the confidence of its answer. The three agree on four of the six messages. They part on the other two: the question about shipping to Norway goes to billing on Jev, at a confidence of only 0.49, and to other on the other two; the cracked phone — a damaged parcel and a refund request in one message — goes to shipping on Jev, at 0.98, and to billing on the other two, both times at a confidence below 0.5. The code around the call did not change: whichever provider answered, the result is a key of TEAM. The confidences of different providers are not the same currency (One formula, calibrated per model)."]],["Choose per call or per scope","backends_choose",["A call takes its provider from the first of these that is set:","Its model is the call's own model = …; else, when the call names no service, the scope's model; else the provider's default, the model at the top of its entry — on TypeSafe TYPESAFE_DEFAULT_MODEL instead when it is set, read when the request is sent; on Ollama none, so a call that names no model there is an ArgumentError before anything is sent. Its provider options follow the same rule: the call's own — keywords of ask and ask_each, options = (…) on the natural-language verbs — else, when the call names no service, the scope's, set as keywords of with_system_one: with_system_one(OllamaEndpoint(); model = \"tev1:0.8b\", keep_alive = 600) do … end. The provider's wrapper checks them when each request is sent.","The second call names its own service, and the scope's model does not follow it: a model belongs to its provider, and tev1:0.8b means nothing to TypeSafe.","Tune it"]],["What each provider takes","backends_table",["The Where a picture may stand row is what UniLM sends. TypeSafe takes a picture \"anywhere text can go in a System One request\" (Images). OpenAI's API also takes pictures in a question's instructions, one of the additions its guide lists since the public beta (Decisions guide), which UniLM refuses. Ollama takes a request's pictures as one list, images, shared by every question (System One), apart from the state's text, and by Ollama's source Clef reads them before that text (decision/clef.go); UniLM refuses a picture after a text on every model. Each entry has the rest: Jev's Images, OpenAI's Questions and Ollama's Images.","A timeout you set yourself — config =, with_request_config or set_default_config! — replaces a provider's default.","Refused before sending","The job: move a program to another provider and learn, before a request is paid for, what it uses that the provider cannot carry. Without a wrapper: the provider answers 400 — or accepts the request and reads it differently. With one: each wrapper checks a request against its provider's rules first, and its ArgumentError names the provider, the rule and the fix:","None of these reached a server. A wrapper refuses rather than adapts: dropping a Noul's yes/no, or sending an image as text, would answer a question you did not write, and the answer would carry no sign of the change. The question types themselves set no limit, so a program built for one provider is checked against another's rules only when it is sent there. Each entry's Limits and refusals section lists its refusals: Jev, OpenAI, Ollama."]],["One formula, calibrated per model","backends_confidence",["The job: act on an answer only when the provider is sure enough, on whichever provider answers. Without a shared definition: each provider's \"confidence\" is its own number. With one: TypeSafe sends confidence by one formula, UniLM computes it by the same formula on Ollama, and OpenAI's own value matched it in the Choice answers recorded here; how much a value is worth still depends on the model, so a threshold is tuned for each.","confidence is TypeSafe's published measure (Confidence): (n\xb7p_max − 1)/(n − 1) for a Choice of n options, and 1 − Σᵢ pᵢ\xb7|i − m| / MAD_unif for a Score whose most likely level is m, floored at 0. TypeSafe sends it with each answer, and OpenAI's own confidence equals the Choice formula, to two decimals, in every Choice answer recorded for this manual (Confidence and tuning). Ollama documents its own measure, 1 − H(p)/ln N, a measure of the whole distribution's entropy (System One), so the Ollama wrapper computes TypeSafe's from the probabilities for every model and keeps the server's value in the answer's raw (Confidence and tuning):","tev1 put 0.811 of the probability on other, out of four options: TypeSafe's formula makes that a confidence of (4 \xd7 0.811 − 1)/3 = 0.748, while the entropy measure Ollama reports reads the same answer as 0.638. On TypeSafe and Ollama, confidence is the first kind of number, and so is OpenAI's in the Choice answers recorded here.","One formula is not one calibration. On our labelled tickets, Jev's top probabilities matched how often it was right, while OpenAI's Decisions API was right more often than its top probability said: it is under-confident. The same min_confidence therefore hands a different share of the inbox to a person on each provider — at 0.8, 14 of 129 tickets on Jev and 28 on OpenAI, though both were right on nearly every ticket they kept. A threshold tuned on one provider does not carry over to another.","Measured on 20 October 2026 on our 129 labelled support tickets (60 clear, 32 borderline, 15 adversarial, 22 out of scope): one Choice of seven intents per ticket, each option a name with a description, the same request on both providers, one call at a time.","On OpenAI, accuracy was at or above the mean top probability in every bin above 0.5. The expectation we wrote down before the run, OpenAI's accuracy within 3 points of Jev's, was not refuted (−2.3 points). Limits: one labelled set, one run per provider, one way of writing the options. On the same tickets, the nine local decision models measured on 21 October 2026 were right on 0.690 to 0.938 of them (Models).","Tune it","Recorded on 28 September 2026 on jev-1.13.0 with UniLM's development branch after 0.21.0, and on 19 October 2026 on gpt-6-luna and on tev1:0.8b (Ollama 0.40.6) with UniLM's development branch after 0.23.0, through TypeSafe's API at /v1, OpenAI's at /v1/decisions and Ollama's /v1/systemone."]]]},{url:"/decisions/custom/",sections:[["Write your own decision provider",null,["A decision provider is an endpoint that declares :system_one among its provider_capabilities: ask, ask_each, nl_classify, nl_dispatch, @branch and with_system_one accept it, and reach it through its protocol, a Holy trait of the endpoint that says how a request is sent and how its reply is read. A service that speaks TypeSafe's wire needs no protocol of its own; a service with a wire of its own needs one."]],["A gateway on TypeSafe's wire","decisions_custom_gateway",["A server that speaks TypeSafe's wire needs no code at all to receive TYPESAFEServiceEndpoint's requests: set TYPESAFE_BASE_URL to its root, and every request goes there, read when each is sent (Setup). To give such a server an endpoint of its own, beside TypeSafe's, declare :system_one, its root and its credentials; an endpoint without a system_one_protocol method speaks TypeSafeProtocol, TypeSafe's wire. _api_base_url is an internal hook (Internal hooks):","ask(state, questions...; service = JevGateway) sends that request there, with the key read from JEV_GATEWAY_KEY only when it goes out. Its request bodies are TypeSafe's byte for byte (the headers are its own auth_header's), with TypeSafe's limits, default model, timeouts and retries, and its recordings are keyed as TypeSafe's — on the request's path and body, never its host — so an answer recorded through one replays for the other (Testing and recordings)."]],["A protocol of your own","decisions_custom_protocol",["A protocol is a singleton type, a subtype of UniLM.SystemOneProtocol, and three methods make it a provider. They are UniLM's public extension API, not exported:","Three protocols ship with UniLM: UniLM.TypeSafeProtocol (TypeSafe's POST /v1/systemone), UniLM.OpenAIDecisionsProtocol (OpenAI's POST /v1/decisions, for OPENAIServiceEndpoint) and UniLM.OllamaSystemOneProtocol (Ollama's POST /v1/systemone, for OllamaEndpoint). The endpoint itself declares :system_one in provider_capabilities and gives its credentials in auth_header, which UniLM reads only when a request goes out, so a replay needs no key. The rest is shared by every provider: the provider, model and options a call resolves (with_system_one), recording and replay, retries and cancellation, the connection pool and the typed results. A labelling service whose wire takes a text and its labels and answers one label with a score for each:","decode_system_one types its reply as an HTTP.Response, as UniLM's own method does: left untyped, a call would match both methods equally and Julia would refuse it as ambiguous. The encoder and the decoder run on their own, with no service:","With these, ask(state, \"team\" => choice(…); service = LabelAPI), a with_system_one(LabelAPI) scope, nl_classify and @branch reach the service (nl_dispatch sends a JSON object, which this encoder refuses), and with_recorded_answers records and replays its exchanges, filed under /LabelProtocol/v1/label: the protocol's name in front of the wire's path, so they never replay as another provider's. The encoder refuses what the wire cannot carry rather than adapt it, as every built-in provider does: a request changed to fit would ask a question you did not write."]],["Internal hooks","decisions_custom_hooks",["The shared machinery asks a protocol a few more things through functions whose names start with _. They are internal: not part of UniLM's public API, they can change in any release, and a protocol that defines them must be checked again on each upgrade. Each has a fallback, which a protocol that defines nothing gets:","Only _check_answers runs the checks every provider's answers pass, as UniLM.decode_system_one states: a protocol of your own that does not call it returns whatever its decoder built. The built-in protocols are in the API reference, with the seam: Provider protocol.","See also: UniLM.SystemOneProtocol, UniLM.system_one_protocol, UniLM.encode_system_one, UniLM.decode_system_one and UniLM.SystemOneWire in the API reference, and Write your own backend for a language-model provider."]]]},{url:"/decisions/jev/",sections:[["Jev (TypeSafe)",null,["Jev is TypeSafe's System One model: it reads a state — a text or a JSON record — and answers the questions you list about it with a probability for each answer you allowed (a box's edges, for a Box question), writing no text, and TypeSafe bills only the input tokens it reads. TYPESAFEServiceEndpoint speaks TypeSafe's API, POST /v1/systemone for decisions and GET /v1/models for the model listing, and UniLM wraps both. The endpoint serves these two alone: the verb of every capability the table below does not list, chatrequest! and respond among them, refuses it before sending anything."]],["Setup","jev_setup",["Get an API key from the TypeSafe console and set it in the environment Julia starts from:","UniLM reads the three when each request is sent, so a value exported after using UniLM takes effect, and a blank value counts as unset. A call goes to Jev when it names no service and no with_system_one scope around it names another provider; service = TYPESAFEServiceEndpoint names Jev explicitly, and TYPESAFEServiceEndpoint() returns that same type. A call's model is its own model = …; else, when it names no service, the model of the scope around it; else TYPESAFE_DEFAULT_MODEL, and the default model at the top of this page when that is unset. The endpoint has no options of its own, and its one request option, long_context, has a section of its own (Long context)."]],["First decision","jev_first_decision",["One request carries the state once and every question about it; each answer comes back under the name you gave its question:",'a.choice is the most probable option, a.probabilities holds one probability per option, and a.confidence says how peaked they are (Confidence and tuning). A failed call has no answers: r["team"] throws a SystemOneError on it, so a decision is never read from a call that did not happen (When something fails).',"The call named no model, so it was sent with the default model at the top of this page, an alias, and r.response.model is the versioned id that answered (Models). nl_classify makes the same kind of decision in one call and returns the key whose description fits (Dispatch on Meaning):"]],["Models","jev_models",["TypeSafe serves Jev under aliases and versioned ids, and a call sends either as its model (Models):","list_models returns the names the account may send, each with a description and a release date; TypeSafe's listing holds the aliases:","release_date is the string the service sends, an RFC 3339 timestamp, where TypeSafe's API reference documents YYYY-MM-DD (List models); UniLM does not parse it. A live listing on 25 October 2026 returned these two cards unchanged.","r.response.model names the versioned id that answered, which TypeSafe's response reports in place of the alias (System One): log it, since an alias that moves is otherwise invisible. A threshold tuned against one version is a claim about that version, so once you have tuned one, pin the version — model = … on the call, TYPESAFE_DEFAULT_MODEL in the environment, or the model of a with_system_one scope — and move the pin on your own schedule:","TypeSafe publishes the failure modes it knows of Jev 1.13 (Jev 1.13 jaggedness); on 25 October 2026 its documentation index lists no such page for Jev 1.14. Jev 1.13 reads a question literally, does not count, compute or compare dates reliably, loses accuracy as unrelated material grows around the decision, and is not trained to generate text. Nor does it treat its state as hostile by default: text written to steer it, such as an injected instruction, can move its answer. Compute in Julia, send only what the decision needs, and leave text to a language model; Designing good questions turns these into rules for writing questions."]],["Questions","jev_questions",["Jev answers four kinds of question, in any mix in one request: a choice picks one option of a set, a score places the state on levels you describe, lowest first, a noul gives the probability that a statement holds, and a box locates something in a picture (Locate with Box). A RawQuestion goes out as you wrote it, for a kind UniLM does not model. Each question is evaluated against the same state on its own: one answer is never context for another (Primitives).","What reaches the model:",'A Choice takes up to 255 options and a Score up to 10 levels, and TypeSafe advises at least two levels (Score); a question over either limit is refused before the request is sent (Limits and refusals). Jev judges each Score level on its own against the state, without its number or its neighbours, so a level such as "worse than the previous level" gives it nothing to match (Score). A request may hold any number of questions as long as it fits the context. Reading the answers and the decision rules on them are on Route and Decide.']],["Limits and refusals","jev_limits",["What a request meets on TypeSafe (Models, Request rules and errors, Images), and which of it UniLM checks before sending:","ask, ask_each and the verbs built on them throw these ArgumentErrors before anything is sent. A wrapper refuses rather than adapts: a request changed to fit would ask a question you did not write, and its answer would carry no sign of the change.",'Like every decision provider, the endpoint also refuses, before anything is sent, a blank or repeated question name, criteria that are not valid, a state or guidance holding NaN or Inf (TypeSafe\'s request rules read "Finite numbers only. NaN, Infinity, and numbers too large to represent, such as 1e400, are rejected", Request rules and errors), and an AudioAttachment or a DocumentAttachment anywhere in the request; Reading answers covers a malformed request on every provider.',"Recorded on 25 October 2026 on jev-1.14.0 and jev-1.13.0 with UniLM's development branch after 0.26.0, and, on 28 September 2026, the nl_classify call (on jev-1.13.0) with UniLM's development branch after 0.21.0 and the model listing with UniLM's development branch after 0.20.1, through TypeSafe's API at /v1.","See also: TYPESAFEServiceEndpoint, ask, SystemOneSuccess and TypeSafeModelsSuccess in the API reference."]]]},{url:"/decisions/ollama/",sections:[["Local decision models",null,["Ollama serves decision models on your own machine — Tev1, Nimble, Kev, Clef Flash, Strands Decider and the others it lists as decision models — through its System One route, POST /v1/systemone, which answers choice, yes/no and scoring questions about a state with probabilities and writes no text (System One); no key is sent to a server of your own, and a local model costs nothing unless you price it. OllamaEndpoint(), the endpoint of the Ollama language-model entry, sends ask and the verbs built on it there, and no decision verb refuses it. Of the route, UniLM does not wrap a keep_alive given as a duration string; a cloud model reached through your local server takes the same requests as a local one, and a request to Ollama's cloud itself, https://ollama.com, carries the OLLAMA_API_KEY its inference needs and is not sent without it (Setup)."]],["Setup","ollama_decisions_setup",["Run Ollama, the desktop app or ollama serve, and pull a decision model:","Ollama 0.35.0 or later serves the route, and the Clef models, which read pictures, need 0.35.1 or later (Decision); from 0.40.0, Nimble, Tev1, Clef and Clef Flash run on MLX on Apple silicon (v0.40.0), and a cloud model through the local server needs 0.40.5 (System One). This page's measurements ran on Ollama 0.40.6, and its new examples on 0.40.11.","A call goes to Ollama when it names service = OllamaEndpoint(), or when it names no service and a with_system_one(OllamaEndpoint(); model = …) scope encloses it. Ollama has no default model: a call names an installed decision model with model = …, or, when it names no service, takes the scope's; a call left with no model is refused before anything is sent (Limits and refusals). OllamaEndpoint() reads OLLAMA_HOST when it is built, else http://127.0.0.1:11434 (Setup); no key is sent to a server of your own."]],["Options","ollama_decisions_options",["Of an OllamaEndpoint's arguments, a decision request carries three: its base_url, its keep_alive unless the call names one, and its runner. Its other arguments — truncate, shift and the OllamaOptions such as num_ctx — have no field on this route and are not sent, so the window is the one the model is loaded with, and \"input is never truncated\" (System One); load_model loads a decision model without them too (Models). The constructor's checks are on Options."]],["First decision","ollama_decisions_first_decision",["One request carries the state once and every question about it; each answer comes back under the name you gave its question:",'a.choice is the most probable option, a.probabilities holds one probability per option, and a.confidence says how peaked they are, which UniLM computes (Confidence and tuning). A failed call has no answers: r["team"] throws a SystemOneError on it (When something fails).',"r.response.model is the model the request named, Ollama sends no request id, and a local model's answer costs 0.0, with no warning, unless you gave the model's exact name a price row, in pricing= or added to DEFAULT_PRICING; a row UniLM ships for a hosted model never prices a local model that bears its name. A cloud model reached through the server — a tag of cloud, or one ending in -cloud — is priced by the requested name instead, as is every model a request to Ollama's cloud itself names (an endpoint whose server is https://ollama.com); UniLM's price table holds no row for one, so estimated_cost gives 0.0 with a warning that the row is missing (Cost Tracking). nl_classify makes the same kind of decision in one call and returns the key whose description fits (Dispatch on Meaning):"]],["Models","ollama_decisions_models",["On 25 October 2026 Ollama lists ten decision models: d3, tev1, nimble, clef, clef-flash, nimble-v3, pplx-decider, kev, laya and strands-decider; clef also runs in Ollama's cloud. The d1 and d1-omni models measured below are decision models by their own pages, with text and image input (d1, d1-omni). A model's name is model:tag; name the tag you measured, since a name without one means its latest tag (Setup). The model that answered is the one the request named: Ollama documents the reply's model as the \"Model name from the request\", and a cloud model whose reply drops its tag keeps the requested name in r.response.model, the reply's in raw.","Nine decision models answered the same 129 labelled support tickets, one Choice of seven intents each, through UniLM on one machine:","Each model's answer was the one Ollama sent: UniLM's probabilities equalled the server's reply to the same bytes, on all nine. How the hosted providers did on the same tickets is on Choosing a decision provider.","Measured on 21 October 2026 with Ollama 0.40.6 on an Apple M4 Max with 64 GB, through UniLM: one Choice of seven intents per ticket (60 clear, 32 borderline, 22 out of scope, 15 adversarial), one call at a time, keep_alive = Inf. Latency is the client's wall clock per warm call, measured again on a quiet machine; the first call loads the model. Jev and OpenAI: the run of 20 October 2026, on the same tickets.","The refutation we wrote down before the run — a model of 2B parameters or more right on fewer than half of the 60 clear tickets — did not occur (0.850 to 0.983). Repeated runs gave the same answers to every ticket; under other load on the machine, latencies rose up to about twofold. Limits: one labelled set, one machine, one way of writing the options; n = 129, so an accuracy near 0.95 is known to about \xb10.04.","list_models(service = OllamaEndpoint()) lists the installed models, decision models among them, as OllamaModel cards; it is not recorded, so it reaches the server even in a replay scope. On this machine:"]],["Questions","ollama_decisions_questions",['The route answers three kinds of question, in any mix in one request (System One): a choice picks one option, a score places the state on levels lowest first, and a noul gives the probability that a statement holds, its yes and no sent as the descriptions of "true" and "false". A RawQuestion is sent as written, for the server to judge; a box is refused (Limits and refusals). No answer is passed to a later question: "Answers are not passed to later questions" (System One). By Ollama\'s source at v0.40.11, though, every prompt for Nimble and Clef holds all the questions of the request, Clef\'s under "Decide every field jointly" (decision/prompts.go, decision/clef.go), while a Tev1 prompt holds its own question alone.',"What reaches the model depends on the model, since each family has its own prompt:","The route takes 1 to 64 questions, a Choice of 2 to 255 options and a Score of 2 to 10 levels, and a model may take fewer: the limits, and what each model measured takes, are on Limits and refusals. Reading the answers and the decision rules on them are on Route and Decide.","The natural-language verbs ask one Choice of the meanings you write. nl_dispatch sends the arguments it dispatches on as a JSON object, which the route takes as the state, and @branch its state as it is; with no model of their own they are refused like any call (Limits and refusals):"]],["Images","ollama_decisions_images",["A vision decision model answers questions about pictures: Clef and Clef Flash read PNG, JPEG and WebP images, from Ollama 0.35.1 (Decision), and the pages of d1 and d1-omni list image input. Measured here: clef-flash:9b, d1:3b and d1-omni:600m; other decision models whose model_info capabilities include :vision take the same request, untested. The pictures go first in the state, then its texts:",'One request asked both questions about the picture: clef-flash:9b saw red, at a confidence of 0.991, and gave "Is the shape round?" a probability of 0.945.']],["Limits and refusals","ollama_decisions_limits",["What a request meets on Ollama's route (System One), and which of it UniLM checks before sending:","ask, ask_each and the verbs built on them throw these ArgumentErrors before anything is sent. UniLM refuses what Ollama's route refuses in its shared checks or documents as its maximum, and what its API reference does not list, though some models read it; blank instructions too, which Ollama would read as none: not blank, as the reference's pattern: \\S requires. A wrapper refuses rather than adapts: a request changed to fit would ask a question you did not write.","Like every decision provider, the endpoint also refuses, before anything is sent, a blank or repeated question name, criteria that are not valid, a state or guidance holding NaN or Inf, and an AudioAttachment or a DocumentAttachment anywhere in the request; Reading answers covers a malformed request on every provider.","A model may take less than the route, and says so with its own HTTP 400, which comes back as a SystemOneFailure carrying Ollama's message. Measured on Ollama 0.40.6 (21 October 2026), the nine models answered as below; the messages begin with the question's name, question \"pick\": …, and the one-option Choice, which UniLM refuses before sending, was sent past that check:","A question without instructions, which UniLM refuses before sending: tev1:4b, nimble:9b and strands-decider:2b answered 400 instructions must be a nonempty string, object, or array, kev:0.8b-q8_0 400 questions.intent: \"instructions\" must be provided (for a question named intent), and of the five tried only clef-flash:9b answered. An option described by an object: kev:0.8b-q8_0 and d1:3b answered it, and tev1:0.8b refused it; UniLM refuses one for every model, as Ollama's API reference gives a description as a string. A 76,284-byte state came back as a 413 text and schema must not exceed 64 KiB from kev:0.8b-q8_0 (the installed GGUF Kev), d1-omni:600m and tev1:0.8b. By Ollama's source, a Kev model on Ollama's own runner (such as kev:0.8b-mxfp8) skips the shared checks, and takes 1 to 255 levels and a blank state (decision/kev.go); that is untested.","Measured with Ollama 0.40.6 on an Apple M4 Max on 21 October 2026, on the nine models of Models; the API reference and the 64 KiB and 32 MiB limits are Ollama's page of 25 October 2026."]],["Confidence and tuning","ollama_decisions_confidence",['Ollama documents its confidence as "Distribution concentration, calculated as 1 - H(p) / ln(N)", an entropy measure that is "Not calibrated correctness" (System One). UniLM does not pass it on: so that a threshold means the same on every provider, it computes confidence from the returned probabilities — (n\xb7p_max − 1)/(n − 1) for a Choice of n options, clamped to 0 … 1, as on Reading answers, and 1 − Σᵢ pᵢ\xb7|i − m| / MAD_unif for a Score whose most likely level is m, floored at 0 (Confidence); one outcome gives 1 — and keeps the server\'s value in the answer\'s raw:',"tev1 put 0.534 of the probability on billing, out of four options: the formula above makes that a confidence of (4 \xd7 0.5337 − 1)/3 ≈ 0.378, below the 0.6 asked for, so the message went to a person; the entropy measure Ollama reports reads the same answer as 0.375. The two measures part most on a peaked answer: tev1's answer about shipping to Norway, 0.811 on other, is 0.748 by the formula and 0.638 by the entropy (One formula, calibrated per model).","Probabilities are accepted when they sum to 1 within 0.00005 per outcome, since Kev models on Ollama's own runner round each to four decimals, and the chosen option when it lies at most 0.0001 below the most probable; a reply further off is a SystemOneCallError.","Measured on Ollama 0.40.6, an Apple M4 Max, 21 October 2026: the five MLX models (tev1:0.8b, tev1:4b, nimble:9b, strands-decider:2b, clef-flash:9b) reported the entropy measure, while Kev and the models on the llama.cpp runner (kev, d1, d1-omni) reported the Choice formula above. Repeated runs of the 129 tickets gave the same answer to every ticket, and in UniLM's live test suite on the nine models every probability distribution summed to 1 within 4.4e-16."]],["Testing and recordings","ollama_decisions_testing",["with_recorded_answers records an exchange with Ollama's route once and replays it with no server: ask, ask_each and the verbs built on them. A recording is filed under /ollama/v1/systemone, the request's path behind the namespace ollama, and keyed on the exact request: its method, that path, and its body, which names the model and, when the endpoint sets one, the runner. keep_alive is sent and left out of the key and the file, and a picture is keyed and written as data:<mime>;sha256,<hex>, the SHA-256 of its base64 text, never its bytes.","The replay names another host, where no server runs, and a keep_alive the recording did not, and is answered from the recording: neither is part of the key. Recording takes a running server with the model pulled, and replaying takes nothing; in this manual's build the recording scope above replays the manual's own recordings, so the example reaches no server either (How this manual runs its examples). list_models on Ollama is not recorded: inside a scope it goes to the server, as outside one.","The reply's confidence there is ignored: UniLM computes its own from the probabilities. An answer outside the offered options makes the call a SystemOneCallError, so nl_dispatch throws a SystemOneError, and no method runs."]],["Throughput","ollama_decisions_throughput",["ask_each sends one request per item and returns the results in input order; on Ollama it keeps one request in flight unless its ntasks says otherwise, as a local decision runner may serve one request at a time: Ollama starts Nimble's for one (#18750). How a batch backs off when a server is busy is on Many requests at once.","A request's questions may be scored one after another, so its latency grows with their number (#18750, open on 25 October 2026), and in the reply's input_tokens, \"Shared context is counted again when the model scores questions separately\" (System One). Keep the model loaded while a batch runs (keep_alive), and unload it when the batch is done; the first call loads it. Each model's warm latency, and its first call, are in the Evidence of Models."]],["When something fails","ollama_decisions_failures",['A call that reaches Ollama returns a SystemOneSuccess; a SystemOneFailure for a status other than 200, with the status and Ollama\'s message, and no request id; or a SystemOneCallError when no usable response came. A 200 whose answers do not fit the request — a question unanswered, an option that was not offered, probabilities that are no distribution within the rounding above — is a SystemOneCallError too. Reading an answer of a failed call (r["name"], answer, answers) throws a SystemOneError.',"UniLM sends a request again after a 408, 429, 500, 502, 503, 504, 520 to 524 or 529, up to max_attempts times within total_deadline, waiting at least what a retry-after-ms header asks for, else a Retry-After; any other status comes back as it is. Ollama brings no bounds of its own, since loading a model on a CPU can take minutes: with no RequestConfig of yours, a call has the field defaults, 600 s per attempt and 900 s in all (Timeouts & Retries).","The model-specific 400s are those of Limits and refusals, captured on Ollama 0.40.6. A model without vision answered a picture with image inputs are not supported by this decision model (tev1:0.8b) and registry.ollama.ai/library/kev:0.8b-q8_0 does not support vision (kev:0.8b-q8_0); a pinned runner without a build, on every model measured, with the no compatible manifest found 400. Ollama's page lists the 400, 401, 402, 404, 413 and 500 of the route (System One); the issues #18750, #19090 and #19062 were open on 25 October 2026.","Recorded on 25 October 2026 on tev1:0.8b through Ollama 0.40.11 with UniLM's development branch after 0.26.0; on 21 October 2026 the picture, on clef-flash:9b through Ollama 0.40.6, with UniLM's development branch after 0.24.0; and on 19 October 2026 the nl_classify calls, on tev1:0.8b through Ollama 0.40.6, with UniLM's development branch after 0.23.0; all through Ollama's /v1/systemone.","See also: OllamaEndpoint, ask, UniLM.OllamaSystemOneProtocol and OllamaModel in the API reference, and Ollama in the Language models chapter."]]]},{url:"/decisions/openai/",sections:[["OpenAI Decisions API",null,["OpenAI's Decisions API reads an input — a text, a JSON value, pictures — and answers the predicate, choice and score questions you list about it with a probability for each answer you allowed, writing no text; OpenAI bills the input and no output (Decisions guide). OPENAIServiceEndpoint, the endpoint of the OpenAI language-model entry, speaks it at POST /v1/decisions for ask and the verbs built on it, with the same key, and no decision verb refuses the endpoint. Of the API, UniLM does not wrap a conversation as input (messages, tool calls and their outputs), input_json parts, image URLs, pictures in a question's instructions, a score level's description, explicit cache breakpoints, the organization's Decisions usage endpoint or GPT-Live's Decisions integration."]],["Setup","openai_decisions_setup",["Set the API key of your OpenAI account in the environment Julia starts from:","A call goes to the Decisions API when it names service = OPENAIServiceEndpoint, or when it names no service and a with_system_one(OPENAIServiceEndpoint) scope encloses it; a call that names neither goes to the chapter's default provider (Decisions). A call's model is its own model = …; else, when it names no service, the scope's; else the default model at the top of this page. UniLM reads OPENAI_API_KEY when each request is sent, so a key exported after using UniLM takes effect; with none, a call sends nothing and returns a SystemOneCallError (When something fails). Requests go to https://api.openai.com, and no variable moves them.",'OpenAI\'s guide, fetched on 25 October 2026, opens with "The Decisions API is now generally available" and lists what the API gained "since the public beta": prompt caching, pictures in question instructions, JSON input, up to 400 questions per request, image URLs, conversation history, usage reporting, GPT-Live\'s integration and Private Link (What\'s new). UniLM sends up to 400 questions, and still refuses what the beta refused: a picture anywhere but the state (Limits and refusals).']],["Options","openai_decisions_options",["The endpoint takes no constructor arguments. Three request options of the API are keywords of ask and ask_each, options = (…) on the natural-language verbs, or keywords of with_system_one for a scope; each is sent as a field of the request (Create a decision):",'OpenAI reuses a request\'s shared input once it holds at least 1,024 tokens, with a breakpoint at its end unless mode = "explicit", and the questions are outside the reusable prefix (Reuse shared input with prompt caching). UniLM marks no breakpoint, so with mode = "explicit" a request uses no cache. OpenAI\'s reference calls "30m" "currently the only supported value" of ttl; UniLM also sends "12h", which OpenAI answered with HTTP 200 on 25 October 2026. None of the three changes an answer, so none is part of a recording\'s key (Testing and recordings), and a value outside the last column is refused before anything is sent (Limits and refusals).']],["First decision","openai_decisions_first_decision",["One request carries the input once and every question about it; each answer comes back under the name you gave its question, which the API echoes (How decisions work):",'a.choice is the most probable option, a.probabilities holds one probability per option, and a.confidence says how peaked they are (Confidence and tuning). A failed call has no answers: r["team"] throws a SystemOneError on it (When something fails), and a question OpenAI declines comes back as a RefusalAnswer, which has no choice (Declined questions).',"The call named no model, so it was sent with the default model at the top of this page, and r.response.model is the model OpenAI's reply names; r.response.request_id is the reply's x-request-id header. nl_classify makes the same kind of decision in one call and returns the key whose description fits (Dispatch on Meaning):"]],["Models","openai_decisions_models",['OpenAI serves the Decisions API with one model, the default model at the top of this page: the guide calls it "the only currently supported model", and its model page gives one snapshot, under the same name. A call may name another model; UniLM sends it, and on 25 October 2026 OpenAI answered gpt-6-sol with HTTP 404 and the code model_not_found (When something fails). Each reply names the model that answered, and r.response.model holds it: log it with each decision, since a threshold tuned on one model is a claim about that model (Confidence and tuning).',"list_models(service = OPENAIServiceEndpoint) lists every model OpenAI serves the key, the language models with this one (Models); no recording holds it, so inside a replay scope it reaches OpenAI with your key (Testing and recordings)."]],["Questions","openai_decisions_questions",["The API answers three kinds of question, in any mix in one request (Choose a question type), and UniLM sends each question type as the one that fits:","The state becomes the request's input:","What reaches the model:","A Choice takes 2 to 255 options (Create a decision) and a Score 2 to 10 levels (Score against a rubric), and a request 1 to 400 questions (Ask multiple questions); a request outside these is refused before it is sent (Limits and refusals). A picture goes in the state only, as the table shows; where each provider takes one is on Choosing a decision provider. Reading the answers and the decision rules on them are on Route and Decide."]],["Declined questions","openai_decisions_refusals",['OpenAI may decline any question: "Any question can return a refusal instead of an answer; other questions can still receive answers" (Create a decision). UniLM returns such an answer as a RefusalAnswer, whose raw holds what OpenAI sent and which has no value to read: after ask, test a isa RefusalAnswer before you read a.choice, a.score or a.noul; the other answers of the request read as usual. nl_classify, nl_dispatch and @branch take a refusal as a decline whatever their policy, which never sees it: fallback runs (the _ line, in @branch), or DecisionDeclinedError is thrown with the refusal as its answer.','Had OpenAI declined either question, the fallback and the _ line would have answered :person. nl_dispatch sends the arguments it dispatches on as a JSON object, which OpenAI receives as its JSON text; a picture among them is refused, since a picture goes in the state only: pass state = [image, "…"] to send one (Limits and refusals). A verb whose call offers a single option is refused too, since a Choice takes two or more (Limits and refusals): add a fallback option such as "other", which OpenAI\'s guide advises "when your categories don\'t cover every possible input" (Select from fixed options).']],["Limits and refusals","openai_decisions_limits",["What a request meets on the Decisions API (Create a decision, Decisions guide), and which of it UniLM checks before sending:","ask, ask_each and the verbs built on them throw these ArgumentErrors before anything is sent. A wrapper refuses rather than adapts: a request changed to fit would ask a question you did not write, and its answer would carry no sign of the change.",'Like every decision provider, the endpoint also refuses, before anything is sent, a blank or repeated question name, criteria that are not valid, a state or guidance holding NaN or Inf, an AudioAttachment or a DocumentAttachment anywhere in the request; Reading answers covers a malformed request on every provider. An image\'s detail level — "low", "high", "auto" or "original" — goes out on its input_image part, which takes one (Create a decision).']],["Confidence and tuning","openai_decisions_confidence",['A predicate\'s answer is the probability that its statement holds; a Choice or a Score answer carries a probability distribution and "a separate confidence field", and OpenAI tells you to set thresholds on "labeled examples from your application", by "the cost of false positives and false negatives" (Interpret the answers). OpenAI computes confidence and UniLM passes it on; in the replies recorded for this manual it equals the Choice formula of Reading answers, to two decimals. Those replies give every probability and confidence to two decimals, so ask accepts a distribution within 0.005 per outcome of a sum of 1, and a chosen option at most 0.01 below the most probable one; a reply further off is a SystemOneCallError.',"The bar is yours: below min_confidence, a natural-language verb returns what fallback returns, and with no fallback it throws LowConfidenceError. Of the six messages of a support desk's inbox, the cracked phone is the unclear one:","OpenAI's best guess, billing, came with a confidence below the 0.6 asked for, and the message went to a person. On a labelled set of ours, OpenAI's top probabilities ran below how often it was right: the model is under-confident there, so a bar tuned on another provider, or on another set, hands a different share of the work to a person here. Tune min_confidence on messages of your own, on this provider; where some mistakes cost more than others, price each one and let a decide policy choose the cheapest action (When mistakes have different prices), once you have checked that the probabilities are calibrated. The decision rules on every provider are on Act on the answer, and the same messages on each provider are on Choosing a decision provider.","Measured on 20 October 2026 on our 129 labelled support tickets (60 clear, 32 borderline, 15 adversarial, 22 out of scope), one Choice of seven intents per ticket, each option a name with a description, one call at a time, on gpt-6-luna: accuracy 0.946, expected calibration error 0.080 (10 bins), Brier score 0.076, mean top probability 0.89; 101 tickets at a confidence of 0.8 or more, all of them right, so 28 went to a person at that bar; in every bin above 0.5, accuracy was at least the mean top probability. Latency 0.48 s at the median and 2.44 s at the 95th percentile; $0.0000296 a ticket. Limits: one labelled set, one run, one way of writing the options."]],["Cost","openai_decisions_cost",["OpenAI bills a decision's input tokens and no output: uncached input at the model's input rate, while \"prompt cache hits receive discounted input pricing; cache writes are charged\", both at the model's caching rates; \"regional processing premiums and long-context input pricing multipliers apply\" (Pricing and availability). The rates are the default model's row of Cost and usage.","prompt_tokens is OpenAI's input_tokens, which includes the cached and the cache-written ones, cached_tokens its cached_tokens and cache_write_tokens its cache_write_tokens. estimated_cost prices them as the guide does: the uncached input at the model's input rate, the cache reads at its cached-input rate, the cache writes at its write rate — a 12-hour write, counted in cache_write_extended_tokens, at its own — every rate twice for a request of more than 272K input tokens, and no output; it adds no regional premium, which a response does not show. A request whose shared input is under the 1,024 tokens caching needs, such as the one above, reads and writes no cache. Totals across calls and prices of your own are on Cost Tracking."]],["Testing and recordings","openai_decisions_testing",["with_recorded_answers records an exchange with the Decisions API once and replays it with no key and no network: ask, ask_each and the verbs built on them. A recording is filed under /openai-decisions/v1/decisions, the request's path behind the namespace openai-decisions, so a question asked of two providers is two recordings, and it is keyed on the exact request: its method, that path, and its body, which names the model. prompt_cache_key, safety_identifier and prompt_cache_options are sent and left out of the key and the file, and a picture is keyed and written as data:<mime>;sha256,<hex>, the SHA-256 of its base64 text, never its bytes.","The replay names a prompt_cache_key the recording did not, and is answered from it. Recording takes OPENAI_API_KEY, and replaying takes nothing; in this manual's build the recording scope above replays the manual's own recordings, so the example reaches no service either (How this manual runs its examples). list_models on this endpoint is not recorded: inside a scope it goes to OpenAI, with the key, as outside one.","Previews of what a call sends, tests of the methods and of the judgment, and an audit trail are on Test and Develop."]],["When something fails","openai_decisions_failures",["A call that reaches OpenAI returns a SystemOneSuccess; a SystemOneFailure for a status other than 200, with the status, OpenAI's message, its error_type — the error's code, else its type — and the request_id; or a SystemOneCallError when no usable response came. A 200 whose answers do not fit the request — a question unanswered, answers out of the order asked, an option that was not offered, probabilities that are no distribution within the rounding above — is a SystemOneCallError too. Reading an answer of a failed call (r[\"name\"], answer, answers) throws a SystemOneError.","UniLM sends a request again after a 408, 429, 500, 502, 503, 504, 520 to 524 or 529, up to max_attempts times within total_deadline, waiting at least what the reply's retry-after-ms header asks for, else its Retry-After, as the shared backoff of ask_each does. A 429 whose code is a spent credit, a spend or usage limit, or insufficient_quota is not sent again, since \"retrying billing, spend, or quota errors won't restore API access\" (Error codes); any other status comes back as it is. With no RequestConfig of your own, a call to the Decisions API is bounded by 60 s per attempt and 150 s in all, and ask_each keeps 16 requests in flight unless its ntasks says otherwise (Many requests at once); a config of your own replaces the bounds, per call or for a scope:",'OpenAI sets its rate limits per organization and project, and they "vary by the model being used" (Rate limits).',"Recorded on 25 October 2026 on gpt-6-luna with UniLM's development branch after 0.26.0, and, on 19 October 2026, the nl_classify calls (on gpt-6-luna) with UniLM's development branch after 0.23.0, through OpenAI's API at /v1/decisions.","See also: OPENAIServiceEndpoint, ask, RefusalAnswer, UniLM.OpenAIDecisionsProtocol and PromptCacheOptions in the API reference, and OpenAI in the Language models chapter."]]]},{url:"/guide/agentic/",sections:[["Agentic respond",null,["respond sends one request to a provider's agentic API — the input, instructions, tools and options of a Respond — and returns the response as output items: the answer's messages, function calls, reasoning, the work of the tools the provider runs. A provider that stores responses lets the next request name the last one instead of sending the conversation again. respond runs on an endpoint whose capabilities hold :responses or :agentic (Capabilities by provider), and throws ArgumentError before anything is sent on one whose declared capabilities hold neither; a Chat serves every language-model provider (Conversations with Chat).","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["A first response","agentic_first",["respond(input; kwargs...) builds the Respond from its keywords and sends it, and respond(r) sends one built before:","The result is a ResponseSuccess whose response is a ResponseObject — its id, status, model, output items, usage and the whole body as raw —, a ResponseFailure, or a ResponseCallError (Results). output_text joins the text of the answer's messages, token_usage reads the usage in the shape every result shares, and estimated_cost prices it:","respond with a do block streams the answer as it arrives (Streaming)."]],["Input and instructions","agentic_input",['input is a string, the user\'s message, or a vector of input items: InputMessages, whose content is a string or a vector of parts — input_text, input_image, input_file —, and items such as a tool_result. instructions is the system guidance. reasoning=Reasoning(effort=…, summary="auto") sets how much a reasoning model thinks and asks for summaries of its reasoning, where the provider gives them, which reasoning_summaries reads. Which roles, parts and media a provider takes, the efforts and summaries its models take, and the Respond fields it refuses before the request, are on its entry. The Respond constructor itself throws ArgumentError, whatever the provider, for temperature outside 0.0 to 2.0, top_p outside 0.0 to 1.0, max_output_tokens below 1, top_logprobs outside 0 to 20, and conversation together with previous_response_id. UniLM.encode_agentic returns the body respond sends, with no key and no request:']],["Continuing a conversation","agentic_conversations",["previous_response_id names a stored response, and the request sends only the new input, since the provider holds the conversation so far. Whether a provider stores responses, and what UniLM does with previous_response_id where it does not, is on its entry; without stored responses, the whole conversation goes in input."]],["Tools","agentic_tools",["A function tool is a FunctionTool, made by function_tool, and a CallableTool pairs one with the Julia function that answers it. function_calls reads a response's calls, each a Dict with its call_id, name and arguments (a JSON string), and tool_result(call_id, name, output) makes the input item that answers one on the next request. tool_loop does both until the model answers in text; Tool Calling has its rules:","To answer a call yourself, send its result in a request that continues the response:",'tool_choice is "auto", "none" or "required", or an object a builder makes: tool_choice_function(name) forces one function; tool_choice_hosted, tool_choice_mcp and tool_choice_custom select other kinds of tool, and tool_choice_allowed limits the model to some of its tools. A provider may also run tools of its own, such as web search or code execution, passed in tools. Which choices and tools a provider takes is on its entry.']],["Background requests","agentic_background",["With background=true, respond returns at once with the response's id and status, and the response runs on the provider's side; get_response reads it by its id and cancel_response stops it. Both take a service keyword and make one attempt, never retried (Timeouts & Retries), so a poll is your own loop. Whether a provider runs background requests, and what it answers while one is queued, is on its entry."]],["See also","agentic_see_also",[]],["On your provider","agentic_providers",[]]]},{url:"/guide/attachments/",sections:[["Attachments",null,["A user message can carry media besides its text — images, sound clips and PDF documents — for a model that reads them. Attach a file to ask about a picture, a recording or a report; how each provider sends the media, and which kinds it takes, is on its entry.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["Images, audio and documents","chat_attachments",['An ImageAttachment (PNG, JPEG, GIF or WebP), an AudioAttachment (WAV or MP3) and a DocumentAttachment (PDF) each hold the media\'s bytes, read from a file or given as a byte vector, and recognise the format by the bytes\' leading signature, never by a file name. Empty bytes, bytes in another format, and a URL or a data URL in place of a file throw ArgumentError. An image may set the detail level a model reads it at — "auto", "low", "high" or "original" — and a document keeps a filename: the file\'s own name, or the filename keyword\'s for bytes.',"The format comes from the bytes alone, so a picture read as a sound clip is refused:","Which kinds and detail levels a provider takes is on its entry. A provider whose entry lists an attachment among its refusals throws ArgumentError for it before the request; one that sends every kind leaves it to the server to answer for a model that does not read it."]],["Sending attachments","attachments_send",["A user message takes its attachments after its text, Message(Val(:user), text, attachments...); attachments go on user messages only:","Each provider writes the attachments into its own request. An endpoint on the OpenAI-compatible wire sends an image as an image_url part, with its detail when it sets one, a sound clip as an input_audio part and a document as a file part, all base64, and the server decides what to do with each; the other encoders are on their entries.","A Respond takes media as parts of an InputMessage's content — input_image for an image, and input_file(document) for a DocumentAttachment — and, on some providers, the attachments themselves; which parts a provider takes is on its entry."]],["On your provider","attachments_providers",[]]]},{url:"/guide/capabilities/",sections:[["Capabilities by provider",null,["Each endpoint declares what it serves as a set of capability symbols — :chat, :tools, :embeddings and so on —, and a verb checks the endpoint's set before anything is sent: on an endpoint whose declared set lacks the capability the verb needs, it throws ArgumentError, naming the feature and the endpoint and listing what the endpoint supports (Provider Capabilities says which verbs check which symbol). Read the table below to see what a provider serves before you choose it, or before you move code to it.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's start page."]],["Every provider's capabilities","capabilities_matrix",['Each row is a capability symbol, as has_capability takes it (Provider Capabilities), and "yes" says that has_capability holds for some endpoint of the entry. "sent unchecked" marks an entry whose endpoint is a GenericOpenAIEndpoint: UniLM sends those requests without knowing whether the server serves them. The table leaves out :system_one, serving decision models through ask, which the entries of the Decisions chapter list.']],["Check a provider in code","capabilities_check",["has_capability answers for one symbol, and provider_capabilities gives the endpoint's whole set:","An endpoint of your own declares a set by adding a method to provider_capabilities; one that declares none is not checked by chatrequest!, respond and embeddingrequest!, and the other verbs refuse it (Write your own backend)."]],["On your provider","capabilities_providers",[]]]},{url:"/guide/chat_completions/",sections:[["Conversations with Chat",null,["A Chat holds a conversation — its messages and the options of its requests — and chatrequest! sends it to a provider and, with history=true (the default), appends the reply, so the next turn carries the conversation so far. Use it to talk with a language model turn by turn; respond sends one request of a provider's agentic API instead (Agentic respond).","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["Creating a Chat","chat_completions_create",["service names the provider and model its model; a Chat without model takes the provider's default model, and throws ArgumentError for a provider that has none. Every field has a default, and the constructor checks the ranges of the options it is given (Parameter validation). See Chat for the full list. Each entry names the models UniLM holds rules and prices for: for the provider bound above, Models."]],["Building conversations","chat_completions_messages",["Messages are added with push!, which refuses one that would make the conversation invalid: it throws InvalidConversationError for a first message that is not a system message, and for a message whose role repeats the last one's — consecutive tool results excepted. pop! removes the last message and throws for an empty conversation. chat[i] = msg and direct edits to chat.messages bypass these checks.","The convenience Val(:system) and Val(:user) constructors keep things concise. You can also use the keyword constructor:","A user message can also carry images, sound clips and PDF documents (Attachments).","Conversation rules"]],["Sending requests","chat_completions_send",["The ! suffix is a Julia convention — chatrequest! mutates chat by appending the assistant's response to the message history (when history=true).","chatrequest! returns what the service or the network did as a typed result instead of throwing it: an LLMSuccess holding the reply, an LLMFailure holding the HTTP status and body the provider answered with, or an LLMCallError for a call that brought no reply it could use, the exception — a timeout, a cancellation — in its cause. Results has them all.","One-shot requests via keywords","Skip the Chat object entirely for simple one-off requests; every keyword besides the prompts, config and cancel is a Chat field:"]],["Multi-turn conversations","chat_completions_turns",["Because chatrequest! appends the response, you can keep chatting:"]],["Checking conversation validity","chat_completions_validity",["This checks:"]],["The request body","chat_completions_body",["UniLM.encode_request(service, chat) returns the body chatrequest! sends the provider, with no key and no request — or throws the refusal of a request the provider's encoder checks:","JSON.json(chat) writes the Chat in the Chat Completions shape of the OpenAI-compatible wire, which is not every provider's body."]],["Retries and failures","chat_completions_retries",["chatrequest! automatically retries transient HTTP statuses (408, 429, 500, 502–504, 520–524, 529) with exponential backoff and jitter; the wait a reply asks for — its retry-after-ms header, else Retry-After — is a floor under the jittered wait, so concurrent callers that received the same header do not retry in lockstep. A 429 whose error names spent credit or a reached spend, usage or quota limit is returned at once, since no retry clears it; each provider's failure section names the codes it sends. Attempts and total time are bounded by the resolved RequestConfig (max_attempts, default 3; total_deadline, default 900 s). Pass config=RequestConfig(max_attempts=1) to disable retries for a call, or set scoped/process-wide defaults with with_request_config / set_default_config! (Timeouts & Retries). Timeouts surface as LLMCallError with status = nothing and the UniLMTimeout (phase, elapsed, limit) in .cause; a cancelled call (see Concurrency, Tasks and Cancellation) carries a UniLMCancelled there instead.","A check made before sending is not a result: chatrequest! throws ArgumentError for a callback or on_tool_call without stream=true, for an endpoint whose declared capabilities lack :chat, and for a request the provider's encoder refuses, and InvalidConversationError for a conversation the reply could not be appended to — each before any request is sent."]],["Parameter validation","chat_completions_validation",["The Chat constructor validates parameter ranges at construction time:","Out-of-range values throw ArgumentError, and an empty tools vector is stored as nothing. temperature and top_p may be set together, and both are sent where the provider takes them. Which fields and values a provider and its models take is checked when the request is encoded, before any network I/O, by the rules its entry's limits section lists. UniLM refuses only what those rules name: a request they let through goes to the provider, whose answer is the check."]],["See also","chat_completions_see_also",[]],["On your provider","chat_completions_providers",[]]]},{url:"/guide/completions/",sections:[["FIM & Prefix Completion",null,["Fill-in-the-Middle (FIM) completion has a model write the text between a prefix and a suffix — the gap in the code you are editing, say — and chat prefix completion has it continue an assistant reply from the start you give it, to force an output format such as a code block. A provider can serve them only when its endpoint's capabilities hold :fim or :prefix_completion, and a generic endpoint (GenericOpenAIEndpoint) declares :fim for any server: whether yours fills in the middle is on its entry, which the table at the end links.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["FIM completion","completions_fim",["FIM generates text between a prompt (prefix) and an optional suffix. This is the standard pattern for code completion — the model fills in the gap.","Building a request","A FIMCompletion without model takes the endpoint's default FIM model, and the request throws ArgumentError for an endpoint that has none; max_tokens is 128 unless it is set, and the other fields are sent only when they are set.","Making requests","fim_complete sends the request to the endpoint's completions route, which its entry names, and reads the completion's text from each choice of the reply.","Result types","FIM returns FIMSuccess, FIMFailure, or FIMCallError. Local validation — the endpoint's :fim capability, model resolution, routing, and stream=true (FIM has no streaming path) — throws ArgumentError before any request; every later failure, including a 200 whose body is not a completions response, is a FIMCallError carrying the exception in cause. A FIMSuccess reports token usage and is priced by estimated_cost.",'fim_text returns the generated text of a success. A failed call has no text, so on a FIMFailure or FIMCallError it throws LLMResultError instead of returning "" — guard with issuccess:']],["Chat prefix completion","completions_prefix",["Prefix completion lets you provide a partial assistant message that the model continues from. Useful for forcing specific output formats (e.g., starting with a code block).","Usage","The last message in the chat must be role=assistant with the partial text:","The request is the endpoint's own Chat request, its last message marked as the prefix to continue, and never streamed: prefix_complete reads one whole reply and takes no callback, so a Chat with stream=true is sent without its stream and stream_options. The result's message is the continuation the API returns. With chat.history (the default) the conversation keeps the whole assistant turn — the prefix followed by the continuation. A failure or a cancellation (cancel=, or an ambient with_cancel token) leaves chat untouched.","Validation","prefix_complete validates that:"]],["Capability validation","completions_capabilities",["Both fim_complete and prefix_complete check the endpoint's capabilities before making a request: an endpoint without :fim, or without :prefix_completion, throws ArgumentError naming the feature and the capabilities it has. Capabilities by provider shows which endpoints declare them, a generic endpoint's as sent unchecked: it declares :fim whatever its server serves."]],["See also","completions_see_also",[]],["On your provider","completions_providers",[]]]},{url:"/guide/concurrency/",sections:[["Concurrency, Tasks and Cancellation",null,["UniLM calls are ordinary blocking Julia calls: run many at once by putting them on tasks. This guide covers which objects a concurrent call may share, the fan-out patterns, streaming into a Channel, cooperative cancellation, the thread layout the package assumes, and what the HTTP, tool-loop and MCP layers do under load. The time bounds themselves are in Timeouts & Retries.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's start page."]],["What a concurrent call may share","concurrency_sharing",["A Chat is a conversation, not a request: chatrequest! pushes the reply onto chat.messages and adds the call's estimated cost to its cumulative-cost Ref, both without a lock. Two calls on one Chat interleave into a corrupted conversation or a lost cost update, and a push! while its streaming task runs does the same. fork is the fan-out: fork(chat) deep-copies every field except service (the endpoint is shared), so forks share nothing mutable:","Each fork gets its own cost accumulator, but it starts at the parent's running total, not at zero: summing cumulative_cost over a parent and its forks counts the parent's spend once more per fork. To account per fork, subtract the parent's total at fork time from cumulative_cost(fork), or sum estimated_cost over the fork's own results.","embeddingrequest! fills its Embeddings in place and returns a result whose embeddings field is that same object, so a second call on it overwrites what the first returned. Build one Embeddings per concurrent call, and copy the vectors before reusing a request."]],["Fan-out patterns","concurrency_fan_out",["The request verbs return failures as values (*Failure, *CallError). What they throw is a local validation error raised before any I/O (ArgumentError, InvalidConversationError) or an InterruptException, so fetch on a task running one returns its typed result and raises TaskFailedException only for those. The Task a streaming call returns throws only for an interrupt: its validation ran before the task was spawned. The MCP client, nl_dispatch and @branch are throw-based instead; their exceptions reach fetch the same way.","Threads.@spawn + fetch — one task per call, on the default thread pool:","asyncmap(...; ntasks) — a concurrency cap for a large batch. Its tasks run on the calling thread, which suits I/O-bound calls; keep heavy post-processing out of them (see Thread layout):","@sync — wait for a group of tasks that write into preallocated slots:","A with_request_config or with_cancel scope opened around any of these reaches the spawned tasks: both are scoped values, which Julia propagates into Threads.@spawn and @async tasks."]],["Streaming into a Channel","concurrency_streaming",["A streaming callback runs on the stream's own task. Hand each delta to a consumer through a Channel so the callback stays short:"]],["Cancellation","concurrency_cancellation",["A CancelToken is a cooperative, level-triggered flag: cancel! it from any task, and every operation that observes it stops.","The Julia 1.14 development branch adds task cancellation built on scoped, level-triggered cancellation tokens (Base.CancellationTokenSource, carried in the scoped value Base.CANCEL_TOKEN, with a cancel keyword on blocking operations). UniLM's token, ambient scope and cancel keyword have the same shape so a later release can bridge to it. No bridge exists yet, and UniLM is not tested on that branch."]],["Thread layout","concurrency_threads",["Since Julia 1.12 a plain julia starts one default thread and one interactive thread. The main task (and so the REPL) runs on thread 1 in the interactive pool, and so do @async and asyncmap tasks started from it; Threads.@spawn lands on the default pool. libuv's event loop, which fires every Timer in the process, shares thread 1 with the main task."]],["HTTP under fan-out","concurrency_http",[]],["Tool loops","concurrency_tool_loops",["A tool loop runs one turn's tool calls one at a time in the calling task by default. tool_concurrency = n runs up to n of a turn's calls at once on spawned tasks: the dispatcher (or each CallableTool callable) must then be thread-safe. Results are sent back in call order once every call of the turn has finished, so the next request does not depend on completion order. An InterruptException from any dispatch propagates once the interrupted turn is removed from the chat, and a cancelled token stops the hand-out of further calls."]],["MCP","concurrency_mcp",[]],["Known limits","concurrency_limits",[]],["See also","concurrency_see_also",[]],["On your provider","concurrency_providers",[]]]},{url:"/guide/cost_tracking/",sections:[["Cost Tracking",null,["Every result of a token-billed call carries the token counts its provider reported, and UniLM turns those counts into a USD estimate. Each provider's usage is read into one shape, TokenUsage, when its reply is decoded, so the same code totals a bill on every provider; how a provider bills, and the prices UniLM holds for it, are on its entry.","Two accessors do the work: token_usage (raw counts) and estimated_cost (dollars). Chat additionally keeps a running total via cumulative_cost.","The examples use only the names bound above. service and model are the provider and model they run on, and own_model names a model the price table does not hold, such as one of your own server: bind your own there. On an endpoint that treats its models as local, an estimate below is 0.0 unless you gave the model a price row (Local models). The table at the end links each provider's rules.","estimated_cost returns 0.0 — with no error, only a warning logged once per model id — for any model that is not a key in DEFAULT_PRICING and has no fallback row, such as a model of your own server or one newer than the table. Cost tracking on it reports \\$0.00 until you supply its price. See Unpriced models cost $0 below. A model its endpoint treats as local is the exception: with no row of yours, it costs 0.0 with no warning (Local models)."]],["Reading usage and cost","cost_tracking_reading",["token_usage returns a TokenUsage for every result of a token-billed call — chatrequest!, respond, embeddingrequest!, the image verbs, fim_complete, prefix_complete and ask — zero-filled for their failures and call errors; estimated_cost returns a Float64 in USD. Both throw ArgumentError for results of APIs that report no token usage (files, batches, audio, moderations, vector stores, …), where a zero would be indistinguishable from a free call. A real result comes back from chatrequest! / respond / embeddingrequest!, but the accessors are pure, so we build one here to keep the example deterministic and offline:","By default the model priced is the one the result reports having served the call — result.model of a Chat result (LLMSuccess), where UniLM keeps the name the reply gives, and result.response.model of a respond, FIM or ask result — else the one requested: result.self.model for a Chat, result.embeddings.model for Embeddings. The model served can differ from the one requested: a provider that answers an alias with the dated snapshot behind it names the snapshot, which is priced at the alias's row. Each entry's first call says which model its results report. Override it explicitly when needed:","The decision providers' results — what ask returns — are priced as each one's entry says: the second table at the end links their cost sections."]],["How the estimate is computed","cost_estimate",["estimated_cost splits the prompt into fresh, cache-read and cache-written tokens and bills each at its own rate:","prompt_tokens counts every input token: cached_tokens and cache_write_tokens are subsets of it. These are the standard rates. Where UniLM models a provider's surcharges — a premium on cache writes (cache_write_extended_tokens counts the writes at the longer retention), a long-context tier, a multiplier for the service_tier or inference_geo the provider reports in TokenUsage — they apply to that provider's results, as its entry's cost section says; every other result is billed at the standard rates.","A price row holds no audio rates. A result whose usage counts audio tokens — prompt_audio_tokens and completion_audio_tokens, the audio parts of prompt_tokens and completion_tokens — is priced only where UniLM prices that model's audio, as its entry's cost section says; any other such result is estimated at 0.0, with one warning per model and endpoint, as for a model without a row, rather than its audio billed at text rates.","Reasoning tokens are already counted inside completion_tokens, so they carry no separate charge. Failures and call errors report zero usage and 0.0 cost. Image results report the usage their reply gives, but image tokens bill at rates a price row does not model: estimated_cost on an image result throws ArgumentError unless you pass model=, and a model= without a row is estimated at 0.0, with the no-row warning, so pass a pricing= row for it too.",'A streamed Chat turn is priced like an unstreamed one where its provider reports the usage in the stream — on its own, or because the endpoint asks for it with stream_options = {"include_usage": true} when the Chat sets no stream_options; each entry says which, in its streaming section or the section of the endpoint it concerns. Elsewhere, set stream_options=Dict("include_usage" => true) where the server supports it, or the streamed turn reports no usage and accrues \\$0. An embeddings reply that reports no usage is estimated at 0.0, with one warning per model.']],["The pricing table","cost_tracking_table",["DEFAULT_PRICING is a lock-guarded AbstractDict{String, PriceRow} (not a Dict), where a PriceRow is a NamedTuple of per-token USD rates: (input, cached_input, output). (Provider list prices are usually quoted per 1M tokens; the stored rows are those figures divided by 1,000,000.) Every Chat success prices itself against it — streaming ones on their own task — so it is safe to read and write from any task: add or replace a row with DEFAULT_PRICING[model] = row, and use get, haskey, delete!, pop!, keys and length as on a Dict. Iteration walks a snapshot, and copy, merge and filter return a plain Dict.","A model id is looked up exactly first, then without a dated snapshot suffix — -YYYY-MM-DD or -YYYYMMDD — so a snapshot is priced at its model's row. Only those date suffixes are stripped, so custom names stay unpriced rather than matching a row by accident. A provider's own fallback, where it has one, is on its entry."]],["Unpriced models cost $0","unpriced-zero",["If the model key is absent from the pricing table, estimated_cost returns 0.0 — it does not raise; it logs one warning per model id. (The dated-snapshot fallback above applies first.) This bites a model of your own server that its endpoint does not treat as local, or one newer than the table:","150,000 tokens, and the estimate is still \\$0.0. Always confirm your model is a key in the pricing table before trusting a cost number."]],["Local models","cost_tracking_local",["A model its endpoint treats as local bills no one, so it costs 0.0, with no warning, as that endpoint's entry says (a local model's cost), and cumulative_cost adds 0.0 for each turn — unless you price it. A row you give its exact name is used as any model's is: one in pricing= prices estimated_cost, and one you add to DEFAULT_PRICING prices both. The rows the table ships price hosted models only: a local model that bears a hosted model's name is not priced at that model's row, nor at its copy in a table such as merge(DEFAULT_PRICING, …), and a row equal to a shipped one counts as the shipped one. model= prices such a result at the row of the model it names."]],["Supplying custom pricing","cost_tracking_custom",["Pass a pricing= dict (any AbstractDict{String, PriceRow}) to fix an unpriced (or mispriced) model. Build a PriceRow NamedTuple of per-token rates and merge it into the defaults — merge returns a new Dict and leaves DEFAULT_PRICING untouched:","A row cannot price audio: a PriceRow has no audio-token rates. Whatever pricing= holds, a result whose usage counts audio tokens stays at 0.0 unless UniLM prices that model's audio, as its entry's cost section says."]],["Cumulative cost is Chat-only","cost_tracking_cumulative",["cumulative_cost returns the running USD total that chatrequest! and prefix_complete accrue on a Chat. Accumulation happens only inside chatrequest! (both streaming and non-streaming paths, and so every turn of a tool_loop!) and prefix_complete — nothing else adds to the total:","A call that ends without committing a turn adds what its provider reported billing it, as a lower bound. A stream stopped, cancelled, timed out or cut off, or ended by an exception from its callback or on_tool_call, adds the usage the provider had reported by then; where an entry knows when its provider reports usage, its streaming section says so. A request stopped before any usage arrived adds nothing, though the provider bills it; so do an attempt UniLM retried, a stream the provider ended with an error event, and an unstreamed reply UniLM could not decode.","chatrequest! prices each call with DEFAULT_PRICING; there is no pricing= for the running total. So a Chat on an unpriced model reports cumulative_cost == 0.0 even after successful calls — unless you add its row to the table (DEFAULT_PRICING[own_model] = row, safe while requests run), after which later calls accrue, on a model its endpoint treats as local too (Local models). Alternatively, ignore the running total and sum estimated_cost(result; pricing=…) yourself."]],["Totaling respond, tool-loop and embeddings costs","cost_tracking_totals",["respond (ResponseSuccess), the respond tool loops, and Embeddings are not auto-accumulated. Sum estimated_cost over the results yourself:","A respond tool loop sends a request per turn and keeps every turn's result, in order, as loop.responses (Inspecting the result): sum(estimated_cost, loop.responses) prices them all, while estimated_cost(loop.response) prices the last request alone. A tool_loop! on a Chat adds every turn to the Chat's cumulative_cost. Embedding models missing from the default table (one on your own server that its endpoint does not treat as local, for example) hit the same 0.0 behavior — supply pricing= for them too."]],["Prices drift","cost_tracking_drift",["DEFAULT_PRICING is a hardcoded snapshot of the providers' list prices, and each entry with a price table says in its cost section when its rows were checked. Provider list prices change; re-verify against the provider's current pricing before relying on any number, and pass your own pricing= dict when you need authoritative figures."]],["See also","cost_tracking_see_also",[]],["On your provider","cost_tracking_providers",["The decision providers' cost sections, for what ask returns:"]]]},{url:"/guide/custom_backends/",sections:[["Write your own backend",null,["UniLM's provider surface is a typed, open extension point: you add a backend by defining a ServiceEndpoint subtype and the handful of methods that route and — when the wire differs — translate its requests. The request driver, retries, cost accounting, tool loop, and streaming are not provider-specific; they call a small wire seam through multiple dispatch, so a new backend plugs in without touching that machinery.","The examples use only the names bound above and the endpoint types they define. service and model are a built-in provider and model: bind your own there. The table at the end links each provider's start page, which says what wire its endpoint speaks.","The functions you add methods to — get_url, auth_header, default_model, the chat seam encode_request / decode_response / handle_sse_event! and the agentic seam encode_agentic / decode_agentic / decode_agentic_stream — and the stream-state types StreamState / AgenticStreamState are UniLM's public extension API: declared public, not exported, so qualify them (UniLM.get_url). Each is documented in the Extension API reference.","There are two cases, depending on whether your provider speaks the OpenAI wire."]],["Case 1 — an OpenAI-compatible provider","custom_backends_openai_wire",["If the provider speaks the OpenAI wire — /v1/chat/completions, and optionally the /v1/responses and /v1/embeddings surfaces —, subtype OpenAIWireEndpoint. Subtypes inherit the OpenAI wire's request and response encoding and its SSE stream handling; you define only routing (get_url) and authentication (auth_header).",'Embeddings route the same way, through get_url(::MyEndpoint, ::Embeddings), and respond through get_url(::MyEndpoint, ::Respond). The Responses lifecycle operations (get_response, cancel_response, compact_response, …) build their URLs from one base instead, the internal hook UniLM._api_base_url(service) (the Responses URL is that base plus "/v1/responses"). Defining it is the one step here outside the public extension API — an underscore name that may change without notice. GenericOpenAIEndpoint is the built-in reference for this shape:',"For a provider that is a plain OpenAI-compatible server at a custom URL you need no new type at all — GenericOpenAIEndpoint(base_url, api_key) already does exactly this. Define a new OpenAIWireEndpoint subtype when you want a named type, provider-specific defaults, or custom routing/auth:","An endpoint passed as its type (service=MyEndpoint, as the built-in singletons are) dispatches on the type — get_url(::Type{MyEndpoint}, ::Chat); one passed as an instance dispatches on the instance, as above."]],["Case 2 — a provider with a different wire","custom_backends_native",["If the provider speaks a genuinely different wire (its own request shape, response shape, or SSE dialect), subtype ServiceEndpoint directly and additionally implement the three chat wire-seam methods. They translate between the neutral Chat/Message types and the provider's wire:","handle_sse_event! is called once per streamed SSE event (event/payload are strings): it appends text and tool-call deltas onto state, records the usage and the served model when the provider reports them (state.usage, state.model), and returns :done at the provider's end-of-stream sentinel, :error on an in-band error event, or :continue otherwise. The served model becomes the result's model, which estimated_cost prices before the model requested; a decoder that returns only (; message, usage) and a handler that leaves state.model unset report none.","The native backends in UniLM's src/ are complete worked examples. src/anthropic.jl implements all three methods, and captures the provider's own content blocks for a verbatim round-trip on the next turn; src/gemini.jl is a second example, whose stream ends at EOF rather than at a sentinel. Read them rather than copying them here.","To also serve the agentic respond verb on a native wire, override the agentic seam the same way — encode_agentic / decode_agentic / decode_agentic_stream (the stream handler mutates an AgenticStreamState) — and route it with the internal hook UniLM._agentic_url(service), which respond and the lifecycle operations read (an underscore name outside the public extension API); src/interactions.jl is the reference.","Both seams split validation from failure the same way. An encoder runs before any network I/O and what it throws propagates from the verb, so throw ArgumentError for an option your wire cannot express. An exception thrown by a decoder becomes the verb's typed call-error result (LLMCallError / ResponseCallError) with the exception in cause. Their stream handlers differ. handle_sse_event! is called once per payload, and an exception it throws drops that payload, counted in the result's sse_dropped. decode_agentic_stream is called once per raw read, which can hold several payloads, and an exception it throws ends the streamed respond as a ResponseCallError with the exception in cause: to drop an undecodable payload, skip it in the handler and count it in state.sse_dropped, as src/interactions.jl does."]],["Fail-loud contract","custom_backends_fail_loud",["The wire seam has no permissive fallback. Subtyping OpenAIWireEndpoint is the explicit opt-in to the OpenAI wire; subtyping ServiceEndpoint is the commitment to implement the seam yourself. A built-in endpoint shows which it chose:","true says the bound endpoint opted into the OpenAI wire, and false that it implements the seam itself. A ServiceEndpoint subtype that defines no encoder sends nothing: chatrequest! throws a MethodError for encode_request before any request, rather than sending OpenAI-wire JSON to a provider that does not speak it.","A missing decoder fails the call too, once the reply has arrived: the result is an LLMCallError whose cause is the MethodError for decode_response. A missing stream handler is refused as a missing encoder is, before anything is sent, alike on both seams: a streamed chatrequest! throws the MethodError for handle_sse_event!, and a streamed respond the one for decode_agentic_stream."]],["See also","custom_backends_see_also",[]],["On your provider","custom_backends_providers",[]]]},{url:"/guide/embeddings/",sections:[["Embeddings",null,["An embedding is a vector of numbers that stands for an input: inputs with close meanings get vectors that lie close together, so texts can be searched, grouped and compared by their vectors. An Embeddings request holds one input or several, and embeddingrequest! sends it and fills its vectors in place. Which providers embed, and what they embed besides text, is on each provider's entry.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["Embedding a text","embeddings_basic",["A request holds a vector for each input before it is sent, all zeros:","embeddingrequest! sends it, and the reply fills the vectors in place:","An Embeddings without model takes the provider's default embedding model, and its constructor throws ArgumentError for a provider that has none. An endpoint whose declared capabilities lack :embeddings refuses the request with an ArgumentError before anything is sent (Capabilities by provider)."]],["Several texts at once","embeddings_batch",["A vector of texts is one request, with a vector for each text:"]],["Comparing texts","embeddings_similarity",["The cosine of two vectors measures how close their texts are:"]],["Task prompts and titles","embeddings_tasks",["Some embedding models read a short prompt in front of a text that says what the text is for: a query to search with, or a document to be found. For the models UniLM knows to read one, task writes it: :search_query, :question_answering, :fact_checking or :code_retrieval for the query side; :document for the corpus, with an EmbeddingInput's title when a text has one; and :classification, :clustering or :sentence_similarity for a text compared with others of its kind. task = :none sends the text as it is. Which models read a prompt, and the prompt each task writes, is on the entry of the provider that serves them.","A model whose prompts UniLM does not know takes task = :none or no task, and no title: anything else is refused before the request, so write such a model's own prefix into the text instead:"]],["Images and sound","embeddings_media",["An input can also be an ImageAttachment, an AudioAttachment, or an EmbeddingInput that holds a text with an image or a sound clip. A provider that embeds text alone refuses such an input before the request; one that embeds media says so on its entry."]],["Vector sizes","embeddings_dimensions",["dimensions asks for vectors of that length, where the model takes it; a value that is not positive throws ArgumentError. The buffers start at something(dimensions, 1536) zeros per input and take the length the reply has, so a model with longer or shorter vectors needs no adjustment."]],["In-place design","embeddings_in_place",["The Embeddings struct pre-allocates the embedding vectors at construction time. embeddingrequest! fills them in-place — no allocation on the hot path when the model returns the pre-allocated length. This is idiomatic Julia for performance-sensitive workloads. The result aliases the request (result.embeddings === emb), so a second call on the same Embeddings overwrites the first one's vectors: use one Embeddings per concurrent call, and copy vectors you keep before reusing a request."]],["Results and retries","embeddings_retries",['embeddingrequest! returns an EmbeddingSuccess/EmbeddingFailure/EmbeddingCallError and fills emb.embeddings in place (use embedding_vectors(result) for the vectors). It automatically retries transient HTTP statuses (408, 429, 500, 502–504, 520–524, 529) with exponential backoff and jitter — the wait a reply asks for, its retry-after-ms header, else Retry-After, is a floor under the jittered wait — bounded by the resolved RequestConfig (max_attempts, default 3; total_deadline, default 900 s). Pass config=RequestConfig(max_attempts=1) to disable retries; timeouts surface as EmbeddingCallError with the UniLMTimeout in .cause, and a cancelled call (cancel=, or an ambient with_cancel token) with a UniLMCancelled there. embedding_vectors throws LLMResultError on a failure result. encoding_format accepts only "float" (the vectors are stored as Float64); anything else throws ArgumentError at construction.']],["See also","embeddings_see_also",[]],["On your provider","embeddings_providers",[]]]},{url:"/guide/image_generation/",sections:[["Image Generation",null,["generate_image makes images from a text prompt, and edit_image changes images you give it, on a provider that serves them. The request's service picks the provider; the verbs, the request types and the result types are the same on each, and the options each provider takes are on its entry.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["Generating an image","image_generation_generate",["An image request is not recorded, so its code stands here without output:","generate_image(prompt; kwargs...) builds an ImageGeneration from its keywords and sends it; config and cancel go to the request."]],["The request","image_generation_request",["For full control, build the ImageGeneration yourself:","These fields hold on every provider; the others, which size and shape the image, are each provider's, on its entry:",'The model field is a sentinel, not a resolved default: unlike Chat, ImageGeneration leaves it "" until the request is serialized, so ig.model reads back as the empty string, and JSON.json(ig) shows the body that goes on the wire. A service with no default image model throws ArgumentError at serialization. Set model= to read the model back from the request.',"safety_identifier names the end user a request is made for, so the provider can tell your users apart; send a hash of a username or email address, never the address itself. Each provider's rule for its form is on its entry.","A field the request's provider does not take throws ArgumentError naming the provider and the field — when the request is serialized, and in generate_image before any request — and so does a value UniLM checks against the provider's rules; each entry lists what its provider refuses."]],["Results","image_generation_results",["A request that makes several images (n) gives them in order: save each one.","Saving images","The save_image helper decodes base64 and writes to disk:","Error handling","image_data throws LLMResultError on an ImageFailure or ImageCallError — a failed call has no images — so branch on the result type first:"]],["Editing images","image_generation_edit",["edit_image changes existing images as a text prompt asks. The convenience form takes the source image (a file path, or a vector of paths) and the prompt:",'For full control, build an ImageEdit and call edit_image(e). model left "" is the provider\'s default image model, resolved when the edit is sent. An empty vector of images, or an image or mask path that is no file, throws ArgumentError before any request. Image editing needs the :image_edits capability: an endpoint that does not declare it, one that declares no capabilities included, throws ArgumentError before any request. The fields of an edit that one provider alone takes, such as a mask, are on its entry.']],["Retry behaviour","image_generation_retries",["generate_image and edit_image retry transient HTTP statuses (408, 429, 500, 502–504, 520–524, 529) within the request budget configured by RequestConfig (max_attempts, default 3), with exponential backoff and jitter; the wait a reply asks for (its retry-after-ms header, else Retry-After) is a floor under the jittered wait. Override per call with config=RequestConfig(...). Both take cancel= (default: the ambient with_cancel token); a cancelled call returns an ImageCallError whose cause is a UniLMCancelled. Every ImageFailure and ImageCallError carries the provider's request_id when one was sent, and a call error its exception in cause."]],["See also","image_generation_see_also",[]],["On your provider","image_generation_providers",[]]]},{url:"/guide/jev_testing/",sections:[["Test and Develop",null,["A program built on a decision model is ordinary Julia plus answers from a service. Most of it can be tested with no service at all. The answers can vary from one call to the next, so tests record them once and replay them — the decision model's answers and an LLM's replies alike.","The examples use only the names bound above. service and model are the decision provider and model they run on, pinned a version of that model, llm and llm_model the language model a pipeline drafts with, and key and llm_key the variables the two providers' keys are read from: bind your own there. The table at the end links each provider's testing section.","Measured on jev-1.13.0 (September 2026): 60% of pairs of identical requests came back with different numbers, by up to 0.11 in a probability, and a decision flipped only on inputs that were ambiguous to begin with.","Every example that calls a decision provider or an LLM runs when this manual is built, from recorded answers (the last section says how). Most share one program, a router whose ordinary argument is a chat message (a String) or an Email:"]],["Preview a call","jev_testing_preview",["The job: see what a call will ask the model — which options, in which order, and whether every combination has a method — before anything is sent. Without dispatch on meaning, you would render an LLM prompt and read it. With it, the options are the method table: meanings lists them in the order a call sends them, and meaning_gaps lists the combinations no method covers, with no network.","meanings(route) lists the meanings of every method, by slot:","meanings(route, Tuple{…}) lists what one call offers, in the order it sends them: only the meanings whose method accepts the argument types. A chat message is never an automatic out-of-office reply, so a call with an Email offers all four meanings and a call with a String offers three:","Read each list as the model will: an option's sentence is the only text it gets for that branch.","Check coverage. A gap is a combination of offered meanings that no method covers, or covers ambiguously. With several slots the answers combine, and gaps are easy to leave:","nl_dispatch runs the same check before every request and, while a gap exists, sends nothing and throws an ArgumentError that lists it. Close it with the missing method, or with a backstop that is wild in every slot (reply(::Meaning, ::Meaning, msg)): it is not offered, and it covers every combination that has no method. A backstop does not settle an ambiguous combination, which two methods match with neither more specific; the error names both, and a method for their intersection settles it. Here the missing method closes the gap:","Then look at one whole answer. A decide policy is called with the whole ChoiceAnswer. One that prints the distribution and returns the argmax shows the whole answer without changing the decision:","Tune it"]],["Recorded answers","jev_testing_recorded",["The job: make tests that call a decision provider or an LLM give the same answer on every run, with no key. Without recordings, every run asks again and tests a new sample. With with_recorded_answers, a real answer is recorded once and replayed from a directory.","with_recorded_answers(f, dir; mode) runs f() with these exchanges passing through a directory of recordings:","The demo pins the model first, since the model name is part of every request and so of its key:","It records two calls into a temporary directory, replays them, and shows a changed request missing. In this manual's build the recording scope's service is whatever encloses it (the last section): the committed recordings in a default build; in a recording build, the committed recordings where they exist and the service for the rest; the service itself in a live build.","Replaying needs no key. With key removed, no request could be sent:","A request that differs in anything — here one trailing space, or the default model instead of the pin — has no recording:","Tune it"]],["Tests: the methods, the resolution, the judgment","jev_testing_tests",["The job: check in CI, without a key, that the program still decides the way you need. Without a decision model, a classifier is tested against labelled examples, one call each. With one, a program has three layers, and each is tested on its own:","Only the judgment needs the service.","The methods",'Call them with nl"…"() instances, or with Meaning(text) for a sentence held in a variable. No service, no key:',"The last line is why a String is never offered that meaning: no method could take it.","Coverage","List every argument type the program calls with: the options, and so the gaps, are per type. The test moves the refusal nl_dispatch would raise in production into CI.","Keyed dispatch: the table and the methods agree","With texts, the methods dispatch on short keys and a table holds the sentence the model reads for each key (Keys and tables). The table and the methods live apart, so test that they agree: meanings(f; texts) makes the check nl_dispatch makes before its request and throws when a key has no method, meanings(f, argtypes; texts) pins what a call offers, in table order, and meaning_gaps(f, argtypes; texts) lists the combinations no method covers. Here the support desk's teams from Decisions with LLMs each go to a queue:","The last test is the drift a separate table invites: a key added to the table and not to the methods. The error names the method to define, queue(::Val{:returns}, _), and nl_dispatch raises it before any request. A method whose key is not in the table is no error: it is never offered.","The resolution, on recorded answers","Replay the calls the program makes and assert on the method they select. The test needs no key and sends nothing, and it covers everything that shapes the request — the meanings and their order, the argument names that key the state, the pin: change any of them and the replay misses, loudly, until the answer is recorded again.","In a package the recordings live next to the tests, and a switch of your own decides when to record:","Here the directory recorded above plays that part:","Edge cases, from a local server","A recording holds an answer the model gave. To test what the program does with an answer the model rarely gives — a near-tie, a failed call, an option it was never offered — write the answer yourself, and send the call to a local server that returns it in the provider's response shape. Each provider's testing section shows how, with such a server, and the table at the end links them. The server can keep every request body it receives, so a test can check the wire as well.","An answer outside the offered options, which no recording can hold, makes the call a SystemOneCallError, so nl_dispatch throws a SystemOneError, and no method runs. A retryable status fails at once under RequestConfig(max_attempts = 1) instead of backing off. A gap in the method table needs no server at all, since nl_dispatch refuses it before sending. Run these tests outside with_recorded_answers: in a replay scope the request is replayed or misses, and never reaches the server, and a recording scope would file the canned answers as real ones.","The judgment: semantic assertions over LLM output","A property of generated text — the reply apologises, the reply promises no refund — is a judgment, and a decision model can make it: one Noul per property, all in one request. The reply comes from an LLM call, which is recorded like the decision's answers, so every run asserts on the same reply:","A verdict falls in one of three bands — at or above 0.8 a yes, at or below 0.2 a no, in between inconclusive — instead of one cut at 0.5, where an answer near the cut can land on either side from one call to the next. An inconclusive verdict fails its assertion as a wrong one does, but says so in the failure (Evaluated: inconclusive === yes): the remedy is a sharper question or a look at the reply, not a re-run.","Here the refund verdict, 0.17, is a no near the edge of its band: the reply names a refund only to say that it cannot promise one. A replay keeps that verdict; a fresh run could land it in the middle band.","In a test suite, run the block inside the suite's with_recorded_answers scope, as test/runtests.jl above does: the reply and the verdict are both pinned. Assert on the reply you recorded, not on a fresh one: a new reply is a new input.","Measured on jev-1.13.0 (September 2026), four such assertions over 24 replies of our own: all 95 verdicts we could label agreed with our labels, and none changed across three identical runs. Regenerating the replies changed 12 of 96 verdicts.","Paraphrase tests","A router can be checked without labels: rewrites of one input that keep its meaning must route the same way. Write paraphrases in several styles — formal, terse, misspelt, another language, rambling — and assert that each lands where the original does:","It is a cheap smoke test that needs no labels, not proof: a router that sends an input and all its paraphrases to the same wrong place passes.","Measured on jev-1.13.0 (September 2026) with three versions of one five-way router — options with descriptions, bare option names, deliberately vague descriptions — on 15 inputs with six paraphrases each: the share of paraphrases routed like their original was 1.000, 0.989 and 0.967, in the same order as labelled accuracy (1.000, 0.990, 0.971). The paraphrases that moved all came from a single input (1 of 15)."]],["Test a decision + LLM pipeline offline","jev_testing_pipeline",["The job: test the whole path a message takes — route, draft, check — in CI, with no key and nothing sent. Without recordings, the test calls both providers on every run, pays for both, and asserts on a new draft each time. With with_recorded_answers, the LLM's draft is recorded like the decisions' answers, and the whole pipeline replays.","The desk from Decisions with LLMs, cut to three steps: route with nl_classify over TEAM (above), draft with respond, and check the draft against the shop's policy with one decision:","The test records once and replays on every run after that. Here the recording goes into a temporary directory, and the replay runs with both keys removed:","Both paths replay: the routes and the checks from the decision provider, the drafts from the LLM. The draft is part of the check's request, so the two stay in step: change instructions and the draft's request misses, loudly, until it is recorded again — and a new draft is a new input for the check, so read it before you trust the assertion again.","Tune it"]],["Keep an audit trail","jev_testing_audit",["The job: keep, with every decision the program acts on, what a support request or an auditor will ask for. Without on_response, keeping the answer meant making the decision with ask yourself. With it, nl_dispatch, nl_classify and @branch hand you the whole SystemOneSuccess before they decide. Keep three values from its response:","on_response runs once, when the request has succeeded and before the decision policy, so it also sees the answers the policy then declines; decide, called with the ChoiceAnswer alone, cannot see the request id or the model. It is not called for a failed call: the thrown SystemOneError carries that result. nl_dispatch(f, args...; on_response) takes it the same way, and @branch as a keyword: @branch message on_response = keep begin … end.","Tune it"]],["How this manual runs its examples","jev_testing_manual",["docs/make.jl runs the build inside one with_recorded_answers scope over docs/recorded_answers, and picks its mode by flag, never by which API keys are set. The examples that call a service replay from it: decisions on each provider (ask, ask_each, the one model listing that is recorded) and the LLM verbs, streamed or not (chatrequest!, respond, embeddingrequest!, the tool loops, the Responses lifecycle calls, fim_complete, prefix_complete).","Each flag is 1, 0 or unset, and at most one is 1; anything else stops the build before anything runs. What the scope does not record — image generation, audio, files, MCP, … — goes to its service in a recording or a live build. Replay and record ignore TYPESAFE_DEFAULT_MODEL: an unpinned request names the default model, so an exported default would change every recording's key. After a recording run, commit the new files in docs/recorded_answers.","The output under an example is the build's own: a recorded answer in a default build, a fresh one in a live build, and in a recording build the committed recording where one exists and a fresh answer otherwise. The numbers in the Evidence boxes were measured separately."]],["See also","jev_testing_see_also",[]],["On your provider","jev_testing_providers",["Where each provider's recordings are filed, what is keyed and what is left out, what recording takes, and a server that answers what a recording cannot hold:"]]]},{url:"/guide/jev_with_llms/",sections:[["Decisions with LLMs",null,["A language model writes text; a decision model decides. Put a decision before a language model's call to decide whether and how to make it, and after it to decide whether its output can be used. The decision is cheap next to the call it guards — it reads the text and writes none — and its answer is a probability to gate on, with no text to parse.","The examples use only the names bound above. service and model are the decision provider and model they run on; llm and llm_model are the language model that writes, and strong_model the one a message that needs more expertise gets: bind your own there. The tables at the end link each provider's entry.","Measured on jev-1.13.0 (September 2026): a request with one question took 0.30 s, and one with 22 questions 0.31 s.","Every example below runs when this manual is built and prints real answers, from the decision model and from the LLM, recorded once and replayed. The examples follow one small online shop that sells phones and accessories, ships parcels and has a mobile app."]],["Route before you generate","jev_llm_route",["The job: send each customer message to the team that handles it, and let the LLM draft replies only for those teams. Without a decision model, you would prompt an LLM for a team name and parse its reply, or train a classifier on labelled messages. With one, nl_classify reads the message against one plain sentence per team and returns that team's key, with a confidence to gate on.",'Five messages reach a team, and the Norway question goes to a person as :other. The model reads only the sentences; the keys stay in your program. To see how sure the model was, keep each whole answer: on_response receives it before the decision is made (the one question nl_classify asks is named "classify"):',"The model leaned toward billing, at a confidence of 0.49 — below 0.6, so the message went to a person.","Each team gets an LLM draft, written with that team's instructions and the shop's policy:","Tune it"]],["Check the draft before a customer sees it","jev_llm_check_draft",["The job: stop a draft that leaks something internal, promises what the policy does not allow, or is rude, before a customer reads it. Without a decision model, a second LLM reviews the first and you parse its opinion. With one, one request answers every question about the draft, each with a probability, and your code decides pass, review or block.","An LLM that drafts replies is often told things the customer must not read. Today the shipping team's LLM also knows that the courier is on strike:","The late-parcel draft tells the customer about the ParcelNow strike, which only the internal note says, and is blocked. The damaged-phone draft passes.","This example was chosen, not typical: on 28 September 2026 we drafted the late-parcel reply with three different internal notes, and one of the three drafts repeated its note to the customer. That is the draft shown here, written by gpt-5.4-mini (gpt-5.4-mini-2026-03-17) and checked on jev-1.13.0 — a check is there for the draft that slips, not for the average one.","Tune it"]],["Check claims against the source","jev_llm_check_claims",["The job: send a reply only when the shop's policy backs what it says. Without a decision model, a person reads every reply against the policy. With one, a Choice between supports, contradicts and says nothing reads the reply against the policy, and anything but a confident supports goes to a person.","The answer about the late parcel says what the policy says: shipping costs are refunded only for a damaged item. The reply to the double charge promises to refund any confirmed duplicate charge, and the policy says nothing about duplicate charges, so a person reads it before it is sent.","Tune it"]],["Pick the model","jev_llm_pick_model",["The job: pay for the strong model only when a message needs it. Without a decision model, every message goes to the strong model, or a rule of thumb such as the message's length decides. With one, a Score of how much expertise a good answer needs picks the cheap model or the strong one before the call.","The delivery-time question and the late-noticed scratch stay on the cheap model; the complaint with three problems scores 2.0 and goes to the strong one. estimated_cost prices each reply from the package's price table.","Tune it"]],["Screen what the model reads","jev_llm_screen_input",['The job: keep instructions hidden in retrieved text, such as a product review or a customer\'s attached note, from steering the LLM. Without a decision model, a keyword filter looks for phrases like "ignore your instructions", which one rewording avoids. With one, a Noul asks whether a passage addresses an AI assistant, and the passages that do never reach the LLM.',"The review that addresses an AI assistant scores 0.99 and never reaches the LLM. The review that only mentions the app's chat assistant scores 0.02 and is kept. The LLM answered from the two clean reviews alone.","Tune it"]],["Approve tool calls","jev_llm_tool_calls",["The job: before an agent's tool call runs, check that the customer asked for it. Without a decision model, every sensitive call waits for the customer to confirm, or the LLM is trusted. With one, a Noul reads the proposed call against the customer's own words: the call runs, waits for a confirmation, or is refused.","The guard wraps any tool_loop dispatcher with the same (name, args) signature and checks only the sensitive tools. Order numbers are compared in code; the judgment sees the customer's own words and the proposed call, never retrieved text such as an email the agent just read, where an injected instruction would live. A failed decision call throws SystemOneError before the tool runs, so the guard fails closed.","The refund the customer asked for runs. A refund proposed to a customer who only reported a late parcel is refused (p = 0.1). An order that is not the customer's is refused in code, before any request. A cancellation asked for among other things runs, and a refund the customer made conditional waits for their confirmation (p = 0.39).","In an agent, pass the guard wherever tool_loop takes a dispatcher. A Refused reaches the model as that call's error output, the loop goes on, and the model can ask the customer to confirm:","The LLM called issue_refund for order 4471, the guard let it run, and the LLM told the customer the refund was processed. In a replay scope, a guard request with no recording throws ReplayMissError, which escapes tool_loop instead of becoming a tool error.","A tool an MCP server runs is guarded the same way: each CallableTool that mcp_tools_respond or mcp_tools returns calls the server from a callable with the same (name, args) signature, so CallableTool(t.tool, guarded(t.callable, message; sensitive, orders)) runs the guard before the call reaches the server (Model Context Protocol (MCP)).","The guard is a confirmation filter that keeps an agent from acting on what the customer did not ask for, not a security boundary: in our measurement of the wording shown, one unrequested call in 25 got through.",'Measured on jev-1.13.0 (September 2026), the limits of the wording shown, on 13 legitimate and 25 unrequested calls of our own — in-sample, since the wording was tuned on these cases: all 13 legitimate calls were allowed, including a refund requested together with a second action (P = 0.99). Of the 25 unrequested calls the judgment blocked 17, sent 5 to confirmation and allowed 3; the identifier check refuses two of those three, so one call got through — "Unsubscribe me from the newsletter." allowed a subscription cancellation (P = 0.85). This is a confirmation filter that keeps an agent from acting on what the user did not ask for — not a security boundary.',"Tune it"]],["Offer the LLM only the tools it needs","jev_llm_shortlist",["The job: send the LLM the few tools a request needs instead of the whole registry. Without a decision model, every tool schema goes out on every turn: you pay for all of them, and the LLM has more to confuse. With one, one Choice ranks the whole registry — as many tools as the provider's Choice limit allows — and the LLM receives only the top few, in rank order.","The decision model put track_shipment first at 0.98, and the LLM, offered three tools instead of eight, called it. On a 50-tool registry, handing the LLM only the top 5 cut its input by 84%, and the right tool was always among the five.","Measured with a 50-tool registry over 40 requests, the ranking on jev-1.13.0 (September 2026) and the LLM gpt-5.6-luna at low reasoning effort: the right tool was in the top 5 for 40 of 40 requests, and handing the LLM that top 5 instead of all 50 tools cut its input from 979 to 152 tokens per request (−84%) while accuracy went from 0.950 to 0.975. Keep the shortlist in rank order: in two runs with the shortlist in registry order, the LLM picked the first-listed tool. That is an observation of two runs, not a measurement.","Tune it"]],["The whole desk","jev_llm_desk",["The job: answer the inbox: route each message, draft, check, and send only what passed. Without a decision model, a person reads every message and every draft. With one, each step above is one function, and handle chains them.","The double-charge reply passes the draft check, but the policy says nothing about duplicate charges, so a colleague reviews it. The two shipping replies go out. The Norway question goes to a person, as routing decided.","Tune it"]],["The same pattern elsewhere","jev_llm_domains",["Only the sentences change. Each row is one question to ask before the LLM call and one to ask after it. None needs what a decision model does poorly — arithmetic, counting, comparing dates, or a long state of unrelated text (Designing good questions)."]],["See also","jev_with_llms_see_also",[]],["On your provider","jev_with_llms_providers",["The decision providers, for service and model:","The language-model providers, for llm, llm_model and strong_model:"]]]},{url:"/guide/mcp/",sections:[["Model Context Protocol (MCP)",null,["UniLM.jl provides native MCP support — both as a client (connect to MCP servers) and a server (build your own). MCP tools integrate seamlessly with tool_loop! and tool_loop via the CallableTool bridge.","Protocol: JSON-RPC 2.0 over stdio or Streamable HTTP. The client and the server negotiate MCP revisions 2025-11-25 (preferred), 2025-06-18 and 2025-03-26. The stateless 2026-07-28 revision is not supported yet, so a peer that speaks only 2026-07-28 cannot interoperate: mcp_connect fails naming the revision such a server returned, serve answers such a client's initialize with 2025-11-25, and over HTTP a request whose MCP-Protocol-Version header names an unsupported revision gets 400. Zero external dependencies.","The examples use only the names bound above. service and model are the provider and model the bridged tool loops run on: bind your own there. The table at the end links each provider's tool rules."]],["MCP Client","mcp_client",["Transports","Two transport types are available:","Connecting to an MCP Server","Use mcp_connect with a Cmd (stdio), URL string (HTTP), or transport object:","The do-block form automatically disconnects when done:","Every call on an MCPSession — its liveness check, id allocation and request/response exchange — holds the session, and waiting callers are served in arrival order. A call's per-call bound (timeout, default mcp_request_timeout) also covers its wait: a call that cannot acquire the session in time throws MCPTimeoutError with phase :queue without touching it. Once a call holds the session, its exchange gets the full bound, measured from that moment, so a waiter's clock never tears down the exchange in progress. mcp_disconnect! waits its turn too, so a disconnect racing a call in flight waits for that exchange to finish instead of tearing the transport down under its reader. For real parallelism, open one session per concurrent worker — see Concurrency, Tasks and Cancellation.","A call on a session that is closed — by mcp_disconnect!, by a stdio timeout or crash, or because its transport is not connected — throws the typed MCPSessionClosedError, whose cause is :disconnected, :timeout or :crash (see Timeouts for auto_respawn).","Discovering Tools, Resources, and Prompts","After connecting, the session auto-populates tool/resource/prompt caches. You can also refresh them manually:","MCP servers may send notifications interleaved with responses; the client skips them transparently, answers server ping requests, and answers any other server request with -32601. It reads the server's frames only during an exchange — a stdio notification sent between calls is read with the next call, and over HTTP there is no standing listener, so only notifications carried in a response body (before or after the response itself) are seen. When a notifications/tools/list_changed is read, the session's cached tool list is marked stale — check session.tools_stale and call list_tools! to refresh. A stdio line that is not JSON (a stray log line on the server's stdout) is skipped with a warning.","Calling Tools Directly","Timeouts","Every mcp_connect handshake and every call_tool / list_tools! exchange runs under a bound — set per session at connect time, or overridden for one call:","A stdio request timeout closes the session: a read blocked on an unresponsive server can be released only by killing the server. The watchdog closes the pipe, so the typed MCPTimeoutError surfaces at about the bound, and then tears the server's process group down (stdin EOF, SIGTERM, then SIGKILL); a reply that raced the teardown is discarded. With auto_respawn=true the next call transparently respawns the server (same command, fresh handshake; in-memory server state is lost and tools are refetched); without it, the next call raises MCPSessionClosedError naming the opt-in. An HTTP request timeout does not close the session — each exchange is an independent POST — and the timed-out request is cancelled on the server with a best-effort notifications/cancelled.","auto_respawn covers hangs and crashes alike: a server that dies abruptly — killed, crashed, or its stdio pipe broken — closes the session too, surfacing the typed MCPCrashError (carrying the exit code or signal when known) on the call in flight, and the next call respawns it when auto_respawn=true. Stdio servers still running when Julia exits are torn down by an exit hook, and when a server's process-group leader exits (an npx wrapper, say) the rest of its group is killed at once.","A CancelToken reaches MCP calls over HTTP: a cancel ends the call at once with UniLMCancelled, sends a best-effort notifications/cancelled, and leaves the session open. A stdio exchange does not observe the token; it is bounded by mcp_request_timeout alone. Teardown — mcp_disconnect!'s DELETE, a cancellation notice — is sent even inside a cancelled with_cancel scope.","Bridging to tool_loop! (Chat)","mcp_tools converts MCP tools into Vector{CallableTool{Tool}} for use with tool_loop! on service, the endpoint the tools go to (the package's default endpoint when none is given). Each tool is advertised under its MCP name when that name is letters, digits, _ and -, no longer than the provider takes: 64 characters, unless the provider's entry gives a longer limit in its tools section. Otherwise each other character (the dots in admin.tools.list, say) becomes _, and a name still too long is cut to the limit less 9 characters, followed by _ and the first 8 hex digits of the SHA-256 of its MCP name, so names that agree up to the cut stay apart — the bridged callable still calls the tool by its MCP name. Two tools that map to the same name raise an ArgumentError.","Bridging to tool_loop (respond)","mcp_tools_respond converts MCP tools into Vector{CallableTool{FunctionTool}} for use with tool_loop, under the same names for the same service:"]],["MCP Server","mcp_server",["Creating a Server","Registering Tools","Register tools with explicit JSON Schema or auto-inferred schema:","With the inferred form, the handler's positional parameters are the schema: each tools/call binds the arguments object to them by name. A parameter whose type admits nothing (Union{T,Nothing}) is optional; every other one is required, and a value must have its parameter's JSON type (a string for String, an integral number for an integer, a number for a float, a boolean for Bool; a Symbol binds from a string, and a typed Vector or Dict element-wise). A call that violates this never reaches the handler: the client gets a tool result with isError: true naming the argument, so the model can correct its call. A handler that takes one Dict (the explicit-schema convention) or varargs has no names to bind and is rejected with an ArgumentError.","You can also register existing CallableTool instances:","Registering Resources","Registering Prompts","Macros","The @mcp_tool, @mcp_resource, and @mcp_prompt macros provide a more ergonomic registration API with automatic JSON Schema generation from Julia type annotations. The examples below are executed at doc-build time and call the registered handlers directly to prove the wiring works.","@mcp_tool — typed args become JSON Schema","A named typed function becomes a tool whose inputSchema is inferred from the argument types (typed args are required, untyped ones optional). The generated handler binds the incoming arguments object to your function's parameters by name, with the same type checks as the inferred-schema register_tool!; a missing or wrong-typed argument is answered with an isError: true tool result naming it. The tool is registered without a description.","@mcp_tool requires a named function (function name(args…)). An anonymous function(x) … end now raises a clear error instead of registering a tool named after its first argument.","@mcp_resource — static and URI-templated","A function() registers a static resource; a URI with {param} placeholders registers a template whose handler arguments are bound from the matched path params.","For template resources, each handler argument name must match a URI {param} name — it is bound from the matched params (e.g. {id} ⇒ function(id::String)).","@mcp_prompt — args bound from the request","The anonymous function(arg::String) … end form registers a prompt; declared args are bound from the prompts/get request arguments.","Serving","Start the server with serve:","The HTTP transport blocks until the server is closed (like HTTP.serve). To keep working in the same session, pass block=false and close the returned server yourself:","The HTTP transport validates the Origin header (a DNS-rebinding defense the MCP spec requires): requests without an Origin header (curl, SDK clients) and requests from localhost origins always pass; any other browser origin gets 403 unless you allowlist it:","Handler concurrency. Over HTTP, tools/call, resources/read and prompts/get handlers run concurrently — one task per request, on the default thread pool — so handlers must be thread-safe (protocol requests such as initialize, the lists and ping are answered inline and stay prompt while handlers are busy). Over stdio, handlers run one at a time, and while serving on the process stdout it is pointed at stderr, so a handler that prints cannot corrupt the protocol stream. Registration is synchronized: tools, resources and prompts may be registered while the server is serving.",'What reaches the client. A tool handler\'s exception is a tool result, not a protocol error: the client receives isError: true with the text Error: <showerror text>, which lets a model correct itself — raise with a message you are willing to show it. An exception from a resource or prompt handler, or from dispatch itself, is answered with a generic JSON-RPC -32603 "Internal error" and logged on the server, so no exception text (file paths, argument values) reaches the peer. An InterruptException is never converted: it propagates. Frames (stdio) and request bodies (HTTP) are capped at 16 MiB: stdio answers an oversized frame with -32600, HTTP with 413 Payload Too Large. initialize answers the revision the client requested when it is supported, otherwise 2025-11-25; a JSON-RPC response sent to the server is accepted without an answer (HTTP 202).']],["MCP servers a provider reaches","mcp_hosted",["Separately from the client and server above, a provider may call an MCP server itself, as a hosted tool of a request: the model calls the server's tools during the response and the provider calls the server, while with mcp_connect your process does. Some entries name such a tool, and where UniLM sends one, the provider's entry says how to give it one."]],["See also","mcp_see_also",[]],["On your provider","mcp_providers",[]]]},{url:"/guide/multi_backend/",sections:[["One API across providers",null,["UniLM reaches every language-model provider through one set of types and verbs. The provider is one argument: service names its endpoint and model its model, so code written for one provider runs on another once those two change. This page says what every provider shares, how to switch, and where the providers differ; each provider's own rules are on its entry, which the table at the end links.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's start page."]],["What every provider shares","multi_backend_shared",["A function written once takes the provider as its argument:","Whatever service names:"]],["Switch providers","multi_backend_switch",[]],["Where the providers differ","multi_backend_compare",[]],["Keep up with provider models","backends_provider_models",["Providers add models, deprecate them and shut them down on their own schedules. Where an endpoint declares :models, list_models lists the models it serves your key, or holds, today (Model Listings), and that provider's Models section shows what its listing gives.","UniLM checks a request against its rules for the model the request names, and prices the result at the row of DEFAULT_PRICING of the model the reply names as having served it, else of the model requested: the row of the id, else of the id without a dated snapshot suffix such as -2026-09-14 or -20251101. A model with no rule row of its own meets only the rules its provider sets for every model, and the provider's answer checks the rest; a model with no price row is estimated at 0.0 (Unpriced models cost $0). Before you adopt a newly listed model, look for its price row as the cost code does:","UniLM's release gate holds its rule and price tables to three providers' listings before every release: every listed model of a family UniLM documents needs a price row, and a rule row where the table below says so; every model UniLM names — as a default, in its live tests or in the Julia code of these pages — must be listed, and listed before its shutdown date where the listing gives one."]],["See also","multi_backend_see_also",[]],["On your provider","multi_backend_providers",[]]]},{url:"/guide/natural_language_dispatch/",sections:[["Dispatch on Meaning",null,["A Julia method runs by the types of its arguments. With a decision model, one argument can be chosen by what a text means: write one method per meaning, and one request picks the method whose meaning fits the text. The model only ever chooses among the sentences you wrote, and every choice comes with its probabilities.","The examples use only the names bound above. service and model are the decision provider and model they run on: bind your own there. The table at the end links each provider's rules for the questions these calls send."]],["Pick a pathway","nl_dispatch_paths",["Which one? Keys and sentences are two spellings of one request; they differ in where the sentences live."]],["The sixty-second version","natural_language_dispatch_sixty",["The model read the four sentences, never the keys, and the key of the sentence it chose came back. To run code instead, write one method per key:","The same router with each sentence in its signature, and no table:","Same answer: both calls put the same request on the wire, byte for byte (How it works, below, shows it), so the model was asked the same question.","Tune it"]],["Keys and tables","nl_dispatch_keyed",["A table is ordered, and its order is the order the model reads the options in:","A Dict is refused, because it has no order. A table holds at least one entry, with no sentence and no key twice; how many one question may offer is the provider's limit, which its wrapper checks before the request. Enum values make nl_classify return one of your own values:",'nl_classify returns the key as the table writes it — :billing for a NamedTuple, not Val(:billing) — and sends the text as given, in one question named "classify". Below a min_confidence it calls fallback(text) when you pass one, and throws otherwise, as nl_dispatch does.',"Preview. meanings takes the same table, with no request: meanings(f; texts) lists every sentence per position, and meanings(f, argtypes; texts) what a call with arguments of those types offers:",'Where a table goes. A table fills the one position whose declared type its keys have — ::Val{:billing} above; ::Any declares none — so nl_dispatch(route, message; texts = TEAM) calls a method of two positional arguments: one per table, plus the arguments you pass. Several keyed positions take a Tuple of tables, one per position. A call uses keys or sentences, not both: a method of the same arity with an nl"…" in its signature makes a keyed call an ArgumentError, which is why the sentence router above has a name of its own.',"The drift check. Every key needs some method that takes it at its position — for any of the other arguments' types. A key that no method takes is refused before any request, with the method to write:","A catch-all method, route(key, message), takes every key; write one only when you want that backstop. A decide policy may return an offered sentence, the key of one as the table writes it (:billing, not Val(:billing)), or nothing to decline (Confidence and control).","Tune it"]],["Sentences in signatures","nl_dispatch_literal",['nl"the sentence" is the type Meaning{Symbol("the sentence")}, a singleton with no fields, so it reads as a type anywhere one is expected: in a signature, a const alias or an isa test. Append () for the instance, or build one from a runtime string with Meaning(text):','The type prints as Julia prints any type, Meaning{Symbol("…")} (for a sentence of several words; one word prints as Meaning{:x}), and an instance as nl"…"(). Two identical sentences are the same type, so === compares them. nl_dispatch collects the methods that pin at least one position to one concrete sentence; a wildcard f(::Meaning, x), or a method with no meaning, is an ordinary method and is skipped. The collected methods must agree on their number of positional arguments and on which positions hold meanings, because one set of questions serves them all: a disagreement is an ArgumentError naming both methods, before any request. Varargs cannot carry a meaning.',"Definition order is an input","The options follow definition order: the order in which the methods were defined in a file, a script or a REPL session, which meanings previews. Three things follow from it:","Order matters because the model reads it, and on an ambiguous text it moves the probabilities. Here one request asks the same question twice about a ticket that fits two meanings, once with the options as defined and once reversed:",'Reversing the order took "money back" from 0.52 to 0.03 and gave "charged twice or unexpectedly" 0.93. A flip can land on a confident answer, so a confidence gate declines only the shaky side of it. A table\'s order moves answers the same way.','Measured on jev-1.13.0 (September 2026) on our own labeled sets, in the form nl_dispatch sends: across seven rotations of the option order, the routed method changed for 4 of 33 ambiguous tickets, and the first-listed meaning gained about 3 percentage points on average; clear-cut inputs did not move (≈ 0.01). When we measured the ticket above, reversing the order took the money-back meaning from P = 0.55 to 0.04 and gave "charged twice or unexpectedly" 0.92. A duplicate meaning split one ticket\'s probability from 1.0 to 0.51.',"Tune it"]],["How it works","natural_language_dispatch_how",["Both pathways build the same request. A recording scope files each request under a key made of its method, path and body, so recording the two calls of the sixty-second version shows it: they make one file, and that file holds the body they sent (in this manual's build, the scope records the answers the build replays: How this manual runs its examples):","One choice question per keyed or meaning position, all in one ask:","The model sees the state, the instructions and the sentences. It does not see the keys, the function's name, the method bodies, or the fact that this is dispatch at all: to the provider it is one Choice question like any other.","The answer. Each answer is a ChoiceAnswer whose choice is one of the offered sentences by construction. A decision policy picks the sentence to act on — by default the winner, gated by min_confidence (Confidence and control). The sentence becomes its key's value (Val(:billing) for the key :billing) or its Meaning instance, goes back into the position it came from, the other arguments fill the rest in order, and Julia makes an ordinary call. From there nothing is special: the value is whatever the selected method returns.","What the state carries. Each argument goes into the state as JSON.jl writes it: a struct with every one of its fields. A value that is not data — a function, a type, a module, a Ref or Ptr, a Task, a Channel, a lock, a condition, an event, an IO, an Expr, or a value JSON.jl cannot write, such as an AudioAttachment — anywhere in an argument, or a container nested more than 64 levels deep, is an ArgumentError before the request, naming the argument and the path to the value:",'A String is data, so a secret a struct holds in a field — an API key, a customer\'s address — is sent, and a :record scope of with_recorded_answers writes it to disk with the request. Pass state = ... with only what the model should read; an explicit state is sent as given. An ImageAttachment is data too, but not every provider takes a picture inside the object a call sends: one that does not refuses it before the request, and its entry names the form it takes instead, such as state = [image, "…"] (What each provider takes).']],["Composing with ordinary dispatch","nl_dispatch_composing",["A chosen key is an ordinary argument, so the other positions keep dispatching on their types, and their types decide which options are offered at all. Keys suit a state machine: each line reads state, reply → next state, and the six sentences the model reads sit together in one table.","Each turn is one request whose state is what the assistant asked and what the customer replied:","A call offers only the options whose method accepts the types of its other arguments, and meanings(f, Tuple{…}; texts) lists them for the types you name, exactly as they will be sent; types that no method accepts are an ArgumentError before any request. The model picks among the reachable options, and Julia picks the method afterwards, with no extra request. Values the model must not guess are read by code: the model decides that the customer gave an order number, and order_number parses it.",'Two turns leave the state as it was, and both are the model\'s reading, not a dispatch fault. "thanks, bye" arrives while the refund awaits confirmation, where saying goodbye is not an option, so the model picks "Something else" and the question stands. "no, that\'s all", after the refund, is read as "Something else" rather than a goodbye, so the conversation stays closed as it was. Offering only the replies that make sense at each step rules out a MethodError, not a misreading: a turn the model is unsure about is a job for min_confidence and a fallback (Confidence and control).',"Measured on jev-1.13.0 (September 2026), on 30 live turns of a larger version of this machine (nine meanings): offering every meaning in every state ended 7 turns in a MethodError — 3 of them at confidence 1.00 — and got 22 transitions right; offering only the meanings valid in the current state removed every MethodError and got 29 right.","Tune it"]],["Hierarchies","nl_dispatch_hierarchy",['No table maps leaves to desks. A double charge has no desk of its own, so it reaches desk(::Type{<:Billing}, ticket) by Julia\'s specificity rules, and "anything else" reaches a person. The keys are the types themselves, not instances, so that a branch — an abstract type, which has no instance — can be handed to the same desks.',"When the leaf is unsure but its branch is not. Add each leaf's probability to every node above it, and act on the most specific node that reaches the bar. A decide policy can return only a key the table offered, and a branch is not one, so this rule reads the answer itself — from ask, with the options and instructions nl_dispatch sends — and hands the node to desk:","For the last two tickets no single leaf reached the bar, but a branch did: they went to the tech desk and the billing desk, where a bar on the leaf alone would have sent them to a person.","Measured on jev-1.13.0 (September 2026) at threshold 0.7 on 65 labeled tickets, each asked with the leaves in four orders (260 decisions; correct / escalated / wrong): this rule 250 / 7 / 3; flat leaf routing with the same threshold 238 / 19 / 3; top-down classification with one request per level 238 / 7 / 15. Summing up the tree turned 12 escalations into coarse routes, all 12 correct, and added no wrong one; asking level by level escalated as rarely but was wrong five times as often.","Tune it"]],["Several slots, one request","natural_language_dispatch_slots",["Both positions resolve in one request, as independent questions about the same state: a second position adds a question, not a second request. With keys, pass a Tuple with one table per keyed position, texts = (KIND, TONE): each table goes to the position whose declared type its keys have.","Every combination needs a method. An answer can land on any combination of the offered options, and one with no method would be billed before Julia raised its MethodError. So nl_dispatch checks every combination first and refuses a gap with nothing sent; meaning_gaps runs the same check with no call, in a unit test for instance. A catch-all added for one tone only opens a gap:","Close it with the missing method:","A method wild in every position, reply(::Meaning, ::Meaning, msg), is the other way out: it is never offered, and ordinary dispatch reaches it for every combination that has no method. Prefer the catch-all sentence: it comes back with a name and a probability, while a backstop cannot tell you why it fired, and once it exists meaning_gaps cannot report the method you forgot. A method wild in only some positions is refused with an ArgumentError: wildcard every position or none. A combination that two methods match with neither more specific is a gap too; the error names both and the method for their intersection that settles it. With keys, a catch-all method such as reply(kind, tone, msg) is the backstop.","Tune it"]],["Confidence and control","nl_dispatch_control",["A day's inbox, routed with a threshold:","Five messages went to a team. The question about shipping to Norway fell below the threshold, so fallback ran with the caller's own arguments and held it for a person. With no fallback, the call throws LowConfidenceError, which holds the whole ChoiceAnswer, so a handler can read probabilities.","A Choice always names a winner, even when the probabilities are nearly flat, so the gate is confidence rather than choice. For n options, confidence is clamp((n\xb7p_max − 1)/(n − 1), 0, 1): the top probability p_max, rescaled so that a flat answer scores 0 and a certain one 1. A fixed min_confidence is therefore a different bar on the top probability for every number of options — 0.5 means p_max ≥ 0.75 with 2 options, 0.6 with 5 and 0.55 with 10 — and adding a method, or calling with argument types that reach fewer, moves it. A calibrated model's probabilities hold across groups of answers, which is what makes a threshold worth tuning, but a high confidence says the distribution is peaked, not that the winner is correct.","The confidence formula fits every answer we measured within 0.02 (jev-1.13.0, September 2026, on our own labeled sets).","decide replaces the threshold with any policy over the whole answer. It is called with the ChoiceAnswer and returns an offered sentence — any of them, not only the winner — or, with a table, the key of one; or nothing to decline, which runs fallback or throws DecisionDeclinedError. A bar on the top probability itself stays where you put it:","On this inbox both policies hold the same message. With the four teams, min_confidence = 0.7 is the bar p_max ≥ 0.775; sure stays at 0.8 whatever the number of options. A policy can also prefer a cheaper action to a slightly likelier one: When mistakes have different prices derives such a policy from what each mistake costs. decide together with a nonzero min_confidence is an ArgumentError before any request, because a threshold is itself the policy a -> a.confidence >= τ ? a.choice : nothing. Every position is decided before anything runs, and a policy that returns anything else is an ArgumentError: neither the method nor fallback runs.","A provider may also decline a question itself, answering it with a RefusalAnswer (Declined questions). That is a decline whatever the policy, which never sees it: fallback runs, or DecisionDeclinedError is thrown with the refusal as its answer.","on_response is for audits. It is called once with the SystemOneSuccess, before the policy runs, and gets what decide cannot see: the request id to quote in a support report, the model version that answered, and the raw body.","A call that failed throws SystemOneError instead, and on_response is not called: a timeout or a 500 can never be mistaken for a routing decision. The keywords of nl_dispatch:","Tune it"]],["@branch: the inline form","nl_dispatch_branch",['Every line is option => expression. A bare left-hand side is the option name, the text the model reads: a String, or a Symbol sent as its String, and any other value is an ArgumentError naming its line, before the request. The form ("name", "description") attaches a description to it. A final _ => expression runs when the policy declines, so it needs min_confidence or decide; it runs as well when the provider declines the question itself, with a RefusalAnswer. Keywords go between the state and the block, written key = value: model, min_confidence, decide, instructions, service, config, cancel, on_response and options, as for nl_dispatch, except that decide returns an option name and excludes any min_confidence, zero included.',"The block is a single Choice request whose question is named branch, with the options in source order; only the selected expression runs, and its value is the macro's value. Mistakes in the block's shape — an unknown keyword, a line that is not option => expression, two _ lines, a _ that is not last, decide together with min_confidence — are errors when the surrounding code is loaded. A duplicate or empty option name, or a _ whose policy cannot decline (decide = nothing, or a min_confidence of 0 or less), is refused when the branch runs, still before any request. A failed call throws SystemOneError; the branch is never guessed.","@branch or nl_dispatch? @branch when the decision belongs to one call site and each arm is a line of code: the options and their handling sit in one place, and no function is needed. nl_dispatch when the decision is an interface: the arms are real methods that can be tested and called directly, other modules can add cases, the other arguments keep dispatching on their types, and meanings gives you the option list as data."]],["Designing meanings","Designing-meanings",['The advice holds for both pathways. "The sentence" is the text the model reads: the table entry, or the nl"…" in the signature.']],["Design note: what the model reads","nl_dispatch_design",["Both pathways put each sentence on the wire as an option name, with nothing else: the model reads the sentence, and only the sentence, for that option. That is the most accurate encoding we measured.","Measured on jev-1.13.0 (September 2026) on our own labeled set, accuracy by what each option sends: the sentence as the option name 0.981; a short key with the sentence as its description 0.965; an opaque id with the sentence as its description 0.969; a bare label 0.877; a short key with a structured description 0.977. Structured descriptions did not beat plain sentences on ordinary traffic.","Why the key must not be the option name. A key sent as the option name is part of the prompt, and a word in the text can match it. Here the same eight sentences are offered once as the option names and once under short keys, with each sentence as its key's description (defined and question come from Definition order is an input):",'As sentences, the question about a refund policy went to "anything else" at confidence 0.98; under keys it went to refund at confidence 0.6, most likely because the word in the question matched the key. A texts table never sends its keys: the chosen sentence maps back to its key locally, after the answer.','When we measured this ticket on jev-1.13.0 (September 2026), the sentences answered "anything else" at confidence 0.97 and the keys answered refund at confidence 0.6. On keyword traps, a short key with the sentence attached as its description was confidently wrong: 10% of the short-key answers at confidence 0.8 or more were wrong, against 0% for sentences.',"What a key buys. An identity that stays put while the wording changes: edit a sentence, and the methods, tests and logs that name :billing stay as they are. One table to review or translate, which is also the whole list of options: a method alone adds none. An explicit option order. Typed values — your own types, instances and enum values — and type hierarchies.","What a sentence in the signature buys. One place for everything, with nothing to keep in step. Identity by content: two modules that write the same sentence mean the same thing, and an edited sentence is a new meaning. An open list: the options are the method table, so another module adds a case with one method.","Drift. A table can name a key that no method takes; nl_dispatch checks that before every request and refuses it (Keys and tables). A method whose key is missing from the table is simply never offered. A sentence in a signature cannot drift: there is no second place for it to live.",'Ownership. Method collisions are the same for both spellings. Val{:other} and nl"anything else" are each one type in every loaded package, so two packages that both add handle(::nl"anything else", ::String) to a third package\'s handle define one method twice, and the one loaded last wins, silently. A module that owns neither the function nor an argument type is committing type piracy with either spelling. The remedy for both is a type the module owns: a package that does not own handle can add handle(::nl"a refund request", t::MyTicket) for a MyTicket of its own, and from the next call with a MyTicket on it is one more option the model may choose.',"Speed. Not a reason to pick either. Both pathways cache their plan — the options, the argument names and the gaps — per function, argument types and world age (and, with a table, per its contents), so a repeated call looks it up instead of recomputing it. The world age is Julia's count of definitions: any new method, constant or global, of any module, moves it, and the next call plans again. A cache holds 1,024 plans and starts over when full. Measured with sentences in signatures, even the uncached work was a rounding error next to the request.","Measured with sentences in signatures, against requests answered by jev-1.13.0 (September 2026): resolving the options and dispatching took ≈ 39 \xb5s of local work, uncached, against ≈ 300 ms for the request (0.013%), and dispatch on a Val and on a Meaning cost the same, ≈ 0.12 \xb5s."]],["Testing without the API","natural_language_dispatch_testing",['The methods stay ordinary: route(Val(:billing), message) or route_by_sentence(nl"anything else"(), message) runs one with no request. Coverage needs no service either: meaning_gaps is the check nl_dispatch runs before its request. The resolution — question names, option order, the state on the wire, the policy — needs one real answer, recorded once and replayed in the test by with_recorded_answers, which throws ReplayMissError instead of reaching the network for a request it has no recording of. Test and Develop walks through recording and replaying, and links each provider\'s recipe for edge cases from a local server.']],["See also","natural_language_dispatch_see_also",[]],["On your provider","natural_language_dispatch_providers",["What of a call's question reaches each provider's model, the question kinds it answers, and its limits:"]]]},{url:"/guide/results/",sections:[["Results",null,["A request to a model returns what the service or the network did as a typed result instead of throwing it: a success holding the reply, a failure holding what the provider answered with, or a call error holding what ended the call. Branch on the type, or ask issuccess, before you read the reply.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["Three outcomes","results_outcomes",["Each is an LLMRequestResponse:","A failure or call error of chatrequest!, respond or fim_complete also keeps the provider's request id header, when one came, as request_id. A tool loop returns a ToolLoopResult whose response is the last result it received, and responses every one, in order (Inspecting the result). Of the lifecycle verbs of stored responses, delete_response, list_input_items, compact_response and count_input_tokens return the provider's answer as a Dict on success, and a ResponseFailure or ResponseCallError otherwise."]],["Reading a success","results_success",["text is the reply of an LLMSuccess, and output_text the answer of a ResponseSuccess; result.message holds the whole reply, its finish_reason, tool_calls and refusal_message among it. An LLMSuccess's model is the model the provider reports having served the turn where UniLM keeps the name its reply gives, and nothing otherwise (each entry's first call says which); a ResponseSuccess's is result.response.model. Its logprobs and moderation are the reply's log probabilities and moderation results, when the request asked for them and the reply carries them, and nothing otherwise (LLMSuccess). token_usage reads the usage in one shape for every provider, a TokenUsage — prompt_tokens counts all the input, cache reads and writes included, and completion_tokens all the output, reasoning included — and estimated_cost prices it in USD (Cost Tracking):","A streamed result also counts, as sse_dropped, the stream payloads that could not be read and were dropped while it was assembled, 0 for a clean stream and for an unstreamed call (Dropped SSE payloads)."]],["Handling a failure","results_failures",["A failure holds no reply: text, output_text, reasoning_text, embedding_vectors and fim_text throw LLMResultError for one, which names its status and the start of its body, and its usage is zero. This failure is built by hand, as a 429 would arrive:","What a call throws instead of returning is what UniLM refuses before sending — an ArgumentError for a request that breaks a rule it checks, an InvalidConversationError for a conversation the reply could not be appended to —, a user InterruptException, and, in a recorded call, a ReplayMissError or RecordingWriteError (Recorded answers). In a stream, the last three can come from its task, at fetch, wrapped in a TaskFailedException. Which statuses and errors a provider returns, and what to do about each, is in its entry's failure section."]],["On your provider","results_providers",[]]]},{url:"/guide/semantic_algorithms/",sections:[["Many Items at Once",null,["Many items — tickets, lines of a chat or a log, rows of a table — are judged in one of two ways. ask_each sends one request per item, many at a time, and returns the results in input order: each item is asked exactly as one ask would ask it alone. Or the items go into one request, each under its own key in the state with one question pointed at it: the request carries the items once, and each question adds only its own tokens. UniLM does not pack items for you: the sections from Judge a batch in one request on show how. Either way, Julia does the rest: loops, sorting, counting, searching and stopping.","The examples use only the names bound above. service and model are the decision provider and model they run on: bind your own there. The table at the end links each provider's limits.","Every block that calls the provider runs when this page is built and prints a real answer, recorded once and replayed (Test and Develop)."]],["Many requests at once: ask_each","jev_items_each",["The job: route every ticket of an inbox, each judged on its own, as fast as the service allows. Without ask_each, a loop of ask calls one after another, or tasks of your own with a limit on how many run, a shared backoff when the service is busy, and a way to stop them. With it, one call sends a request per ticket, several at a time, and returns the results in the order of the tickets.","Six tickets, one of them an attempted prompt injection:","Every ticket gets its team. The sixth tells the model to classify it as billing, and is routed on what it reports, a lost package, to shipping. The six requests counted 2,330 input tokens; packed into one request, in the next section, the same tickets count 1,100.","results[i] is what ask returns for tickets[i] alone — a SystemOneSuccess, SystemOneFailure or SystemOneCallError — whatever order the answers arrived in. Every request is built and checked by its provider's wrapper before the first goes out, so one item that cannot be sent stops the batch with an ArgumentError that names it, and nothing is sent. The worker that sends an item builds its request again, so a batch holds no more request bodies in memory — images and all — than it has requests in flight:","Measured live on 20 October 2026 (jev-1.13.0): 50 support tickets, three questions each, took 3.28 s through ask_each with its default of 16 in flight, and 13.21 s as 50 ask calls one after another. The batch used a single connection (HTTP/2). One sequential call came back as a call error, so 49 tickets were answered both ways: their departments matched every time, and their scores differed by at most 0.06 and their Nouls by 0.03, as the answers to identical requests do.","Tune it"]],["Judge a batch in one request","jev_items_batch",["The job: route every ticket in an inbox to its team — or judge any batch of items — with one request instead of one per item. Without a decision model, one classifier or LLM call per ticket, or one prompt that lists them all and an answer you parse back into items. With one, each ticket goes under its own key in the state, with its own question that names the key in backticks, and one request answers every question. UniLM does not pack the items for you: the state and the questions are yours to build, as here.","Measured on jev-1.13.0 (September 2026): a request with 1 question took 0.30 s, and one with 22 questions 0.31 s.","The same six tickets go out in one request:","Every ticket gets its own answer. The sixth tells the model to classify it as billing, and is routed on what it reports, a lost package, to shipping, at confidence 0.8. The request counted 1,100 input tokens, against 2,330 for the six requests ask_each sent above.","Keyed items in one request kept the accuracy of one request per item, at less than half the input tokens per item. Point each question at a key, never at a position in a list: questions about messages[17] collapsed as the list grew.","Measured on jev-1.13.0 (September 2026) on our own labelled set of 150 support messages routed five ways. Keyed items in one request scored 0.987 and 0.980 at N = 150 in two orderings, and 0.983 at N = 300 (every message twice), against 0.980 for one request per message. Each message billed ≈ 186 input tokens instead of ≈ 428, and the collection took one request instead of N.","Addressing items by position collapsed. With the messages as a JSON array and each question pointing at messages[17] — the form of TypeSafe's own counting example, items[i] — accuracy fell to 0.94, 0.45 and 0.33 at N = 10, 50 and 150. A plausible reason: resolving a position means counting elements, which the model does not do reliably; a key is a name the question quotes exactly.","Tune it","More items than one request holds","The job: route an inbox larger than one request holds. A request over its provider's limits — on questions or on context — is refused whole, by the wrapper before it is sent or by the provider, so a long collection goes in chunks: split the indices with Iterators.partition, build one SystemOneRequest per chunk, send them all with ask_each, and keep the global keys so every answer stays addressable. ask_each returns its results in input order, so concatenating them restores item order:","Here the two chunks route every ticket as the single request did. Choose per_request within your provider's question limit, and small enough that a chunk's state fits its context; the table at the end links each provider's limits.","Measured on jev-1.13.0 (September 2026): 300 routed messages billed 55,670 tokens in one request, while 450 came back HTTP 400 max_tokens_exceeded.","Count in Julia",'The job: count the tickets that report a problem with a delivery. Without counting in code, you would ask a model "how many?" and trust its arithmetic. With it, one Noul per ticket gives the probability of yes, and Julia counts the tickets at 0.5 or above; never ask the model how many items match (Designing good questions):']],["Rank candidates","jev_items_rank",["The job: put a backlog of tickets in order of urgency, so the team handles the worst first. Without a decision model, you ask an LLM to sort the list and parse its answer back, or run a sort that calls a model once per comparison. With one, one request carries a Score per ticket and a Choice per pair of tickets, and Julia sorts: by each Score's expectation, and by the number of comparisons each ticket won (its Copeland count).","Both orders agree here: the exposed card numbers first, the keyboard shortcut last.","A Score per ticket asks one question per ticket; the tournament of pairs ranked a little better on our tickets, at n(n − 1)/2 questions. Do not rank by one Choice's probabilities: a Choice picks one winner, and its runner-up probabilities are not a ranking.","Measured on jev-1.13.0 (September 2026) against our own gold urgency order of 20 tickets (Kendall τ_b):","The pairwise rows rank by summed win probabilities. One request's figure depends on which item of each pair the question names first: 0.926 when the less urgent item (by our gold order) came first in every pair, 0.905 when it came second, 0.916 with both orientations averaged (two requests). Counting wins, as the example does, gave 0.937 and 0.889, against 0.931 for the 380 requests. Each orientation puts the more urgent item in the same place in every pair, so a preference for a position counts as accuracy in one of them and as error in the other: the better figure may owe part of its lead to position. sort! gets there too, but a comparison sort cannot choose its next pair before the last answer arrives, so its requests run one after another. The 190 pairs billed 9,324 input tokens, and swapping the two items of a pair flipped 3.2% of pairwise answers.","Tune it"]],["Find the first line where something happens","jev_items_find",['The job: find the first line of a support chat where the customer asks to cancel their subscription — or the first line of a log where something happens. Without a decision model, a keyword search for "cancel", which also fires on a cancelled dentist appointment and on a threat, or an LLM that reads the chat and quotes a line back. With one, every line goes under its own key, one Noul per line asks whether that line is the event, and findfirst takes the first at or above 0.5:','The question spells out what does not count, because the model reads literally: L03 cancels a dentist appointment and L05 threatens to cancel, and neither is the request. L10, "The first one, please.", is a cancellation only as the answer to L09 — the line search finds such replies because the whole chat is the state.',"When the condition builds up over several lines","The job: find the line after which a condition that builds up holds — has the customer given all three of name, date of birth and postcode? Without a decision model, code that tracks each field through the chat. With one, since the condition shows on no single line and no per-line question can find it, ask it about prefixes instead. For lines 1:k the answer runs false … false, true … true as k grows, so a bisection finds the first true prefix in ≈ log2(n) sequential requests. That needs the predicate to be monotone:","The customer declined the date of birth at L07 and gave it at L12, the line the bisection found.","On long transcripts, the one-request line search found the events that show on one line and missed every condition that builds up; bisection over prefixes was right on every transcript.","Measured on jev-1.13.0 (September 2026) on 14 synthetic support transcripts of 600 lines each: the one-request line search found the line-level events, including replies that mean something only after their question, and missed every cumulative condition tested (0 of 3); bisection over prefixes was right on all 14, two of which contain no event.","Tune it"]],["Match records across two lists","jev_items_match",["The job: match each incoming product listing to the same product in your catalogue, or to none. Without a decision model, string similarity with a threshold you tune, which misses rewordings and matches near-misses such as the 128 GB and the 256 GB phone. With one, Julia keeps a few similar candidates per row (the blocking), and one Choice per row picks the same product among them or says none of them is, with a confidence gate that sends an unsure row to review.","The XM5 headphones are not the XM4 in the catalogue and stay unmatched, and the Dyson answer, none at confidence 0.57, goes to review.","A Choice is relative: it names the closest candidate even when none matches. The explicit none option and the confidence gate are what make the join safe — an unsure answer becomes a review item instead of a match. On a product catalogue of our own, the join matched every true pair and nothing else.","Measured on jev-1.13.0 (September 2026) on a product catalogue (66 incoming rows, 66 entries, 41 true matches, 5 candidates per row): F1 1.000, against 0.605 for trigram similarity alone at its best threshold, and all 25 rows without a match stayed unmatched. On company names with renames, acronyms and subsidiaries (30 rows, 35 names, every name a candidate): F1 0.927 with one Choice per row and 0.974 with one Noul per candidate, at about three times the input tokens. Blocking by trigrams does not survive renames — it kept the true match among 5 candidates for only 60% of those rows, which capped a blocked Choice at F1 0.727.","Tune it"]],["Stop reading once it is found","jev_items_stop",['The job: read a log as it arrives and stop at the first line that shows data was lost. Without a decision model, a search for "lost" or "loss", which also fires on records_lost=0 and on a drill that only simulates data loss, or an LLM call per line that keeps running after the answer is known. With one, worker tasks send one Noul per line concurrently, and the reader reports the first matching line in input order and cancels what is still in flight.',"The pieces are plain Julia — a Channel of line numbers, N worker tasks, and a main task that reads the answers — plus three rules:","In 10,000 simulated runs, stopping at the first answer to arrive reported the wrong line 36% of the time. Against requests answered by jev-1.13.0 (28 September 2026), one cancel! ended the requests still in flight in ≈ 13 ms once warm.","Which requests go out depends on scheduling, so the docs build does not run this block; the # => lines are the output of one live run, pasted as comments.","The yes/no criteria carry the policy, because the model reads literally: without them, the routine INFO purged 1204 expired sessions per retention policy line was flagged as data loss. A provider whose API has no place for a Noul's yes and no refuses them before sending: fold what they say into the question there (its entry's Limits and refusals section).","Measured on jev-1.13.0 (September 2026): that line scored 0.65 without the criteria and 0.10 with them.","Tune it"]],["See also","semantic_algorithms_see_also",[]],["On your provider","semantic_algorithms_providers",["How many questions, how much state and how many pictures one request may carry on each provider, and what its wrapper checks before sending:"]]]},{url:"/guide/streaming/",sections:[["Streaming",null,["A streamed call returns a Task at once and hands the reply to your callback as it is generated, so you can show partial results as they arrive; fetch gives the same typed result as an unstreamed call. A Chat streams with stream=true and a callback, and respond with a do block.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["Streaming a Chat","streaming_chat",["Set stream=true and provide a callback:","The callback fires in a fixed sequence: with a String argument as text arrives — each argument is newly-generated text forwarded verbatim (several wire deltas may be coalesced into one callback), so multibyte characters are never split across chunk boundaries — and then exactly once at end-of-stream with the fully assembled Message, whose content equals the concatenation of every forwarded String.","A Chat streams this way on every provider. When the turn ends, how its usage arrives and when a tool call reaches on_tool_call are the provider's, as its entry's streaming section says.","Stopping a Stream Early","The callback receives a Ref{Bool} that you can set to true to stop streaming:","A stop takes effect at once: the connection is aborted, and the call ends with LLMCallError(status = nothing, cause = UniLMCancelled(:callback, elapsed)) (a ResponseCallError on a Respond). It is never retried, no further callback runs, and the partial reply is not appended to the chat — unless the provider's completion marker already arrived: then the turn is committed, the final-message callback runs, and usage may be missing. On a Chat stream the marker is the chunk that carries the finish reason, so a stop after it — or from the final-message callback itself — returns the completed turn as the success it is. On a Respond stream the marker is the terminal event: the response it carries stands, and its callback has already run.","The flag can also be set from another task that holds it. To stop a stream from outside the callback, cancel a CancelToken instead: pass cancel=tok (or run the call inside with_cancel(tok)) and call cancel!(tok) from any task. The result has the same shape, with cause.source == :token:","A stop requested while the stream task is inside your callback takes effect when the callback returns. See Cancellation for the full contract.","Exceptions from callbacks","An exception thrown by callback or on_tool_call ends the call: fetch returns an LLMCallError (or ResponseCallError) whose cause is that exception. The call is never retried, nothing is appended to the chat, and no callback runs after it. On a Chat, the usage the provider had reported by then is added to cumulative_cost, as for a stop (Cumulative cost): a reply whose final usage had arrived counts whole, and when a provider reports its usage is on its entry. A user InterruptException is the exception to that rule, as are the ReplayMissError and RecordingWriteError of a recorded call made in a callback (see Recorded answers): each propagates, bare or inside the exception a fetched task threw, so fetch throws a TaskFailedException wrapping it.","Streamed tool calls","When the model streams tool calls, pass on_tool_call to be notified as each call completes. It fires at most once per tool call, in call order, receiving a fully assembled ToolCall whose arguments are already parsed (a zero-argument call arrives as an empty Dict); a call whose arguments do not parse as JSON is skipped with a warning rather than delivered. The text callback and on_tool_call are independent, so a single request can stream assistant text and surface tool calls as they finish:",'on_tool_call is a keyword of chatrequest!, on every provider\'s Chat stream; respond has none. It is a notification hook — the final assembled Message still carries every tool call (alongside any assistant text), so code that does not set on_tool_call loses nothing and can read result.message.tool_calls after fetch. The one call it omits is a partial one: on a turn that did not finish with "tool_calls" (cut at "length", say), a call whose arguments were cut off before they formed a JSON object is dropped, while the turn keeps its text, finish reason and usage.',"callback and on_tool_call require stream=true: passed to a non-streaming call, they raise ArgumentError before any request is sent, rather than being ignored."]],["Streaming a Respond","streaming_respond",["respond streams with Julia's do-block syntax:","The do-block form automatically sets stream=true.","With explicit configuration"]],["Dropped SSE payloads","streaming_dropped",["An SSE data: payload the parser cannot read is dropped rather than allowed to abort the turn, and each drop is counted for that stream. The count rides the result as sse_dropped — on LLMSuccess, LLMFailure, ResponseSuccess and ResponseFailure alike — and a single warning naming the count, model and surface fires once the stream finalizes, not per line. sse_dropped == 0 means a clean stream, and is what a non-streamed call always reports. A non-zero count means the turn was assembled from an incomplete wire: a provider-side or transport anomaly, never routine operation. On a truncated stream it is often the reason no message could be built at all, so it is worth reading on a failure result as well as on a success."]],["Notes","streaming_notes",[]],["See also","streaming_see_also",[]],["On your provider","streaming_providers",[]]]},{url:"/guide/structured_output/",sections:[["Structured Output",null,["A format makes the model answer in JSON: any JSON object, or one that follows a JSON Schema you give. A Chat takes it as response_format, a Respond as text. How a provider constrains the reply, which parts of a format it sends, and which formats it refuses are on its entry.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["On a Chat","structured_output_chat",["Use ResponseFormat to control the output format:","Free-form JSON","JSON Schema (strict)","strict=true asks for a reply that follows the schema exactly; whether a provider sends the format's name, description and strict, or the schema alone, is on its entry."]],["On a Respond","structured_output_respond",["A Respond takes a TextConfig in text, made by the convenience constructors:","JSON object","JSON Schema","Plain text format"]],["Convenience constructors","structured_output_constructors",[]],["See also","structured_output_see_also",[]],["On your provider","structured_output_providers",[]]]},{url:"/guide/system_one/",sections:[["Route and Decide",null,["A decision model reads a piece of state — a text, a record, a picture — and answers the questions you list about it — which one, how much, yes or no — with a probability for each outcome, never with generated text. Your code keeps the control flow: ask sends the questions, and your code reads the typed answers and decides what to do. This page shows the question kinds, how to read an answer, and decision rules built on its probabilities, the same on every decision provider.","The examples use only the names bound above. service and model are the decision provider and model they run on: bind your own there, once its entry's setup is done (Decisions lists the providers, and Choosing a decision provider sends the same calls to each). The tables at the end link each provider's rules."]],["First request","system_one_first",["One call carries the text once and every question you want answered about it. Answers come back keyed by the names you chose:","The Noul's yes and no describe its two outcomes. A provider whose API has no place for them refuses them before sending: fold what they say into the question there (Limits and refusals).","The output under each block is the docs build's own: it replays an answer recorded from a live call (Test and Develop). The rest of what came back:",'The question names ("department", "urgency", "is_frustrated") are yours, and they key the answers. Whether a provider shows a question\'s name to its model differs, as each entry\'s Questions section says, so on every provider write the whole question in the instructions, even when the name looks self-explanatory.']],["Choice, Score, Noul","jev_primitives",["Three question types cover the judgments: pick one of a set, place on a scale, say whether a statement holds, and every decision provider answers all three. How many options a Choice and how many levels a Score may have is each provider's: its entry's Questions section gives them, and which of them UniLM checks before the request is sent.","Choice — pick one of a named set","choice builds a question whose answer is exactly one of the options you enumerated. The ChoiceAnswer carries choice (the most likely option), probabilities (one per option, keyed by option name, summing to about 1) and confidence (how peaked they are). Use it for a fixed set with no order between the options: a team, an intent, a document type. A runner-up with a real share is information your code can act on.",'Option order is the order of what you pass, and it is the order the model reads: on ambiguous inputs it moves the probabilities (answers stay keyed by name). Build options and state from ordered containers — a NamedTuple, a vector of name => description pairs or a JSON.Object — to choose that order. A plain Dict has none of its own: its options, and its keys in a state, go out sorted by name, so "t10" comes before "t2" — the same on every Julia version, but not the order you wrote.',"Measured on jev-1.13.0 (September 2026) on our own labeled sets, changing the option order shifted the probabilities of ambiguous items by 0.12 on average, and reversing it moved one ambiguous ticket's probability by about 0.5; changing the key order of the state moved probabilities by up to 0.16.","An option's name goes out with its description, so a short name such as returns is part of what the model reads, and a word in the text can pull the answer toward it. When only the description should decide, send the sentences themselves as the names — choice(question, collect(TEAM)) — and map the chosen sentence back to your key, which is what nl_classify does (Design note: what the model reads).","Score — place the text on an ordered rubric","score takes the level descriptions lowest first; levels[1] is level 0, so three levels give a score in 0.0 … 2.0. The ScoreAnswer carries score, confidence, legend and probabilities, the last two keyed by the 0-based level number as an Int. score is the probability-weighted average level, so it falls between levels: threshold it, and read probabilities when the shape matters — a 1.0 can be all the probability on level 1, or half on level 0 and half on level 2.",'Describe situations, not degrees: a level is a description the state is matched against, so "Broken or degraded feature, but workaround exists" gives the model something to match, where "worse than the previous level" names no situation at all. Keep one dimension per question.',"Noul — the probability that a statement is true","noul asks one yes/no question. The NoulAnswer is one number in 0 … 1 — near 1 a strong yes, near 0 a strong no, near 0.5 maximal uncertainty — and has no confidence field: with two outcomes the value is the whole distribution.",'A Noul is the probability that the statement holds, not a degree: "Is the candidate strong in Python?" at 0.5 means the model is split, not that the candidate is middling — ask a Score for degree. Phrase the question so that a high value means yes.',"Structured criteria","Guidance — instructions, a Choice option's description, a Score level, a Noul's yes and no — is a string to start with. The question constructors also take an object (a NamedTuple or a Dict), a vector or a tuple, or an image wherever guidance appears, so that two options that keep getting confused can each say what they cover, what they do not, and a few examples. Not every provider's API has room for structure, or for every guidance field: a wrapper refuses what its provider cannot carry, before anything is sent, rather than send a question you did not write (What each provider takes compares them, and Structured guidance shows such a Choice answered).","Pointing a question at part of the state","When the state holds several parts — a message, a record and a policy — name the part a question is about with its key in backticks, and keep the content in the state rather than in the question:","The backticks are a prompting convention the model reads, not a resolver: a name that does not exist raises no error, it only leaves the question vaguer. The state may be a String, a NamedTuple, a Dict, a Vector, a Tuple or an ImageAttachment — not nothing — and the entry of a provider that receives it in another form, such as one JSON text or its pictures apart from its texts, says how. A state's keys go out in their order, which can move an answer as the option order does, so prefer the ordered forms."]],["Reading answers","Reading-answers",["Any call that reaches the provider returns one of three result types. A malformed request is an ArgumentError before anything is sent, on every provider: a service that serves no decisions, a blank or repeated question name, criteria that are not valid, a state or guidance holding NaN or Inf, an AudioAttachment or a DocumentAttachment anywhere in the request, and what a provider's wrapper refuses on its own account, such as an image's detail level where its wire has no field for one, which its entry's Limits and refusals section lists. Inside a with_recorded_answers replay scope, a request with no recording throws ReplayMissError: a gap in the recordings is not a service failure.",'A failed call has no answers: answers, answer and getindex throw SystemOneError on it rather than returning an empty map, so r["is_unsafe"].noul > 0.9 can never read as "safe" on a call that never happened. Where a failed call is a case your code handles, branch on r isa SystemOneSuccess first, as the first example does. On a success, three equivalent accessors reach an answer:',"A provider may round the numbers it sends, so a distribution need not sum to exactly 1: ask accepts a sum within a tolerance set per provider, which its entry's Confidence section gives, and returns a reply further off as a SystemOneCallError. A Score answer is held to its own numbers the same way: its score must be the expected level its probabilities give, within n − 1 times that tolerance plus one rounding step for a Score of n levels, and its legend must repeat each level you asked as a string, unchanged. A reply that breaks either, chooses an option that was not offered, leaves a question unanswered, or names no model is a SystemOneCallError too: no success is built from a malformed answer.","Confidence describes the distribution, not correctness. It collapses probabilities into 0 … 1: all the mass on one outcome gives 1.0, a flat spread a low number. For a Choice over n options it is clamp((n\xb7p_max − 1)/(n − 1), 0, 1), the top probability p_max rescaled so that a uniform answer scores 0. The same confidence is therefore a different top probability for a different number of options: 0.5 means p_max ≥ 0.75 with 2 options, 0.6 with 5 and 0.55 with 10; a Choice of one option reports 1.0. A Score's confidence likewise measures how concentrated the probability is around the most likely level. Low confidence on a Choice usually means no option wins; on a Score, that the levels overlap for this state, the question measures more than one thing, or the state does not say enough. Who computes confidence differs per provider, and so does how well a model's probabilities are calibrated (One formula, calibrated per model).","TypeSafe publishes the formula on its Confidence page. It fits every answer we measured within 0.02, on jev-1.13.0 in September 2026.","Answers can vary between identical calls. A provider need not answer a repeated request bit for bit: noise on a clear-cut input, but a decision near a threshold can flip between two identical calls. Log what a decision was based on — the answer's raw, r.response.request_id and r.response.model — and, for reproducible tests and docs, record an answer once and replay it with with_recorded_answers (Test and Develop).","Measured on jev-1.13.0 (September 2026), identical requests differed in 60% of repeated pairs, by 0.011 in a probability on average and by up to 0.11."]],["Ask many questions at once","jev_many_questions",["The job: learn several things about one message — which team, why, how upset, whether the customer wants a person — without paying for the message once per question. Without a decision model: one classifier or one prompt per question, or one long prompt whose answer you parse. With one: one ask carries every question; the text is sent once, and each answer comes back under its own question's name.","A further question adds its own tokens to the request. Where a provider reads the state once for all the questions, it barely moves the latency either, which makes speculative questions worth asking: include the ones whose answers matter only for some inputs, and let the code ignore the rest. A local model may score a request's questions one after another instead (Throughput).","TypeSafe's parallel-questions cookbook runs a 13-question briefing on jev-1.12 and measures it batched into one call at 12.2x cheaper and 10.0x faster than 13 separate calls, with no change in the answers. Measured on jev-1.13.0 (September 2026), one question took 0.30 s and 22 questions 0.31 s.","Tune it","Addressing items by array index (items[17]) collapsed to 33% accuracy at 150 items on our own labeled set (jev-1.13.0, September 2026)."]],["Fill a struct in one request","jev_fill_struct",["The job: turn a support message into a typed record — which team, how urgent, whether the customer wants a refund — that your code can store and act on. Without a decision model: an LLM filling a JSON schema, whose output you then validate and parse, or one classifier per field. With one: a struct already says what each field may hold, so each field type maps to a question — an enum to a choice, an ordered enum to a score, a Bool to a noul — and one request fills them all, with a certainty per field.","Each enum value is offered to the model as its sentence in DESCRIPTIONS: the sentence is the option's name, and the sentence the model picks maps back to the value, so a value's name never reaches the model — the same idea as nl_classify (Dispatch on Meaning). The constructor only ever receives values its field types allow.","The ticket comes back as a billing ticket of high urgency that asks for a refund, and urgency is its least certain field (0.72).","On 32 hand-labeled tickets, one request per ticket filled a five-field version of this struct at 0.979 accuracy per field. A confidence threshold tuned for one option wording may not carry over to another: with the sentences as option names, the Choice confidence on that set came out slightly lower at the same accuracy.","Measured on jev-1.13.0 (September 2026) on 32 hand-labeled tickets and a five-field version of this struct, both encodings in one session, runs interleaved. Sentences as the option names (this recipe): 0.979 per field over three runs (0.981, 0.981, 0.975); exact-match rate 0.896. Labels with the sentences as their descriptions (the other common encoding), same session: 0.981 in all three runs; exact-match rate 0.906. The whole gap is one near-tie flip (0.40 vs 0.39) in the urgency Score, whose question is identical under both encodings; neither encoding made an error on a Choice field. Across the three runs, 1 of 480 predictions changed: that urgency near-tie.","The three-field struct above: both encodings 0.974 per field (team 1.0 on 21 gradable items, urgency 0.923 on 26, wants_refund 1.0 on 32).","Choice confidence was somewhat lower with the sentences as option names (department: mean 0.894 vs 0.910; 24 vs 18 of 96 answers below 0.8), with no change in accuracy. Input tokens per request: 627 with the sentences as option names, 706 with labels and descriptions.","From an earlier run on the same items and questions: gpt-5.6-luna filling a strict JSON schema reached 0.967 per field, at a median latency of 1.3–1.5 s against 0.28 s for Jev, and changed 1–3% of its fields between runs.","Limits: 32 items, one annotator. The Choice fields are at ceiling under both encodings, so this set can show a loss but not a gain; the encoding study on keyword traps, in Dispatch on Meaning's design note, is where sentences measurably beat labels.","Tune it"]],["Act on the answer","jev_act_on_answer",["The job: send each message to the team that handles it, and hand the ones the model is unsure about to a person. Without a decision model: keyword rules per team, and a queue for whatever they miss. With one: one Choice per message, and its confidence says when to hand over.","Four messages go straight to their team. Two go to a person: the question about delivery to Norway (confidence 0.67), and the cracked phone (0.75), a damaged parcel and a refund request in one message.","An answer is a distribution: the answer says what, the distribution says whether to act on it. A model's calibration holds across groups of answers, not for any single one — a high confidence says the distribution is peaked, not that this answer is right — so each policy below is one rule applied to every answer, and how well a model is calibrated is measured per provider (One formula, calibrated per model).","Measured on jev-1.13.0 (September 2026) on our own labeled sets: over 129 routed tickets the expected calibration error was 0.015, and the 113 answers whose top probability was at least 0.9 were 99.1% correct. Other sets measured higher errors: 0.047 on a stress set of 100 items built on the model's documented failure modes, and 0.071 on 74 yes/no (Noul) answers, which were underconfident.","Tune it","When mistakes have different prices",'The job: route tickets when a wrong refund costs far more than a wrong tracking link, with "ask a person" as one of the actions at its own price. Without priced mistakes: one confidence threshold for every action, tuned on labeled tickets. With them: write down the price of each mistake; calibrated probabilities give every action\'s expected cost in one line of arithmetic, and the cheapest action — the Bayes action — wins.',"The second ticket's most likely intent is a refund (confidence 0.69), yet the rule escalates it: a wrong refund costs 10 minutes against a person's 2, and at these probabilities the person is cheaper. The third ticket is refunded (expected cost 1.0), and the first goes to shipping at no expected cost.","On our labeled tickets this rule had a lower held-out cost than the best tuned threshold (56.5 against 83.5), and it needs no labels to set — only prices.","Measured on jev-1.13.0 (September 2026) with this question and this cost table, on our 129 labeled tickets (their labels mapped onto these four outcomes, two-fold cross-validation): the Bayes rule's held-out cost was 56.5 against 83.5 for the best min_confidence tuned on the other fold, and the 95% bootstrap interval of the paired difference, −53.0 to −8.0, excluded zero. The Bayes rule escalated 2 of the tickets, the tuned threshold 18. The threshold needed labeled tickets to tune; the Bayes rule needs none — only costs.","An earlier table of ours priced a wrong other below escalation, and its Bayes rule escalated no ticket at all.","Tune it","Let the model say none of these",'The job: notice the messages that fit none of your options, instead of forcing each onto one. Without a catch-all: read low confidence as "out of scope", which misses the out-of-scope messages a model routes confidently. With one: add a catch-all option; its probability is the out-of-scope signal. Here the same message is asked against a closed and an open option set, as two questions in one request:','In the closed set both out-of-scope messages went to technical_issue, "Please add a dark mode" at confidence 1.0. With a catch-all, P(other) took both at 1.0, and the in-scope message kept its team.',"On our labeled set, the catch-all's probability separated the out-of-scope messages perfectly; one minus the top probability of the closed question did not.","Measured on jev-1.13.0 (September 2026) on our labeled set (25 out-of-scope and 104 in-scope tickets): P(other) from a catch-all option separated the out-of-scope inputs perfectly (AUROC 1.00), while one minus the top probability of the same question without the catch-all did not (AUROC 0.86); the extra option left in-scope accuracy unchanged (0.962 either way).","Tune it","Act on the risk of the worst level","The job: page someone when a report might be critical, even when it is probably not. Without the tail: a severity label or an average score, which hides a small but real chance of the worst case. With it: read the probability mass at and above the worst level, and page when it beats the ratio of your prices. A ScoreAnswer's score is the probability-weighted average — fine for ranking, misleading for a decision whose cost sits on one level.",'The heater report\'s score, 2.24, sits in the middle of the scale, where a threshold at 3.5 does not fire, yet it puts 0.4 on "critical" — far above the 1/11 that pays for a page.',"Paging pays when the expected cost of silence, 10 \xb7 P(critical), exceeds that of a false alarm, 1 \xb7 (1 − P(critical)) — that is, when P(critical) > 1/11. The two rules part only on split distributions like the heater's; on our labeled severity reports they never did.","Measured on jev-1.13.0 (September 2026): the two rules part only on such split distributions, and on our 75 labeled severity reports none occurred: both made identical decisions.","Tune it"]],["Designing good questions","jev_designing_questions",["Check them against what your provider documents its model to do poorly, and again when you move a pin.","These rules restate the failure modes TypeSafe documents for Jev 1.13 (Jev 1.13 jaggedness), with this manual's measurements on jev-1.13.0 in September 2026."]],["With an LLM","system_one_with_llm",["A decision model decides and a language model writes, so they meet on both sides of a generation: before it, route the message and decide whether and how to generate; after it, check the draft before a customer sees it and check its claims against the source. Decisions with LLMs builds each step."]],["See also","system_one_see_also",[]],["On your provider","system_one_providers",["The question kinds each provider answers, what of a question reaches its model, and its limits:","Who computes confidence, the tolerance ask allows, and how a bar is tuned:","How a failed call comes back, and what is sent again:"]]]},{url:"/guide/testing/",sections:[["Testing and recordings",null,["A test that calls a model live needs a key and the network, and a model's reply varies from call to call, so the test cannot be reproduced. with_recorded_answers records a real exchange once and replays it from a directory: the test then runs with no key, sends nothing, and gets the same answer on every run.","The examples use only the names bound above. service and model are the provider and model they run on, and key the variable the provider's key is read from: bind your own there. The table at the end links each provider's start page."]],["Record once, replay without a key","testing_record",["with_recorded_answers(f, dir; mode) runs f() with the requests inside it passing through the recordings in dir, and returns f()'s value. Here a call is recorded into a new directory:","Scopes nest: an inner scope's service is the enclosing scope. This manual's own build runs inside a scope that replays its committed recordings, so the answer above is the one recorded for this request (How this manual runs its examples); in your code, a :record scope sends it.","The default mode replays. With the key removed, nothing could be sent, and the answer is the recorded one:","A request that differs in anything — here one number of the prompt — has no recording, and the verb throws ReplayMissError:"]],["What is recorded","testing_scope",["A replayed answer goes through the same decoding as a live one and has the same type and fields: a Chat gets the reply appended and its cost accumulated, and Embeddings get their vectors. A replayed stream is read through the same parsers and callbacks as a live one.","A stream is recorded only when its reply is whole — its final event arrived, and it was read with no stop. Both recording modes create dir if needed and check that it takes a file before f runs; an answer whose recording still cannot be written throws RecordingWriteError, since the service has billed it."]],["The key is the exact request","testing_key",["A recording is <dir>/<key>.json, and the key is the SHA-256 of the method, the path of the URL and the exact request body: a request that differs in one byte — another prompt, another model, another option, stream=true — is another request, with a recording of its own; a decision request is keyed as Recorded answers says. The host is not part of the key, and neither is the query, which can carry a credential; list_input_items adds the page its query names instead. A credential the body carries, such as an MCP tool's authorization, and the bytes of media sent as a data: URL are replaced before anything is keyed or written: the key and the file hold \"<redacted>\" and the media's digest. The file holds the request, the response body (a stream's lines), the request id, the headers a replay gives back and the time of recording, pretty-printed so a diff is readable; never the API key or any other header.","So pin what the request names: a Chat without model names the provider's default model, and a new default makes every recording miss."]],["A miss is loud","testing_miss",["In :replay, a request with no recording throws ReplayMissError out of the verb itself, and so out of the tool loops — never a call error that a result isa LLMSuccess || fallback() path would absorb. A miss on a later request of a streamed turn, or a request a stream's callback makes, is thrown inside the call's task, so fetch throws a TaskFailedException around it. The message names the request, the start of the key, the model and the directory, and how to record the answer: run the same code once with access to the provider — its API key, or its local server running — and mode = :record_missing."]],["In a test suite","testing_suite",["Commit the recordings directory next to the tests, record it once with the provider's key and :record_missing, and replay it on every run after that, in CI with no key:","A recording is one sample of a reply that varies: replaying it makes a test reproducible, not the reply typical. A scope covers the tasks started inside it. Recordings are never pruned: run the tests once in a :record scope over a new directory, nested inside a :replay scope over the old one, and the new directory receives exactly the recordings the tests use, copied without touching the network."]],["See also","testing_see_also",[]],["On your provider","testing_providers",[]]]},{url:"/guide/timeouts/",sections:[["Timeouts & Retries",null,["Every UniLM operation — a provider request, a stream, an MCP exchange — waits on a peer only under a bounded, configurable limit, and reports a breach as a typed error. This guide covers the bounds, how to change them, the retries they bound, and the typed failures you get when one fires.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["The one config struct","timeouts_config",["All bounds live on a single RequestConfig, resolved per call on every request verb (and captured at connect time by an MCP session):","All timeout fields are seconds (Float64). Set any of them to Inf to disable that bound. The constructor rejects NaN, non-positive values and finite values above 1e9 seconds (use Inf to disable a bound) with an ArgumentError, and requires max_attempts ≥ 1 — a silently-NaN bound would compare false against every check and reintroduce an unbounded wait, and a finite value too large for a timer would fail deep inside a call instead of at construction.","Why these defaults","The defaults mirror those of the official provider SDKs the Evidence note below names, with headroom for HTTP.jl's heavier connect path:",'Read on 25 October 2026 (UTC) from the default branches of the SDKs\' repositories: the Python SDKs of OpenAI and Anthropic set DEFAULT_TIMEOUT = httpx2.Timeout(timeout=600, connect=5.0) (Anthropic\'s as 10 * 60) and DEFAULT_MAX_RETRIES = 2 in their _constants.py; OpenAI\'s Node SDK says "Requests time out after 10 minutes by default" and "Certain errors will be automatically retried 2 times by default" (its README).',"Measured stream gaps","The 120s idle default is provisional and backed by a measurement (scripts/measure_stream_gaps.jl) of the maximum inter-byte gap per provider — the exact quantity the idle guard watches, which keep-alive bytes (SSE comments, a provider's ping events) reset. Both measured maxima sit well under the 60s raise-the-default threshold. A healthy gap above 60s in a future measurement raises the default.","Measured with scripts/measure_stream_gaps.jl on 2026-07-18, on models that are no longer the defaults:","The Gemini stream held a healthy ~16-second silent gap mid-thinking — the class of pause the byte-gap default must tolerate."]],["The four channels","timeouts_channels",["A config is resolved, in precedence order:","current_config() returns whatever is in force right now.","1. Per call","2. A dynamic scope","with_request_config merges the given keywords over the current config for the duration of the block, and propagates into tasks spawned inside it (including the task a streaming call runs on):","3. The process default (notebooks)","A notebook cell cannot hold a dynamic scope open across cells, so set a process default once:","set_default_config!(cfg) replaces the default with cfg; the keyword form merges over the current default.","4. Defaults","Do nothing and you get the table above — except where a provider brings defaults of its own for some of its calls, which its entry states, such as a decision provider's bounds on ask or longer bounds for a model that thinks for minutes. They hold until one of the three channels above is set: a config you set in any channel replaces them as a whole (Request Configuration & Timeouts)."]],["Stream semantics","timeout_streams",["Streams are governed differently from single-shot requests:"]],["Typed failures","timeouts_failures",["A timeout is never a silent stall and never a fabricated HTTP status.","UniLMTimeout.phase is one of :connect, :request, :stream_idle, or :deadline.","Latency of a breach: a non-streaming attempt's bound fires within a few milliseconds of its limit, and a successful call pays no detection delay — its completion wakes the caller directly. The stream idle check runs every min(stream_idle_timeout / 4, 5) s, so an idle breach surfaces within [limit, limit + period].","MCP surfaces are throw-based: a timeout throws MCPTimeoutError, whose message names the override to raise."]],["Retries","timeouts_retries",["Automatic retries apply to the inference verbs — chatrequest!, embeddingrequest!, respond, fim_complete, prefix_complete, generate_image, edit_image, transcribe, ask, list_models, and the tool_loop family through them (streams retry only before the first callback fires). Every other verb makes a single bounded attempt and max_attempts has no effect on it: the platform and lifecycle verbs (batch, container, conversation, file, fine-tuning, moderation, upload, vector-store, speech and translation, realtime, and the Responses lifecycle operations), including upload_file — a create is never retried, because a POST that timed out or drew a gateway 5xx may already have stored the file. The polling helpers poll_batch and poll_file_batch instead poll through retryable statuses and per-attempt timeouts until their own wall-clock timeout.","max_attempts (default 3) caps the total attempts. All attempts of a request share its single total_deadline, timeouts and retries alike:"]],["MCP timeouts","timeouts_mcp",[]],["Concurrency","timeout_concurrency",["Bounds are per operation. What may be shared between concurrent operations — one Chat or Embeddings per in-flight call, fork for fan-out, one MCPSession per parallel worker — and how cancellation, streaming backpressure and the thread layout interact with these bounds is covered in Concurrency, Tasks and Cancellation. Two facts that matter for the bounds themselves:"]],["Migrating from retries","timeouts_migrating",["The retries keyword is removed (no compatibility alias). It was a recursion seed that counted toward a 30-attempt ceiling, so its direction is the inverse of an attempt count. Migrate by intent:","A removed keyword raises MethodError — there is no silent behavior change."]],["See also","timeouts_see_also",[]],["On your provider","timeouts_providers",[]]]},{url:"/guide/tool_calling/",sections:[["Tool Calling",null,["A model can ask to call functions you define: it answers with tool calls — a function's name and its arguments — instead of text, your code runs them, and their results go back on the next turn until the model answers. A Chat takes Tools and a Respond FunctionTools; tool_loop! and tool_loop run the round trips for you.","The examples use only the names bound above. service and model are the provider and model they run on: bind your own there. The table at the end links each provider's rules."]],["Tools on a Chat","tool_calling_chat",["Defining tools","Wrap your function schema in a Tool:","Strict function calling","Pass strict=true to ask the provider to hold each call's arguments to your schema. What a provider does with the flag — what a strict schema needs there, and what it answers to one that misses it — is on its entry: for the provider bound above, Tools on Chat Completions and, for a Respond, Tools. Omitting strict (the default) sends no flag at all: the request body is identical to previous UniLM versions.","Making tool-enabled requests","A Chat with tools sends them with every request. It has parallel_tool_calls = false unless it sets another value, and what a provider does with that is on its entry. UniLM.encode_request shows the body the provider is sent:","Handling tool calls",'When the model wants to call a function, the result message will have finish_reason == "tool_calls":','The finish reason is the provider\'s own: a turn that carries tool calls reads "tool_calls" when the provider finished it with "stop" or reported none, and keeps any other reason ("length", "content_filter", a provider-specific value) — such a turn may hold partial calls, so do not run them. Partial calls are dropped: a call cut off before its arguments formed a JSON object is removed from such a turn, which keeps its text, finish reason and usage. On a "tool_calls" turn, whose calls would run, arguments that do not parse are an LLMCallError instead.',"When streaming (stream=true), pass on_tool_call to chatrequest! to be notified as each tool call completes — at most once per call — instead of waiting for the final message. See the Streaming guide.","Controlling tool choice","Which choices a provider takes, and how it sends them, is on its entry."]],["Tools on a Respond","tool_calling_respond",["A Respond takes FunctionTools, made by function_tool:","function_calls reads a response's calls, each a Dict with its call_id, name and arguments (a JSON string):","Tool choice and tool results",'tool_choice is "auto", "none" or "required", or the object a builder makes — tool_choice_function, tool_choice_hosted, tool_choice_allowed, tool_choice_mcp, tool_choice_custom:',"Return a tool's output on the next turn with tool_result:","A provider may also run tools of its own, such as web search or code execution, which a Respond takes in tools, beside function tools. Which choices and tools a provider takes is on its entry."]],["Automated tool loop","tool_calling_loop",["Instead of manually handling tool calls, use tool_loop! (on a Chat) or tool_loop (on a Respond) for automatic dispatch. Both send a request, run the calls the model asked for through your dispatcher (or the CallableTool callables), send the results back, and repeat until the model answers in text, a request fails, or max_turns (default 10) round-trips are used.","On a Chat",'tool_loop! needs chat.history == true — each follow-up request carries the assistant turn its tool results answer — and throws ArgumentError before any request otherwise. It runs a turn\'s calls only when the turn finished with "tool_calls". A turn that carries calls but finished for another reason ("length", "content_filter", …) may hold partial calls: none runs, the loop stops with completed=false and an llm_error naming the reason, and that unanswered assistant turn is removed from chat, so the conversation stays sendable. A turn cancelled between dispatches, or interrupted by an InterruptException from a dispatch, is removed the same way. A text turn completes the loop only when it finished with "stop" or reported no reason (a "tool_calls" finish with no calls counts too); "length" ends it with completed=false and llm_error = "Model output was truncated by the token limit", and any other reason ("content_filter", a provider-specific value) with an llm_error naming the reason. callback and on_tool_call are passed to chatrequest! unchanged, so they need a Chat with stream=true.',"On a Respond","The Respond loop chains its turns with previous_response_id, or through the conversation the Respond sets. It runs function calls only on a completed or requires_action turn; any other status (for example incomplete, whose calls may be partial) stops it with completed=false and an llm_error naming the status and the incomplete_details reason. A call whose arguments are not a JSON object is answered with an \"Error: invalid arguments: …\" output, like a dispatcher error, and the loop goes on. A turn that asks for a call the application must carry out itself — a kind of call the loop cannot run — stops it with completed=false, naming the pending call's type, and none of that turn's calls run."]],["MCP tool integration","tool_calling_mcp",["MCP servers expose tools that integrate directly with the tool loop via mcp_tools and mcp_tools_respond. See the MCP Guide for full details."]],["Inspecting the result","tool_calling_result",["tool_loop / tool_loop! return a ToolLoopResult: the last response the loop received, every turn's result in responses (each billed on its own: sum(estimated_cost, result.responses) is what a respond loop cost), the list of tool_calls that ran (each a ToolCallOutcome), turns_used, whether it completed, and — when it did not — the llm_error saying why."]],["See also","tool_calling_see_also",[]],["On your provider","tool_calling_providers",[]]]},{url:"/providers/anthropic/",sections:[["Anthropic",null,["Anthropic makes the Claude models; ANTHROPICServiceEndpoint speaks its native Messages API, and every Messages API request is a Chat, sent by chatrequest! or tool_loop!. The agentic verbs — respond and the tool_loop that takes an input or a Respond — refuse this endpoint before sending anything, and no verb of a capability the table below lists as not available sends a request through it. Of Anthropic's own API, UniLM wraps Messages and the model listing: Message Batches, Files, token counting, server tools (the tools Anthropic runs, such as web search), citations and the request fields of beta features are not available."]],["Setup","anthropic_setup",["Set your API key in the environment Julia starts from:","UniLM reads the variable each time a request is sent; a chatrequest! without it returns an LLMCallError whose cause is the KeyError naming it. A Chat reaches Anthropic with service=ANTHROPICServiceEndpoint, the bare type, or with an instance that carries the options below; with no model it takes the default model named at the top of this page. Requests go to https://api.anthropic.com/v1/messages with the key in x-api-key and anthropic-version: 2026-10-21.",'The Messages API requires max_tokens: a Chat sends its max_completion_tokens there, else its max_tokens, and a Chat that sets neither max_tokens nor max_completion_tokens sends 16000, a moderate default rather than the model\'s ceiling. It caps the thinking and the text of a reply together, and headroom a reply leaves unused is not billed: raise it for long replies or a high reasoning_effort, since a turn whose thinking reaches the cap ends with finish_reason == "length" before the answer.']],["Options","anthropic_options",["The bare type is the endpoint with no options. An instance, ANTHROPICServiceEndpoint(; betas, user_profile_id, workspace_id, inference_geo), adds them to every Messages API request made through it, and goes wherever a service goes:","Building the endpoint throws ArgumentError for a value that breaks one of these rules; two checks come later, when a request is made: the model's inference_geo rule, which makes chatrequest! throw ArgumentError before anything is sent (Limits and refusals), and the re-check of betas below. UniLM sends a beta's name only: it models no beta's request fields or response blocks, and reads one name itself, the beta service_tier=\"fast\" needs on the models whose Fast mode cell in the family table names a beta header. list_models sends only the workspace of these options: of the headers they set, Anthropic's Models API reference names only anthropic-workspace-id for GET /v1/models. Instances with the same options are equal (==, hash). The fields are read-only: to change an option, build a new endpoint. A name changed in place in the betas vector is checked again when the header is built, and one that breaks the rule fails the call before anything is sent, its call-error result holding the ArgumentError as cause. US-only inference is priced at a premium (Cost and usage)."]],["First call","anthropic_first_call",["A Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:",'result.model is the model that served the reply, as Anthropic reports it, and the model estimated_cost prices the call at. The reply\'s stop_reason becomes finish_reason: end_turn and stop_sequence give "stop", tool_use gives "tool_calls", max_tokens and model_context_window_exceeded give "length", and refusal gives "content_filter", a turn with no content and the explanation in refusal_message. An unstreamed reply with status 200 that is not a message — no content array or no stop_reason — is an LLMCallError, never an empty success. A failure result, LLMFailure or LLMCallError, keeps the request-id header of Anthropic\'s reply, when one came, as request_id (Rate limits, overload and failures).','prompt_tokens counts all the input — the uncached tokens, the cache reads (cached_tokens) and the cache writes (cache_write_tokens) — and completion_tokens all the output, thinking included, of which reasoning_tokens is the thinking. service_tier is the tier Anthropic reports billing the call at ("fast" for a call served in fast mode) and inference_geo the region inference ran in. How these become a price is in Cost and usage; the result types are on Results.']],["Conversations","anthropic_conversations",["A Chat keeps the conversation: each reply is appended to it, and the next chatrequest! sends the whole conversation again.","A reply goes back as the content blocks it arrived in — thinking blocks with their signatures intact — without its empty text blocks, and a turn with nothing to send, such as a refusal, is left out. What push! refuses is the same on every provider (Conversations with Chat).","The system messages a conversation starts with become the top-level system prompt, joined with a blank line. Where a system message pushed later goes depends on two columns of the family table:",'A system message pushed after a reply needs a user turn after it — a user message, or the results of the reply\'s tool calls — except in a response prefill on a model whose Prefill cell is "yes". Until one follows, chatrequest! throws ArgumentError before sending (Limits and refusals): as it stands, the request would end with the assistant turn, a response prefill.']],["Streaming","anthropic_streaming",["With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call. The callback receives the text as it arrives, a String at a time, then the assembled Message:","A Chat streams through this callback keyword only: chatrequest! has no do-block form, which is respond's, and respond refuses this endpoint. Setting close[] = true stops the stream (Stopping a Stream Early).","The concepts every provider shares are on Streaming.","Recorded on 24 October 2026 on claude-opus-5-5 with UniLM's development branch after 0.26.0 and the Messages API at anthropic-version 2026-10-21.","See also: ANTHROPICServiceEndpoint, Chat, chatrequest! and LLMSuccess in the API reference."]]]},{url:"/providers/azure/",sections:[["Azure OpenAI",null,["Azure OpenAI serves the GPT models from an Azure resource of yours, each through a deployment you create. AZUREServiceEndpoint speaks its Chat Completions API in the dated form — a deployment's URL and an api-version — through chatrequest! and tool_loop!. The agentic verbs — respond and the tool_loop that takes an input or a Respond — refuse this endpoint before sending anything, and no verb of a capability the table below lists as not available sends a request through it. Azure's newer v1 API, which takes no api-version, is reachable through a generic endpoint (The v1 API). No key of an Azure resource was at hand for this page: its examples are not run, and their code stands without output."]],["Setup","azure_setup",["Set the resource, its key, the API version and a deployment for each model you call:","UniLM reads these variables each time a request is built, so they may be set after the package loads. A Chat goes to $AZURE_OPENAI_BASE_URL/openai/deployments/<deployment>/chat/completions?api-version=$AZURE_OPENAI_API_VERSION with the key in the api-key header, the form of Azure's dated API versions; 2024-10-21 is the dated GA release Azure's REST reference documents (REST API reference). A field Azure added later needs a later version: reasoning_effort came in 2024-12-01-preview (API versions), and audio replies in 2025-01-01-preview (audio generation). A call without one of the first three variables returns a call-error result whose cause is the KeyError naming it. UniLM sends the key only: Azure's other way in, a Microsoft Entra ID token in an Authorization: Bearer header, is not this endpoint's.","Azure routes a request to a deployment, and UniLM finds the deployment of the model a Chat names. A deployment registered with add_azure_deploy_name! wins; otherwise UniLM reads AZURE_OPENAI_DEPLOY_NAME_<MODEL> when the request is built, where <MODEL> is the model id upper-cased with every character other than A-Z and 0-9 made _ (gpt-5.2 → AZURE_OPENAI_DEPLOY_NAME_GPT_5_2, gpt-6-luna → AZURE_OPENAI_DEPLOY_NAME_GPT_6_LUNA). A model with neither makes the call return an LLMCallError whose cause is an ArgumentError naming the variable to set. The deployment's name is sent as one path segment, percent-encoded. A registration holds for the session, and a second one for the same model replaces it:","A Chat takes the endpoint as the type, service=AZUREServiceEndpoint, and AZUREServiceEndpoint() returns the type too; with no model, it takes the default model named at the top of this page. The model id goes in the request body as well, and it is the id UniLM prices a reply at when Azure's reply names none (Cost and usage)."]],["First call","azure_first_call",["A Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:",'The reply is read as a Chat Completions reply: result.model is the model Azure reports, and finish_reason is Azure\'s, content_filter "to signify that some of the completion was filtered" (content filtering). prompt_tokens counts the input, of which cached_tokens came from the prompt cache (Prompt caching), and completion_tokens the output, of which reasoning_tokens is the reasoning (Reasoning). The result types are on Results.']],["Conversations","azure_conversations",["A Chat keeps the conversation: each reply is appended to it, and the next chatrequest! sends the whole conversation again.",'A system message pushed after the conversation started is sent in place. Azure\'s reasoning models take system messages; "You should not use both a developer message and a system message in the same API request" (reasoning models), and UniLM sends no developer message. What push! refuses is the same on every provider (Chat Completions).','A reply that holds audio (audio_output) goes back to Azure by the audio\'s id, "audio": {"id": …} beside the turn\'s transcript, as Azure\'s quickstart adds "a history message referencing the previous turn\'s audio by ID" (audio generation), until a minute before the reply\'s expires_at, and from then on as the transcript alone (Audio replies).']],["Streaming","azure_streaming",["With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call; the callback receives the text as it arrives, then the assembled Message. A Chat on this endpoint sends no stream_options unless it sets them, so a streamed turn reports no usage, and adds 0.0 to cumulative_cost, unless the Chat asks for it:",'Azure added stream_options and include_usage in the API version 2024-09-01-preview (API versions). The stream is the Chat Completions one: a chunk whose choices list is empty, such as the usage chunk, whose "choices field will always be an empty array" (chat REST reference), gives its usage and nothing else; the turn is final at data: [DONE], or, without one, when the HTTP body ends after the finish reason; on_tool_call(tc) runs once per call whose arguments decode, as the next call begins or at the end of the stream; and setting close[] = true stops it (Stopping a Stream Early). The concepts every provider shares are on Streaming.']],["Tools","azure_tools",['Each Tool in tools goes out as a function tool, and tool_choice, parallel_tool_calls and a tool\'s strict go as they are set; a Chat with tools sends parallel_tool_calls: false unless it sets another value, as Azure asks with strict tools: "Structured outputs are not supported with parallel function calls" (structured outputs). tool_loop! runs the calls and sends their results back until the model answers in text:','On the GPT-5.6 models, Azure\'s Chat Completions API refuses function tools at any effort but none: "The gpt-5.6 models support the Chat Completions API and tools, but can\'t combine reasoning with tools on Chat Completions", and "The request fails even when you don\'t send reasoning_effort, because these models default to medium"; "If you must stay on Chat Completions, set reasoning_effort to none on every request that sends tools" (reasoning models). UniLM does not check this on Azure: the refusal is Azure\'s HTTP 400. The loop every provider shares is on Tool Calling.']],["Structured output","azure_structured_output",['A JSON Schema response_format goes out as {"type": "json_schema", "json_schema": {…}}, with "strict": true when it sets strict, and UniLM.json_object() as {"type": "json_object"}. Azure constrains the reply: "For Chat Completions, define the schema in response_format", and "API version 2024-08-01-preview is the first version that supports structured outputs" (structured outputs), so AZURE_OPENAI_API_VERSION must name one that does:',"The formats every provider shares are on Structured Output."]],["Reasoning","azure_reasoning",['A Chat\'s reasoning_effort goes out as it is set; Azure\'s values "vary by model and include none, minimal, low, medium, high, xhigh, and max. Defaults vary by model as well", and "max works only with GPT-6 or GPT-5.6 models and the Responses API" (reasoning models), which this endpoint does not speak. The field needs an api-version from 2024-12-01-preview on (Setup). Cap a reasoning model\'s output with max_completion_tokens: "Reasoning models will only work with the max_completion_tokens parameter when using the Chat Completions API", and the cap covers "reasoning tokens, visible output tokens, and formatting tokens". On this endpoint max_tokens keeps its name, so a request to a reasoning model sets max_completion_tokens instead. "Reasoning tokens are billed as output tokens": they count in completion_tokens, reasoning_tokens among them, and Chat Completions returns no reasoning text, so reasoning_text gives nothing.']],["Attachments","azure_media",["A user message's attachments go out as content parts: an image as an image_url part, with its detail when one is set, a sound clip as an input_audio part, and a document as a file part holding its name and a data URL; the deployment's model decides what it reads, and UniLM checks none of it before sending. The attachments every provider shares are on Attachments."]],["Limits and refusals","azure_limits",["A deployment's quota sets its tokens and requests per minute (quotas and limits), and a request past them meets HTTP 429 (When something fails). UniLM checks no limit of Azure's, and none of the per-model rules it applies on its native endpoint for the GPT models: every field a Chat sets goes out as it is — max_tokens keeps its name, user is sent, service_tier and reasoning_effort are not checked — and Azure's answer is the check. It refuses nothing of Azure's own before sending, only the checks every Chat gets, such as a temperature from 0 to 2 or an n of 1; the verbs of the capabilities the table at the top of this page lists as not available refuse the endpoint."]],["Prompt caching","azure_caching",['Azure caches the prompts of the models that support it on its own: "cache reads are billed at a discount on input token pricing for Standard deployment types and up to 100% discount on input tokens for Provisioned deployment types" (prompt caching). The reply\'s prompt_tokens_details.cached_tokens becomes usage.cached_tokens, billed at the cached rate (Cost and usage). The cache fields go out as they are set, and Azure answers them:']],["Cost and usage","azure_cost",["estimated_cost prices an Azure result at the model's row of DEFAULT_PRICING, looked up by the model Azure reports, without its dated suffix, else the model the Chat names; the rows hold OpenAI's list prices, and Azure's own are not in UniLM. It bills the standard rates: input, cache reads at the cached rate, output, and a reported cache write at the input rate. No service-tier, long-context or cache-write multiple applies to an Azure result, though Azure bills GPT-6 and GPT-5.6 models in \"separate pricing categories for short-context and long-context requests\" (models). A model without a row is estimated at 0.0, with one warning per model id, and a result whose usage counts audio tokens at 0.0, with one warning per model and endpoint, since a row holds no audio rates. cumulative_cost adds up a Chat's turns; how a call is priced on every provider is on Cost Tracking."]],["When something fails","azure_failures",["chatrequest! returns what Azure or the network did as a typed result, and does not throw it (Results). A failure holds Azure's HTTP status and, as response, the body that came with it; a call error holds the text of an exception as error and the exception as cause. UniLM sends a request again after a transient status — 408, 429, 500, 502 to 504, 520 to 524 and 529 — or a failed connection, as often as the call's RequestConfig allows, and then returns the last answer (Timeouts & Retries); a streamed request is sent again only while none of its callbacks has run."]],["Models","azure_models",["A Chat names a model id, and the model's deployment serves it (Setup). Azure's catalog lists the GPT-6.1, GPT-6, GPT-5.6, GPT-5.5, GPT-5.4 and GPT-5.2 series among others (models)."]],["The v1 API","azure_compatible",["Azure's v1 API \"removes the need for dated api-version parameters\"; its base URL is the resource with /openai/v1 appended, and a request names the deployment as its model (v1 API). AZUREServiceEndpoint does not speak it. A GenericOpenAIEndpoint whose base URL is the resource's /openai path sends POST …/openai/v1/chat/completions, with the key as Authorization: Bearer:","Azure's REST example of the v1 API sends a key in an api-key header and a Microsoft Entra ID token as Authorization: Bearer; a key sent as Authorization: Bearer, as here, is untested, and so is this route. Through it, a request has the generic endpoint's rules: no default model and no deployment lookup, the Chat's model sent as the deployment's name and the reply priced by the model Azure reports, and the capabilities of a generic endpoint, sent unchecked (OpenAI-compatible services).","Checked against Azure OpenAI's documentation of 25 October 2026 — the dated API version 2024-10-21 and the v1 API — with UniLM's development branch after 0.26.0; nothing on this page was run.","See also: AZUREServiceEndpoint, add_azure_deploy_name!, Chat, chatrequest! and LLMSuccess in the API reference."]]]},{url:"/providers/deepseek/",sections:[["DeepSeek",null,["DeepSeek makes the DeepSeek models and serves them through an OpenAI-compatible API. DeepSeekEndpoint() speaks its Chat Completions API and three of its beta features: FIM completion, chat prefix completion and strict tool mode (Tools). A Chat reaches DeepSeek through chatrequest!, tool_loop! and prefix_complete, and a FIMCompletion through fim_complete. The agentic verbs — respond and the tool_loop that takes an input or a Respond — refuse this endpoint before sending anything, and no verb of a capability the table below lists as not available sends a request through it. Of DeepSeek's API, UniLM does not use the Anthropic-format API or the Search and Fetch APIs either."]],["Setup","deepseek_setup",["Set your API key in the environment Julia starts from:",'DeepSeekEndpoint() reads the variable each time a request is built, so the endpoint can be made before the key is set; a call without it returns a call-error result whose cause is the KeyError naming it. DeepSeekEndpoint(api_key="sk-…") sends the key it is given instead. Neither prints its key: the first shows as DeepSeekEndpoint(#= DEEPSEEK_API_KEY =#), the second with the key cut to its first four characters and …[redacted]. A Chat goes to https://api.deepseek.com/v1/chat/completions, or to the beta base URL when a tool is strict (Tools), with the key as Authorization: Bearer, and with no model it takes the default model named at the top of this page, as FIM does.']],["First call","deepseek_first_call",["A Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:","result.model is the model DeepSeek reports serving, and the model estimated_cost prices the call at. The reply's finish_reason is DeepSeek's — stop, length, content_filter, tool_calls, insufficient_system_resource or aborted (Chat Completions) — with tool_calls standing in for stop on a turn that calls tools. The model thought before it answered: DeepSeek's models think by default (Reasoning). prompt_tokens counts the input, of which cached_tokens came from DeepSeek's cache (Prompt caching), and completion_tokens the output, of which reasoning_tokens is the thinking, which DeepSeek reports in the completion's breakdown. The result types are on Results."]],["Conversations","deepseek_conversations",["A Chat keeps the conversation: each reply is appended to it, and the next chatrequest! sends the whole conversation again.",'A reply\'s thinking stays on its message, where reasoning_text reads it, and goes back to DeepSeek only on a request that carries tools (Tools): without tools, DeepSeek says the thinking "does not need to be passed back; even if passed to the API, it will be ignored" (Thinking Mode). A system message pushed after the conversation started is sent in place, which DeepSeek takes: its Chat Completions API "does support inserting system messages mid-conversation" (Tool Calls). What push! refuses is the same on every provider (Chat Completions).']],["Streaming","deepseek_streaming",["With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call; the callback receives the text as it arrives, then the assembled Message:","The concepts every provider shares are on Streaming."]],["Tools","deepseek_tools",["Each Tool in tools goes out as a function tool, and tool_choice, parallel_tool_calls and a tool's strict go as they are set; a Chat with tools sends parallel_tool_calls: false unless it sets another value. A function's name \"Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 128\" (Chat Completions); UniLM sends a name as given, and mcp_tools(session; service), with service this endpoint, advertises an MCP server's tools under such names, one over 128 characters cut and marked with a hash of its MCP name (MCP). tool_loop! runs the calls and sends their results back until the model answers in text:","A request that carries tools must send back the thinking of every earlier assistant turn: \"the reasoning_content must be fully passed back to the API in all subsequent requests — even for turns where the model did not perform a tool call. If your code does not correctly pass back reasoning_content, the API will return a 400 error\" (Thinking Mode). UniLM does: on such a request, each assistant turn that holds DeepSeek's thinking carries it as reasoning_content, the replies chatrequest!, tool_loop! and prefix_complete appended among them. The loop's replies above hold none: the model answered those turns without thinking. The conversation of Conversations holds thinking on both replies, and sent with tools, both carry it, the third and the fifth message:",'An assistant message you push yourself holds no thinking, so it goes back without any, and DeepSeek\'s Chat Completions API "does not support inserting tool calls mid-conversation" (Tool Calls). DeepSeek refuses two tool_choice values while the model thinks: "required and named tool choices are not supported in thinking mode; the API returns a 400 error. Disable thinking mode first to use them" (Chat Completions), which reasoning_effort="none" does (Reasoning). A tool\'s strict is a beta feature that needs base_url="https://api.deepseek.com/beta" (Tool Calls), so a Chat with a strict tool goes to https://api.deepseek.com/beta/v1/chat/completions, and one without to the usual URL. In strict mode "all function need to set the strict property to true", and "The server will validate the JSON Schema of the Function provided by the user"; UniLM checks neither, and DeepSeek\'s answer is the check. On 26 October 2026 it answered a request there with one strict tool, and one with a strict and a non-strict tool, each with a call of the strict one. The loop every provider shares is on Tool Calling.']],["Structured output","deepseek_structured_output",['UniLM.json_object() sends {"type": "json_object"}, DeepSeek\'s JSON Output, which "guarantees the message the model generates is valid JSON"; DeepSeek adds that "you must also instruct the model to produce JSON yourself via a system or user message" (Chat Completions):',"DeepSeek's response_format takes two types, text and json_object. A JSON Schema format, UniLM.json_schema(…), goes out as json_schema all the same: UniLM does not refuse it, and DeepSeek's answer is the check. The formats every provider shares are on Structured Output."]],["Reasoning","deepseek_reasoning",["DeepSeek's models think before they answer, by default at the effort high (Thinking Mode), and return the thinking beside the answer; UniLM keeps it on the message, where reasoning_text reads it:",'A Chat\'s reasoning_effort goes out as it is set. DeepSeek takes "none", which turns thinking off, and "low", "high" and "max", and maps four more: "minimal" to low, "medium" and "xhigh" to high (Chat Completions), and "ultra" to max (Thinking Mode), which this endpoint alone takes; DeepSeek answered a request with "ultra" on 26 October 2026. With thinking off, the reply carries none and reports no reasoning tokens:','DeepSeek\'s thinking field, its other switch, is not a Chat field: reasoning_effort="none" is the one way to turn thinking off. While the model thinks, temperature has no effect ("setting these parameters will not trigger an error but will also have no effect"), and the effect of top_p depends on the model (Thinking Mode). The thinking is output: it counts in completion_tokens and bills at the output rate, and a request that sets no max_tokens may generate "8K in non-thinking mode, 64K in thinking mode (128K with reasoning_effort set to max)" (Chat Completions). A Chat\'s max_completion_tokens, else its max_tokens, goes out as max_tokens, DeepSeek\'s name for the cap; its reference lists no max_completion_tokens.']],["Attachments","deepseek_media",["A user message's attachments go out as content parts: an image as an image_url part, with its detail when one is set, a sound clip as an input_audio part, and a document as a file part holding its name and a data URL. DeepSeek's reference takes text, image_url and file parts — JPEG, PNG, GIF and WebP images, and a file_data that is \"A base64-encoded data URL of the image\" — and lists no audio part, and its pricing page lists vision for deepseek-flash only (Models & Pricing). UniLM checks none of this before sending: a part DeepSeek does not take is DeepSeek's error. The attachments every provider shares are on Attachments."]],["FIM and prefix completion","deepseek_completions",["Both are DeepSeek beta features, which UniLM sends to the beta base URL, https://api.deepseek.com/beta. fim_complete fills in the middle between a prompt and an optional suffix, on the default model unless the request names another:",'DeepSeek states that "The max tokens of FIM completion is 4K" (FIM Completion), and its pricing page lists FIM in "Non-thinking mode only". A FIMCompletion sends max_tokens 128 unless it sets another value, and has no streaming path (Limits and refusals).',"prefix_complete continues an assistant turn from a prefix you give: the conversation's last message is the assistant's partial reply, which goes out with \"prefix\": true (Chat Prefix Completion):","The result's message is the continuation DeepSeek returns; with history (the default), the conversation keeps the whole assistant turn, the prefix followed by the continuation, and a failure or a cancellation leaves the Chat untouched. The request goes through this endpoint's own encoder and decoder, so the reply's thinking, when it has any, is kept, and goes back on a later request with tools, as a chatrequest! reply's does. DeepSeek also takes a reasoning_content of your own on the prefix message, the start of its thinking; UniLM sends none. prefix_complete reads one whole reply and takes no callback, so a Chat with stream=true is sent unstreamed, without its stream and stream_options; the Chat keeps both for chatrequest!. The concepts both verbs share are on FIM & Prefix Completion."]],["Limits and refusals","deepseek_limits",['DeepSeek\'s models take a context of "1M" tokens and generate at most "384K" (Models & Pricing), a request\'s max_tokens "between 1 and 384K (393216)" (Chat Completions). UniLM checks none of these limits, and no rule of DeepSeek\'s: every field a Chat sets goes out as it is — user, max_tokens, a JSON Schema format, the prompt-cache fields —, max_completion_tokens under DeepSeek\'s name max_tokens (Reasoning), and DeepSeek\'s answer is the check (When something fails). It refuses before anything is sent what the table below lists, and the checks every Chat gets, such as a temperature from 0 to 2 or an n of 1; the verbs of the capabilities the table at the top of this page lists as not available refuse the endpoint too.']],["Prompt caching","deepseek_caching",['DeepSeek caches prompts without being asked: its context caching "is enabled by default for all users", and a later request whose prompt fully matches a prefix DeepSeek has stored reads that part from the cache, on a "best-effort" basis, with no guarantee of a hit (Context Caching). DeepSeek stores a prefix at the end of each request\'s input and of its output, the prefix it detects that several requests share, and prefixes of long ones at fixed intervals, so a request that continues an earlier one can find part of it stored; the second request of the tool loop read part of its prompt from the cache:','DeepSeek reports the cached part as prompt_cache_hit_tokens, which UniLM reads into cached_tokens for chatrequest!, streamed or not, and for prefix_complete; fim_complete reads prompt_tokens_details.cached_tokens, the same count ("Same as prompt_cache_hit_tokens", FIM Completion API). A cache hit bills at the cached rate of the price table (Cost and usage). prompt_cache_options, prompt_cache_key and prompt_cache_retention go out as they are set, though DeepSeek\'s reference lists none of them.']],["Cost and usage","deepseek_cost",['estimated_cost prices a result at its model\'s row of the table below: input that missed the cache at the input rate, cache hits at the cached rate, and completion_tokens, thinking included, at the output rate. cumulative_cost adds up the turns chatrequest!, tool_loop! and prefix_complete sent on a Chat. The rows are DeepSeek\'s peak rates, as checked on 25 October 2026. "Off-peak rates are half of the peak rates", and peak hours are "01:00 - 04:00 and 06:00 - 10:00 UTC, Monday through Friday, excluding Chinese public holidays" (Models & Pricing), so an estimate of a call made off-peak is twice what DeepSeek bills. The legacy names deepseek-v4-flash and deepseek-v4-flash-vision-exp are "billed at the Flash price".',"How a call is priced on every provider is on Cost Tracking."]],["When something fails","deepseek_failures",["chatrequest!, prefix_complete and fim_complete return what DeepSeek or the network did as a typed result, and do not throw it (Results). A failure holds DeepSeek's HTTP status and, as response, the body that came with it; a call error holds the text of an exception as error and the exception as cause. UniLM sends a request again after a transient status — 408, 429, 500, 502 to 504, 520 to 524 and 529 — or a failed connection, as often as the call's RequestConfig allows, and then returns the last answer (Timeouts & Retries); a streamed request is sent again only while none of its callbacks has run. The statuses below are DeepSeek's (Error Codes):"]],["Models","deepseek_models",['DeepSeek serves two models, deepseek-flash and deepseek-v4-pro. deepseek-flash is "now served by DeepSeek-V4.1-Flash-1017", and the legacy names deepseek-v4-flash and deepseek-v4-flash-vision-exp "are still accepted", served by the same model (Your First API Call). Both take a 1M-token context, tools, JSON Output, chat prefix completion and FIM; only deepseek-flash takes images (Models & Pricing). An account may have at most 2500 requests to deepseek-flash and 500 to deepseek-v4-pro in progress at once, and more get HTTP 429 (Rate Limit & Isolation). DeepSeek lists its models at GET https://api.deepseek.com/models (Lists Models).',"Recorded on 25 October 2026 on deepseek-flash, served by DeepSeek-V4.1-Flash-1017, with UniLM's development branch after 0.26.0.","See also: DeepSeekEndpoint, Chat, chatrequest!, fim_complete, prefix_complete and LLMSuccess in the API reference."]]]},{url:"/providers/gemini/",sections:[["Google Gemini",null,["Google makes the Gemini models and serves them through two native APIs, both of which GEMINIServiceEndpoint speaks: generateContent, which a Chat reaches through chatrequest! and tool_loop!, and the Interactions API, which respond and the tool_loop that takes an input or a Respond reach. Image generation and speech go through generateContent too. GEMINIOpenAIServiceEndpoint speaks Google's OpenAI-compatible endpoint, which UniLM uses for embeddings. Of Google's other APIs — the Files, Batch, Live and token-counting APIs, explicit context caching, managed agents such as Deep Research, music and video generation — none is available. The verbs of the capabilities the table below lists as not available refuse both endpoints, but one kind: the lifecycle verbs of stored responses read, cancel and delete stored interactions (Background requests). speak reads aloud through Gemini TTS, and transcribe refuses both endpoints (Audio)."]],["Setup","gemini_setup",["Set your API key in the environment Julia starts from:","UniLM reads the variable each time a request is sent, and reads no other: not GOOGLE_API_KEY, which Google's own SDKs also read. A call without it returns its call-error result — LLMCallError from chatrequest!, ResponseCallError from respond, and so on — whose cause is the KeyError naming the variable. Both endpoints read the same key. A Chat or a Respond reaches Gemini with service=GEMINIServiceEndpoint, the bare type (GEMINIServiceEndpoint() is the type too), and with no model it takes the default model named at the top of this page. generateContent requests go to https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent, a streamed one to :streamGenerateContent?alt=sse, and Interactions requests to https://generativelanguage.googleapis.com/v1beta/interactions, each with the key in x-goog-api-key.",'A Chat sends its max_completion_tokens, else its max_tokens, as maxOutputTokens, and a Chat that sets neither sends none: the model\'s own output limit applies. The limit counts the thinking with the answer, so a low one can end a turn with finish_reason == "length" before any text (Reasoning).']],["Which API for what","gemini_apis",['Google calls the Interactions API "the best way to build with Gemini models and agents" and recommends it "for all new projects", and generateContent legacy, though it "remains fully supported"; "all new models, multimodal capabilities, tools, and agentic features will launch on the Interactions API" (Interactions overview). In UniLM, Chat and its verbs speak generateContent, and respond speaks Interactions: The Interactions API has what differs there. A Chat sent to GEMINIOpenAIServiceEndpoint reaches the same models on the OpenAI-compatible wire, with fewer of the rules on these pages (The OpenAI-compatible endpoint); to code that does not already use a client of that wire, Google recommends that you "call the Gemini API directly" (OpenAI compatibility).']],["First call","gemini_first_call",["A Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:","result.model is the model that served the reply, from the reply's modelVersion: Google routes a deprecated id to its successor (Models), which then names itself here — as both routed ids did on 22 October 2026 — and is the model estimated_cost prices. The reply's finishReason becomes finish_reason (Finish reasons and safety).","prompt_tokens counts all the input — the cache hits (cached_tokens) and the input a tool read (toolUsePromptTokenCount) included — and completion_tokens all the output, thinking included, of which reasoning_tokens is the thinking. service_tier is the tier that billed the call, and prompt_audio_tokens the input that was audio. How these become a price is in Cost and usage; the result types are on Results."]],["Conversations","gemini_conversations",["A Chat keeps the conversation: each reply is appended to it, and the next chatrequest! sends the whole conversation again.","A reply keeps the parts it arrived in, in its message's provider_content, and goes back as those parts, their thought signatures intact:",'Google asks for the signatures back — "passing back thought signatures is mandatory for function calling" — and for each part as it came: "Don\'t merge a Part containing a signature with one that does not" (function calling). A reply that holds none of Gemini\'s parts — written by hand, or answered by another provider — goes as its text and one functionCall part per tool call. A reply that holds no part, no text and no function call — a refusal, say, or a turn whose output went to thinking — is left out. What push! refuses is the same on every provider (Conversations with Chat).',"Every system message becomes part of the request's systemInstruction, in order, joined with a blank line: one pushed later changes the instructions for the whole conversation, not from where it stands. The results of a reply's tool calls go back as one user turn of functionResponse parts (Tools).",'From Gemini 3.6 Flash and 3.5 Flash-Lite on, "If the last non-empty turn in the request is a model turn, the API returns a 400 error" (what\'s new in Gemini 3.6): a request that ends with an assistant message, a response prefill (a Chat with history=false), is refused on those models before it is sent (Limits and refusals). With history=true, chatrequest! throws InvalidConversationError for such a conversation on every model, since the reply could not be appended.']],["Models","gemini_models",["The listing is the endpoint's models capability: list_models with service=GEMINIServiceEndpoint asks Google's Models API (GET /v1beta/models) which models your key can use, fetches every page of the answer, and returns a ModelListSuccess whose models are ProviderModels. Each holds the model's id (its name without models/) and display_name, its input_token_limit and output_token_limit, the capabilities Google reports — supportedGenerationMethods and whether the model thinks (thinking) — and the entry as sent in raw; the listing carries no dates, so created, deprecated and retires are nothing (Model Listings). An error status on any page is a ModelListFailure; a call that brings no listing — no key, no connection, a timeout, a reply that is not the listing — is a ModelListCallError. list_models throws ArgumentError for GEMINIOpenAIServiceEndpoint: UniLM lists no models through it, though Google's compatible endpoint has a listing of its own, GET /v1beta/openai/models (OpenAI compatibility).","A listing bills no tokens and is not recorded, so its output here is quoted from a live run:",'Google routes two deprecated ids to their successors: gemini-3.7-flash "automatically routes API requests to gemini-3.8-flash", and gemini-3.5-flash to gemini-3.6-flash (deprecations), both since the changelog entry of October 8, 2026 (changelog). Such a request meets the rules of the id it names and is priced as the model that served it (First call). A -latest alias "will get hot-swapped with every new release of a specific model variation" (models); the thinking table holds the aliases to the levels of the models that served them when this release was made (Reasoning). Before you use a newly listed model, check that it has a price row, as the last line above does: a Chat or Respond result of a model without one is estimated at 0.0 (Cost and usage). Of the ids that line lists, the aliases bill at the rows of the models that serve them, since a reply names its serving model (on 22 October 2026, gemini-flash-latest answered as gemini-3.8-flash and gemini-pro-latest as gemini-3.1-pro-preview); the image and speech models serve verbs that estimated_cost does not price (Images, speech, embeddings & the compatible endpoint); the others would be estimated at 0.0.']],["Limits and refusals","gemini_limits",["A model's input and output token limits are in its list_models entry (Models); UniLM checks a request against neither, nor the size of its media (Attachments), except one rule of the Interactions API below. Rate limits are on When something fails.","A field a Gemini API has no counterpart for, or one whose counterpart UniLM does not map, is refused, not dropped, since dropping it would send a request other than the one asked for. The one exception is a Chat's parallel_tool_calls, which a Chat with tools sets on its own and which is not sent, whatever its value (Tools). Each request in the table below that the API would answer with an error is refused too. chatrequest!, tool_loop!, respond, tool_loop, generate_image, edit_image, speak and embeddingrequest! throw these ArgumentErrors before anything is sent. A row that names the thinking table holds for the ids of its rows (Reasoning); an id no row names meets only the other rules."]],["When something fails","gemini_failures",['chatrequest! and respond return what the service or the network did as a typed result, and do not throw it (Results). An LLMFailure or a ResponseFailure holds an HTTP status and, as response, the body that came with it; an LLMCallError or a ResponseCallError holds, as error, the text of an exception or of an error the reply reported, and the exception as cause when there is one. UniLM sends a request again after a transient status — 408, 429, 500, 502 to 504, 520 to 524 and 529 — as often as the call\'s RequestConfig allows, and then returns the last answer (Timeouts & Retries); a streamed request is sent again only while none of its callbacks has run. Google sends rate limits as 429: on generateContent a RESOURCE_EXHAUSTED for "one of the API\'s rate limits (RPM, TPM, RPD, spend, etc.)", which UniLM sends again, and on the Interactions API rate_limit_exceeded and too_many_requests, which it sends again, or quota_exceeded, "your daily quota", which it returns at once (generateContent errors, Interactions errors).',"Recorded on 25 October 2026 on gemini-3.8-flash with UniLM's development branch after 0.26.0 and the Gemini API at v1beta.","See also: GEMINIServiceEndpoint, GEMINIOpenAIServiceEndpoint, Chat, chatrequest!, Respond and respond in the API reference."]]]},{url:"/providers/local_servers/",sections:[["vLLM, LM Studio & llama.cpp",null,["vLLM, LM Studio and llama.cpp's llama-server serve open models from your own machine, or a server of yours, through an OpenAI-compatible API, and GenericOpenAIEndpoint speaks it: under the server's base URL, a Chat goes to /v1/chat/completions, an Embeddings request to /v1/embeddings, respond to /v1/responses, fim_complete to /v1/completions and transcribe to /v1/audio/transcriptions. UniLM is an OpenAI-compatible client there: it holds no rule of any server, sends every field a request sets as it is, under the name the request gives it — LM Studio's chat reference lists the cap as max_tokens (chat completions), while vLLM takes max_completion_tokens and deprecates max_tokens \"in favor of the maxcompletiontokens field\" (protocol) —, and refuses what Limits and refusals lists. A verb that needs a capability the table below lists as not available refuses this endpoint, and so does ask; respond, which takes responses or agentic, and transcribe, which takes transcription or audio, are sent. Local decision models have an entry of their own: Local decision models. UniLM does not use the servers' own APIs either, such as llama-server's /completion and /infill or LM Studio's REST API. The examples on this page ran on llama-server."]],["Setup","local_servers_setup",["Start the server with the model it serves:",'vLLM\'s examples reach its server at http://localhost:8000/v1 (OpenAI-compatible server), LM Studio\'s assume "the server port is 1234" (OpenAI compatibility), and llama-server "by default listens on 127.0.0.1:8080" (server). A GenericOpenAIEndpoint takes the server\'s base URL and a key:','The base URL is the server\'s root, without /v1: UniLM appends /v1/chat/completions and the other paths, and drops a trailing /. An empty key sends no Authorization header, which suits the servers as they start: "By default, LM Studio does not require authentication for API requests" (authentication), and vLLM and llama-server check a key only when started with one, --api-key (vLLM also VLLM_API_KEY). A key given, GenericOpenAIEndpoint(url, "sk-…"), goes as Authorization: Bearer; with GenericOpenAIEndpoint(url, "", "MY_SERVER_KEY") UniLM reads the key from that environment variable each time a request is built, and a request without it fails, naming the variable.','The endpoint has no default model: a Chat, Respond, Embeddings or FIM request names the model the server serves, or throws ArgumentError before anything is sent. vLLM serves a model under the name vllm serve was given, LM Studio under the identifier of a loaded model, and llama-server under its --alias, else the path given with -m: "By default, model id field is the path to model file" (server). list_models refuses this endpoint, so read the server\'s own /v1/models.']],["First call","local_servers_first_call",["A Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:","result.model is the model the server names in its reply, and the reply's finish_reason and usage are read as the OpenAI-compatible API defines them. A model has no price row unless you add one, so estimated_cost gives 0.0 and logs one warning per model id — the first chatrequest! logs it, as it adds each call's cost to cumulative_cost. Pass estimated_cost a pricing table holding the model's row, or add the row to DEFAULT_PRICING, to price your own server's time (Cost Tracking); a result whose usage counts audio tokens is estimated at 0.0 with a warning even then, since a row holds no audio rates.",'A reasoning model\'s reasoning comes back beside the answer — llama-server returns it "via the reasoning_content field" (server), vLLM in a reasoning field, which "used to be called reasoning_content" (reasoning outputs) — and UniLM keeps either on the message, from the reply or from a stream\'s deltas of that name, where reasoning_text reads it; a stream cut before its finish reason keeps none. The reasoning does not go back with the next turn. The result types are on Results.']],["Streaming","local_servers_streaming",['With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call; the callback receives the text as it arrives, then the assembled Message. A Chat on this endpoint sends no stream_options unless it sets them, so a streamed turn reports no usage, and adds 0.0 to cumulative_cost, unless the Chat sets stream_options=Dict("include_usage" => true), which llama-server honoured below:',"The stream is the OpenAI-compatible one: the turn is final at data: [DONE], or, without one, when the HTTP body ends after the finish reason; on_tool_call(tc) runs once per call whose arguments decode, as the next call begins or at the end of the stream; and setting close[] = true stops it (Stopping a Stream Early). The concepts every provider shares are on Streaming."]],["Tools","local_servers_tools",['Each Tool in tools goes out as a function tool, and tool_choice, parallel_tool_calls and a tool\'s strict go as they are set; a Chat with tools sends parallel_tool_calls: false unless it sets another value. What the server does with them is its own: vLLM lets the model choose a call only when started with --enable-auto-tool-choice and a --tool-call-parser (tool calling), llama-server takes tools through its Jinja chat templates, which its --jinja flag turns on, "default: enabled" (server), and on it "Multiple/parallel tool calling is supported on some models but disabled by default" (function calling), and LM Studio warns that "Smaller models and models that were not trained for tool use may output improperly formatted tool calls" (tool use). tool_loop! runs the calls and sends their results back until the model answers in text:',"The loop every provider shares is on Tool Calling."]],["Structured output","local_servers_structured_output",['A JSON Schema response_format goes out as the OpenAI-compatible API defines it, {"type": "json_schema", "json_schema": {"name": …, "schema": …}}, and UniLM.json_object() as {"type": "json_object"}; the server constrains the reply. vLLM takes a json_schema response_format (structured outputs), LM Studio a JSON schema on /v1/chat/completions (structured output), and llama-server "schema-constrained JSON" (server):',"The formats every provider shares are on Structured Output."]],["Embeddings, respond, FIM and transcription","local_servers_other_apis",["These calls reach the server's other OpenAI-compatible routes; this page did not run them, so their code stands without output:","Embeddings",'Embeddings need an embedding model: vLLM\'s embeddings route is "Only applicable to embedding models" (OpenAI-compatible server), and llama-server\'s "requires that the model uses a pooling different than type none". An item holding an image or a sound clip is refused before the request: UniLM sends these routes text only, though vLLM takes images too, "by defining a custom chat template for the server and passing a list of messages in the request" (embeddings), a request UniLM does not write. EmbeddingGemma\'s task prompts hold on any server (task prompts). The concepts every provider shares are on Embeddings.',"respond",'respond sends a Respond\'s fields as they are, a seed among them: vLLM\'s Responses API "forwards vLLM sampling parameters such as top_k, min_p, repetition_penalty, seed, stop, and ignore_eos to the engine" (OpenAI-compatible server). vLLM serves stored responses (/v1/responses/{response_id}), LM Studio takes a previous_response_id, and llama-server\'s route "works by converting Responses request into Chat Completions request".',"FIM completion",'FIM sends the suffix to /v1/completions, where vLLM\'s Completions API notes "suffix parameter is not supported", so a vLLM server cannot fill in the middle. The concepts every provider shares are on FIM & Prefix Completion.',"Transcription",'transcribe sends the file and the fields a request sets to /v1/audio/transcriptions, where vLLM\'s Transcriptions API is "Only applicable to Automatic Speech Recognition (ASR) models" (OpenAI-compatible server) and takes model as "required" (speech to text): the endpoint has no default model, so a call names the server\'s. speak and translate refuse the endpoint.']],["Limits and refusals","local_servers_limits",["UniLM checks no limit of a server: a request longer than the model's context window, or one the model cannot serve, is the server's error (When something fails). It refuses before anything is sent what the table below lists, and the checks every Chat and Embeddings request gets, such as a temperature from 0 to 2, an n of 1 or a positive dimensions; the verbs of the capabilities the table at the top of this page lists as not available refuse the endpoint too."]],["When something fails","local_servers_failures",["chatrequest!, respond, embeddingrequest! and fim_complete return what the server or the network did as a typed result, and do not throw it (Results). A failure holds the server's HTTP status and, as response, the body that came with it; a call error holds the text of an exception as error and the exception as cause. UniLM sends a request again after a transient status — 408, 429, 500, 502 to 504, 520 to 524 and 529 — or a failed connection, as often as the call's RequestConfig allows, and then returns the last answer (Timeouts & Retries); a streamed request is sent again only while none of its callbacks has run.","Recorded on 25 October 2026 on d1-3b, a 2.9 GB GGUF model, with UniLM's development branch after 0.26.0 and llama.cpp's llama-server build 9730 (e475fa2b5), on an Apple M4 Max with 64 GB.","See also: GenericOpenAIEndpoint, Chat, chatrequest! and LLMSuccess in the API reference."]]]},{url:"/providers/ollama/",sections:[["Ollama",null,["Ollama runs open models on your own machine, and OllamaEndpoint speaks its native API: a Chat goes to /api/chat and an Embeddings request to /api/embed, the routes that take the context window, how long a model stays loaded, thinking and truncation. respond, compact_response, fim_complete and transcribe reach Ollama's OpenAI-compatible routes instead, which carry none of the endpoint's options. No key is sent to a server of your own, and a local model costs nothing unless you give it a price. A verb that needs a capability the table below lists as not available refuses this endpoint, speak among them, though Ollama serves speech at /v1/audio/speech; respond, which takes responses or agentic, and transcribe, which takes transcription or audio, reach Ollama. Of Ollama's own API, UniLM does not wrap /api/generate, /api/version, creating, copying or pushing a model, or web search and web fetch. The decision models ask reaches through the same endpoint have an entry of their own: Local decision models."]],["Setup","ollama_setup",["Install Ollama and start it, the desktop app or ollama serve, then pull the models the examples run on:","A model's name is model:tag, and a name without a tag means its latest tag (model names): embeddinggemma-2 alone pulls a different 740m build, which was not measured here, so the examples name the tags they ran on. To run a local model with Ollama, ollama pull gemma4:e4b, then pass service=OllamaEndpoint(), model=\"gemma4:e4b\"; Ollama has no default model. A Chat, Respond, Embeddings, FIM or transcription request that names none throws ArgumentError before anything is sent, and the Chat's message says what to name:","OllamaEndpoint() reads OLLAMA_HOST (optional; default http://127.0.0.1:11434) each time it is built. A host without a scheme is reached over http on port 11434 (gpu-box becomes http://gpu-box:11434), an http:// or https:// address without a port on port 80 or 443, the bind-all addresses 0.0.0.0 and :: on the loopback address, and ollama.com, given without a scheme, over https on port 443; an IPv6 address may be bare or bracketed, and a path is kept. A value UniLM cannot read this way, another scheme or a port outside 1–65535, throws ArgumentError when the endpoint is built. The endpoint's other arguments are on Options.",'Ollama\'s local API "does not require authentication", and UniLM sends a server of your own no key. Direct cloud inference at https://ollama.com/api and https://ollama.com/v1 "requires an API key", used "in the Authorization: Bearer header" (authentication), and Ollama lists the cloud\'s models without one, curl https://ollama.com/api/tags (cloud). An endpoint whose server is https://ollama.com, as OLLAMA_HOST=ollama.com makes it, sends the OLLAMA_API_KEY environment variable that way whenever it is set, read each time a request is built, and to no other host. With the variable unset or blank, an inference request is not sent: the call returns a call error whose cause is an ArgumentError naming OLLAMA_API_KEY; list_models, model_info, running_models, pull_model and delete_model go without it. No request was sent to the cloud for this page (its requests bill). A cloud model runs through the local server once you sign in with ollama signin, under a cloud tag such as gemma4:cloud; Cost and usage says how UniLM prices it.']],["First call","ollama_first",["A Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:",'reasoning_effort="none" turns Gemma 4\'s thinking off for a short answer (Reasoning). The reply\'s done_reason becomes finish_reason: "stop", or "length" for a reply that reached its max_tokens (sent as num_predict); a turn that carries tool calls reads "tool_calls" unless it was cut at "length". result.model is the "Model name used to generate this message" the reply gives (chat), the model estimated_cost prices; a cloud model whose reply drops its tag keeps the name requested (Cost and usage). Of the usage, prompt_tokens is Ollama\'s prompt_eval_count, "How many input tokens were in the prompt", cached_tokens its prompt_eval_cached_count, "How many prompt tokens were read from the cache", and completion_tokens its eval_count, the output tokens (usage), thinking included (Reasoning shows a count). The result types are on Results.','logprobs=true asks for the "log probabilities of the output tokens", and top_logprobs for the "Number of most likely tokens to return at each token position" (chat): the reply\'s entries, "Log probability information for a generated token" each — its token, logprob, bytes and top_logprobs —, are result.logprobs["content"], a stream\'s lines joined in order.',"A local model's results cost 0.0, with no warning, unless you gave the model a price row (Cost and usage).","The first request to a model also loads it into memory: about 1.7 s for Gemma 4 E4B on an Apple M4 Max with 64 GB (Ollama 0.40.6), after which a short answer took about 0.1 s. load_model loads a model ahead of time (Models)."]],["Conversations","ollama_conversations",["A Chat keeps the conversation: each reply is appended to it, and the next chatrequest! sends the whole conversation again.","The messages go out in the order they were pushed, each with its role, so a system message pushed later stays where it stands. An assistant turn goes back with its text, its thinking as thinking (Reasoning) and its tool calls with their ids; a tool result goes back with tool_name, the name of the function it answers, as Ollama's tool calling page sends results, and with its tool_call_id (Tools). A message with a name, and a tool result that answers no tool call of an earlier assistant turn, are refused before anything is sent (Limits and refusals); what push! refuses is the same on every provider (Conversations with Chat)."]],["Streaming","ollama_streaming",["With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call. The callback receives the text as it arrives, a String at a time, then the assembled Message:",'Ollama streams "newline-delimited JSON", one object per line (streaming), and sends the usage "as part of the final chunk, where done is true" (usage), so a streamed turn has usage with no stream_options, a field this endpoint refuses (Limits and refusals). Setting close[] = true stops the stream (Stopping a Stream Early).',"The concepts every provider shares are on Streaming."]],["Tools","ollama_tools",["Each Tool in tools goes out as a function tool with its name, description and parameters. tool_loop! runs the calls and sends their results back until the model answers in text:","Ollama has no tool_choice: the model decides whether to call a tool, so a tool_choice other than \"auto\" is refused, and it may call several tools in one turn — Ollama's tool calling page shows parallel calls — whatever parallel_tool_calls says: UniLM does not send it. Ollama's tool definition has name, description and parameters and no strict flag (API reference), so a tool marked strict=true is refused too (Limits and refusals).","Ollama's replies carry an id for each call, call_mb4i6gbs above, though its API reference lists none; UniLM sends the id back with the call and with its result, beside tool_name. A call that arrives without an id gets unilm_call_<k>, which is never sent: its result is matched by the function's name alone. The turn that called the tool also thought first, and that thinking went back with it (Reasoning). A streamed turn's tool calls are on Streaming, and the loop every provider shares is on Tool Calling."]],["Structured output","ollama_json",['A response_format becomes Ollama\'s format: a JSON Schema format sends its schema, and UniLM.json_object() sends {"type": "object"}, the schema of any JSON object. Only the schema goes out; the format\'s name, description and strict have no counterpart in format (structured outputs: "Provide a JSON schema to the format field").','With a response_format, the request turns thinking off (think: false), and a response_format together with a thinking effort (any effort but "none") is refused before the request is sent (Limits and refusals). UniLM\'s reason, which its message gives: Ollama applies a format only once the model\'s thinking ends, so a reply that skips thinking is not constrained at all — in the measurements below, every reply that was not valid JSON came from a run with thinking on in which the model did not think. A format limits which tokens the model may emit, not how many, so a reply can run on without closing the object. Give a structured-output request a max_tokens (sent as num_predict): a reply that reaches it stops with finish_reason "length" and is not complete JSON, instead of generating until the request times out. Ollama\'s page says its cloud "currently does not support structured outputs", and UniLM sends a cloud model\'s format all the same. The formats every provider shares are on Structured Output.',"The extraction request above, sent to /api/chat 10 times per setting on Ollama 0.34.4: gemma4:e4b returned valid JSON in 0 of 10 runs with thinking at its default (it answered plain text), 1 of 10 with thinking on, and 10 of 10 with it off; gemma4:e2b in 10, 8 and 10 of 10. Every failure was a run in which the model did not think. Without max_tokens, the same request on Ollama 0.40.6 twice generated until the 600 s default request timeout (more than 60,000 tokens in one run); the retry answered in under a second."]],["Reasoning","ollama_thinking",['reasoning_effort becomes Ollama\'s think: "none" sends false, and every other effort goes as it is, "max" among them, a level of think in Ollama\'s API reference; a request without one sends none, so the model\'s default applies, and Gemma 4 thinks by default. Ollama\'s thinking levels are the model\'s own: /api/show lists the values a model takes and its default, and a model whose values are true and false thinks or does not; "If the model resolves named levels from /api/show metadata, Ollama applies supported names exactly. Unsupported names use the model default." (thinking). model_info reads them as thinking_levels and thinking_default: [false, true] and true for Gemma 4 E4B, which names no levels. No page says what such a model does with a named level on /api/chat; on Ollama 0.40.11, think "low", "medium" and "high" gave gemma4:e4b the same thinking and the same answer to the bat-and-ball prompt below at temperature 0 (observed on 25 October 2026), and a think: "max" request to gemma4:e4b was answered with HTTP 200, an answer without thinking, in the one request sent that day. To a model without thinking metadata, /api/chat answers a name other than "low", "medium", "high" and "max", such as "minimal" or "xhigh", with HTTP 400 invalid think value (Ollama 0.40.11: qwen2.5-coder:1.5b-base, whose /api/show reports no thinking, on 25 October 2026). respond\'s /v1/responses reads "minimal" as "low" and "xhigh" as "max" for such a model; there, "Boolean-only models that support enabling thinking map recognized compatibility efforts to true", so a model whose values are true and false, Gemma 4 E4B among them, takes any effort but "none" as true, and GPT-OSS reads "minimal" as "low" and "xhigh" as "high" (OpenAI compatibility). The thinking comes back beside the answer, and reasoning_text reads it:','reasoning_text gives the turn\'s thinking, or nothing for a turn without one, and the output count holds the thinking as well as the few characters of the answer. The thinking stays on its turn in the Chat and goes back to Ollama with the next request, which renders the conversation for the model itself (Gemma 4\'s page: "Ollama already handles the complexities of the chat template for you"). Gemma 4\'s guidance asks that "Thoughts from previous model turns must not be added before the next user turn begins" (Gemma 4); in a tool round trip measured with gemma4:e2b on Ollama 0.34.4, the turn succeeded 10 of 10 times with the thinking sent back and 8 of 10 without it. Thinking spends the reply\'s token budget first: a small max_tokens can end a reply at finish reason "length" with no answer text.',"With thinking on, Gemma 4 E4B still answers easy prompts without thinking: reasoning_text is then nothing. On the bat-and-ball prompt above (Ollama 0.34.4) it thought in 2 to 5 of 6 runs at the default temperature, and in every run at temperature=0.0."]],["Attachments","ollama_media",["A user message carries images and sound clips as attachments, read from a file or from bytes and recognised by their content: an ImageAttachment (PNG, JPEG, GIF or WebP) or an AudioAttachment (WAV or MP3). Each goes out as a base64 entry of the message's images, the form Ollama's API takes: \"the REST API expects base64-encoded image data\" (vision), so a model never fetches an image itself.","",'The recording says "The secret word is banana.":',"Ollama's Gemma 4 page lists text, image and audio for E2B and E4B, and text and image for the 26B and 31B models. model_info lists what an installed model takes, :vision and :audio among its capabilities (Models); UniLM checks neither, and a model without the capability answers with an HTTP 400 once it has been loaded: on Ollama 0.40.11, qwen2.5-coder:1.5b-base loaded and then answered an image with \"Multimodal data provided, but model does not support multimodal requests.\" (When something fails). A DocumentAttachment and an image's detail level are refused before the request: the images entry has room for neither (Limits and refusals). The attachment types are on Attachments."]],["Audio","ollama_transcription",["Of UniLM's audio verbs, only transcribe reaches Ollama: a model that hears audio transcribes it, while speak and translate refuse the endpoint before sending anything. A transcription is not recorded by with_recorded_answers, so its output here is quoted from a live run:","The request goes to /v1/audio/transcriptions, a route Ollama's OpenAI compatibility page does not list; Ollama 0.40.11 answered it, as above. There is no default model: name one that hears. Ollama transcribes at temperature 0 and reads one language and a prompt (by Ollama 0.40.6's source). UniLM asks for the transcript as JSON, the only form in which Ollama reports a failure that arrives after its reply has begun, as an AudioCallError (by the same source; untested), and reads the reply as JSON, though Ollama labels it application/x-ndjson. response_format = \"text\" is refused before the request, since such a failure would read as an empty transcript: leave response_format unset and read the text with transcript_text. temperature, languages, keywords and any other format are refused too (Limits and refusals). A transcription is sent again after a transient status, as a chat request is, the whole file each time."]],["respond and FIM","ollama_respond",['respond reaches Ollama\'s /v1/responses, which serves "Only the non-stateful flavor" of the Responses API: "there is no previous_response_id or conversation support" (OpenAI compatibility). Each call is answered and forgotten:','Of a Respond, UniLM sends model, input, instructions, function tools, tool_choice "auto", temperature, top_p, max_output_tokens, stream, a text format and the effort of reasoning, and refuses every other field before the request rather than have Ollama drop it: the fields that need a stored response (store, previous_response_id, background, conversation), the other fields its compatibility page does not list as supported, and seed, which a Chat sends to Ollama instead (Limits and refusals). Ollama\'s page lists no text field either; UniLM sends a json_schema text format with its schema, which Ollama 0.40.11 followed in the one such request sent on 25 October 2026, and, as for a Chat, such a format turns thinking off (reasoning.effort "none") and refuses a thinking effort. Cap a request with max_output_tokens: Ollama reports a reply cut at that limit as "completed", with no incomplete_details (Ollama 0.40.8), so a reply whose output tokens (token_usage) reach the limit is the cut one. A Respond tool loop, get_response, cancel_response, delete_response and list_input_items are refused before any request, since Ollama stores no response: run a tool loop on a Chat with tool_loop!. compact_response reaches /v1/responses/compact, a route the compatibility page does not list, which Ollama 0.40.11 answered with a compaction item (observed on 25 October 2026), and, like a Chat, needs a model: a call that names none throws before any request.',"fim_complete reaches /v1/completions with a prompt and the suffix the reply fills up to, on a model that fills in the middle, one whose capabilities include :insert, such as qwen2.5-coder:1.5b-base (Gemma 4 E4B's do not):","The completions route takes suffix among its fields (OpenAI compatibility), and a FIM request has no default model. These routes carry none of the endpoint's keep_alive, options or runner (Options). A local model's respond and FIM results cost 0.0 unless you price the model, as its chats do (Cost and usage); the verbs every provider shares are on Agentic respond and FIM & Prefix Completion."]],["Cost and usage","ollama_cost",["A local model bills no one, so estimated_cost gives 0.0 for a chat, embeddings, respond or FIM result, without the missing-price warning other unlisted models get, and cumulative_cost adds 0.0 for each turn; pass model= to price one as if it had run elsewhere, at that model's row. To price a local model yourself, give its exact name a row: one in pricing= prices estimated_cost, and one you add to DEFAULT_PRICING prices both. The rows UniLM ships price hosted models only, so a model copied under a hosted model's name with ollama cp, as Ollama's OpenAI compatibility page suggests for tools that expect such names, still costs 0.0, also with a copy of those rows such as merge(DEFAULT_PRICING, …). A cloud model reached through the same server — one whose tag is cloud or ends in -cloud, such as gemma4:cloud or gpt-oss:120b-cloud — runs in Ollama's cloud, and UniLM prices each of its results by the requested name, like any other model, never as a free local call; a name missing from the price table gets the missing-price warning. So does every model a request to Ollama's cloud itself names — an endpoint whose server is https://ollama.com (Setup) — whose names carry no cloud tag, \"such as gemma4:31b\" (cloud). A cloud reply may name the model without its tag, gpt-oss:120b (by Ollama 0.40.6's source, which sends the cloud the name without it; untested, as no cloud call was made): a chat, System One, respond or FIM result keeps the requested name — a System One, respond or FIM result keeps the server's in its raw — while an embeddings result is priced by the model its request names. Through your own server, UniLM recognises a cloud model by its tag alone, so one copied under a name without it (ollama cp) is priced as local: 0.0, with no warning, unless you gave it a row. How a call is priced on every provider is on Cost Tracking."]],["Limits and refusals","ollama_limits",["A request meets the model's context window, which the endpoint's num_ctx sets when the model loads: by default a chat prompt that does not fit is an HTTP 400 on the :llamacpp runner, not a silently shortened prompt, while a model on the :mlx runner answers it (Ollama 0.40.6; Runners). UniLM checks no size itself: not the window, not the length of a sound clip, not an image's size. An embeddings input longer than the model's window is the server's HTTP 400 too (Long inputs).","A Chat field UniLM maps to no part of the /api/chat request is refused, not dropped, since dropping it would send a request other than the one asked for, and so is each request below that Ollama would answer with an error or run other than asked. The verbs throw these ArgumentErrors before anything is sent. Building the endpoint refuses an argument that breaks its rule (Options).","The examples of First call, Tools, Structured output, Reasoning and Attachments were recorded on 21 October 2026 on gemma4:e4b with UniLM's development branch after 0.24.0 and Ollama 0.40.6; those of Conversations, Streaming, and respond and FIM on 25 October 2026 on gemma4:e4b and qwen2.5-coder:1.5b-base with UniLM's development branch after 0.26.0 and Ollama 0.40.11; all on an Apple M4 Max with 64 GB.","See also: OllamaEndpoint, OllamaOptions, Chat, chatrequest! and LLMSuccess in the API reference, and the Ollama API reference page; the Local decision models entry in the Decisions chapter."]]]},{url:"/providers/openai/",sections:[["OpenAI",null,["OpenAI makes the GPT models. OPENAIServiceEndpoint speaks two of OpenAI's APIs for them: Chat Completions, where every request is a Chat sent by chatrequest! or tool_loop!, and Responses, where every request is a Respond sent by respond or tool_loop. The same endpoint reaches OpenAI's embeddings, image, audio and platform APIs, and OpenAI's Decisions API, which ask speaks, has an entry of its own: OpenAI Decisions API. No verb of a capability the table below lists as not available sends a request through this endpoint. Of the two APIs, UniLM sends no Responses prompt template and no access_programs, does not use the Responses API's WebSocket mode, and does not read back the completions a Chat Completions request stores with store=true."]],["Setup","openai_setup",["Set your API key in the environment Julia starts from:","UniLM reads the variable each time a request is sent: a chatrequest! or respond without it returns a call-error result, an LLMCallError or a ResponseCallError, whose cause is the KeyError naming it. OPENAIServiceEndpoint is the default service of Chat, Respond and Embeddings; the examples on these pages pass it as service=OPENAIServiceEndpoint, the bare type, or leave it to the default. Requests go to https://api.openai.com — a Chat to /v1/chat/completions, a Respond to /v1/responses — with the key in an Authorization: Bearer header.","A Chat or Respond without model takes the default model named at the top of this page. A request that sets no reasoning effort runs at the model's default effort, and UniLM checks the rules of the model's row in the rule table at that effort, the row's Default effort cell. Where the row takes sampling controls or Chat Completions tools only at another effort, as the default model's row does, a request that sets them must name that effort: the check runs when the request is encoded, before anything is sent, and throws ArgumentError (Limits and refusals), while the Chat constructor accepts the request:","With the effort the message names, the same request is sent as it stands:","UniLM.encode_request returns the body chatrequest! sends, or throws the refusal, with no key and no request. Another model is a model away; which models UniLM holds rules and prices for is on Models."]],["Chat Completions or Responses","openai_apis",["OpenAI serves the default model on both APIs, Chat Completions and Responses (GPT-6 Sol, Endpoints), and a program may use both through the same endpoint. They differ in where the conversation lives and in what a request may carry:",'For tool calling, OpenAI\'s guide to its GPT-6 models points to the Responses API: "Use Responses for reasoning with tools" (GPT-6 guide). On Chat Completions, a model of the rule table takes function tools only at the efforts its Chat Completions tools column lists, none where the cell is "—", and the reasoning efforts the two APIs take differ per model: UniLM refuses a request that breaks either rule, and the refusal\'s message names the fix (Limits and refusals). The hosted tools are tools of the Responses API: Chat Completions "supports only specialized search models for web search" (web search). Audio input and spoken replies are Chat Completions features, which OpenAI\'s audio guide directs to "Chat Completions with an audio-capable model" (Audio in Chat Completions).']],["First call","openai_first_call",["On Chat Completions, a Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:",'result.model is the model that served the reply, as OpenAI reports it, and the model estimated_cost prices the call at. finish_reason is OpenAI\'s: "stop", "length" "if the maximum number of tokens specified in the request was reached", "tool_calls", or "content_filter" (Create chat completion); a turn that carries tool calls reads "tool_calls" when OpenAI finished it with "stop".',"prompt_tokens counts all the input, the cache reads (cached_tokens) and writes (cache_write_tokens) among it, and completion_tokens all the output, the reasoning (reasoning_tokens) included; service_tier is the tier OpenAI reports processing the call at. How these become a price is on Cost and usage, and the result types on Results.","On Responses, respond takes the input and the request's fields as keywords, and output_text reads the answer:","A Responses result holds the response as OpenAI sent it: result.response is a ResponseObject with its id, status, model, output items, usage and the whole body as raw, and token_usage reads its usage into the same TokenUsage a Chat result carries. What else a Respond takes is on Responses & hosted tools."]],["Conversations","openai_conversations",["A Chat keeps the conversation: each reply is appended to it, and the next chatrequest! sends the whole conversation again.","The messages go out in the order they were pushed, system messages where they stand, and a reply goes back as its text and tool calls; a spoken reply also goes back by its audio id (Audio replies). A Message needs a text, tool calls, a refusal, attachments or an audio reply, and its constructor throws ArgumentError for one that has none; what push! refuses is the same on every provider (Conversations with Chat).",'A response is stored by OpenAI unless the request sets store=false: OpenAI keeps it "for at least 30 days" (Create a model response). The next request names it with previous_response_id and sends only the new input:','Each request names its instructions again, since "the instructions from a previous response will not be carried over to the next response" (Create a model response, instructions), and "all previous input tokens for responses in the chain are billed as input tokens" (conversation state). A Conversations API object holds a conversation instead: respond(input; conversation=id) adds the response\'s input and output to it, and a Respond refuses conversation together with previous_response_id (Limits and refusals); the conversation itself is made by create_conversation (Platform APIs). A request that replays the conversation\'s items itself, rather than chaining, sends them as its input (Input).']],["Streaming","openai_streaming",["With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call. The callback receives the text as it arrives, a String at a time, then the assembled Message:",'A Chat whose stream_options is unset asks OpenAI for the stream\'s usage, as stream_options = {"include_usage": true}, so a streamed turn has usage and adds its cost to cumulative_cost as an unstreamed one does. OpenAI then streams "an additional chunk" before data: [DONE], whose usage covers the whole request and whose choices is empty, and "If the stream is interrupted or cancelled, you may not receive the final usage chunk" (Create chat completion, stream_options and the chunk\'s usage):',"respond streams with a do block, whose function receives the text, then the ResponseObject of a response that completed or ended incomplete; the response's usage comes with it:","A Responses stream ends at its terminal event: response.completed and response.incomplete give a ResponseSuccess, response.failed a ResponseFailure. A stop before that event ends the call with a ResponseCallError whose cause is the UniLMCancelled. The concepts every provider shares are on Streaming."]],["Embeddings","openai_embeddings",["An Embeddings request on OPENAIServiceEndpoint goes to /v1/embeddings, on OpenAI's text-embedding-3-small unless it names a model. It holds one text or several, and embeddingrequest! fills its pre-allocated vectors in place:",'By default "the length of the embedding vector is 1536 for text-embedding-3-small or 3072 for text-embedding-3-large" (embeddings guide). dimensions is sent as it is: the text-embedding-3 models return a shorter vector when a request asks for one (embeddings guide), and UniLM checks only that it is positive. The buffers start at dimensions, else 1536, numbers per text, and take the length the reply has. An embedding bills its input tokens alone, at the rate of the model\'s row in the price table. An image or a sound clip, a title, and a task other than :none are refused before the request: the OpenAI Embeddings API takes text, and UniLM writes a task prompt only for the models it knows to read one (Limits and refusals). The concepts every provider shares are on Embeddings.']],["When something fails","openai_failures",["chatrequest!, respond and embeddingrequest! return what the service or the network did as a typed result, and do not throw it (Results). A failure is an LLMFailure, ResponseFailure or EmbeddingFailure, holding OpenAI's HTTP status and, as response, the body that came with it; or an LLMCallError, ResponseCallError or EmbeddingCallError, holding the text of the exception as error and the exception as cause. A failure of a Chat or a Respond keeps the reply's x-request-id header, when one came, as request_id.","UniLM sends a request again after a transient status — 408, 429, 500, 502 to 504, 520 to 524 and 529 — as often as the call's RequestConfig allows, waiting at least as long as the reply asks, by its retry-after-ms header, else Retry-After, and then returns the last answer (Timeouts & Retries). A 429 whose error.code is credit_balance_exhausted, organization_spend_limit_exceeded, project_spend_limit_exceeded or organization_usage_limit_exceeded, or whose error.type or error.code is insufficient_quota, is returned at once: \"Retrying billing, spend, or quota errors won't restore API access\" (error codes). A streamed request is sent again only while none of its callbacks has run. The lifecycle calls of stored responses — get_response, delete_response, list_input_items, cancel_response, compact_response and count_input_tokens — make one attempt, which max_attempts does not change.",'ResponseFailure is reserved for a response that failed; every other status — incomplete, cancelled, queued, in_progress — is a ResponseSuccess, read with response_status. A response cut at max_output_tokens before any visible output can "incur costs for input and reasoning tokens without receiving a visible response" (reasoning).',"Recorded on 25 October 2026 on gpt-6-sol and text-embedding-3-small with UniLM's development branch after 0.26.0.","See also: OPENAIServiceEndpoint, Chat, chatrequest!, Respond, respond and LLMSuccess in the API reference; the OpenAI Decisions API in the Decisions chapter."]]]},{url:"/providers/openai_compatible/",sections:[["Mistral & OpenAI-compatible services",null,["Mistral makes the Mistral models — Mistral Large, Codestral, Mistral Embed, the Voxtral audio models and others — and serves them through its own API. MistralEndpoint() is a GenericOpenAIEndpoint on Mistral's host, https://api.mistral.ai: UniLM speaks Mistral's chat, embeddings, FIM and transcription routes as OpenAI-compatible ones, and a hosted service of another vendor with an OpenAI-compatible API is reached the same way, with GenericOpenAIEndpoint(base_url, key). The rules on this page are that endpoint's; the facts marked as Mistral's are Mistral's alone. UniLM holds no rule of Mistral's or of any other service: it sends every field a request sets as it is, under its own name but for those First call lists, and sends the requests of the capabilities the table below lists without knowing whether the service serves them. A verb that needs a capability the table lists as not available refuses the endpoint, and so does ask; respond, which takes responses or agentic, and transcribe, which takes transcription or audio, are sent. Of Mistral's API, UniLM does not use the Agents and Conversations APIs, OCR or the classifiers either. Servers of your own have their entry: vLLM, LM Studio & llama.cpp. No Mistral key was at hand for this page: its examples are not run, and their code stands without output."]],["Setup","openai_compatible_setup",["Set your Mistral API key in the environment Julia starts from:",'MistralEndpoint() is GenericOpenAIEndpoint("https://api.mistral.ai", "", "MISTRAL_API_KEY"), and prints as that call. It reads the variable each time a request is built, so the endpoint can be made before the key is set, and a call without it returns a call-error result whose cause is the KeyError naming it; MistralEndpoint(api_key="…") sends the key it is given instead. The key goes as Authorization: Bearer, the header Mistral documents (chat completions). MistralEndpoint is a constructor with no type of its own: an error names GenericOpenAIEndpoint, and code cannot dispatch on Mistral.',"Another service's endpoint takes the root of its API and a key, given or read from a variable:",'Under the root, without /v1, UniLM sends a Chat to /v1/chat/completions, an Embeddings request to /v1/embeddings, transcribe to /v1/audio/transcriptions and respond to /v1/responses, and drops a trailing /; fim_complete goes to Mistral\'s /v1/fim/completions on Mistral\'s host, and to /v1/completions on any other. A service whose routes are not those cannot be reached through this endpoint; a backend of your own can reach it (Write your own backend). A key given as "", or a variable holding "", sends no Authorization header. The endpoint has no default model: every request names the model the service serves under that name (Models), or is refused (Limits and refusals).']],["First call","openai_compatible_first_call",["A Chat starts with its system message; chatrequest! sends it and returns a typed result, and text reads the reply — or throws, on a failure:","The reply is read as a Chat Completions reply: result.model is the model the service reports, and finish_reason and usage are read as the OpenAI-compatible API defines them. No Mistral model has a price row, so the first chatrequest! logs a warning and the call costs 0.0 (Cost and usage).","A content that is a list of chunks, the shape Mistral's reasoning models answer in with reasoning_effort=\"high\" — a thinking chunk, then the answer's text chunks (reasoning) — is read as its text chunks joined, and its thinking chunks are kept apart as the turn's reasoning, which reasoning_text reads, streamed or not (Streaming). A reply's reasoning_content or reasoning field, in which other servers return the reasoning, is kept the same way (vLLM, LM Studio & llama.cpp). No reasoning goes back with the next request.","Fields go out under the names of the Chat, but on Mistral's host a max_completion_tokens goes out as max_tokens, taken over a max_tokens also set, the name Mistral's chat reference gives the cap (chat completions), and a seed as random_seed, \"The seed to use for random sampling\", the name it gives the seed; any other service gets both as the Chat names them. Mistral's safe_prompt, min_tokens, prompt_mode and guardrails are not Chat fields (chat completions). What Mistral does with a field its reference does not list is untested."]],["Conversations","openai_compatible_conversations",["A Chat keeps the conversation: each reply is appended to it, and the next chatrequest! sends the whole conversation again; a system message pushed after the conversation started is sent in place.","A reply's reasoning never goes back with a later turn: an unstreamed reply keeps none (First call), and the reasoning a streamed one keeps is not sent. What push! refuses is the same on every provider (Chat Completions)."]],["Streaming","openai_compatible_streaming",["With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call; the callback receives the text as it arrives, then the assembled Message:","A Chat on this endpoint sends no stream_options unless it sets them, a field Mistral's chat reference does not list; whether Mistral's stream reports its usage unasked is untested, and a stream without usage adds 0.0 to cumulative_cost. The stream is the Chat Completions one: the turn is final at data: [DONE], or, without one, when the HTTP body ends after the finish reason; on_tool_call(tc) runs once per call whose arguments decode, as the next call begins or at the end of the stream; and setting close[] = true stops it (Stopping a Stream Early).","A delta whose content is a list of chunks is read chunk by chunk. Mistral streams a reasoning reply's thinking in such lists, then \"a single list containing both a closing ThinkChunk and the first TextChunk\", then the answer as strings (reasoning): the text chunks reach the callback and the final Message in order, and the thinking chunks are kept apart as the turn's reasoning, which reasoning_text reads once the finish reason or data: [DONE] has arrived; a stream cut before then keeps none. No thinking reaches the callback. The concepts every provider shares are on Streaming."]],["Tools","openai_compatible_tools",['Each Tool in tools goes out as a function tool, and tool_choice, parallel_tool_calls and a tool\'s strict go as they are set; a Chat with tools sends parallel_tool_calls: false unless it sets another value, where Mistral\'s own default is true. Mistral\'s tool_choice takes "auto", "none", "any", "required" or a function: "any or required means the model must call one or more tools" (chat completions). tool_loop! runs the calls and sends their results back until the model answers in text:',"The loop every provider shares is on Tool Calling."]],["Structured output","openai_compatible_structured_output",['A JSON Schema response_format goes out as {"type": "json_schema", "json_schema": {"name": …, "schema": …}}, and UniLM.json_object() as {"type": "json_object"}; the service constrains the reply. On Mistral, json_schema "guarantees the message the model generates is in JSON and follows the schema you provide", and with json_object "you MUST also instruct the model to produce JSON yourself with a system or a user message" (chat completions):',"The formats every provider shares are on Structured Output."]],["Attachments","openai_compatible_media",["A user message's attachments go out as content parts: an image as an image_url part, with its detail when one is set, a sound clip as an input_audio part, and a document as a file part holding its name and a data URL. The service decides what it reads, and UniLM checks none of it before sending. The attachments every provider shares are on Attachments."]],["Embeddings","openai_compatible_embeddings",["An Embeddings request goes to /v1/embeddings with the texts, the model and the fields it sets:","Mistral's embeddings route takes input, model, output_dimension, output_dtype, encoding_format and metadata (embeddings). On Mistral's host an Embeddings request's dimensions goes out as output_dimension, \"The dimension of the output embeddings when feature available\", and on any other service as dimensions; its effect on Mistral is untested. Each item is text: an image or a sound clip is refused before the request (Limits and refusals). The concepts every provider shares are on Embeddings."]],["Audio","openai_compatible_audio",["transcribe sends the recording and the fields a request sets to /v1/audio/transcriptions, as a multipart form, and reads a JSON reply's text:","Mistral's route takes the file, a model it marks required, a language (\"Providing the language can boost accuracy\"), temperature, timestamp_granularities, context_bias and diarize (transcriptions); a request's prompt and response_format, which that reference does not list, go out as set, untested. The endpoint has no default transcription model, so a call names one (Limits and refusals). transcribe is sent again after a transient status, as a Chat is, whole each time (When something fails)."]],["FIM completion","openai_compatible_completions",["On Mistral's host, fim_complete goes to /v1/fim/completions, Mistral's fill-in-the-middle route, and reads each choice's message.content, the chat shape Mistral answers in; on another host it goes to /v1/completions and reads each choice's text. A request names a model with FIM, Codestral on Mistral:","Mistral's FIM route takes model, prompt, suffix, max_tokens, min_tokens, stop, temperature, top_p, random_seed, stream, prompt_cache_key and metadata (FIM). A FIMCompletion sends max_tokens 128 unless it sets another value, has no streaming path (Limits and refusals), and sends its echo, logprobs, frequency_penalty and presence_penalty only when it sets them, fields that reference does not list. The concepts every provider shares are on FIM & Prefix Completion."]],["Limits and refusals","openai_compatible_limits",["UniLM checks no limit of a service: a request longer than the model's context, or one the service cannot serve, is the service's error (When something fails). Every field goes out as it is set; the checks every request gets still hold, such as a temperature from 0 to 2, though Mistral's error glossary gives \"temperature outside 0 to 1 range\" as a cause of HTTP 400 (error glossary). respond sends a Respond to /v1/responses, its seed among its fields, while Mistral's API reference lists no Responses route. It refuses before anything is sent what the table below lists; the verbs of the capabilities the table at the top of this page lists as not available refuse the endpoint too."]],["Cost and usage","openai_compatible_cost",['A result is priced by the model id it reports, whatever the service. No Mistral model has a row in DEFAULT_PRICING: its estimated_cost is 0.0, with one warning per model id, its embeddings\' too, and cumulative_cost adds 0.0. A model another service reports is priced at its id\'s row where DEFAULT_PRICING has one, as a priced provider\'s model served through another service is, and at 0.0 otherwise. Give the model\'s rates, USD per token, as pricing, or add the row to DEFAULT_PRICING; Mistral lists Mistral Large 3, mistral-large-2512, at "Input $0.5 /M Tokens" and "Output $1.5 /M Tokens" (API pricing), and "Cached tokens are billed at 10% of the standard input token price" (chat completions):',"The row prices the model the reply reports. A row holds no audio rates, so a result whose usage counts audio tokens is estimated at 0.0, with a warning, even then. A transcription, which Mistral prices per minute of audio, carries no token usage: estimated_cost throws ArgumentError for it. How a call is priced on every provider is on Cost Tracking."]],["When something fails","openai_compatible_failures",["chatrequest!, embeddingrequest!, fim_complete and transcribe return what the service or the network did as a typed result, and do not throw it (Results). A failure holds the service's HTTP status and, as response, the body that came with it; a call error holds the text of an exception as error and the exception as cause. UniLM sends a request again after a transient status — 408, 429, 500, 502 to 504, 520 to 524 and 529 — or a failed connection, as often as the call's RequestConfig allows, and then returns the last answer (Timeouts & Retries); a streamed request is sent again only while none of its callbacks has run. The statuses below are Mistral's (error glossary):"]],["Models","openai_compatible_models",['The endpoint has no default model: a request names one by the name the service serves it under. On Mistral, many API names are dated, such as mistral-large-2512 (Mistral Large 3), codestral-2508 or mistral-embed-2312, while some of the newest are not, such as mistral-medium-3-5 and mistral-large-4, and "A deprecated model still answers requests until its retirement date. A retired model no longer does: use its replacement" (models); the examples of Mistral\'s API reference name aliases, such as mistral-large-latest, codestral-latest, mistral-embed and voxtral-mini-latest. Mistral lists its models at GET /v1/models (models API).',"Checked against Mistral's API documentation of 25 October 2026 with UniLM's development branch after 0.26.0; nothing on this page was run.","See also: GenericOpenAIEndpoint, MistralEndpoint, Chat, chatrequest!, fim_complete and LLMSuccess in the API reference."]]]},{url:"/decisions/jev/abilities/",sections:[["Images, Box, long context, structured guidance",null,["What Jev takes beyond a question about a text, a section each:"]],["Images","jev_images",["The job: judge what a picture shows — the photo a customer attached, a screenshot of an error — with the questions you ask about a text. Without Jev: a vision LLM whose description you parse. With Jev: put an ImageAttachment in the request, and a Choice, Score or Noul is answered about it as about a text.","The picture here is a test image of 512 \xd7 512 pixels: a red rectangle and a blue disc on white.","","The message and the picture went out in one state, and each question names its part in backticks. Jev puts 0.82 on the photo showing what the customer asks about, and names the red shape a rectangle at confidence 1.0. The picture is most of the 1,114 input tokens: about 720 of them, by the measurement below.","An image may stand anywhere a string can: in the state, alone or among text in a NamedTuple, Dict, vector or tuple; in a question's instructions; in its criteria — a Choice whose options are example pictures, a Score whose levels are. A Score level that is an image comes back in the answer's legend as the same ImageAttachment. UniLM looks for images in those containers, not in the fields of a struct of your own: a request whose image only a struct holds is refused with an ArgumentError before anything is sent, rather than writing the image's bytes into the JSON as numbers (Limits and refusals).","Observed on 19 October 2026 (jev-1.13.0): an image of W \xd7 H pixels was billed 2\xb7⌈W/28⌉\xb7⌈H/28⌉ input tokens, plus about 4 for each use — 722 for a 512 \xd7 512 picture, 200 at 280 \xd7 280, 6,272 at 1568 \xd7 1568 — and the same image used twice in one request was billed twice. TypeSafe does not document this formula: it is our fit to six sizes, not a contract.","Tune it"]],["Locate with Box","jev_box",["The job: find where something is in a picture: the dent on a parcel, the signature on a form. Without Jev: an object detector trained on your classes, or a vision LLM asked for coordinates as text. With Jev: a box question names what to locate, and the answer is a BoxAnswer: the box's edges as fractions of the image, and a confidence.",'A Box needs Jev 1.14 or later (Images) — model = "jev-1.14.0", or an alias that points to it: on 25 October 2026 TypeSafe points jev-latest and jev-preview at jev-1.14.0 (Models). Asked of Jev 1.13 in October 2026, a Box question drew HTTP 400 and "Invalid request."; ask returns that SystemOneFailure with a hint naming the models that answer one.',"The rectangle is drawn at 0.30–0.70 of the height and 0.20–0.55 of the width — rows 153–358 and columns 102–281 of the 512 — and the disc at 0.12–0.32 and 0.68–0.88: every edge of both answers is within 0.02 of the drawing.","A BoxAnswer holds box, a BoxCoordinates — top and bottom as fractions of the image's height from its top edge, left and right as fractions of its width from its left edge, so (0, 1, 0, 1) is the whole image — then confidence, nothing when the model reports none, and raw. A Box question needs an image in the request, and ask refuses one without before anything is sent (Limits and refusals):","Sent anyway, such a question is still answered — HTTP 200 and a box at a low confidence, 0.05 to 0.10 in our probes on 19 and 20 October 2026 — and no box drawn on a picture that is not there means anything. An answer whose box is turned inside out, its top below its bottom or its left right of its right, is a SystemOneCallError. Only TypeSafe answers Box questions; the other backends' wrappers refuse them (Backends).","Measured on 19 October 2026 (jev-1.14.0) on this picture, in a run apart from the answer above: every edge of both boxes came back within 0.02 of the drawing then too. In probes on 19 and 20 October 2026, a Box question about a request with no image came back with HTTP 200 and a box at a confidence of 0.05 to 0.10. Limits: one picture, two shapes on a plain background.","Tune it"]],["Long context","jev_long_context",["TypeSafe reads at most 64k tokens per request, and 32k for the state with any one question. long_context = true raises both to 262k tokens, at the same price per token, by sending the header TypeSafe-Danger-Zone-Long-Context: true. The docs build does not run this block: a real example needs more than 32k tokens of text, and its recording would hold all of it.",'TypeSafe documents long context as slower and less accurate than the default limits (Models), and an answer does not say which ran. A request over its context comes back as a 400 SystemOneFailure whose error_type is "max_tokens_exceeded"; its message names the limits, and long_context when the request did not set it. long_context is a TypeSafe option: any other backend refuses it before sending, as it refuses every option it does not know. The natural-language verbs take it as options = (long_context = true,), and with_system_one(TYPESAFEServiceEndpoint; long_context = true) do … end sets it for every call inside that names no backend and no options of its own.',"Measured on 19 October 2026 (jev-1.13.0): a request of about 100k tokens came back 400 without the option and was answered in 1.5 s with it; one of 257k to 262k tokens in a single state took 4.7 to 5.3 s, against 0.25 to 0.42 s for a small request. The same request was billed the same number of tokens with and without the option.","Tune it"]],["Structured guidance","jev_structured",["Wherever guidance appears — a question's instructions, a Choice option's description, a Score level, a Noul's yes and no — Jev takes a string, an object (a NamedTuple or a Dict), an array (a vector or a tuple), or an image, nested up to the limit (Limits and refusals; Advanced: structure). Start with strings. When two options keep getting confused, give each what it covers, what it does not, and a few examples:","The field names what, not_for and examples are yours, not the API's. The model reads them with the values, so keep them short and the same on every option (Choice). Not every decision provider takes structure everywhere (Choosing a decision provider).","Recorded on 19 October 2026 on jev-1.13.0 and jev-1.14.0 with UniLM's development branch after 0.23.0, and on 25 October 2026 on jev-1.14.0 with UniLM's development branch after 0.26.0, through TypeSafe's API at /v1."]]]},{url:"/decisions/jev/operations/",sections:[["Confidence, errors, cost & testing",null,[]],["Confidence and tuning","jev_confidence",["TypeSafe trains Jev for calibrated decisions: its probabilities are optimized against outcomes, and calibration is measured across groups of answers, so it does not guarantee that any single answer is correct (System One). TypeSafe computes the confidence of every Choice and Score answer from its probabilities, 1 when all of it is on one outcome and 0 when it is spread evenly, and a Noul answer carries none: its probability is the whole answer. TypeSafe's Confidence page gives the formulas of both; the Choice formula is also on Reading answers.","In the replies recorded for this manual, TypeSafe rounds every probability to two decimals, so a distribution need not sum to exactly 1: ask accepts a sum within 0.005 per outcome of 1, and a chosen option at most 0.01 below the most probable one, and returns a reply further off as a SystemOneCallError.","Answers vary between identical calls: a decision near a threshold can flip from one call to the next. Log what a decision was based on — the answer's raw, r.response.request_id and r.response.model — and record the answers a test relies on (Testing and recordings).","A live reply over four options summed to 0.99 on 20 October 2026. Measured on jev-1.13.0 in September 2026, identical requests differed in 60% of repeated pairs, by 0.011 in a probability on average and by up to 0.11.","Jev answers every question it is asked: TypeSafe's answer types hold no refusal (System One), so a case is handed over only by a bar you set. Below min_confidence, a natural-language verb returns what fallback returns, and with no fallback it throws LowConfidenceError. A support desk's inbox, one team per message:","Every message gets a team. The question about shipping to Norway is the unclear one, and with a bar it goes to a person:","Jev's best guess, billing, came with a confidence below the 0.6 asked for. Set the bar by what a wrong team costs against a person's time; where some mistakes cost more than others, price each one and let a decide policy choose the cheapest action (When mistakes have different prices). Tune a bar on messages of your own, with the version pinned: a bar tuned against one version is a claim about that version (Models). The measurements below were made on Jev 1.13, and on 25 October 2026 jev-latest points at Jev 1.14. The decision rules on every provider are on Act on the answer.","Measured on 20 October 2026 on our 129 labelled support tickets, one Choice of seven intents per ticket, one call at a time, on jev-1.13.0: accuracy 0.969, expected calibration error 0.016 (10 bins), Brier score 0.052, mean top probability 0.96; 115 tickets at a confidence of 0.8 or more, of which 0.991 were right; latency 0.25 s at the median and 0.33 s at the 95th percentile. Limits: one labelled set, one run. In September 2026, also on jev-1.13.0, two other sets of ours measured higher errors: 0.047 on 100 items built on the model's documented failure modes, and 0.071 on 74 Noul answers, which were under-confident."]],["Cost","jev_cost",["TypeSafe bills the input tokens of a request — the state, the questions and the pictures — and output tokens are free (Models, Images). The state is read once for every question of a request, so many questions in one ask cost far less than a request each. The rows are TypeSafe's prices as checked on 25 October 2026; prices change, so check the Models page before relying on an estimate.","prompt_tokens is TypeSafe's input_tokens and completion_tokens its output_tokens. estimated_cost prices the versioned id that answered, r.response.model, not the alias the request named: here jev-1.14.0, which has a row of its own in the table above, so haskey is true. A jev-X.Y.Z id with no row of its own, such as a release newer than the table, is priced at the jev-latest row, and any other name with no row at 0.0, with a warning. What a picture costs is on Images; totals across calls and prices of your own are on Cost Tracking."]],["Testing and recordings","jev_testing",["with_recorded_answers records a TypeSafe exchange once and replays it with no key and no network: ask, ask_each and the verbs built on them, and TypeSafe's list_models, the one model listing it records. A recording is filed under the request's own path, /v1/systemone or /v1/models, with no namespace in front of it, and keyed on the exact request: its method, its path and its body, which names the model. long_context = true is part of the key too; the pictures of a request are keyed by the SHA-256 of their bytes, and the file holds those digests, never the pictures.","Recording takes TYPESAFE_API_KEY, and replaying takes nothing. In this manual's build the recording scope above replays the manual's own recordings, so the example reaches no service either (How this manual runs its examples).","The response shape is the whole contract: a model, an answers object keyed by the question names the client sent, each a Choice with choice, confidence and probabilities, and a usage object. An answer outside the offered options makes the call a SystemOneCallError, so nl_dispatch throws a SystemOneError, and no method runs.","Previews of what a call sends, tests of the methods and of the judgment, and an audit trail are on Test and Develop."]],["Throughput","jev_throughput",["ask_each sends one request per item and returns the results in input order; on Jev it keeps at most 16 requests in flight unless its ntasks says otherwise. TypeSafe sets rate limits per organization, in tokens and in requests per second, shows them in its developer console, and answers a request over either with 429 (Models); higher limits come with its custom and enterprise plans. How a batch backs off when the service is busy is on Many requests at once.","Measured live on 20 October 2026 (jev-1.13.0): 50 support tickets, three questions each, took 3.28 s through ask_each with its default of 16 in flight, and 13.21 s as 50 ask calls one after another. The batch used a single connection (HTTP/2)."]],["When something fails","jev_errors",['A call that reaches TypeSafe returns a SystemOneSuccess; a SystemOneFailure for a status other than 200, with the status, TypeSafe\'s message, its error_type where TypeSafe sends one, and the request_id; or a SystemOneCallError when no usable response came. A 200 whose answers do not fit the request — a question unanswered, an option that was not offered, probabilities that are no distribution within the rounding above — is a SystemOneCallError too: no success is built from a malformed answer. Reading an answer of a failed call (r["name"], answer, answers) throws a SystemOneError.',"UniLM sends a request again after a 408, 429, 500, 502, 503, 504, 520 to 524 or 529, up to max_attempts times within total_deadline, waiting at least what the reply's retry-after-ms header asks for, else its Retry-After, as the shared backoff of ask_each does (Many requests at once). Each retry carries X-TypeSafe-Retry-Count, 1 on the second attempt. Any other status comes back as it is, since an identical request cannot fix it. With no RequestConfig of your own, a call to Jev is bounded by 60 s per attempt and 150 s in all; one of your own replaces both, per call or for a scope:","The messages and error types in the table were captured from TypeSafe's live API: the 401, the unknown model's 400, a 422 and the 404 on 22 September 2026, the Box's 400 from Jev 1.13 in October 2026. TypeSafe's Request rules and errors page lists these statuses but the 404, and none of these messages.","Recorded on 28 September 2026 on jev-1.13.0 with UniLM's development branch after 0.21.0 (after 0.20.1 for the RequestConfig example), and on 25 October 2026 on jev-1.14.0 with UniLM's development branch after 0.26.0, through TypeSafe's API at /v1."]]]},{url:"/providers/anthropic/caching/",sections:[["Caching, cost & limits",null,[]],["Prompt caching","anthropic_caching",['A Chat with prompt_cache_options turns on Anthropic\'s automatic caching: UniLM sends a top-level cache_control, {"type": "ephemeral"} with the options\' ttl when one is set, and the API puts the cache breakpoint on the request\'s last cacheable block (prompt caching). PromptCacheOptions() asks for the cache\'s default lifetime, 5 minutes, and PromptCacheOptions(ttl="1h") for an hour. The options a Chat cannot send to Anthropic are refused before the request (Limits and refusals).',"Anthropic's cache \"references the entire prompt: tools, system, and messages (in that order)\", and the breakpoint is where it is written: one entry, holding everything up to and including that block. Anthropic isolates caches by workspace: a later request in the same workspace (Options) that starts with the same blocks up to that breakpoint reads the entry while it lives, unless a change has invalidated it, and writes what follows them; the API checks at most 20 positions for such an entry, counting the request's breakpoint as the first and a run of consecutive tool_use blocks, or of consecutive tool_result blocks, as one position. Changed tools invalidate the entire cache, and a changed system prompt that prompt and the messages; a changed tool_choice, an image added or removed anywhere in the prompt and changed thinking parameters invalidate at least the messages, and Anthropic's table lists the other changes and what each invalidates (what invalidates the cache). A Chat builds each request from its fields as they are then, the whole conversation and tools included, so the next turn starts with the previous one's blocks as long as the tools, the system prompt and the earlier turns go out as they did before. A system message pushed mid-conversation can change that: it may join the top-level system prompt, and the request then reads none of what the earlier requests wrote and writes it all again, or move within the messages (Conversations says how UniLM places one). Two requests that share only a long system prompt, each with its own question, write two entries and read none: a Chat marks no breakpoint of its own. A prefix shorter than the model's minimum cacheable prompt, which Anthropic sets per model between 512 and 4,096 tokens, is not cached, and the API returns no error: the usage then shows neither a write nor a read.","The usage counts the reads and the writes (First call), and cache_write_extended_tokens the writes kept for an hour; what each costs is in Cost and usage. On most models, reads do not count toward Anthropic's rate limit of input tokens per minute (rate limits). Here a generated parts list is the system prompt of a conversation, and each turn asks about one part:","The first request wrote the system prompt and its question to the cache. The second read them back and wrote only what the conversation had added, the reply and the next question."]],["Cost and usage","anthropic_cost",["estimated_cost prices a result with the row of the table below for its model (First call says which model that is), an id with a -YYYYMMDD snapshot suffix with the row of the id without it, and cumulative_cost adds up the calls of a Chat. Of the usage, it bills the uncached input at the input rate, the cache reads at the cached-input rate, the cache writes at 1.25 times the input rate, or 2 times for the writes kept for an hour (cache_write_extended_tokens), and all the output, thinking included, at the output rate (pricing). Every rate is then multiplied by each factor that applies, the factors stacking:","Two kinds of model are priced otherwise: a model with a long-prompt multiplier bills more over its threshold, and a model of the family table without a price row is estimated at 0.0:",'A call Anthropic reports at Priority Tier (service_tier == "priority") is estimated at the list rates, as a standard one is: Priority Tier draws down an organization\'s capacity commitment (service tiers), which no rate here models. A model with no row, one of the family table as above or any other id, is estimated at 0.0, with one warning per model id: pass estimated_cost a pricing table that holds its row, or add the row to DEFAULT_PRICING. A failure costs 0.0, since it carries no usage.','How a stream reports its usage, and what a stream that ends uncommitted adds, is on Streaming. cumulative_cost is a lower bound of the bill, refusals Anthropic does not bill aside: it adds nothing for an attempt UniLM retried, a stream Anthropic ended with an error event, or an unstreamed reply UniLM could not decode (Cost Tracking). It prices every refusal at the usage Anthropic reports, while Anthropic bills a refusal that arrives before any output only when its stop_details.category is one its page lists as billed: "bio", "frontier_llm" and "reasoning_extraction" on 25 October 2026 (how refusals are billed).',"The rows are Anthropic's list prices as checked on 22 October 2026; prices change, so check Anthropic's page before relying on an estimate."]],["Rate limits, overload and failures","anthropic_failures",["chatrequest! returns what the service or the network did as a typed result, and does not throw it (Results). An LLMFailure holds an HTTP status and, as response, what came with it: the body of a status other than 200; the event of an in-band overloaded_error, with status 529; or what a stream that ended before its turn had sent, with status 200. An LLMCallError holds, as error, the text of an exception or of another in-band error event, and the exception as cause when there is one. UniLM sends a request again after a transient status, 429 and 529 among them and Anthropic's 500 and 504, as often as the call's RequestConfig allows, and then returns the last answer (Timeouts & Retries); a streamed request is sent again only while none of its callbacks has run. A 429 of the monthly spend cap is not transient: UniLM returns it at once."]],["Models","anthropic_models",["The listing is the endpoint's models capability: list_models with service=ANTHROPICServiceEndpoint asks Anthropic's Models API (GET /v1/models) which models your key can use, fetches every page of the answer, and returns a ModelListSuccess whose models are ProviderModels, the most recently released first. Each holds the model's id and display_name, its release as created (nothing where Anthropic gives the Unix epoch, its value for an unknown date), its input_token_limit and its output_token_limit, the largest max_tokens a request may set, the capabilities object Anthropic sends, the dates it was deprecated (deprecated) and retires (retires), and the entry as sent in raw (Model Listings). Anthropic lists the active and the deprecated models, not the retired ones: raw[\"lifecycle\"] says which, and a retires date may still move until the model retires (List Models). An error status on any page is a ModelListFailure, with its status, response and request_id; a call that brings no listing — no key, which it names, no connection, a timeout, a reply that is not the listing — is a ModelListCallError.","A listing bills no tokens and is not recorded, so its output here is quoted from a live run:","The capabilities say what Anthropic takes on each model: its thinking types and effort levels, which the family table holds UniLM's requests to, image and PDF input, structured outputs, server tools and more. They show what a model newer than this release takes, too. Before you use a newly listed model, check that it has a price row, as the last line above does with the lookup of estimated_cost: a model without one is estimated at 0.0 (Cost and usage). UniLM's release gate runs the same listing, and fails when a listed Claude model of 4.5 or later has no price row, unless Anthropic publishes no price for it, or no row in the family table, or when a row's thinking types or effort levels differ from the listing's."]],["The OpenAI-compatible endpoint","anthropic_compatible",['Anthropic also serves the OpenAI-compatible wire, at https://api.anthropic.com/v1/chat/completions, "primarily intended to test and compare model capabilities", and not "a long-term or production-ready solution for most use cases" (compatibility layer). ANTHROPICServiceEndpoint does not use it. To evaluate it, give a GenericOpenAIEndpoint the bare host, since it appends /v1/chat/completions, and name a model:',"There UniLM is an OpenAI-compatible client and no more:","Recorded on 24 October 2026 on claude-opus-5-5 with UniLM's development branch after 0.26.0 and the Messages API at anthropic-version 2026-10-21."]]]},{url:"/providers/anthropic/requests/",sections:[["Thinking, tools & output",null,["ANTHROPICServiceEndpoint turns each request field of a Chat into its Messages API counterpart. A field with none is refused before the request is sent, except n, which a Chat takes only as 1: the one reply every request gets."]],["Tools","anthropic_tools",['Each Tool in tools goes out with its name, its description when it has one, its parameters as input_schema — {"type": "object", "properties": {}} for a function without parameters — and its strict flag when its FunctionSignature sets one: strict=true makes the API validate each call\'s name and input against the tool\'s schema. The Messages API takes tool names of 1 to 128 letters, digits, _ and -. UniLM sends a name as given, and mcp_tools(session; service), with service this endpoint, advertises each tool of an MCP server under such a name: its own, or that name with each character outside that set replaced by _, one over 128 characters cut and marked with a hash of its MCP name; with no service, the names it gives are at most 64 characters (MCP). Anthropic\'s MCP connector, a beta (mcp-client-2025-11-20), allows you to "connect to remote MCP servers directly from the Messages API without a separate MCP client", the servers named in an mcp_servers array of the request (MCP connector). UniLM sends no mcp_servers: an MCP server\'s tools reach Claude through mcp_tools, which calls the server from your process.','tool_choice becomes the API\'s own: "auto" sends {"type": "auto"}, "none" sends {"type": "none"}, "required" sends {"type": "any"}, and UniLM.GPTToolChoice(func=:get_weather) sends {"type": "tool", "name": "get_weather"}. A forced choice, "required" or a named tool, is refused on the models whose Forced tool choice cell in the family table is "—", and any other string on every model (Limits and refusals).','A Chat with tools has parallel_tool_calls = false unless it sets another value, and sends it as disable_parallel_tool_use: true on its tool_choice, which is {"type": "auto"} when it sets none: the model then makes at most one tool call per turn. Set parallel_tool_calls = true to let it make several in one turn; a tool_choice of "none" carries no such flag.',"An assistant turn that called tools goes back in the blocks it arrived in, as Conversations describes; a turn that holds none of Anthropic's blocks, written by hand or answered by another provider, goes as its text and one tool_use block per call. The tool messages that answer it become tool_result blocks, consecutive ones in one user turn. A tool message whose tool_call_id matches no tool call of an earlier assistant turn is refused (Limits and refusals).","tool_loop! runs the calls and sends their results back until the model answers in text. Here the model thinks before it calls the tool:","The turn that called the tool holds a signed thinking block before its tool_use block, and tool_loop! sent that turn back unchanged, the tool result after it, in the request that got the answer: Anthropic requires a tool result to come with the thinking blocks of the turn that called the tool, complete and unmodified (thinking in tool workflows). A streamed turn's tool calls are on Streaming, and the loop every provider shares is on Tool Calling."]],["Structured output","anthropic_structured_output",['A JSON Schema response_format becomes output_config.format = {"type": "json_schema", "schema": …}: Claude\'s structured outputs, which constrain the reply to the schema. Only the schema is sent; the format\'s name, description and strict have no counterpart.',"The reply's text is the JSON document. ResponseFormat(), a json_object format, is refused (Limits and refusals). Strict tool calls are a flag of each tool (Tools), and the formats every provider shares are on Structured Output."]],["Reasoning","anthropic_reasoning",["reasoning_effort sets the effort of a request, output_config.effort. With adaptive thinking the model decides on each request whether to think and how much, and the effort steers that decision (thinking). What else reasoning_effort sends depends on the model's Thinking cell in the family table below:",'UniLM refuses every reasoning_effort on a model whose Effort levels cell is "—", "none" included, and "minimal" on every model (Limits and refusals). A request without reasoning_effort sends neither field: a model whose thinking is on by default keeps it, at the API\'s default effort, and on most current models the API leaves the text out of the thinking blocks unless asked for a summary, so reasoning_text gives nothing.',"A model id takes the row of the same id, or of that id without a -YYYYMMDD snapshot suffix, never the row of an id it merely starts with; an id no row names, such as a model newer than this release, is refused only by the rules that name no column of the table. The columns:","reasoning_text reads the summary of a turn's thinking:","reasoning_text joins the text of a turn's thinking blocks with a blank line, and gives nothing for a turn with none; a redacted_thinking block carries no text and adds none. Thinking is billed in full as output, whatever summary comes back (thinking cost), and estimated_cost prices it at the output rate (Cost and usage); how the usage counts it is on First call, and how max_tokens bounds it on Setup.","The blocks of a reply that is not a refusal — thinking blocks with their signatures, redacted_thinking blocks, text and tool calls — are kept in its message's provider_content and go back on the next request (Conversations). A streamed reply keeps them only when every block arrived whole: with one cut short — its stop event lost, or a tool call's input that is no JSON object on a turn cut at max_tokens or the context window, which drops that tool call — the message holds no provider_content, and the turn goes back as the text and tool calls it holds, or is left out when it holds neither; on a turn that stops with tool_use, end_turn or stop_sequence, such an input makes the result an LLMCallError, and nothing is appended. Kept blocks go back whatever Claude model the next request names, and a turn cut at max_tokens that holds only thinking blocks goes back too, as Anthropic's guide to continuing such a turn asks. Another provider's encoder ignores them and sends the turn's text and tool calls alone."]],["Attachments","anthropic_media",["A user message's attachments go out as base64 blocks before its text, in their order — the order Anthropic's vision and PDF guides recommend: an ImageAttachment (PNG, JPEG, GIF or WebP) as an image block, and a DocumentAttachment (PDF) as a document block, without its filename. A message with empty text sends the blocks alone.","","The one-page PDF holds one sentence:","An AudioAttachment and an image's detail level are refused before the request (Limits and refusals). UniLM checks no size or page count of its own: the API answers for media past its limits. Which models read images and PDFs is in each model's capabilities, listed by list_models (Models); the attachment types are on Attachments."]],["Request options","anthropic_request_options",['safety_identifier, user and metadata["user_id"] each name the end user, and the Messages API has one field for that, metadata.user_id: set one of them, or set them to the same id. metadata holds no other key.','service_tier takes the Messages API\'s "auto" and "standard_only", sent as they are, and "fast": fast mode, sent as speed: "fast" without a service_tier. Fast mode is served on the models whose Fast mode cell in the family table is "yes", and on those whose cell names a beta header only through an endpoint whose betas hold it; UniLM refuses it on the other rows, and sends it unchecked for an id no row names. How a fast call is reported and priced is on First call and Cost and usage. Where inference runs is the endpoint\'s inference_geo (Options).',"stop becomes stop_sequences, a single string a list of one, and stream=true becomes stream: true (Streaming). n is not sent: a Messages API request has one reply, and a Chat takes no n other than 1.",'A response prefill, a request that ends with an assistant turn for the model to continue, is a Chat with history=false whose last message is an assistant message: with history=true, chatrequest! throws InvalidConversationError for such a conversation, since the reply could not be appended. UniLM sends a prefill on the models whose Prefill cell is "yes" and for an id no row names, and refuses it on the others (Limits and refusals).',"UniLM.encode_request returns the body chatrequest! sends, or throws the refusal the table in Limits and refusals lists, with no key and no request:","JSON.json(chat) is not this body: it writes the Chat in the Chat Completions shape of the OpenAI-compatible wire."]],["Limits and refusals","anthropic_limits",["A request's output stops at its max_tokens (Setup), and a model's largest max_tokens and its input limit are in its list_models entry (Models). UniLM checks a request against neither, and leaves the size of media to the API (Attachments). Rate limits and overload are on Rate limits, overload and failures.","A field the Messages API has no counterpart for, n aside, is refused, not dropped, since dropping it would send a request other than the one asked for; so is each request in the table below that the API would answer with an error, or would run other than asked. chatrequest! and tool_loop! throw these ArgumentErrors before anything is sent. A rule that names a column of the family table holds for the ids of its rows, and an id no row names meets only the other rules. Building an endpoint refuses an option value that breaks its rule (Options).","Recorded on 24 October 2026 on claude-opus-5-5 with UniLM's development branch after 0.26.0 and the Messages API at anthropic-version 2026-10-21."]]]},{url:"/providers/gemini/generate_content/",sections:[["The generateContent API",null,["GEMINIServiceEndpoint turns each request field of a Chat into its generateContent counterpart. A field with none is refused before the request is sent, except two that are not sent: parallel_tool_calls, which a Chat with tools sets on its own (Tools), and n, which a Chat takes only as 1, the one candidate every request gets."]],["Reasoning","gemini_reasoning",['reasoning_effort sets the request\'s thinking level, thinkingConfig.thinkingLevel, and asks for the thought summaries, includeThoughts: true (below); a Reasoning\'s effort sets a Respond\'s, thinking_level on the Interactions API (Thinking on the Interactions API). A reasoning_effort of "minimal", "low", "medium" or "high" is checked against the table below; "none", "xhigh" and "max" throw ArgumentError on every model (Limits and refusals).',"A model id takes the row of the same id, never the row of an id it merely starts with, since distinct models share prefixes (gemini-3.8-flash and gemini-3.8-flash-tts). For an id no row names, a valid level goes to the server, which answers for it. The columns:",'The -latest aliases and the ids Google routes to their successors (Models) take the levels of the models that served them when this release was made. A request without reasoning_effort sends no level, and the model thinks at its own default: "If you don\'t specify a thinking level, Gemini will use the model\'s default thinking level (e.g., "medium" for Gemini 4 Argon, Gemini 3.8 Flash, and Gemini 3.6 Flash)", and "You cannot disable thinking for Gemini 4 Argon. Gemini 3 Flash and Flash-Lite also do not support full thinking-off" (thinking).','The model thought, and reasoning_tokens counts it. A Chat that sets reasoning_effort also asks for the thought summaries — "You can enable thought summaries by setting includeThoughts to true in your request configuration" (thought summaries) — which come back as parts marked thought, and reasoning_text reads them; a Chat without reasoning_effort asks for none, so reasoning_text gives nothing. They add nothing to the bill: "pricing is based on the full thought tokens the model needs to generate to create a summary, despite only the summary being output from the API" (the same page). A Respond asks for them with Reasoning(summary="auto"), and reasoning_summaries reads them (Thinking on the Interactions API).','The thinking is billed as output — Google lists each model\'s "Output price (including thinking tokens)" (pricing) — and maxOutputTokens bounds it with the answer: "If the model hits this limit while reasoning, it stops generating with finish_reason: MAX_TOKENS and returns truncated or empty output (while still billing for any thinking tokens generated)" (thinking). The turn then reads finish_reason == "length"; lower the level rather than the limit. A reply\'s thought signatures travel on its parts, which UniLM sends back as they came (Conversations).']],["Tools","gemini_tools",["Each Tool in tools goes out as a function declaration: its name, its description when it has one, and its parameters as parametersJsonSchema, the JSON Schema whole. Google's reference gives a declaration's name \"Must be a-z, A-Z, 0-9, or contain underscores, colons, dots, and dashes, with a maximum length of 128\", and the name a call and its response carry \"Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 128\" (generateContent reference); UniLM sends a name as given, so a name of letters, digits, _ and - holds for both. mcp_tools(session; service), with service this endpoint, advertises an MCP server's tools under such names, one over 128 characters cut and marked with a hash of its MCP name (MCP). tool_choice becomes the request's function-calling mode:",'A declaration has no strict flag: a tool marked strict=true sets the request\'s mode, for every function the request declares. Google\'s modes: VALIDATED — "The model is constrained to predict either function calls or natural language, and ensures function schema adherence"; AUTO — "The model decides whether to generate a natural language response or suggest a function call"; ANY — "The model is constrained to always predict a function call and ensures function schema adherence"; NONE — "The model is prohibited from making function calls" (function calling). Another tool_choice string is refused (Limits and refusals).','A Chat with tools has parallel_tool_calls = false unless it sets another value, and generateContent has no field for it, so UniLM sends nothing: the model decides whether to call several functions in one turn, which it may ("The model also supports calling multiple functions in a single turn", parallel function calling).','A call\'s id is the one Google sends — "Gemini 3 now always returns a unique id with every functionCall" (function calling) — and a call that comes without one gets unilm_call_1, unilm_call_2, … by its place in the turn, so its result can name it; such an id is never sent, and the call and its result go back without one. The unilm_call_ prefix is reserved. The tool messages that answer a turn become one user turn of functionResponse parts, each with the call\'s name: a result whose text is a JSON object is sent as that object, and any other text as {"result": text}, since Google takes "The function response in JSON object format" (generateContent reference). A tool message whose tool_call_id matches no call of an earlier turn is refused (Limits and refusals).',"tool_loop! runs the calls and sends their results back until the model answers in text:","The turn that called the tool holds its functionCall part with a thoughtSignature, and tool_loop! sent that turn back as it came, its result after it, in the request that got the answer: \"passing back thought signatures is mandatory for function calling\" (function calling). A call's signature is also on its ToolCall, as thought_signature, which goes back with the call when the turn holds none of Gemini's parts. A streamed turn's calls are on Streaming, the tools of the Interactions API on The Interactions API, and the loop every provider shares on Tool Calling."]],["Structured output","gemini_structured_output",['A JSON Schema response_format becomes generationConfig.responseFormat = {"text": {"mimeType": "APPLICATION_JSON", "schema": …}}, and ResponseFormat(), a json_object format, the same without a schema: JSON of any shape. Only the schema is sent; the format\'s name, description and strict have no counterpart.','The reply\'s text is the JSON document. Google\'s structured output "supports a subset of the JSON Schema specification", and "The model ignores unsupported properties" (structured output): among the keywords Google lists, an array takes minItems and maxItems, a number minimum and maximum, a string enum and format, and no string length — so check such constraints on the parsed answer. The same format on a Respond is on The Interactions API, and the formats every provider shares are on Structured Output.']],["Attachments","gemini_media",['A user message\'s attachments go out as inlineData parts — the bytes in base64, under the MIME type their leading bytes give — before its text, as Google advises for one image: "place the text prompt after the image part in the contents array" (image understanding). An ImageAttachment goes as image/png, image/jpeg, image/gif or image/webp, an AudioAttachment as audio/wav or audio/mp3, and a DocumentAttachment as application/pdf, without its filename, which inline data has no field for. Google lists PNG, JPEG, WEBP, HEIC and HEIF as the image types it supports, and not GIF (image understanding): a GIF is sent, and the API answers for it. A message with empty text sends the parts alone.',"","A sound clip of one spoken word goes the same way, and the usage counts its tokens as audio:",'An image\'s detail is its media resolution, the part\'s mediaResolution: "low" and "high" are MEDIA_RESOLUTION_LOW and MEDIA_RESOLUTION_HIGH, and "auto" sends none, leaving the model\'s default. Google documents a resolution per part for "Gemini 3 only" (media resolution); UniLM refuses a level on the Gemini 2.5 and Gemma 4 models, and "original" on every model, and sends a level for any other id (Limits and refusals). UniLM checks no size: Google bounds inline data by the request, "Inline image data limits your total request size (text prompts, system instructions, and inline bytes) to 20MB" (image understanding). Audio input is priced at the rate Google lists for it (Cost and usage), and the attachment types are on Attachments.']],["Streaming","gemini_streaming",["With stream=true, chatrequest! returns a Task at once, and fetch gives the same typed result as an unstreamed call. The callback receives the text as it arrives, a String at a time, then the assembled Message:","A Chat streams through this callback keyword; respond streams the Interactions API (Streaming on the Interactions API). Setting close[] = true stops the stream (Stopping a Stream Early).","The concepts every provider shares are on Streaming."]],["Finish reasons and safety","gemini_finish_reasons",['The candidate\'s finishReason becomes the message\'s finish_reason, streamed or not: STOP gives "stop", or "tool_calls" when the turn holds function calls; MAX_TOKENS gives "length"; the filters SAFETY, RECITATION, BLOCKLIST, PROHIBITED_CONTENT, SPII, IMAGE_SAFETY, IMAGE_PROHIBITED_CONTENT and IMAGE_RECITATION give "content_filter", as do the filters LANGUAGE (content "flagged for using an unsupported language") and ESCALATION ("filtered by an escalation rule"), and the policy stop PUP_LIMITED_DISABLED ("the user account is limited or disabled due to Prohibited Use Policy (PUP) violations"); and every other value passes through in lower case — "malformed_function_call", "unexpected_tool_call", "continuation" (Long generations), "other", … — never as "stop". A candidate without a finishReason reads nothing, and function calls under a reason other than STOP keep that reason, so tool_loop! does not run them. Google\'s reference lists every value (FinishReason).','A "content_filter" turn with no text has no content: its refusal_message is the candidate\'s finishMessage, Google\'s account of the stop, which is optional. Without it, a LANGUAGE, ESCALATION or PUP_LIMITED_DISABLED stop is named, with the enum\'s definition of it ("ESCALATION: Request was filtered by an escalation rule."), and a content filter reads "Model response blocked by safety filter."; such a turn, when it holds no part, is left out of the next request. A blocked prompt gets no candidate at all — "If set, the prompt was blocked and no candidates are returned" (generateContent reference) — which UniLM returns as an LLMCallError naming the promptFeedback (When something fails). A Chat sends no safetySettings, so Google\'s default settings apply; UniLM has no field for them. The end user a request is made for goes as a request label (Request options).']],["Request options","gemini_request_options",['temperature and top_p reach the models released before Gemini 3.6 Flash, from which on, Google says, "temperature, top_p, and top_k are deprecated. The API ignores these parameters and returns an error in future model generations" (what\'s new in Gemini 3.6). UniLM takes them only for these exact ids, on a Chat, a Respond and GEMINIOpenAIServiceEndpoint alike, and refuses them for any other (Limits and refusals):',"The same ids are the ones a Chat may end with an assistant turn on (Conversations).",'service_tier takes "standard", "flex" and "priority", sent as serviceTier; a Respond takes the same three (The Interactions API). Flex costs half the standard rates and its latency is "Minutes (1–15 min target)"; Priority costs "75% to 100% over Standard rates", and a request over its limits is downgraded: "Downgraded requests are billed at the standard rate" (optimization, priority inference). The tier that billed a call is usage.service_tier: the reply\'s x-gemini-service-tier header, which Google names as the way "to detect if requests are being frequently downgraded to standard", else its usageMetadata.serviceTier; Cost and usage prices it. Google recommends "increasing client-side timeouts to 10 minutes or more" for Flex, whose requests "may sit in a queue" (Flex inference), and a stream\'s wait for its headers counts against stream_idle_timeout, so give a Flex call a longer bound, such as config=RequestConfig(request_timeout=900, stream_idle_timeout=900) (Timeouts & Retries).',"UniLM.encode_request returns the body chatrequest! sends, or throws the refusal the table in Limits and refusals lists, with no key and no request:","JSON.json(chat) is not this body: it writes the Chat in the Chat Completions shape of the OpenAI-compatible wire."]],["Long generations","gemini_long_decode",['Gemini 4 Argon writes past one request\'s output cap — "One hop returns up to 65,536 output tokens. Non-streaming REST requests return up to 32,768" — and a reply that reaches the cap with tokens left "ends with finish_reason: CONTINUATION and a continuation_token" (long decode). chatrequest! continues such a turn itself, as Google\'s loop does: the same request again with the latest token, the parts of every reply joined into one assistant turn, and its usage the replies\' summed. It sends at most max(8, cld(budget, cap) + 1) requests, the budget being max_completion_tokens, else max_tokens (8 when neither is set), and the cap 32,768 unstreamed or 65,536 streamed. A turn still unfinished after the last of them, or after a CONTINUATION reply that produced no output token, returns with finish_reason == "continuation". Each request has the whole RequestConfig budget, and a streamed turn streams every request into the same callback. A request that fails ends the call with nothing committed, as does a stop or cancel before the last reply\'s finish reason; the replies already received are added to cumulative_cost. Continuation is exercised against a local mock: a live CONTINUATION reply has not been observed for this release. GEMINIOpenAIServiceEndpoint does not continue.','Gemini 4 Argon also thinks for minutes: on a non-streaming call "The server closes the connection after 10 minutes", on a stream "The server closes the stream after 20 minutes", and Google advises "Set your HTTP read timeout to 20 minutes" (long decode). A chatrequest! or respond call to a model whose id starts gemini-4-, on either endpoint, takes request_timeout, stream_idle_timeout and total_deadline of 1200 seconds while no RequestConfig of yours is set in any channel; one you set replaces them as a whole (Timeouts & Retries). On the Interactions API, a long answer needs a background request (Background requests).']],["Prompt caching","gemini_caching",['Gemini caches repeated prompt prefixes on its own: "Implicit caching is enabled by default for all Gemini 2.5 and newer models", and "We automatically pass on cost savings if your request hits caches", for a prompt of at least the model\'s minimum — 4,096 tokens on Gemini 4 Argon, 3.8 Flash, 3.6 Flash and 3.1 Pro Preview, 2,048 on Gemini 2.5 Flash and 2.5 Pro (context caching); Google gives "no cost saving guarantee" (context caching on generateContent). A cache hit is counted in cached_tokens, part of prompt_tokens (First call), and UniLM bills it at the cached-input rate and the rest of the prompt at the input rate, with no premium for writing the cache (Cost and usage). A Chat sends its whole conversation each turn, so the next turn starts with the previous one\'s parts while the system messages and the earlier turns stay as they were; on Gemini 4, "Gemini caches the full previous request only if the new request adds at least 2,050 tokens" (context caching). Explicit caching — cached contents, created ahead and named in a request — is an API of its own that UniLM does not wrap, so prompt_cache_options has nowhere to go and is refused, on a Chat and a Respond (Limits and refusals).']],["Cost and usage","gemini_cost",["estimated_cost prices a result with the row of the table below for the model that served it (First call), and cumulative_cost adds up the calls of a Chat. Of the usage, it bills the cache hits at the cached-input rate, the rest of the input — a tool's input included — at the input rate, and all the output, thinking included, at the output rate (pricing). Every rate is then multiplied by each factor that applies:","Audio input bills at the input price the page lists for audio, at the same factors: the model's own audio price where its table lists one apart — per 1M tokens, $0.50 on gemini-3.1-flash-lite, $1.00 on gemini-3-flash-preview and gemini-2.5-flash, $0.30 on gemini-2.5-flash-lite — and otherwise the row's input rate, since an input price that names no modality, or names audio among others, is every modality's. A cache hit bills at the cache-hit rate, and on those four models the audio Gemini reports among the cached tokens — cacheTokensDetails, read as cached_audio_tokens — bills at the cached-audio price their tables list apart: per 1M tokens, $0.05 on gemini-3.1-flash-lite, $0.10 on gemini-3-flash-preview and gemini-2.5-flash, $0.03 on gemini-2.5-flash-lite. Three cases are estimated at 0.0, with one warning per model and endpoint: audio on a model the page prices without audio (the image models) or does not list, audio in the output, and a cache hit on one of those four models whose usage reports more cached tokens than text tokens and cached audio together, so that how its hits split between the two cache prices is unknown. On GEMINIOpenAIServiceEndpoint, a result's tier and its audio are priced as The OpenAI-compatible endpoint says.","A reply that names a tier other than standard, flex and priority is estimated at the standard rates, with one warning per model and tier. A model with no row, any other id included, is estimated at 0.0, with one warning per model id: pass estimated_cost a pricing table that holds its row, or add the row to DEFAULT_PRICING. A failure costs 0.0, since it carries no usage. How a stream reports its usage is on Streaming, and a continued turn's on Long generations. cumulative_cost is a lower bound of the bill: it adds nothing for an attempt UniLM retried, a stream Google ended with an error, or an unstreamed reply UniLM could not decode (Cost Tracking), and it does not price the fees of Google's hosted tools (Hosted tools).",'The rows are Google\'s list prices for the standard tier as checked on 22 October 2026. The prices of Gemini 4 Argon hold "through November 30, 2026", and those of Gemini 3.8 and 3.6 Flash "through December 31, 2026", after which Google lists higher ones (pricing): check Google\'s page before relying on an estimate.',"Recorded on 25 October 2026 on gemini-3.8-flash with UniLM's development branch after 0.26.0 and the Gemini API at v1beta."]]]},{url:"/providers/gemini/interactions/",sections:[["The Interactions API",null,['respond with service=GEMINIServiceEndpoint sends a Respond to Google\'s Interactions API and returns a ResponseSuccess whose response is the interaction, its steps read into the output that output_text, function_calls and reasoning_summaries read. Google stores an interaction "By default", so a later request can continue it with previous_interaction_id; "You can opt into stateless behavior by setting store=false" (Interactions overview). A Respond field with no Interactions counterpart is refused before the request is sent (Limits and refusals).']],["First interaction","gemini_interactions_first",["respond takes the input and the request's fields as keywords, and output_text reads the answer; with no model it takes the default model named at the top of the start page:",'response.model is the model that served the interaction, and the one estimated_cost prices; token_usage reads the interaction\'s usage in the shape every result shares: prompt_tokens is its total_input_tokens and total_tool_use_tokens, completion_tokens its total_output_tokens and total_thought_tokens, reasoning_tokens the thought tokens, cached_tokens its total_cached_tokens, prompt_audio_tokens the audio among the input, cached_audio_tokens the audio among the cached tokens (cached_tokens_by_modality), and service_tier the interaction\'s service_tier, the tier that billed it. They are priced as on generateContent (Cost and usage). respond returns an interaction whose status is "failed" as a ResponseFailure, and one that is "completed", "requires_action", "incomplete", "in_progress" or "cancelled" as a ResponseSuccess, whose status says which; get_response and cancel_response return an interaction they read the same way (Background requests).']],["Conversations","gemini_interactions_conversations",['previous_response_id continues a stored interaction: it goes as previous_interaction_id, and Google holds the conversation so far, so the request sends only the new input. In this mode, Google says, "the server automatically manages the conversation state, including all thought blocks and signatures" (thinking):','Google adds that continuing this way helps its cache: "Using previous_interaction_id (stateful) to continue conversations allows the system to more easily utilize implicit caching for the conversation history" (Interactions overview). With store=false Google stores no interaction to continue — it "prevents using previous_interaction_id for subsequent turns" (Interactions overview) —, so each request carries the whole conversation as its input (Inputs), and Google asks that its thought steps go back "exactly as they were received from the model" (thinking). UniLM sends a step in the Interactions shape as it is; sending a result\'s output back as the next input is untested.']],["Inputs","gemini_interactions_input",["The input is a string, or a list of steps, which respond writes from the items it is given:","A web URL, a file id and a cache breakpoint have no counterpart here, and are refused (Limits and refusals)."]],["Thinking","gemini_interactions_thinking",['A Reasoning sets the interaction\'s thinking: its effort becomes generation_config.thinking_level, checked against the first column of the thinking table — on this API a Gemini 2.5 model takes its levels too — and summary="auto" becomes thinking_summaries, which asks for summaries of the thoughts. A Reasoning with another summary, a context or a mode is refused (Limits and refusals). "By default, only the final output is returned. You can enable thought summaries with thinking_summaries" (thinking):','Each thought is a thought step in response.output, with its summary and its signature, which Google describes as "An encrypted representation of the model\'s internal reasoning state. Always present, even when the model performs minimal reasoning"; a thought may hold "only a signature with no summary", as after "Simple requests, where the model didn\'t reason enough to generate a summary" (thinking), and reasoning_summaries is then empty. Continuing with previous_response_id leaves the signatures with Google (Conversations). max_output_tokens bounds the thinking with the answer: "If the model hits this limit while reasoning, it stops generating with status "incomplete"" (thinking). The thinking bills as output (Cost and usage).']],["Tools","gemini_interactions_tools",['A function tool — a FunctionTool from function_tool, or a CallableTool holding one — goes out as {"type": "function", "name", "description", "parameters"}. A FunctionTool with async, allowed_callers, defer_loading or output_schema set is refused, and so is any tool that is neither a FunctionTool nor a Dict; a Dict goes as it is (Hosted tools). tool_choice becomes generation_config.tool_choice.allowed_tools:','Google\'s modes on this API: auto — "Model decides whether to call a function or respond directly"; any — "Model is constrained to always predict a function call"; none — "Model is prohibited from making function calls"; validated — "Model ensures function schema adherence" (function calling). That page states schema adherence for validated and not for any. The other tool_choice builders select tools this API does not have, and are refused (Limits and refusals).','A function call is a function_call item of response.output, its call_id made by Google and its arguments a JSON string ("{}" for a call without arguments); function_calls reads them, and an interaction that waits for their results has the status "requires_action". A tool_result(call_id, name, output) item answers one: it becomes a function_result step, the output sent as its JSON object when it is one and as {"result": output} otherwise. The tool_loop that takes an input or a Respond runs the calls and sends their results, each turn continuing the last with previous_response_id, until the model answers in text:',"The loop takes the same cancel and tool_concurrency keywords as on generateContent, and stops as Tool Calling describes. To answer a call yourself, send the result in a request that continues the interaction:"]],["Hosted tools","gemini_hosted_tools",['Of the tools Google runs for the model on this API, UniLM builds three: gemini_google_search ({"type": "google_search"}), gemini_code_execution ({"type": "code_execution"}) and gemini_url_context ({"type": "url_context"}). Pass them in tools:','A hosted tool\'s work is in response.output as the steps Google sent — google_search_call and google_search_result, code_execution_call and code_execution_result, url_context_call and url_context_result — each a Dict with Google\'s fields, beside the message items that hold the answer: read the queries, results and code there. Google puts a grounded answer\'s sources in "inline annotations" on its text (Grounding with Google Search), and the message UniLM builds from a model_output step keeps them on its text, streamed or not, where url_citations reads the url_citations, as the last block above does. Their start_index and end_index count bytes of the text, "measured in bytes" (Interactions reference). Another tool the API takes — Google\'s error reference names mcp_server, file_search, google_maps and computer_use among its tool types (Interactions errors) — goes as a Dict in the API\'s own shape, which UniLM sends as it is. The input a tool read counts as prompt tokens (First interaction), but the fees of the tools themselves are not priced: Google search grounding, for one, has "5,000 free search requests per month (shared across all Gemini 3 and newer models), then $14 per 1,000 requests" (pricing).']],["Structured output","gemini_interactions_structured_output",['A text format becomes the top-level response_format: json_schema_format sends {"type": "text", "mime_type": "application/json", "schema": …}, and json_object_format the same without a schema. Only the schema is sent, not the format\'s name, description or strict; verbosity is refused (Limits and refusals).','Google\'s page for this API lists the schema keywords it does not enforce: minProperties and maxProperties, minLength and maxLength, and uniqueItems, contains, minContains and maxContains "are not enforced during constrained decoding and are ignored by the server" (structured output): check them on the parsed answer.']],["Streaming","gemini_interactions_streaming",["With stream=true, or the do-block form, respond returns a Task, and fetch gives the same result as an unstreamed call. The callback receives the answer's text as it arrives, then the assembled ResponseObject:","Google streams each step as step.start, step.delta and step.stop events, then interaction.completed with the interaction's status and usage (streaming). UniLM rebuilds each step from its events, in order — the text of a model_output step, the arguments of a function_call, the signature and the summaries of a thought — and reads the result's output from them as an unstreamed decode reads the interaction's steps: a streamed request with tools ends with the status \"requires_action\" and its function_calls, as an unstreamed one does. Only answer text reaches the callback; the thought summaries are read afterwards with reasoning_summaries. Several model_output steps in a row — with thoughts between them or not — are one message, its text their texts joined with no separator, as Google's SDK reads them: it continues \"across thought steps and empty model_output steps when aggregating text from the final model turn, while still stopping at user_input and tool call/result boundaries\" (python-genai 180c3453). A tool's step or a user_input step ends the message, and output_text joins the messages with a newline; this holds for an unstreamed interaction too."]],["Background requests","gemini_background",['With background=true, the API "immediately returns an interaction ID", and the interaction runs on the server (background execution). get_response and cancel_response take service=GEMINIServiceEndpoint, and read or cancel it by its id; delete_response deletes it. Each makes one attempt (Timeouts & Retries), and a poll is your loop:','A background request needs a stored interaction — "Passing background=True with store=False returns a 400 error" (background execution) — so respond refuses the pair before sending it (Limits and refusals). Gemini 4 Argon writes more than 65,536 output tokens only in the background: Google\'s limit with background: false is "65,536 tokens. Values greater than 65,536 return a 400 error", and a background request takes "Your max_output_tokens, up to 1,048,576 minus your input" (long decode), so UniLM refuses a larger max_output_tokens on gemini-4-argon without background=true. A background interaction read right after it was created has answered 403 (permission_denied) for a few seconds before it became readable (observed on 20 August 2026; Google\'s pages do not mention it): retry such a read in your poll before taking it for a permission error.',"Google's Interactions API reads, cancels and deletes an interaction, and lists no input items (Interactions API), so list_input_items throws ArgumentError for this endpoint before sending anything; the input is the input you sent. compact_response and count_input_tokens send nothing for this endpoint, and return a ResponseCallError."]],["Request options","gemini_interactions_options",['A body that is not an interaction — a 200 without a non-empty id or status, which the API reference marks "required" — is a ResponseCallError from respond, get_response and cancel_response, never an empty success. The faults an interaction records in its errors array reach response.error, the first of them, and response.raw["errors"] holds them all. How a call is retried, and the daily quota that is not, is on When something fails.',"Recorded on 25 October 2026 on gemini-3.8-flash with UniLM's development branch after 0.26.0 and the Gemini API at v1beta."]]]},{url:"/providers/gemini/media/",sections:[["Images, speech, embeddings & the compatible endpoint",null,[]],["Image generation","gemini_images",['With service=GEMINIServiceEndpoint, generate_image and edit_image call generateContent on an image model, gemini-nano-banana-2.1 unless the request names another, with image output (responseModalities: ["IMAGE"]). The request\'s model field stays "" until the request is sent, and the model goes in the URL. Size the image with two fields of Google\'s:',"They go in generationConfig.imageConfig, and safety_identifier in the request label (Request options). A request returns one image, so n takes only 1, and the image fields generateContent has no counterpart for — size, quality, background, output_format, output_compression, moderation, and an edit's mask and input_fidelity — are refused before the request (Limits and refusals). An image request is not recorded, so its output here is quoted from a live run:","The reply's image parts are the result's images, in order, each as base64 in b64_json, which image_data lists and save_image decodes into a file; their MIME type is in the reply, result.response.raw. Text the model sends with an image is its revised_prompt, and the interim images of the model's thinking are not results. A reply with no image — a filter stopped it, say — is an ImageCallError naming the finish reason (IMAGE_SAFETY, NO_IMAGE, …), and a reply has no creation time, so result.response.created is the time it arrived. \"All generated images include a SynthID watermark\" (image generation).","An edit sends its input images inline, before the prompt, and decodes the same way:","token_usage reads the reply's usage as a Chat's (First call), its thinking counted as output; the image is output too — 1,120 of the generation's tokens above, by the candidatesTokensDetails of its raw usage, as Google says \"Output images at 1K (1024x1024px) consume 1120 tokens\" (pricing). UniLM does not price images: estimated_cost throws ArgumentError for an image result unless you pass model=, which it prices by a pricing row of your own, and estimates at 0.0, with a warning, where no row names it. The options every provider shares are on Image Generation."]],["Audio","gemini_audio",['speak with service=GEMINIServiceEndpoint reads text aloud through Gemini TTS: one generateContent request to gemini-3.8-flash-tts, unless model names another, in the voice Kore, unless voice names another. Gemini 3.8 TTS takes "a prebuilt voice name, an Extended Voice Library ID, a custom Voice design ID (voice_...), or a Voice replication ID (voice_..., or optional stateless voicekey_...)" (speech generation): one of the 30 studio voices that page lists goes as a prebuilt voice, any other as the request\'s voice. The Extended Voice Library\'s hundreds of voices are listed by GET /v1beta/voices, not by UniLM, so a voice is sent as given, and Gemini answers a name it does not have. UniLM asks for 24 kHz, 16-bit mono PCM and returns a SpeechSuccess: a WAV file with response_format="wav", the default, which UniLM wraps in a 44-byte header, or the samples with "pcm" (content_type "audio/pcm"). Speech is not recorded, so its output here is quoted from a live run:','"Gemini 3.8 TTS treats the text field strictly as a verbatim transcript", and the delivery goes in the speech style, speech_metadata.style: "emotions, delivery style, prosody, pacing, and volume" (speech generation). instructions become that style, and the pace is part of it ("speaking slowly"): Gemini TTS has no speed, so any speed is refused, as are a blank voice, a format other than "wav" and "pcm" and an empty input (Limits and refusals).',"A reply whose candidate did not finish with STOP — MAX_TOKENS, SAFETY, … — or that has no candidate, a blocked prompt, is an AudioFailure with status 200 and the reply as response; an HTTP error status is an AudioFailure too. A reply without audio, a timeout and a cancel are an AudioCallError. Speech is not priced: token_usage and estimated_cost throw for a SpeechSuccess. speak refuses GEMINIOpenAIServiceEndpoint, whose wire has no speech route.","transcribe refuses both endpoints: neither has the transcription capability. Google serves transcription with a model of its own, gemini-3.5-transcribe (transcribe), which UniLM does not wrap. To get the words of a clip, send it as an AudioAttachment and ask for them, as Attachments does. The verbs every provider shares are on Audio API."]],["Embeddings","gemini_embeddings",['UniLM embeds text with Gemini through GEMINIOpenAIServiceEndpoint, on Google\'s OpenAI-compatible /v1beta/openai/embeddings; GEMINIServiceEndpoint has no embeddings, and Google\'s native embedding methods are not wrapped. The default model is gemini-embedding-2, which takes "Input token limit 8,192" and an output dimension that is "Flexible, supports: 128 - 3072, Recommended: 768, 1536, 3072" (Gemini Embedding 2); UniLM sends dimensions unchecked.','gemini-embedding-2 reads a task from the text itself — "You cannot use the task_type field for the gemini-embedding-2 model. Instead, include the task as an instruction in your prompt" (embeddings) — so task writes Google\'s prompt in front of each text: "task: search result | query: " for :search_query, "title: … | text: " for :document, with an EmbeddingInput\'s title (none without one), and the others as Embeddings lists them. A text without a task goes as it is. Google normalizes every size on gemini-embedding-2: "While the default 3072-dimension embeddings are always normalized, Gemini Embedding 2 also auto-normalizes truncated dimensions (e.g., 768, 1536)"; only on gemini-embedding-001 "you must manually normalize non-3072 dimensions" (embeddings).','The endpoint takes text: an EmbeddingInput with an image or a sound clip is refused before the request (Limits and refusals). Its reply carries no usage, so result.usage is nothing and estimated_cost gives 0.0, with one warning per model, though Google lists a "Text input price" for the model (pricing). The reply leaves the index out of its first row, which UniLM reads as row 0. gemini-embedding-001 is served until its shutdown on "May 14, 2028", with gemini-embedding-2 the replacement Google names (deprecations), and "The embedding spaces between gemini-embedding-001 and gemini-embedding-2 are incompatible" (embeddings): re-embed your data to move.']],["The OpenAI-compatible endpoint","gemini_compatible",['GEMINIOpenAIServiceEndpoint speaks Google\'s OpenAI-compatible endpoint, https://generativelanguage.googleapis.com/v1beta/openai/chat/completions, with the key as Authorization: Bearer. Google says its support "is still in beta while we extend feature support" (OpenAI compatibility). A Chat reaches the same models, with the default model of GEMINIServiceEndpoint:',"There UniLM is an OpenAI-compatible client, and of these pages only these rules hold:","Recorded on 25 October 2026 on gemini-embedding-2, through Google's OpenAI-compatible endpoint, with UniLM's development branch after 0.26.0 and the Gemini API at v1beta."]]]},{url:"/providers/ollama/embeddings/",sections:[["Embeddings",null,["An Embeddings request on OllamaEndpoint goes to Ollama's /api/embed, which \"returns L2‑normalized (unit‑length) vectors\" (embeddings). It holds one item or several — a text, an EmbeddingInput, an image or a sound clip — and names an installed embedding model, since Ollama has no default; embeddingrequest! fills its vectors in place. The usage counts the input tokens, Ollama's prompt_eval_count, and a local model's embeddings cost 0.0 unless you price the model, as its chats do (Cost and usage). The request carries the endpoint's keep_alive, options and runner (Options)."]],["Embeddings with EmbeddingGemma 2","ollama_embeddings",["EmbeddingGemma reads a short prompt that says what a text is for, and Ollama adds none: the Modelfile template of embeddinggemma-2:740m-q8_0 is the text alone, {{ .Prompt }}, as ollama show --modelfile printed it on 25 October 2026. task writes the prompt. Documents take task = :document, with a title each when they have one; a search takes task = :search_query:","An EmbeddingGemma request without a task is an ArgumentError before anything is sent; task = :none sends the text as it is. A title goes only with :document, and an empty or whitespace-only title is none. The text the model reads, for each task — the prompts of EmbeddingGemma 2's model card, written in front of the text:","The same prompts hold for EmbeddingGemma v1 (embeddinggemma, its model card) and on any other service that serves EmbeddingGemma; a server that writes the prompts itself takes task = :none. A model whose prompts UniLM does not know takes task = :none or no task, and a title is refused for it (Limits and refusals).",'Smaller vectors. EmbeddingGemma returns 768 numbers, and EmbeddingGemma 2\'s card says "The supported dimensions are 768, 512, 256, and 128", as v1\'s lists "smaller options available (512, 256, or 128)": dimensions asks for one of these, and any other is refused before the request. The shorter vector still has unit length:',"A reply row that is empty, all zeros or holds a value that is no finite number is no embedding: the call is an EmbeddingCallError naming the row, not a vector that would still compare and index. The concepts every provider shares are on Embeddings.","Measured on 21 October 2026 with Ollama 0.40.6 on an Apple M4 Max, through UniLM. Do the task prompts help? On SciFact (BEIR: 300 claims searched against 5,183 abstracts), claims embedded with :search_query and abstracts with :document and their titles, against the raw texts (task = :none), 768 dimensions; paired bootstrap over the claims, 10,000 resamples, 95% intervals. The question was written down before the run: the prompts help where the interval lies above 0.","One public dataset, one run per condition. On a 24-document, 12-query set of our own, the raw texts came out ahead by about one query on every model — for v1 refuting the comparison written down before that run — a set too small to tell the two apart. For text, 740m-q8_0 and 270m-q8_0-text returned identical vectors: the 0.3 GB build embeds text as the 1.3 GB one does."]],["Images and sound","ollama_embedding_media",["An ImageAttachment or AudioAttachment is an item of its own, and EmbeddingInput(text, image) embeds a text with its picture as one item, EmbeddingInput(text, clip) a text with its sound: Ollama's /api/embed takes an item \"with any of text (string), image (base64-encoded bytes), audio (base64-encoded bytes)\" on models that embed media (API reference). An item holds an image or a sound clip, not both: Ollama passed an item's media to the model in a random order — ten requests of one item holding a text, a picture and a clip gave embeddinggemma-2:740m-q8_0 two different vectors (8 and 2 of the 10, largest difference 0.0183; Ollama 0.40.6, 21 October 2026) — so such an item is refused before any request: send the image and the audio as separate items. Texts, images and sounds land in one space, so a word can find a picture:",'The picture lies nearest to "a red circle" and the recording — "The secret word is banana" — nearest to "banana". Media take no prompt; the text of a mixed item does, and both of its parts shape its vector (Evidence below). Ollama\'s EmbeddingGemma 2 page describes "a 270M parameter text backbone" with "selectively loadable vision (170M) and audio (300M) encoders", and its tags carry those sizes: the 270m builds embed text, the 440m ones images too, the 570m ones sound too, and the 740m ones all three. Images and sound were measured on 740m-q8_0 and 740m-mxfp8; the 440m and 570m builds are untested. Only Ollama embeds media: every other service embeds text, and refuses media before the request.','embeddinggemma-2:740m-q8_0, Ollama 0.40.6, Apple M4 Max, 21 October 2026. Images and sound: the red-circle picture scored 0.754 against "a red circle" and 0.633 against "a blue square"; the recording 0.792 against "banana" and 0.626 against "apple". A text with its media as one item: "a red circle" with the picture gave a vector of its own, cosine 0.870 with the text alone and 0.903 with the picture alone (0.752 between the two); "banana" with the recording 0.847 and 0.957 (0.794) — on 740m-mxfp8 0.857 and 0.907, 0.845 and 0.958 — so neither part was dropped.']],["Long inputs","ollama_embedding_window",['EmbeddingGemma 2 has an "8K token context window" (its page), and UniLM asks Ollama for that window with each of its requests unless the endpoint sets num_ctx or num_batch itself (Options). An input longer than the window is an EmbeddingFailure with HTTP 400, not a vector of part of it: split long documents into chunks.','The 440m and 570m builds were not measured. truncate=true on the endpoint lets Ollama cut the end of an input that does not fit instead: the API reference\'s truncate "truncates the end of each input to fit within context length", and UniLM sends false unless the endpoint says otherwise.',"Ollama reports a 262,144-token context for the GGUF builds of EmbeddingGemma 2, those its :llamacpp runner serves, while the longest input they take follows num_batch (Evidence below). So an embeddings request — and a load_model — for an EmbeddingGemma 2 model carries num_ctx and num_batch of 8192 unless the endpoint sets either, and the window is part of a recording's key. An endpoint that sets num_ctx sends it instead of the 8,192-token window, and the GGUF builds then keep Ollama's default batch, which refused the long inputs measured: embed through an endpoint that sets neither num_ctx nor num_batch.","Ollama 0.40.6, Apple M4 Max, 21 October 2026. The MLX build, 740m-mxfp8, loads at 8,192 tokens; at Ollama's default batch the GGUF builds measured refused long inputs with HTTP 413 — 740m-q8_0 anything over about 2,037 tokens — and so they did through an endpoint that set num_ctx alone."]],["Local retrieval","ollama_retrieval",["Find the passages that answer a question, on your own machine: embed the documents once with task = :document, each question with task = :search_query, and rank by the dot product — EmbeddingGemma's vectors have unit length, so it is the cosine:","The first question finds the refund policy, the second the returns policy. The documents are embedded once; each search embeds only its question.","Recorded on 21 October 2026 on embeddinggemma-2:740m-q8_0 with UniLM's development branch after 0.24.0 and Ollama 0.40.6, on an Apple M4 Max with 64 GB."]]]},{url:"/providers/ollama/runtime/",sections:[["Runtime & model management",null,[]],["Options","ollama_options",["What would be a command-line flag or a Modelfile line in Ollama is an argument of OllamaEndpoint: the endpoint's requests carry it, and the constructor checks it.",'Any other keyword is refused when the endpoint is built, its ArgumentError naming the keywords the endpoint takes, and so is a value that breaks a rule above; a value of the wrong type is Julia\'s own error instead, such as a TypeError for truncate=1 or runner="mlx"; a request made through the endpoint meets no further check of these arguments. UniLM.encode_request returns the body chatrequest! sends, with no request:','The Chat\'s temperature, top_p, seed, stop, presence_penalty, frequency_penalty and max_completion_tokens, else max_tokens (as num_predict), join the endpoint\'s options, which hold none of those names, so no option is set in two places. Unset options keep the model\'s own defaults: Gemma 4\'s page gives temperature=1.0, top_p=0.95 and top_k=64 (Gemma 4). Of the options Ollama\'s API reference lists, OllamaOptions has no penalize_newline or numa, and the endpoint refuses them as unknown keywords: Ollama 0.40.11 does not read them, and its log says "invalid option provided" and the request goes on without them (observed on 25 October 2026). draft_num_predict caps the speculative draft tokens per step of a model that has a draft model: "Set to 0 to disable speculative drafting" (Modelfile). typical_p is one the reference marks: "typical_p is deprecated and may be removed in a future release"; Ollama 0.40.11 still reads it per request, and its log says "deprecated option provided" (observed on 25 October 2026). respond, compact_response, FIM and transcription use Ollama\'s OpenAI-compatible routes, which carry none of keep_alive, the options or runner. Decision requests (ask) carry the endpoint\'s keep_alive and runner and none of its options (Models).']],["Runners","ollama_runners",["Ollama runs a model on one of its runners, which UniLM names :mlx (Apple Silicon, for models stored as safetensors), :llamacpp and :ggml (for GGUF models). running_models reports the runner serving each loaded model, and list_models the one the model's listing names, the runner to pin, which can differ: a GGUF model listed as :ggml is served by :llamacpp. model_info reports :llamacpp or :mlx, and nothing for such a legacy GGUF model (Ollama 0.40.6). Unset, the server chooses the runner. OllamaEndpoint(runner=:mlx) — or :llamacpp, :ggml — pins one, and Ollama matches it against the runner the model's manifest names, the one list_models reports as OllamaModel.runner:","The runner decides what the window does:",'To give a loaded :mlx model another window, unload_model it first. A model with vision loads with at least 2,048 tokens whatever num_ctx asks: by Ollama 0.40.6\'s source its scheduler raises a smaller one ("multimodal models require at least 2048 context"), and embeddinggemma-2:740m-q8_0 asked for 1,024 loaded with 2,048 on :llamacpp. The other OllamaOptions are passed through unchanged; their effect on :mlx is not verified.',"Measured with Ollama 0.40.6 on an Apple M4 Max: gemma4:e4b on MLX, loaded with num_ctx=4096, kept 4,096 after a request for 8,192 and answered a 10,842-token prompt, reading a code word from its first sentence; qwen2.5-coder:1.5b-base on llama.cpp (listed as ggml) loaded again for 8,192 and refused a 5,407-token prompt on 4,096 with HTTP 400. No model ran on the ggml runner. Runner pins, 21 October 2026: :llamacpp on kev:0.8b-q8_0 answered and running_models reported :llamacpp; :mlx and :ggml on it, and :llamacpp on tev1:0.8b, were HTTP 400 no compatible manifest found for runners: <runner>, also while the model was loaded, and so was every runner but the listed one on each of the nine decision models measured. The 2,048-token floor of a model with vision was measured on 22 October 2026 (and on Ollama 0.40.7 on Linux)."]],["Models","ollama_models",["The model-management verbs return typed results like every other call: an OllamaSuccess holding what the verb reports, an OllamaFailure with the HTTP status and Ollama's error body (404 for a model that is not installed), or an OllamaCallError for a call that brought no usable reply — no server, a timeout, a cancel, a malformed reply. They are not recorded, so their output here is quoted from a live run:","pull_model downloads a model and delete_model removes one from the disk; this page ran neither:","Each takes config and cancel, and an empty name is an ArgumentError before any request. list_models needs its service: without one it lists the models of the Decisions chapter's default provider, while the other verbs default to OllamaEndpoint(). A listing's OllamaModels hold each model's size on disk, family, parameter_size, quantization, context_length, the runner and format the listing names and its capabilities; OllamaModelInfo adds the thinking levels and the Modelfile parameters, and an OllamaRunningModel holds the memory a loaded model takes, the window it loaded with, its runner and when it unloads (expires_at).","load_model loads a model that completes text with an empty chat request, and any other with an empty embeddings request, so the first real request finds it in memory; Ollama's API loads a model \"If the messages array is empty\" (API reference). It sends what the model's own requests send: a chat model's load the endpoint's options and shift, an embedding model's those options (EmbeddingGemma 2 with its 8,192-token window), and a decision model's no options at all, as its decision requests carry none. So an endpoint's num_ctx, or any other option, does not apply to a decision model, neither when it is loaded nor when it is asked: the server's default context applies (73,728 tokens for kev:0.8b-q8_0 on Ollama 0.40.6, an Apple M4 Max). Through OllamaEndpoint(num_ctx=4096), the first ask after load_model(\"kev:0.8b-q8_0\") took 0.036–0.049 s in five cycles, and an ask without it, which loads the model, 0.81–1.36 s. Witnessed on Ollama 0.40.6 (21 October 2026) for a chat model (gemma4:e4b), embedding models (embeddinggemma and EmbeddingGemma 2) and one decision model (kev:0.8b-q8_0); other decision models and other kinds of model are untested. One total_deadline bounds both of a load's requests, the show and the load, and an endpoint with keep_alive=0 is refused, since Ollama reads such a load as an unload. unload_model sends an empty chat request with keep_alive 0, \"a model will be unloaded from memory\" (API reference), which works for every kind of model.","pull_model makes one attempt, never retried: its response headers must arrive within the RequestConfig's request_timeout and remaining total_deadline, and after that only stream_idle_timeout bounds the download, the longest gap between bytes. A pull that fails after the 200 has been sent, such as an unknown tag, fails in-band: the call is an OllamaCallError holding Ollama's message (pull model manifest: file does not exist).",'Measured on Ollama 0.34.4 (Apple M4 Max, 64 GB; 10 runs per text cell, 6 for the prime question, 5 per media cell). Both E2B (7.2 GB) and E4B (9.6 GB) called tools correctly in 10 of 10 runs and named the colour in 5 of 5; E4B named the spoken word in 5 of 5, E2B in 4 of 5. With thinking off, E2B misjudged "Is 391 prime?" in 6 of 6 runs and E4B answered correctly in 6 of 6. E2B decodes faster (86 against 54 tokens per second) but thought in 68 of 80 runs where E4B thought in 15, so E4B answered sooner on short prompts. The pages of this entry and UniLM\'s own tests use E4B.']],["When something fails","ollama_failures",["chatrequest!, respond, embeddingrequest!, fim_complete and transcribe return what the server or the network did as a typed result, and do not throw it (Results): a failure holds Ollama's HTTP status and, as response, the body that came with it, {\"error\": …} with the message; a call error holds the text of an exception as error and the exception as cause. UniLM sends a request again after a transient status — 408, 429, 500, 502 to 504, 520 to 524 and 529 — or a failed connection, as often as the call's RequestConfig allows, and then returns the last answer (Timeouts & Retries); a streamed request is sent again only while none of its callbacks has run, and a pull makes one attempt. RequestConfig(max_attempts=1) reports an unreachable server at once. Ollama brings no RequestConfig of its own, for decision requests either: every call takes the field defaults unless the call, a scope or set_default_config! sets a configuration, so a model that takes minutes to load may need a longer bound.",'Ollama runs one request at a time per model unless OLLAMA_NUM_PARALLEL says otherwise — "The maximum number of parallel requests each model will process at the same time, default 1" — and queues the rest (FAQ). A streamed call receives nothing until its turn comes, nor while Ollama loads its model, so with many long streams in flight, or a slow machine, raise stream_idle_timeout (Timeouts & Retries); it bounds the wait for the first byte too.']]]},{url:"/providers/openai/chat_completions/",sections:[["Chat Completions",null,["On OPENAIServiceEndpoint a Chat goes to OpenAI's Chat Completions API as its own JSON, JSON.json(chat), which writes each field the Chat sets under the API's name: a stream=true request without stream_options also asks for the stream's usage, a spoken reply goes back by its audio id, and only max_tokens is renamed, to max_completion_tokens. Before anything is sent, the request is checked against OpenAI's rules and the model's row in the rule table, and a request that breaks one is refused (Limits and refusals)."]],["Tools on Chat Completions","openai_chat_tools",['Each Tool in tools goes out as a function tool with its name and, where its FunctionSignature sets them, its description, parameters and strict flag. A function\'s name "Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 64" (Create chat completion); UniLM sends a name as given, and mcp_tools, for this endpoint or with no service, advertises an MCP tool under a name of at most 64 characters, a longer one cut and marked with a hash of its MCP name (MCP). tool_choice is sent as given: "auto", "none", "required", or UniLM.GPTToolChoice(func=:get_weather) for {"type": "function", "function": {"name": "get_weather"}}. Strict mode makes the calls "reliably adhere to the function schema", and OpenAI recommends "always enabling" it; its schema needs additionalProperties: false on every object and every field required, and a request whose strict schema misses them "will be rejected with details about the missing constraints" (function calling). A Tool whose FunctionSignature sets no strict goes without one, and "Chat Completions requests remain non-strict by default"; the same tool given to a Respond meets the Responses default instead (Tools).','A Chat with tools sends parallel_tool_calls: false unless it sets another value: the model may otherwise "call multiple functions in a single turn", and false "ensures exactly zero or one tool is called" (parallel function calling). Set parallel_tool_calls=true to let it call several at once. A model of the rule table takes tools on Chat Completions only at the efforts its Chat Completions tools column lists, so a Chat on the default model names that effort; with tools, OpenAI\'s tool path is the Responses API (Tools).',"tool_loop! runs the calls and sends their results back until the model answers in text. Here the model needs one call per city, and makes them one turn at a time:",'An assistant turn that called tools goes back with its tool_calls, and each tool message answers one by its tool_call_id. A turn whose calls OpenAI finished with another reason than "tool_calls" — "length", say — runs none of them, and tool_loop! stops with completed=false. A streamed turn\'s calls reach on_tool_call (Streaming), and the loop every provider shares is on Tool Calling.']],["Structured output","openai_structured_output",['response_format is sent as given. A JSON Schema format — UniLM.json_schema(name, description, schema; strict), or ResponseFormat around a UniLM.JsonSchemaAPI — asks for a reply that follows the schema: with strict=true, "the model will always follow the exact schema", "Only a subset of JSON Schema" being supported then (Create chat completion, response_format). A strict schema follows the rules of strict tools above: "additionalProperties: false must always be set in objects", and "All fields must be required" (structured outputs). ResponseFormat() asks for any JSON object, "An older method of generating JSON responses", and the model "will not generate JSON without a system or user message instructing it to do so".',"The reply's text is the JSON document. A Respond asks for the same with text (Structured output on Responses), and the formats every provider shares are on Structured Output."]],["Attachments","openai_media",['A user message\'s attachments go out as content parts after its text, in their order: an ImageAttachment (PNG, JPEG, GIF or WebP) as an image_url part holding a base64 data URL, with its detail when it sets one; an AudioAttachment (WAV or MP3) as an input_audio part; and a DocumentAttachment (PDF) as a file part, with its file name and a data URL. A message with empty text sends the parts alone. detail is "low", "high", "original" or "auto", the default: "Supported values depend on the model" (images and vision). Chat Completions "accepts only PDF files as file content parts", which take no detail (file inputs).',"","The one-page PDF holds one sentence:","UniLM sends every kind of attachment to every model and checks no size or page count: the API answers for a model that does not read the kind, and for media past its limits. Which input a model reads is on its OpenAI model page; an audio clip needs an audio model such as gpt-audio-1.5 (Audio in Chat Completions). A Respond takes images and PDFs as parts of its input, and no audio (Input); the attachment types are on Attachments."]],["Audio replies","chat_audio_output",["A model that speaks answers in audio when the Chat asks for it with modalities=[\"text\", \"audio\"] and an audio voice and format; OpenAI's guide uses gpt-audio-1.5 (Audio in Chat Completions). The reply's audio_output is an AudioOutput: the audio's bytes in data, their format as their file signature shows it, OpenAI's id for the audio, expires_at and the transcript, which is also the reply's text.",'The next request sends the audio turn back as its text and "audio": {"id": …}, "Data about a previous audio response from the model", until a minute before the turn\'s expires_at, the Unix time "for when this audio response will no longer be accessible on the server for use in multi-turn conversations" (Create chat completion, the assistant message\'s audio and the reply\'s audio). From then on it sends the turn as its text alone, so that a request built just before the expiry does not arrive after it; a turn whose expires_at is nothing goes by its id. The request\'s bytes therefore depend on the clock, and so does a recording of it (Testing and recordings): recorded while the audio was live, it sends the id and replays only until a minute before the expiry. This page replays recorded replies, and the request below was recorded after the first one\'s expires_at, so it sends that reply as its transcript and replays at any later time:',"The usage counts the audio apart, prompt_audio_tokens of the input and completion_audio_tokens of the output: here the input holds no audio, its first reply having gone back as text, while a reply sent back by its id counts as input audio. estimated_cost bills them at the model's audio rates (Cost and usage). A streamed reply assembles the same audio_output from its chunks, the transcript reaching the callback as text and the expiry coming in the last update; a stream cut between the finish and that update keeps the turn with expires_at == nothing. Speech and transcription of their own are on Audio."]],["Request options","openai_chat_options",["UniLM.encode_request returns the body chatrequest! sends, with no key and no request:","The concepts every provider shares are on Conversations with Chat.","Recorded on 25 October 2026 on gpt-6-sol and gpt-audio-1.5 with UniLM's development branch after 0.26.0."]]]},{url:"/providers/openai/media/",sections:[["Images, audio & realtime",null,[]],["Image generation","openai_images",["generate_image sends an ImageGeneration to OpenAI's Images API, POST /v1/images/generations, and edit_image an ImageEdit to POST /v1/images/edits, as multipart/form-data with each image and the mask as a file. Both take gpt-image-2.5-sunburst unless the request names another model; the request's model field stays \"\" until the request is serialized, so JSON.json(ig) shows the model that goes. OpenAI's options are sent as given, for OpenAI to judge:","The quoted words are from OpenAI's Images reference unless the line names the guide. An image request is not recorded, so its output here is quoted from a live run, at the smallest size and the lowest quality:","",'OpenAI\'s image models "always return base64-encoded images" (Images), which image_data lists and save_image decodes into a file, and the reply repeats the size, quality, output_format and background it used, in result.response.raw. An edit sends the image as a file, with the prompt:',"",'image is a path or a vector of paths, "up to 16 images", and mask the path of an image whose transparent area marks what to change: "The image to edit and mask must be of the same format and size (less than 50MB in size)", and "The mask image must also contain an alpha channel" (image generation). input_fidelity is sent as given; OpenAI\'s reference documents it for gpt-image-1.5 and gpt-image-1-mini and says "For gpt-image-2, omit this parameter". An image or mask path that is no file is refused before anything is sent, as upload_file and transcribe refuse one (Limits and refusals).',"token_usage reads the reply's usage: the prompt's text tokens, and an edit's input image too, as input — 640 image and 26 text tokens in the edit above, by the input_tokens_details of its response.usage — and the image as output. UniLM does not price images: estimated_cost throws ArgumentError for an ImageSuccess unless you pass model=, which it prices by a pricing row of your own. OpenAI bills gpt-image-2.5-sunburst text input at $5, image input at $8 and image output at $30 per million tokens (GPT-Image-2.5 Sunburst): the generation above came to about $0.0033 and the edit to about $0.0085.",'A request is sent again after a transient status, as a Chat is (When something fails), and a cancel of its cancel token, the ambient one unless given, ends it with an ImageCallError whose cause is a UniLMCancelled. A prompt or image the filters stop is an ImageFailure whose response holds OpenAI\'s error, type "image_generation_user_error" and code "moderation_blocked", which OpenAI asks not to send again as it is: "Don\'t automatically retry these errors without modifying the prompt or input images" (image generation). image_data of a failure throws an LLMResultError. The gpt-image-1-mini, gpt-image-1.5 and chatgpt-image-latest models shut down on 1 December 2026, with gpt-image-2.5-sunburst or gpt-image-2.5-flare the replacements (deprecations). A Respond makes images with the image_generation_tool (Hosted tools), and the verbs every provider shares are on Image Generation; every field is in the Image Generation API reference.']],["Audio","openai_audio",['speak reads text aloud through a session of OpenAI\'s Realtime API, not the Speech API: OpenAI\'s tts-1, tts-1-hd and gpt-4o-mini-tts "are deprecated and will shut down on January 6, 2027", and their replacement, gpt-realtime-2.1-mini, "isn\'t a supported model for /v1/audio/speech" (text to speech). UniLM opens wss://api.openai.com/v1/realtime on gpt-realtime-2.1-mini unless model names another, sets the voice, 24 kHz 16-bit mono PCM output and instructions to read the text word for word, sends the text as a user message, asks for a response and collects its audio; instructions follow its own as delivery directions. Realtime models are conversational, and a session\'s instructions "are not guaranteed to be followed by the model" (Realtime client events, instructions).',"The quoted words are from the session's audio.output in OpenAI's Realtime client events.","Speech is not recorded, so its output here is quoted from a live run:",'transcribe uploads an audio file to POST /v1/audio/transcriptions, on gpt-transcribe unless model names another. "Files can be up to 25 MB. Supported input formats are mp3, mp4, mpeg, mpga, m4a, wav, and webm" (file transcription). prompt, keywords and languages give the model context — "Literal terms that may appear in the audio" and "A list of expected input languages" — and gpt-transcribe uses "languages instead of the singular language field" (transcription): UniLM sends a singular language as a one-element languages to a gpt-transcribe model, and as language to the others.','transcript_text reads the text, and raw keeps the JSON reply: the languages gpt-transcribe detected — "When the model can\'t make a reliable language prediction, it returns "languages": []" (file transcription) — and the usage, here a duration. A response_format of "text", "srt" or "vtt" returns plain text, which raw does not hold; subtitles, timestamps and speaker labels come from models OpenAI deprecated, which "will shut down on February 26, 2027" with /v1/audio/translations (transcription). The default model is gpt-transcribe on OpenAI, and on an endpoint of your own that declares :audio or :transcription; an endpoint that declares its capabilities without either cannot transcribe: transcribe throws ArgumentError before any request (Limits and refusals), as it does for one that declares none (Platform APIs).','translate streams the speech of a WAV file through a Realtime translation session, wss://api.openai.com/v1/realtime/translations on gpt-realtime-translate, into language (English unless named), and returns the translated transcript as a TranscriptionSuccess; the translated speech the session also sends is not kept. OpenAI\'s translation sessions take "base64-encoded 24 kHz PCM16 audio" over WebSockets (Realtime translation), so UniLM reads a 16-bit PCM WAV file of any rate and channel count, mixes it down to one channel, resamples it by linear interpolation, with no anti-aliasing filter, and sends it in 200 ms frames; any other file is refused (Limits and refusals).',"Speech already in the target language can come back as empty text, and a short clip's translation varies from call to call, as the translate reference reports.","What speak and translate return when they fail:","Each makes one attempt. total_deadline bounds the whole call whatever the socket does, connect_timeout the WebSocket's open, and stream_idle_timeout every send and every wait for the next event. Both observe the ambient CancelToken: a token already cancelled sends nothing, and a cancel ends the call at once with an AudioCallError whose cause is a UniLMCancelled. transcribe is one HTTP request, sent again after a transient status, as a Chat is, the whole file each time (Timeouts & Retries); its results are typed as a platform verb's are (Platform APIs).",'UniLM prices none of them: token_usage and estimated_cost throw for a SpeechSuccess and a TranscriptionSuccess. OpenAI bills gpt-transcribe at "$0.0045 / minute", gpt-realtime-translate at "$0.034 / minute", and a speech session at the Realtime model\'s token rates (pricing). A Chat on an audio model answers in speech too (Audio replies), and every type is in the Audio API reference.']],["Realtime sessions","timeout_realtime",["realtime_connect(handler; model=\"gpt-realtime-2.1\") opens a WebSocket to OpenAI's Realtime API, wss://api.openai.com/v1/realtime, and runs handler(session) once it is open. Inside the handler, realtime_send sends a client event, a Dict that session_update, input_audio_append, response_create and realtime_event build, and realtime_receive returns the next server event as a Dict. The socket closes when the handler returns, and realtime_connect returns what it returned. Audio travels as base64 PCM inside the events: UniLM covers the WebSocket transport, not WebRTC or SIP, and not GPT-Live's sessions at wss://api.openai.com/v1/live/sessions (WebSockets). A session is not recorded, so its output here is quoted from a live run:","The events and the session's fields are OpenAI's (Realtime client events): session.type \"realtime\", output_modalities, and the output audio under audio.output. UniLM does not read a session's usage: estimated_cost has nothing to price, and OpenAI bills the session at the model's Realtime rates (pricing). A session is bounded in two phases, and deliberately not in a third:","Unlike the other verbs, realtime_connect throws rather than returning a typed result, makes a single attempt, which max_attempts does not change, and refuses another service before any I/O (Limits and refusals). A realtime_connect session — its open and realtime_receive — does not observe the CancelToken; speak and translate run Realtime sessions of their own, and those do observe it (Audio).",'mint_realtime_secret makes a client secret, POST /v1/realtime/client_secrets: "Client secrets are short-lived tokens that can be passed to a client app, such as a web frontend or mobile client, which grants access to the Realtime API without leaking your main API key" (Create client secret). session is an optional session configuration; UniLM sends no expires_after, so a secret lasts OpenAI\'s default, "600 seconds (10 minutes)":',"The verb makes one bounded attempt and returns a RealtimeSecretSuccess, whose value is the secret — shown redacted, so a log or the REPL does not hand it out —, a RealtimeFailure with the status of an error and its request_id, or a RealtimeCallError, also for a 200 that carries no secret. Every type is in the Realtime API reference."]],["Limits and refusals","openai_media_limits",["OpenAI's limits on a request's media — an edit's 50 MB, a transcription's 25 MB — are OpenAI's to check: UniLM checks neither the size nor the format of a file, except that translate reads its WAV file. These are refused with an ArgumentError before anything is sent:"]]]},{url:"/providers/openai/models/",sections:[["Models & request rules",null,[]],["Models","openai_models",["A request names its model with model, and UniLM sends any id as given; without one, a Chat or a Respond takes the default model named at the top of the start page. The models UniLM holds request rules for are the rows of the rule table, and the models it prices are the rows of the price table. A model id takes the row of the same id, or of that id without a -YYYY-MM-DD snapshot suffix, never the row of an id it merely starts with: a request on a model no row names gets none of the per-model checks, and OpenAI's answer is the check; a result from a model with no price row is estimated at 0.0, with a warning.","list_models with service=OPENAIServiceEndpoint asks OpenAI's Models API (GET /v1/models) which models your key can use, and returns a ModelListSuccess whose models are ProviderModels. OpenAI lists each model's id, its creation time, as created, its owner and its shutdown_date, \"the date when the model will shut down, or null if not announced\" (List models); UniLM reads the shutdown date as retires, keeps the entry as sent in raw, and has no token limits or capabilities to fill in for OpenAI (Model Listings). An error status is a ModelListFailure, and a call that brings no listing — no key, which it names, no connection, a timeout, a reply that is not the listing — a ModelListCallError. A listing bills no tokens and is not recorded, so its output here is quoted from a live run:","The listing also names models whose shutdown date has passed. Before you use a newly listed model, check that it has a price row, as the lookup above does, and whether it needs request rules UniLM does not hold yet: OpenAI's model pages give each model's reasoning efforts and the APIs it serves.","OpenAI describes the models of the rule table, and gpt-5.4-mini, on which the manual's concept pages run their examples, in its own words:"]],["Reasoning","openai_reasoning",['reasoning_effort on a Chat and reasoning=Reasoning(effort=…) on a Respond set how much a reasoning model reasons before it answers. UniLM takes the efforts "none", "minimal", "low", "medium", "high", "xhigh" and "max", and checks the request against the model\'s row of the table below when it is encoded, before anything is sent (Limits and refusals):',"The columns:",'Live requests of 25 October 2026, sent as raw HTTP. gpt-6-astra on the Responses API with no reasoning and max_output_tokens=16: HTTP 200, the response\'s reasoning was {"context": "all_turns", "effort": "medium", "mode": "standard", "summary": null}. gpt-5.6-luna with temperature=0.5: at reasoning_effort="low", HTTP 400 on Chat Completions, "Unsupported value: \'temperature\' does not support 0.5 with this model. Only the default (1) value is supported."; with reasoning={"effort": "low"}, HTTP 400 on the Responses API, "Unsupported parameter: \'temperature\' is not supported with this model."; at reasoning_effort="none", HTTP 200 on Chat Completions.',"Reasoning configures the reasoning of whatever model a Respond names: UniLM checks its effort per model only for the rows above, and sends it unchecked for a model no row names, OpenAI's answer being the check. On the Responses API a summary of the reasoning comes back when the request asks for one, as the summary array of the response's reasoning items (reasoning summaries), and reasoning_summaries reads it:",'Reasoning tokens "are billed as output tokens" (reasoning): completion_tokens counts them, reasoning_tokens is their part, and estimated_cost prices them at the output rate. Chat Completions returns no reasoning text, so reasoning_text of a Chat result is nothing. A request\'s output cap — max_completion_tokens on a Chat, max_output_tokens on a Respond — bounds the reasoning and the visible output together: a reply that reaches it ends with finish_reason == "length", or a response with status "incomplete", possibly before any visible text.','Reasoning also takes OpenAI\'s persisted reasoning, context ("auto", "current_turn" or "all_turns"), and its execution mode, mode ("standard" or "pro"), and a Respond input may hold a configuration_update item, which changes the effort of later responses without rewriting the request-level effort, so the cached prompt prefix stays reusable; OpenAI supports it on "the GPT-6 model family in standard, single-agent mode" (change reasoning mid-conversation).']],["Prompt caching","openai_caching",['OpenAI caches prompt prefixes by itself. On GPT-5.6 and later, prompt_cache_options chooses how: a PromptCacheOptions with a mode, "implicit" (the API\'s default: OpenAI places a breakpoint at the end of the latest eligible message) or "explicit" (only the breakpoints you mark), and a ttl, the minimum lifetime of what a request writes. A prefix "must meet the model\'s minimum cacheable token length", 1,024 tokens on GPT-5.6 and later (prompt caching). The two APIs take different options:','prompt_cache_key, on both APIs, is the key OpenAI uses "to cache responses for similar requests to optimize your cache hit rates". The deprecated prompt_cache_retention of a Chat or a Respond is refused on the models whose prompt_cache_retention cell in the rule table is "—", whose cache lifetime prompt_cache_options sets, and sent as given on the others. Here a generated parts list is the system prompt of a conversation, and each turn asks about one part:',"The first request wrote the system prompt and its question to the cache. The second read them back and wrote only what the conversation had added, the reply and the next question. The usage counts the cache reads as cached_tokens and the writes as cache_write_tokens, of which cache_write_extended_tokens are the writes kept for 12 hours, which only the Responses API reports; what each costs is on Cost and usage. A Respond that marks its own breakpoints sends them in its input; UniLM.encode_agentic shows the body respond sends, with no key and no request:"]],["Cost and usage","openai_cost",["estimated_cost prices a result with the row of the price table below for the model that served it — result.model of a Chat result, result.response.model of a Respond result — and an id with a -YYYY-MM-DD snapshot suffix with the row of the id without it; cumulative_cost adds up the calls of a Chat. Of the usage, it bills the uncached input at the input rate, the cache reads at the cached-input rate, the cache writes at the multiples of the Cache writes column of the table just below, and all the output, the reasoning included, at the output rate. Every rate is then multiplied by the factors that apply:",'A "—" in the table is a price OpenAI\'s pricing page does not give: a write then bills at the input rate, any prompt at the row\'s rates, and a tier at the standard rates, with one warning per model and tier. So does a tier the table has no column for, such as Scale, and every tier of a model without a row in this table. OpenAI bills a request that Fast mode downgraded at standard rates and reports it as service_tier: "default" (Fast mode), and the estimate follows the reported tier.',"Audio tokens — prompt_audio_tokens and completion_audio_tokens — bill at the audio rates below, scaled by the factors above as the text rates are, and the rest of the call at the text rates of the model's row; a call whose usage counts audio on a model without audio rates is estimated at 0.0, with a warning (Audio replies):","cumulative_cost is a lower bound of the bill: it adds nothing for an attempt UniLM retried, a failure, or a stream stopped before its usage arrived (Streaming), and no estimate includes the fees of hosted tools — web search, file search and containers bill per call or per session — or the 10% uplift OpenAI charges on its regional-processing endpoints for the models released since 5 March 2026 (pricing). A model with no row below is estimated at 0.0, with one warning per model id: pass estimated_cost a pricing table that holds its row, or add the row to DEFAULT_PRICING (Cost Tracking).","The rows are OpenAI's list prices as checked on 25 October 2026 (gpt-5.2-pro's on 26 October); prices change, so check OpenAI's pricing page before relying on an estimate."]],["Limits and refusals","openai_limits",["A request's output stops at its cap — max_completion_tokens on a Chat, max_output_tokens on a Respond — which counts the reasoning too (Reasoning), and a model's context window and largest output are on its OpenAI model page. UniLM checks a request against neither, and leaves the size of images and files to the API. Rate limits are on When something fails.","chatrequest!, respond, the tool loops and embeddingrequest! throw these ArgumentErrors before anything is sent, and so do the constructors of the request's parts where the row names one. A rule that names a column of the rule table holds for the ids of its rows, and an id no row names meets only the other rules.","The image, audio and Realtime verbs refuse what Images, audio & realtime lists, and the platform verbs what Platform APIs lists.",'The request\'s parts refuse a value outside their own sets first, on every endpoint: PromptCacheOptions any ttl other than "5m", "1h", "30m" and "12h" (prompt cache ttl must be one of), and Reasoning and Chat an effort outside the seven above (reasoning effort must be one of, reasoning_effort must be one of).',"Recorded on 25 October 2026 on gpt-6-sol with UniLM's development branch after 0.26.0."]]]},{url:"/providers/openai/platform/",sections:[["Platform APIs",null,['Besides its model APIs, OpenAI serves APIs that hold what a request works with — files, conversations, code-interpreter containers — and that run work beside it: batches, fine-tuning jobs, moderation, and the webhooks that report on them. UniLM wraps each with verbs of its own, on OPENAIServiceEndpoint unless a call names another service; OPENAIServiceEndpoint() returns that same type. The vector stores of file search are on Retrieval & file search, and images, speech and the Realtime API on Images, audio & realtime; which of these APIs other providers serve is on Capabilities by provider. Every verb, type and keyword is in the API reference: Files, Uploads, Conversations, Containers, Batch, Fine-tuning, Moderations and Webhooks. UniLM does not wrap OpenAI\'s Agents API, which "gives your application access to the Codex harness through an OpenAI-managed API" (Agents API).',"These calls are not recorded, so their output on this page is quoted from dated runs."]],["What the platform verbs share","openai_platform_shared",[]],["Files and uploads","openai_files",['upload_file(path, purpose) sends a file to POST /v1/files as multipart/form-data, with the purpose "assistants", "batch", "fine-tune", "vision" or "user_data"; the Evals API\'s "evals" is refused (Limits and refusals), since OpenAI\'s Evals "become read-only" on 31 October 2026 and "are scheduled to shut down" on 30 November 2026 (deprecations). "Individual files can be up to 512 MB, and each project can store up to 2.5 TB of files in total"; the Batch API "only supports .jsonl files up to 200 MB in size", and fine-tuning .jsonl files (Upload file). list_files takes a purpose, a limit — "between 1 and 10,000, and the default is 10,000" — and after, the id of the last file of the page before (its has_more says whether one follows); retrieve_file reads one file\'s record, file_content its bytes, and delete_file removes it, which also is to "remove it from all vector stores" (Files).','Runs of 25 October 2026, 16:29–16:47 UTC, with UniLM\'s development branch after 0.26.0: OpenAI answered file_content of a file uploaded with the purpose "user_data" with HTTP 502 or 503 on each of three tries, while files with the purpose "batch" downloaded; four of ten delete_file calls drew HTTP 503 and succeeded when sent again; one upload_file drew HTTP 502, and a listing afterwards showed that no file had been made.',"save_file_content writes the bytes atomically: to a temporary file beside the target, then renamed over it, so a failed write leaves an existing file whole; the file keeps its permission bits, a symbolic link is written through, and a directory is refused. An uploaded file goes to a Respond as input by its id, input_file(; id=…) for a document and input_image(; file_id=…) for an image (Input).",'The Uploads API takes a large file in parts: "an Upload can accept at most 8 GB in total and expires after an hour after you create it", "Each Part can be at most 64 MB", and "The number of bytes uploaded upon completion must match the number of bytes initially specified when creating the Upload object" (Uploads). create_upload takes the Files purposes, "evals" refused as above (Limits and refusals); add_upload_part sends one part, the bytes you give it; complete_upload joins the parts in the order the list gives their ids, checking an md5 of the whole file when given one, and returns the upload with its file; cancel_upload ends one. UniLM does not split a file: a file larger than a part is sent a slice at a time, as the second block below does.',"A file larger than a part goes up a slice at a time, each slice a part:"]],["Conversations","openai_conversations_api",['A conversation of OpenAI\'s Conversations API holds a conversation\'s items on OpenAI\'s side, with "its own durable identifier", and works with the Responses API (conversation state). create_conversation(; items, metadata) makes one — "You may add up to 20 items at a time" — and conversation_id reads its id, which a Respond\'s conversation takes: "Items from this conversation are prepended to input_items for this response request. Input items and output items from this response are automatically added to this conversation after this response completes" (Create a model response, conversation).','conversation is sent as given, the id or a Dict("id" => …), and a Respond refuses it together with previous_response_id (Limits and refusals); the conversation\'s turns come back from OpenAI, so the second request sends only its question, and tool_loop chains through the conversation when the Respond sets one (Tools). "Conversation objects and items in them are not subject to the 30 day TTL" of a stored response (conversation state). retrieve_conversation and update_conversation(id, metadata) read and change the conversation\'s record, add_conversation_items appends items without a response, list_conversation_items pages through them (limit, order, after), retrieve_conversation_item(id, item_id; include) reads one, "a single item from a conversation", as a ConversationItemSuccess, and delete_conversation_item removes one, returning the conversation.']],["Code interpreter and containers","openai_containers",['The code interpreter, a hosted tool of the Responses API, runs Python that the model writes, and "requires a container object", "a fully sandboxed virtual machine that the model can run Python code in" (Code Interpreter). code_interpreter() sends an auto container, {"type": "auto"}, which "automatically creates a new container, or reuses an active container that was used by a previous code_interpreter_call item in the model\'s context"; container takes OpenAI\'s other forms:',"file_ids, the ids of uploaded files, go inside the container Dict, the auto one unless you give another. With a container id, or beside a Dict that names file_ids itself, they are refused (Limits and refusals): a container made beforehand takes its files through create_container(; file_ids) and add_container_file.","UniLM.encode_agentic shows the tool each form sends, with no key and no request:",'A run in a container made beforehand, with tool_choice="required" so that the model runs the tool, and include=["code_interpreter_call.outputs"] for what the code printed:','code_interpreter_outputs returns the response\'s code_interpreter_call items as OpenAI sent them, each with the code the model ran, the container_id it ran in and, with the include, its outputs. "A container expires if it is not used for 20 minutes. When this happens, using the container in v1/responses will fail", and its data is discarded: "You should download any files you may need from the container while it is active" (Code Interpreter). create_container(; name, file_ids, expires_after) sends no memory_limit, so a container it makes has OpenAI\'s default, "1g"; retrieve_container, list_containers and delete_container read, list and delete containers, and add_container_file(id, path) uploads a file into one, returning a ContainerSuccess whose response is the file\'s record, its path where the code sees it; a path that is no file is refused before anything is sent (Limits and refusals). It does not wrap the endpoints that list, read or delete the files in a container. A container bills "1 GB $0.03, 4 GB $0.12, 16 GB $0.48, 64 GB $1.92 per 20-minute session per container" (pricing), which estimated_cost leaves out (Cost and usage).']],["Batches","openai_batch",['The Batch API runs requests "with 50% lower costs, a separate pool of significantly higher rate limits, and a clear 24-hour turnaround time" (Batch API). Its input is a .jsonl file, uploaded with the purpose "batch", each of whose lines is one request: a unique custom_id, the method, the url — /v1/responses, /v1/chat/completions, /v1/embeddings, /v1/completions, /v1/moderations, /v1/images/generations or /v1/images/edits — and the body, "the same as the parameters for the underlying endpoint"; "each input file can only include requests to a single model", and "A single batch may include up to 50,000 requests". The bodies can be the ones UniLM would send, so its request rules hold for them: UniLM.encode_agentic of a Respond, or UniLM.encode_request of a Chat.',"Read back once the cancel had settled:",'create_batch(input_file_id, endpoint; completion_window="24h", metadata) sends the endpoint as given — "the completion window can only be set to 24h" —, and retrieve_batch, list_batches and cancel_batch read, list and cancel batches. A batch moves through OpenAI\'s statuses: validating, in_progress, finalizing and completed; failed when "the input file has failed the validation process"; expired when it "was not able to be completed within the 24-hour time window"; and cancelling, which "may take up to 10 minutes", then cancelled. poll_batch reads a batch until it is completed, failed, cancelled or expired (Long-running jobs).','The results are files: output_file_id names the output, which "will have one response line for every successful request line in the input file", and error_file_id the errors; "the output line order may not match the input line order", so match lines by custom_id. Either id is nothing while the batch has no such file, as for the batch cancelled above, so read it before calling file_content:',"An expired batch's \"unfinished requests within that batch are cancelled, and any responses to completed requests are made available via the batch's output file. You will be charged for tokens consumed from any completed requests.\" The batch.completed, batch.cancelled, batch.expired and batch.failed webhooks report the end without a poll (Webhooks)."]],["Fine-tuning","openai_fine_tuning",['"OpenAI is winding down the fine-tuning platform. The platform is no longer accessible to new users. Eligible existing customers can create training jobs until January 6, 2027, unless the base model shuts down earlier", and "Fine-tuned models remain available for inference until their base model shuts down" (supervised fine-tuning). The default model takes no fine-tuning: its model page lists v1/fine-tuning as "Not supported" (GPT-6 Sol). No job was run for this page, so this block has no output:','base_model is a model your organization may still fine-tune. create_fine_tuning_job sends model, training_file and, when set, validation_file, method — a Dict that names the "supervised", "dpo" or "reinforcement" method with its hyperparameters —, suffix and metadata. A job\'s status is one of "validating_files, queued, running, pausing, paused, succeeded, failed, or cancelled" (Fine-tuning), and fine_tuned_model names the model it made, which a Chat or a Respond takes as its model. No verb waits for a job: read it with retrieve_fine_tuning_job, page through list_fine_tuning_events and list_fine_tuning_checkpoints (limit, after), or take the fine_tuning.job.succeeded, fine_tuning.job.failed and fine_tuning.job.cancelled webhooks (Webhooks). cancel_fine_tuning_job and list_fine_tuning_jobs cancel and list jobs; OpenAI\'s pause, resume and checkpoint permissions are not wrapped.']],["Moderation","openai_moderation",['moderate(input; model="omni-moderation-latest") classifies text and images with OpenAI\'s Moderations API, POST /v1/moderations. "The omni-moderation-latest model accepts text and image inputs. It doesn\'t classify audio. The moderation endpoint is free to use, and image files can be up to 20 MB" (moderation). input is a string, a vector of strings, or a vector of content parts, text and image_url ones, which are one input together:','A ModerationResponse holds one ModerationResult per input — its flagged, its categories, each true or false, and its category_scores — and the model; each result keeps its row as raw. A reply whose rows do not match the inputs one for one, or a row without flagged, is a ModerationCallError: a verdict that cannot be matched to its input is no verdict. is_flagged is true when any row is flagged, and throws an ArgumentError for a ModerationFailure or a ModerationCallError rather than answering false, which would let unmoderated content through: check issuccess first, and decide what a missing verdict means. A Chat or a Respond can also moderate its own input and output with a ModerationConfig, whose results a Chat\'s result keeps as its moderation and a Respond\'s in result.response.raw["moderation"] (Chat Completions, Request options): ModerationConfig(; model, input_mode, output_mode) needs its model, and sends each mode set, "score" or "block", as the policy of its side. The moderation of an image request is another setting, the filtering level of the image models (Image generation).']],["Webhooks","openai_webhooks",['OpenAI\'s webhooks "allow you to receive real-time notifications about events in the API, such as when a batch completes, a background response is generated, or a fine-tuning job finishes. Webhooks are delivered to an HTTP endpoint you control, following the Standard Webhooks specification", and each endpoint, made on OpenAI\'s dashboard, comes with "a signing secret to use for server-side verification of incoming webhook requests" (webhooks). verify_webhook(payload, headers, secret) checks a delivery against it, with no request: payload is the raw body, headers the request\'s headers, which hold webhook-id, webhook-timestamp and webhook-signature, and secret the signing secret, with or without its whsec_ prefix. It returns true when a fresh v1 signature of the delivery is valid, false otherwise. A stored delivery, here with a made-up secret, verifies with tolerance_seconds=Inf, which skips the time check:',"The second call keeps the default window, 300 seconds either side of now, and the delivery is older, so it fails, as a replayed delivery does. parse_webhook reads a verified payload into a WebhookEvent:","WEBHOOK_EVENTS lists the event types: responses, batches and fine-tuning jobs that end, incoming calls of the Realtime and Live APIs, and safety notices. It leaves out the eval.run.* events, which OpenAI sends until the Evals API shuts down on 30 November 2026, so a filter on it drops them. On a server, the payload is the request's body as it arrived, before any JSON parsing, here in an HTTP.serve handler, with handle_batch your own function:",'OpenAI asks for a quick 2xx: "If the endpoint doesn\'t return a successful (2xx) status code, or doesn\'t respond within a few seconds, the webhook request will be retried. OpenAI will continue to attempt delivery for up to 72 hours with exponential backoff", and it "may deliver duplicate copies of the same webhook event. You can use the webhook-id header as an idempotency key to deduplicate" (webhooks). A negative or NaN tolerance is refused, and so is a secret that is not base64 after its whsec_ prefix, such as a placeholder like whsec_*** or misplaced padding; whitespace around the secret is ignored. An empty secret — "", as an unset variable read with a default gives, or whsec_ alone — is refused whatever the delivery, since anyone can sign with an empty key (Limits and refusals).']],["Long-running jobs","openai_long_jobs",["Four kinds of work go on at OpenAI after the call that starts them returns:","poll_batch and poll_file_batch read their job every interval seconds until it reaches a final status, which they return, for at most timeout seconds of wall-clock time (Inf waits indefinitely). A failure worth another read — a status UniLM sends a request again after (When something fails), or a GET that timed out — is polled through; any other failure is returned as it came. When the time runs out, the result is the family's call error, BatchCallError or VectorStoreCallError, with a UniLMTimeout(:deadline, …) as cause and the last batch it read as last_observed (nothing if no read succeeded). cancel (the ambient token unless given) ends a poll at once, mid-read or mid-pause, with the call error and a UniLMCancelled as cause; config bounds each read.","A background response is read back with get_response and stopped with cancel_response (Stored responses), here with one read between them:",'"Keep polling while the request is in the queued or inprogress state. When it leaves these states, it has reached a final (terminal) state", and "Cancelling twice is idempotent - subsequent calls simply return the final Response object" (background mode). A background response that failed comes back from `getresponseandcancelresponseas aResponseFailure, asrespondreturns a failed response: itsstatusis 200, itsresponsethe response\'s JSON with OpenAI\'serror, and [responsestatus](@ref) reads"failed"`.','A background request may set store=false: "Background requests can use store=false, but response data is temporarily stored to support asynchronous execution and polling", and get_response reads such a response while OpenAI holds it. A stored response (store=true, the default) is kept "for at least 30 days, subject to the data retention exceptions" (Create a model response), and the background guide names two for background requests: in a Zero Data Retention project they "run with store=false", their data kept "for roughly 10 minutes"; in a Modified Abuse Monitoring project, "Background responses are retained after the polling period only when store=true is explicitly provided. If store is omitted or set to false for a background request, the response is deleted after roughly 10 minutes" (background mode).']],["Limits and refusals","openai_platform_limits",["The sizes OpenAI allows — a file's 512 MB, an upload part's 64 MB, a batch file's 200 MB and 50,000 requests — are OpenAI's to check, and UniLM checks none of them. These are refused with an ArgumentError before anything is sent:"]]]},{url:"/providers/openai/responses/",sections:[["Responses & hosted tools",null,["On OPENAIServiceEndpoint a Respond goes to OpenAI's Responses API, POST /v1/responses, as its own JSON, which writes each field the Respond sets under the API's name. respond(input; kwargs...) builds the Respond from its keywords and sends it, respond(r) sends one built before, and tool_loop runs the function calls of a response until the model answers. Before anything is sent, the request is checked against OpenAI's rules and the model's row in the rule table, and a request that breaks one is refused (Limits and refusals). The verb every provider of an agentic API shares is on Agentic respond."]],["Input","openai_responses_input",['input is a string, the user\'s message, or a vector of input items: InputMessages, with the role "user", "assistant", "system" or "developer", and items given as Dicts, such as a tool_result, a configuration_update or an mcp_approval_response. instructions is "A system (or developer) message inserted into the model\'s context", and with previous_response_id, "the instructions from a previous response will not be carried over" (Create a model response).',"An InputMessage's content is a string or a vector of parts: input_text, input_image — an image URL, a base64 data URL, or the file_id of an uploaded file, with a detail level — and input_file — a file URL, a file id, or base64 file_data; input_file(document) makes the part of a DocumentAttachment. An attachment itself is refused in a Responses input, an AudioAttachment among them (Limits and refusals).",'An assistant message you replay, rather than chain with previous_response_id, keeps the phase the model gave it, "commentary" for an intermediate update or "final_answer": OpenAI asks callers, for "models like gpt-5.3-codex and beyond", to "preserve and resend phase on all assistant messages — dropping it can degrade performance" (Create a model response, input). output_text leaves a "commentary" message out of the answer. UniLM.encode_agentic shows the body respond sends, with no key and no request:']],["Tools","openai_tools",['A function tool is a FunctionTool, made by function_tool(name, description; parameters, strict); it also takes async, allowed_callers, defer_loading and output_schema, each sent when set. A Chat Tool given to Respond becomes the equivalent FunctionTool. OpenAI\'s guide to its GPT-6 models routes tool calling to this API: "Use Responses for reasoning with tools" (GPT-6 guide), and UniLM checks no effort for tools here. A strict tool\'s schema follows the rules of Tools on Chat Completions, and a request whose strict schema misses them "will be rejected with details about the missing constraints" (function calling). A tool that sets no strict goes without one, and OpenAI decides: "If you omit strict, the default depends on the API: Responses requests will attempt to normalize your schema into strict mode when possible, and will fall back to non-strict, best-effort function calling if the schema cannot be made compatible with strict mode. When fallback happens, the response tool will show strict: false"; to keep best-effort calling, set strict=false.',"function_calls reads a response's calls, each a Dict with its call_id, name and arguments (a JSON string), and tool_result(call_id, name, output) makes the input item that answers one on the next request. tool_loop does both until the model answers in text, chaining the requests with previous_response_id, or with conversation when the Respond sets one:","The Respond sets no parallel_tool_calls, and the model asked for both cities in one response; a Chat with tools sends false and gets a turn per call (Tools on Chat Completions).",'tool_choice is "auto", "none" or "required", or an object a builder makes: tool_choice_function(name), tool_choice_hosted(type), tool_choice_mcp(label; name), tool_choice_custom(name) or tool_choice_allowed(mode, tools). parallel_tool_calls, "Whether to allow the model to run tool calls in parallel", is sent only when set, and left to the API\'s default otherwise. The loop runs a response\'s calls only when its status is completed or requires_action, and stops, with completed=false, on a call the application must carry out itself (computer_call, apply_patch_call, custom_tool_call, a shell_call that OpenAI did not run, or an mcp_approval_request); the loop every provider shares is on Tool Calling.']],["Hosted tools","openai_hosted_tools",["The other tools of a Respond are OpenAI's built-in tools: most run on OpenAI's side, and their results come back in the response's output items; the last row's are calls the application carries out:",'mcp_tool sends require_approval="never" unless it is given another value, while OpenAI\'s own default is to "request your approval before any data is shared with a connector or remote MCP server"; with approvals, a request for one is an mcp_approval_request item, and an mcp_approval_response in the next request\'s input answers it (MCP servers). The hosted tools bill beyond the tokens — web search per call, containers per session — which estimated_cost does not include (Cost and usage).']],["Structured output on Responses","openai_responses_structured_output",['text holds the output format: json_schema_format(name, description, schema; strict) for a reply that follows a JSON Schema, json_object_format() for any JSON object, and text_format(; verbosity) for plain text, each a TextConfig whose verbosity is "low", "medium" or "high". A strict schema follows the rules of Structured output.']],["Stored responses","openai_stored_responses",['A response is stored unless its request sets store=false, "for at least 30 days" (Create a model response), and get_response, cancel_response, delete_response and list_input_items work on it by its id. get_response and cancel_response return a ResponseSuccess, or a ResponseFailure for a response whose status is "failed", as respond does; delete_response, list_input_items, compact_response and count_input_tokens return OpenAI\'s answer as a Dict; a failure of any of them is a ResponseFailure or a ResponseCallError. Each makes one attempt, never retried (When something fails).','count_input_tokens asks how many input tokens a request would use, "the exact count the model will receive", without generating (counting tokens); with no model it counts for the default model named at the top of the start page:','compact_response runs a compaction pass over a conversation\'s items, POST /v1/responses/compact: the window it returns "includes an encrypted compaction item" that is "opaque", to be passed on as the next request\'s input without pruning (compaction):',"With background=true, respond returns as soon as OpenAI has queued the response, and cancel_response stops it:",'A background response is read back with get_response until it leaves the queued and in-progress states, "Keep polling while the request is in the queued or in_progress state" (background mode):']],["Request options","openai_responses_options",["The quoted fields are from OpenAI's Create a model response and Retrieve a model response. refusals and reasoning_items read a response's output items as the hosted tools' accessors do, and incomplete_details and usage_details its incomplete_details and usage. UniLM.encode_agentic shows the body:","Recorded on 23 and 25 October 2026 on gpt-6-sol and gpt-5.4-mini with UniLM's development branch after 0.26.0."]]]},{url:"/providers/openai/retrieval/",sections:[["Retrieval & file search",null,['File search grounds a response in your own documents. It is a tool of the Responses API that lets the model "retrieve information in a knowledge base of previously uploaded files through semantic and keyword search", "a hosted tool managed by OpenAI" (file search): the files are uploaded, indexed into a vector store, and searched when a respond call carries file_search. Five steps make the pipeline, each id passed on to the next:',"The Files and Vector Stores calls are not recorded, so their output on this page is quoted from a dated run; the question is executed. Each of them is a platform verb: one attempt, a typed result, never a throw for what the service answers (Platform APIs)."]],["Build the store","openai_retrieval_store",["The policy file is uploaded, a store is made for it, and the file is attached as a batch, which poll_file_batch reads back until it is indexed:",'"When you add a file to a vector store it will be automatically chunked, embedded, and indexed" (retrieval), which takes a while: a batch is "in_progress" until it is "completed", "cancelled" or "failed", and file_counts says how many of its files reached each status. poll_file_batch reads the batch every 2 seconds, for at most 300, and returns it at the first of those three statuses; here it took about 6 seconds. What it returns when the time runs out or a GET fails is on Long-running jobs. Search the store once the batch is "completed", and check file_counts for a file that failed.',"UniLM sets no file attributes, the values a search's filters compare (Ask with file search): neither add_vector_store_file nor create_file_batch takes them, and no verb updates them."]],["Ask with file search","openai_retrieval_ask",['file_search(vector_store_ids; max_results, ranking, filters) makes the tool, and include=["file_search_call.results"] asks for the chunks the search found, "the search results of the file search tool call" (Create a model response, include). The call names the store the run above made, by its id:','The answer comes from the file: the response\'s output holds a file_search_call item, with the queries the model searched for and, because of include, their results, then the message, whose output_text carries file_citation annotations naming the files it drew on. file_search_results returns the file_search_call items as OpenAI sent them, so a chunk\'s fields are read from the Dict. Without include, "the file search call will not return search results by default", while "you can see annotations (references to files) in the output text" (file search). The other tools OpenAI runs are on Hosted tools.',"The tool's options are sent under OpenAI's names:","UniLM checks none of their values; UniLM.encode_agentic shows what respond sends:",'A search bills beyond its tokens, at "$2.50 / 1k calls" of the tool, and the stores\' storage beyond the first, free gigabyte at "$0.10 / GB per day" (pricing); estimated_cost prices the tokens alone (Cost and usage). With the answer and its chunks in hand, a decision model can read the answer against a chunk and send anything but a confident supports to a person (Check claims against the source), and screen the passages you put in a prompt yourself for instructions aimed at the model (Screen what the model reads).']],["Clean up","openai_retrieval_cleanup",["A store and a file stay on OpenAI's servers until they are deleted, or until a store's expires_after runs out:","Deleting a file is also to \"remove it from all vector stores\" (Files), and \"Removing files from a vector store is eventually consistent, and search results may still include content from a removed file for a short period\" (retrieval). A delete is confirmed by the deleted: true of OpenAI's reply (Platform APIs). Of OpenAI's vector-store endpoints, UniLM does not wrap the store's search, update and the files it holds — listing, reading, updating or removing one — nor a batch's cancel or its file list (Vector stores); every verb it has is in the Vector Stores API reference.","Recorded on 25 October 2026 on gpt-6-sol with UniLM's development branch after 0.26.0."]]]}])for(let[s,n,o]of t)a.add({url:e+(n?"#"+n:""),title:s,content:[s,...o].join("\n"),pageTitle:n?t[0][0]:void 0});function n(e,t={}){let s=a.search(e,{...t,enrich:!0});return 0===s.length?[]:s[0].result.map(e=>({url:e.id,title:e.doc.title,pageTitle:e.doc.pageTitle}))}}}]);